/* ==================== Script 208 ==================== */
/* ===== Editor step 24: true original colour + sharper preview =====
   1. Temperature / Tint were faked with sepia + hue-rotate, which rotates EVERY colour (skin turns yellow-green, yellow
      emojis turn green). They are now real white-balance channel gains (SVG feColorMatrix), so neutral colours stay neutral.
   2. The Hue effect no longer defaults to a +40deg shift.
   3. Filter strings such as "none blur(4px)" are invalid CSS and were silently ignored; they are cleaned before use.
   4. "Original colour" button (preview toolbar): removes every colour change from all clips, with Undo.
   5. Preview draws with high-quality smoothing, and "Match source" lifts a low project resolution up to the video's own. */
(function(){
  "use strict";
  var NS="http://www.w3.org/2000/svg", host=null, made={};
  function ensureHost(){
    if(host&&host.isConnected) return host;
    host=document.createElementNS(NS,"svg"); host.setAttribute("width","0"); host.setAttribute("height","0");
    host.setAttribute("aria-hidden","true"); host.style.cssText="position:absolute;width:0;height:0;overflow:hidden;pointer-events:none";
    document.body.appendChild(host); made={}; return host;
  }
  /* kind "t" = temperature (+ warm / - cool), "g" = tint (+ green / - magenta). value is the slider value, -100..100 */
  window.amiyoWBFilter=function(kind,v){
    v=Math.max(-100,Math.min(100,Number(v)||0)); if(Math.abs(v)<.5) return "";
    var id="amiyoWB_"+kind+"_"+Math.round(v*2), h=ensureHost();
    if(!made[id]||!h.querySelector("#"+id)){
      var r=1,g=1,b=1;
      if(kind==="t"){ var k=v/100*0.16; r=1+k; b=1-k; g=1+k*0.15; }
      else { var k2=v/100*0.12; g=1+k2; r=1-k2*0.5; b=1-k2*0.5; }
      var f=document.createElementNS(NS,"filter"); f.setAttribute("id",id); f.setAttribute("color-interpolation-filters","sRGB");
      f.setAttribute("x","0"); f.setAttribute("y","0"); f.setAttribute("width","100%"); f.setAttribute("height","100%");
      var m=document.createElementNS(NS,"feColorMatrix"); m.setAttribute("type","matrix");
      m.setAttribute("values",[r,0,0,0,0, 0,g,0,0,0, 0,0,b,0,0, 0,0,0,1,0].join(" "));
      f.appendChild(m); h.appendChild(f); made[id]=1;
    }
    return "url(#"+id+")";
  };
  window.amiyoCleanFilter=function(f){
    f=String(f==null?"none":f).replace(/^none\s+/,"").replace(/\s{2,}/g," ").trim();
    return f||"none";
  };

  /* ---- high quality smoothing on the working canvas ---- */
  try{ ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality="high"; }catch(e){window.__swl&&window.__swl(e)}

  /* ---- Original colour: strip every colour change from every clip (undoable) ---- */
  var COLOR_FX=["brightness","contrast","saturation","grayscale","sepia","hue","invert","lumBrightness","lumContrast","lumSaturation","lumTemp","lumTint","lumHue","lumFade"];
  function resetAllColour(){
    var before=deepClone(serializableProject()), changed=0;
    (project.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){
      var n0=(c.effects||[]).length;
      if(n0){ c.effects=c.effects.filter(function(x){ return COLOR_FX.indexOf(x.name)<0; }); changed+=n0-c.effects.length; }
      if(c.filter){ c.filter=null; c.filterAmt=1; changed++; }
      if(c.look&&c.look!=="none"){ c.look="none"; changed++; }
      if(c.lut&&(c.lut.enabled||c.lut.table)){ c.lut.enabled=false; changed++; }
      if(c.cgLook){ c.cgLook=null; changed++; }
      if(c.colorWheels){ c.colorWheels={shadows:{x:0,y:0,l:0},midtones:{x:0,y:0,l:0},highlights:{x:0,y:0,l:0}}; }
    }); });
    var after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Original colour",before:before,after:after}); project.history.index++;
    try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)}
    try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)}
    toast(changed?("Original colour restored ("+changed+" colour change"+(changed===1?"":"s")+" removed)"):"No colour changes found on any clip");
  }
  window.amiyoOriginalColour=resetAllColour;

  /* ---- Match source: raise project resolution to the video's own (max 1920 wide) ---- */
  function matchSource(){
    var vw=videoEl.videoWidth||0, vh=videoEl.videoHeight||0;
    if(!vw||!vh){ toast("Play or select the video first so its size is known"); return; }
    var sc=Math.min(1,1920/Math.max(vw,vh*16/9)), W=Math.round(vw*sc/2)*2, H=Math.round(vh*sc/2)*2;
    if(W<=project.settings.width&&H<=project.settings.height){ toast("Project is already at "+project.settings.width+"×"+project.settings.height); return; }
    project.settings.width=W; project.settings.height=H;
    try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
    toast("Project resolution set to "+W+"×"+H+" to match the video");
  }

  var bar=document.querySelector(".preview-toolbar"), q=document.getElementById("qualityBtn");
  if(bar){
    function mk(id,label,title,fn){
      var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id=id; b.textContent=label; b.title=title; b.onclick=fn;
      if(q&&q.parentNode===bar) bar.insertBefore(b,q); else bar.appendChild(b); return b;
    }
    mk("origColourBtn","Original colour","Remove every colour change (hue, tint, temperature, looks, LUTs, wheels) from all clips. Undo brings them back.",resetAllColour);
    mk("matchSrcBtn","Match source","Raise the project resolution to the video's own size for a sharper preview and export",matchSource);
  }
})();

