/* ==================== Script 209 ==================== */
/* ===== Editor step 25: Auto fix (white balance + gentle sharpen) =====
   Samples the raw video frame (not the graded preview), finds the colour cast with a gray-world estimate that ignores
   near-black / near-white pixels, and sets Temperature and Tint on the selected clip to cancel it. Undoable. */
(function(){
  "use strict";
  function autoFix(){
    var f=getClip(); if(!f||f.track.kind!=="video"){ toast("Select a video clip on the timeline first"); return; }
    var vw=videoEl.videoWidth, vh=videoEl.videoHeight;
    if(!vw||!vh){ toast("Move the playhead onto the clip first so a frame is loaded"); return; }
    var c=document.createElement("canvas"); c.width=96; c.height=54;
    var x=c.getContext("2d",{willReadFrequently:true}), d;
    try{ x.drawImage(videoEl,0,0,96,54); d=x.getImageData(0,0,96,54).data; }catch(e){ toast("Couldn't read this frame"); return; }
    var r=0,g=0,b=0,n=0;
    for(var i=0;i<d.length;i+=4){ var l=.299*d[i]+.587*d[i+1]+.114*d[i+2]; if(l<30||l>225) continue; r+=d[i]; g+=d[i+1]; b+=d[i+2]; n++; }
    if(n<50){ toast("Frame is too dark or bright to measure"); return; }
    r/=n; g/=n; b/=n;
    var kT=(b-r)/(b+r), temp=Math.max(-60,Math.min(60,kT/.16*100));
    var r2=r*(1+temp/100*.16), b2=b*(1-temp/100*.16), g2=g*(1+temp/100*.16*.15), m=(r2+b2)/2;
    var kG=(m-g2)/(g2+m/2), tint=Math.max(-60,Math.min(60,kG/.12*100));
    var before=deepClone(serializableProject()), clip=f.clip;
    applyColorFx(clip,"lumTemp",Math.round(temp),0);
    applyColorFx(clip,"lumTint",Math.round(tint),0);
    if(!(clip.effects||[]).some(function(e){ return e.name==="sharpen"; })) clip.effects.push({id:uid("fx"),name:"sharpen",enabled:true,value:.6});
    var after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Auto fix",before:before,after:after}); project.history.index++;
    try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)}
    toast("Auto fix: temperature "+Math.round(temp)+", tint "+Math.round(tint)+" + light sharpen");
  }
  window.amiyoAutoFix=autoFix;
  var bar=document.querySelector(".preview-toolbar"), ref=document.getElementById("matchSrcBtn");
  if(bar){
    var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id="autoFixBtn"; b.textContent="Auto fix";
    b.title="Fix the colour cast of the selected clip (white balance) and add light sharpening. Undo brings it back.";
    b.onclick=autoFix;
    if(ref&&ref.parentNode===bar) bar.insertBefore(b,ref); else bar.appendChild(b);
  }
})();

