    var f=getClip(); if(!f||f.track.kind!=="video") return; var c=f.clip;
    var e=(c.effects||[]).find(function(x){ return x.name==="vibrance"; }), val=e?(Number(e.value)||0):0;
    var wrap=document.createElement("div");
    wrap.innerHTML='<label class="field" style="display:flex;justify-content:space-between">Vibrance (skin-safe) <output id="cu_vbOut">'+val.toFixed(2)+'</output></label><input type="range" id="cu_vb" min="-1" max="1" step="0.05" value="'+val+'">';
    g.appendChild(wrap);
