/* ==================== Script 214 ==================== */
/* ===== Editor step 30: Before / After =====
   Press and HOLD the "Before/After" button to see the selected clip with all colour, effects, looks and wheels removed;
   release to bring them back. Nothing is changed permanently: the settings are put aside while held and restored on
   release, when the pointer leaves the button, when the tab is hidden, and before the project is saved. */
(function(){
  "use strict";
  var held=null, KEYS=["effects","filter","filterAmt","look","lut","cgLook","colorWheels","lumWheels"];
  function start(){
    if(held) return; var f=getClip(); if(!f||f.track.kind!=="video"){ toast("Select a video clip on the timeline first"); return; }
    var c=f.clip; held={c:c,saved:{}};
    KEYS.forEach(function(k){ held.saved[k]=c[k]; });
    c.effects=(c.effects||[]).filter(function(e){ return e.name==="denoise"&&false; });
    c.filter=null; c.look="none"; c.lut=null; c.cgLook=null; c.colorWheels=null;
    var b=document.getElementById("beforeAfterBtn"); if(b) b.textContent="Original";
    try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
  }
  function end(){
    if(!held) return; var h=held; held=null;
    KEYS.forEach(function(k){ if(h.saved[k]===undefined) delete h.c[k]; else h.c[k]=h.saved[k]; });
    var b=document.getElementById("beforeAfterBtn"); if(b) b.textContent="Before/After";
    try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
  }
  window.amiyoEndBeforeAfter=end;
  var sa=window.scheduleAutosave;
  if(typeof sa==="function") window.scheduleAutosave=function(){ end(); return sa.apply(this,arguments); };
  document.addEventListener("visibilitychange",function(){ if(document.hidden) end(); });
  window.addEventListener("pagehide",end); window.addEventListener("blur",end);
  var bar=document.querySelector(".preview-toolbar"), ref=document.getElementById("autoLevelsBtn");
  if(bar){ var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id="beforeAfterBtn"; b.textContent="Before/After";
    b.title="Hold to see the original, unedited look of the selected clip"; b.style.touchAction="none";
    b.addEventListener("pointerdown",function(e){ e.preventDefault(); start(); });
    ["pointerup","pointerleave","pointercancel"].forEach(function(t){ b.addEventListener(t,end); });
    b.addEventListener("keydown",function(e){ if(e.key===" "||e.key==="Enter"){ e.preventDefault(); start(); } });
    b.addEventListener("keyup",function(e){ if(e.key===" "||e.key==="Enter") end(); });
    if(ref&&ref.parentNode===bar) ref.after(b); else bar.appendChild(b); }
})();

