    if(Math.abs(tint)>=1) setFx(clip,"lumTint",Math.round(tint));
    if(Math.abs(bright-1)>.01) setFx(clip,"lumBrightness",+bright.toFixed(2));
    if(Math.abs(con-1)>.01) setFx(clip,"lumContrast",+con.toFixed(2));
