    await new Promise(function(res){ v.addEventListener("loadeddata",res,{once:true}); v.addEventListener("error",res,{once:true}); setTimeout(res,4000); });
    var inP=clip.inPoint||0, outP=clip.outPoint!=null?clip.outPoint:(inP+clip.duration), mid=inP+(outP-inP)/2;
    await new Promise(function(res){ v.addEventListener("seeked",res,{once:true}); try{ v.currentTime=Math.min(mid,(v.duration||mid)-.05); }catch(e){ res(); } setTimeout(res,1500); });
