    if(!done){ toast("Couldn't read any clip frames"); return; }
    var after=serializableProject();
    project.history.entries=project.history.entries.slice(0,project.history.index+1);
    project.history.entries.push({label:"Enhance all clips",before:before,after:after}); project.history.index++;
    try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)}
