/* ==================== Script 217 ==================== */
/* ===== Editor step 33: Smoother quality =====
   Quality: Auto used to drop to a soft Draft preview as soon as a frame took over 45 ms, which on a busy timeline happened
   almost immediately. Now:
   - Auto only switches to Draft when playback is really struggling (average over 90 ms) and returns to Full after 1.5 s of
     recovery (under 40 ms), and never when paused.
   - First-time default is Auto with the higher threshold; your saved choice is respected.
   - The preview canvas keeps high-quality smoothing at all times except Draft. */
(function(){
  "use strict";
  var KEY="amiyo_editor_preview_quality", on=false, since=0;
  function mode(){ try{ var v=localStorage.getItem(KEY); return (v==="full"||v==="draft"||v==="auto")?v:"auto"; }catch(e){ return "auto"; } }
  window.__amiyoDraft=function(){
    var m=mode();
    if(window.__amiyoExporting||m==="full") return false;
    if(m==="draft") return true;
    if(!isPlaying){ on=false; return false; }
    var a=(window.__amiyoPerf&&window.__amiyoPerf.avg)||0, now=performance.now();
    var _ph=false; try{ _ph=matchMedia("(pointer:coarse)").matches; }catch(e){}   /* Plus step 3: phones go to draft at 34 ms, not 90 ms */
    if(!on&&a>(_ph?34:90)){ on=true; since=now; }
    else if(on&&a<(_ph?22:40)&&now-since>(_ph?2500:1500)) on=false;
    return on;
  };
  try{ ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality="high"; }catch(e){window.__swl&&window.__swl(e)}
  try{ viewCtx.imageSmoothingEnabled=true; }catch(e){window.__swl&&window.__swl(e)}
  var b=document.getElementById("qualityBtn");
  if(b) b.title="Auto keeps full quality and only lightens the preview if playback becomes very slow. Exports always use full quality.";
})();

