/* ==================== Script 219 ==================== */
/* ===== Editor step 35: one "Fix" menu =====
   The preview toolbar had grown by eight buttons. They now live in a single "Fix" menu (Enhance, Enhance all, Colour
   doctor, Original colour, Auto fix, Auto levels, Denoise, Match source). Before/After stays on the toolbar because it
   is press-and-hold. Works with mouse, touch and keyboard (Esc closes, arrow keys move). */
(function(){
  "use strict";
  var bar=document.querySelector(".preview-toolbar"); if(!bar) return;
  var items=[
    ["enhanceBtn","Enhance","One click: colour cast, exposure, denoise, sharpen, vibrance"],
    ["enhanceAllBtn","Enhance all clips","Same, measured per clip"],
    ["colourDoctorBtn","Colour doctor","Find out why colours look wrong"],
    ["origColourBtn","Original colour","Remove all colour changes"],
    ["autoFixBtn","Auto fix","White balance + light sharpen"],
    ["autoLevelsBtn","Auto levels","Exposure and contrast"],
    ["denoiseBtn","Denoise on/off","Reduce grain on the selected clip"],
    ["matchSrcBtn","Match source resolution","Sharper preview and export"]
  ];
  var menuBtn=document.createElement("button"); menuBtn.type="button"; menuBtn.className="toolbtn"; menuBtn.id="fixMenuBtn";
  menuBtn.textContent="Fix ▾"; menuBtn.setAttribute("aria-haspopup","menu"); menuBtn.setAttribute("aria-expanded","false");
  menuBtn.title="Colour and quality fixes for the selected clip";
  var first=null; items.forEach(function(it){ var b=document.getElementById(it[0]); if(b&&!first) first=b; });
  if(first&&first.parentNode===bar) bar.insertBefore(menuBtn,first); else bar.appendChild(menuBtn);
  items.forEach(function(it){ var b=document.getElementById(it[0]); if(b) b.style.display="none"; });

  var pop=document.createElement("div"); pop.id="fixMenu"; pop.setAttribute("role","menu"); pop.hidden=true;
  pop.style.cssText="position:fixed;z-index:99998;min-width:230px;max-width:92vw;background:#171310;border:1px solid #4a3f35;border-radius:10px;padding:6px;box-shadow:0 10px 30px rgba(0,0,0,.55);font:13px system-ui,sans-serif";
  items.forEach(function(it){
    if(!document.getElementById(it[0])) return;
    var r=document.createElement("button"); r.type="button"; r.setAttribute("role","menuitem"); r.dataset.t=it[0];
    r.style.cssText="display:block;width:100%;text-align:left;background:none;border:0;color:#eee;padding:8px 10px;border-radius:7px;cursor:pointer";
    r.innerHTML='<div style="font-weight:600">'+it[1]+'</div><div style="font-size:11px;color:#9a8f84">'+it[2]+'</div>';
    r.onmouseenter=r.onfocus=function(){ r.style.background="#2a221c"; }; r.onmouseleave=r.onblur=function(){ r.style.background="none"; };
    r.onclick=function(){ close(); var t=document.getElementById(it[0]); if(t) t.click(); };
    pop.appendChild(r);
  });
  document.body.appendChild(pop);
  function place(){ var q=menuBtn.getBoundingClientRect(), w=pop.offsetWidth||240;
    pop.style.left=Math.max(6,Math.min(innerWidth-w-6,q.left))+"px"; pop.style.top=(q.bottom+6)+"px"; }
  function openM(){ pop.hidden=false; place(); menuBtn.setAttribute("aria-expanded","true"); var f=pop.querySelector("button"); if(f) f.focus(); }
  function close(){ pop.hidden=true; menuBtn.setAttribute("aria-expanded","false"); }
  menuBtn.onclick=function(e){ e.stopPropagation(); pop.hidden?openM():close(); };
  document.addEventListener("pointerdown",function(e){ if(!pop.hidden&&!pop.contains(e.target)&&e.target!==menuBtn) close(); });
  window.addEventListener("resize",function(){ if(!pop.hidden) place(); });
  document.addEventListener("keydown",function(e){
    if(pop.hidden) return; var bs=[].slice.call(pop.querySelectorAll("button")), i=bs.indexOf(document.activeElement);
    if(e.key==="Escape"){ close(); menuBtn.focus(); }
    else if(e.key==="ArrowDown"){ e.preventDefault(); bs[(i+1)%bs.length].focus(); }
    else if(e.key==="ArrowUp"){ e.preventDefault(); bs[(i-1+bs.length)%bs.length].focus(); }
  });
})();

