/* ==================== Script 220 ==================== */
/* ===== Editor step 36: automatic colour-cast alert =====
   When the playhead rests on a video clip, the raw frame is checked once per clip (and again if its colour settings
   change). If skin tones are far from natural, or the editor's settings shift the hue, a small banner offers
   "Fix colour" (one-click Enhance + hue correction when needed) or "Details" (Colour doctor). Never while playing or
   exporting, and a clip you dismiss is not asked about again this session. */
(function(){
  "use strict";
  var asked={}, timer=null, banner=null;
  function hueOf(r,g,b){ var mx=Math.max(r,g,b), mn=Math.min(r,g,b), d=mx-mn; if(!d) return 0; var h;
    if(mx===r) h=((g-b)/d)%6; else if(mx===g) h=(b-r)/d+2; else h=(r-g)/d+4; h*=60; return h<0?h+360:h; }
  function skinHue(el,cv){
    var x=cv.getContext("2d",{willReadFrequently:true}), d; try{ x.drawImage(el,0,0,cv.width,cv.height); d=x.getImageData(0,0,cv.width,cv.height).data; }catch(e){ return null; }
    var hs=[]; for(var i=0;i<d.length;i+=4){ var r=d[i],g=d[i+1],b=d[i+2], mx=Math.max(r,g,b), mn=Math.min(r,g,b), l=.299*r+.587*g+.114*b;
      if(!mx||l<60||l>225) continue; var s=(mx-mn)/mx; if(s<.28||s>.9) continue; var h=hueOf(r,g,b); if(h>=15&&h<=110) hs.push(h); }
    if(hs.length<60) return null; hs.sort(function(a,b){return a-b;}); return hs[hs.length>>1];
  }
  function activeClip(){
    for(var t=0;t<project.tracks.length;t++){ var tr=project.tracks[t]; if(tr.kind!=="video") continue;
      for(var k=0;k<tr.clips.length;k++){ var c=tr.clips[k]; if(c.assetId&&c.kind!=="adjustment"&&currentTime>=c.start&&currentTime<c.start+c.duration) return c; } }
    return null;
  }
  function sig(c){ return c.id+"|"+JSON.stringify([c.effects,c.filter,c.look,c.cgLook,c.colorWheels]).length; }
  function hide(){ if(banner){ banner.remove(); banner=null; } }
  function show(clip,msg,key,suggestHue){
    hide(); banner=document.createElement("div"); banner.setAttribute("role","status");
    banner.style.cssText="position:fixed;left:50%;bottom:14px;transform:translateX(-50%);z-index:99997;max-width:94vw;background:#201812;color:#f3e9de;border:1px solid #e07a3a;border-radius:10px;padding:10px 12px;font:13px/1.4 system-ui,sans-serif;box-shadow:0 8px 24px rgba(0,0,0,.5);display:flex;gap:8px;align-items:center;flex-wrap:wrap";
    banner.innerHTML='<span>'+msg+'</span>';
    function btn(t,fn){ var b=document.createElement("button"); b.type="button"; b.className="chip"; b.textContent=t; b.onclick=fn; banner.appendChild(b); }
    btn("Fix colour",function(){
      hide(); var f=getClip(); 
      try{ var before=deepClone(serializableProject()); var st=window.amiyoFrameStats&&window.amiyoFrameStats();
        if(st){ window.amiyoEnhanceClip(clip,st); if(suggestHue!=null){ applyColorFx(clip,"lumHue",suggestHue,0); } }
        var after=serializableProject(); project.history.entries=project.history.entries.slice(0,project.history.index+1);
        project.history.entries.push({label:"Fix colour",before:before,after:after}); project.history.index++;
        try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} renderAll(); toast("Colour fixed. Undo (Ctrl+Z) reverts it.");
      }catch(e){ toast("Couldn't fix automatically — try Fix ▾ → Colour doctor"); }
    });
    btn("Details",function(){ hide(); if(window.amiyoColourDoctor) window.amiyoColourDoctor(); });
    btn("Dismiss",function(){ hide(); });
    document.body.appendChild(banner); setTimeout(function(){ if(banner&&banner.parentNode) hide(); },15000);
  }
  function check(){
    timer=null; if(isPlaying||window.__amiyoExporting||!videoEl.videoWidth||document.getElementById("colourDoctor")) return;
    var clip=activeClip(); if(!clip) return; var key=sig(clip); if(asked[key]) return;
    var rc=document.createElement("canvas"); rc.width=160; rc.height=90; var pc=document.createElement("canvas"); pc.width=160; pc.height=90;
    var rawH=skinHue(videoEl,rc), preH=skinHue(viewCanvas,pc); if(rawH==null||preH==null) return;
    asked[key]=1;
    if(Math.abs(rawH-preH)>8) show(clip,"The editor is shifting this clip's colours (skin looks "+(preH>rawH?"greener":"redder")+" than the video).",key,null);
    else if(rawH>55) show(clip,"This video's skin tones look yellow-green.",key,Math.round(Math.max(-90,Math.min(0,28-rawH))));
  }
  function schedule(){ if(timer) clearTimeout(timer); timer=setTimeout(check,900); }
  ["seeked","loadeddata","pause"].forEach(function(ev){ videoEl.addEventListener(ev,schedule); });
  var ra=window.renderAll; window.renderAll=function(){ var r=ra.apply(this,arguments); try{ schedule(); }catch(e){window.__swl&&window.__swl(e)} return r; };
})();

