/* ==================== Script 221 ==================== */
/* ===== Editor step 37: Split compare =====
   "Split" toolbar button puts a draggable divider on the preview: the LEFT side shows the raw, unedited video frame and
   the RIGHT side shows your edited result, so you can judge colour, noise and sharpness side by side. Nothing is
   changed in the project. Press Split again (or Esc) to close. Preview only; exports are not affected. */
(function(){
  "use strict";
  var bar=document.querySelector(".preview-toolbar"); if(!bar) return;
  var on=false, split=.5, ov=null, handle=null, raf=0, labL=null, labR=null;
  function activeClip(){
    for(var t=0;t<project.tracks.length;t++){ var tr=project.tracks[t]; if(tr.kind!=="video") continue;
      for(var k=0;k<tr.clips.length;k++){ var c=tr.clips[k]; if(c.assetId&&c.kind!=="adjustment"&&currentTime>=c.start&&currentTime<c.start+c.duration) return c; } }
    return null;
  }
  function build(){
    ov=document.createElement("canvas"); ov.style.cssText="position:fixed;z-index:60;pointer-events:none";
    handle=document.createElement("div"); handle.setAttribute("role","slider"); handle.setAttribute("aria-label","Split position"); handle.tabIndex=0;
    handle.style.cssText="position:fixed;z-index:61;width:30px;margin-left:-15px;cursor:ew-resize;touch-action:none;display:flex;align-items:center;justify-content:center";
    handle.innerHTML='<div style="width:2px;height:100%;background:#ff8a3d;position:absolute"></div><div style="position:relative;width:26px;height:26px;border-radius:50%;background:#ff8a3d;color:#1a1009;font:700 12px system-ui;display:flex;align-items:center;justify-content:center">⇔</div>';
    function lab(t,right){ var d=document.createElement("div"); d.textContent=t; d.style.cssText="position:fixed;z-index:61;pointer-events:none;background:rgba(0,0,0,.6);color:#fff;font:600 11px system-ui;padding:2px 7px;border-radius:5px"; d.dataset.r=right?"1":""; return d; }
    labL=lab("Original",0); labR=lab("Edited",1);
    document.body.appendChild(ov); document.body.appendChild(handle); document.body.appendChild(labL); document.body.appendChild(labR);
    var drag=false;
    function move(e){ var q=viewCanvas.getBoundingClientRect(); split=Math.max(.02,Math.min(.98,(e.clientX-q.left)/q.width)); }
    handle.addEventListener("pointerdown",function(e){ drag=true; handle.setPointerCapture(e.pointerId); move(e); });
    handle.addEventListener("pointermove",function(e){ if(drag) move(e); });
    ["pointerup","pointercancel"].forEach(function(t){ handle.addEventListener(t,function(){ drag=false; }); });
    handle.addEventListener("keydown",function(e){ if(e.key==="ArrowLeft") split=Math.max(.02,split-.03); else if(e.key==="ArrowRight") split=Math.min(.98,split+.03); });
  }
  function frame(){
    if(!on) return; raf=requestAnimationFrame(frame);
    var q=viewCanvas.getBoundingClientRect(), dpr=Math.min(2,devicePixelRatio||1), w=Math.round(q.width*dpr), h=Math.round(q.height*dpr);
    ov.style.left=q.left+"px"; ov.style.top=q.top+"px"; ov.style.width=q.width+"px"; ov.style.height=q.height+"px";
    if(ov.width!==w||ov.height!==h){ ov.width=w; ov.height=h; }
    var x=ov.getContext("2d"); x.clearRect(0,0,w,h);
    var clip=activeClip(), iw=videoEl.videoWidth, ih=videoEl.videoHeight;
    if(clip&&iw){
      x.save(); x.beginPath(); x.rect(0,0,w*split,h); x.clip();
      x.fillStyle="#000"; x.fillRect(0,0,w,h); x.imageSmoothingQuality="high";
      var ks=clip.scale==null?1:clip.scale, dw=w*ks, dh=dw*(ih/iw); if(clip.fit==="cover"){ dh=h*ks; dw=dh*(iw/ih); }
      var kx=clip.x==null?.5:clip.x, ky=clip.y==null?.5:clip.y;
      x.translate(w*kx,h*ky); x.rotate((clip.rotation||0)*Math.PI/180); try{ x.drawImage((window.__amiyoFastVF&&window.__amiyoVFrame)||videoEl,-dw/2,-dh/2,dw,dh); }catch(e){window.__swl&&window.__swl(e)}
      x.restore();
    }
    var sx=q.left+q.width*split;
    handle.style.left=sx+"px"; handle.style.top=q.top+"px"; handle.style.height=q.height+"px";
    labL.style.left=(q.left+8)+"px"; labL.style.top=(q.top+8)+"px";
    labR.style.left=(q.right-8-labR.offsetWidth)+"px"; labR.style.top=(q.top+8)+"px";
  }
  function toggle(){
    on=!on; btn.setAttribute("aria-pressed",String(on)); btn.style.outline=on?"2px solid #ff8a3d":"";
    if(on){ if(!ov) build(); [ov,handle,labL,labR].forEach(function(e){ e.style.display=""; }); frame(); }
    else{ cancelAnimationFrame(raf); [ov,handle,labL,labR].forEach(function(e){ if(e) e.style.display="none"; }); }
  }
  document.addEventListener("keydown",function(e){ if(on&&e.key==="Escape") toggle(); });
  var btn=document.createElement("button"); btn.type="button"; btn.className="toolbtn"; btn.id="splitCompareBtn"; btn.textContent="Split";
  btn.title="Split view: raw video on the left, your edit on the right"; btn.setAttribute("aria-pressed","false"); btn.onclick=toggle;
  var ref=document.getElementById("beforeAfterBtn"); if(ref&&ref.parentNode===bar) ref.after(btn); else bar.appendChild(btn);
})();

