    if(pts.length<6) break;
    var ws=pts.map(function(p){ return p.w; }).sort(function(a,b){ return a-b; }), th=ws[ws.length>>1]*.4;
    pts=pts.filter(function(p){ return p.w>=th; });
    if(pts.length<6) break;
    var sw=0,sk=0,st=0,skk=0,skt=0;
    pts.forEach(function(p){ var w=p.w+.05; sw+=w; sk+=w*p.k; st+=w*p.t; skk+=w*p.k*p.k; skt+=w*p.k*p.t; });
    var den=sw*skk-sk*sk; if(Math.abs(den)<1e-9) break;
    var P2=(sw*skt-sk*st)/den, ph2=(st-P2*sk)/sw;
