async function analyzeBuffer(chs,sr,t0,t1){
  var n0=Math.max(0,Math.floor(t0*sr)), n1=Math.min(chs[0].length,Math.floor(Math.min(t1,t0+600)*sr));
  var env=await envelope(chs,sr,n0,n1), on=env.on, hopSec=env.hopSec;
  var P0=findTempo(on,hopSec), ph0=findPhase(on,P0), g=refineGrid(on,P0,ph0), P=g.P, ph=g.ph;
  var span=on.length*hopSec, beats=[], sum=0, tot=0, i;
  for(var k=0;ph+k*P<on.length-1;k++){ var t=(ph+k*P)*hopSec; beats.push(t); sum+=on[Math.round(ph+k*P)]||0; }
  for(i=0;i<on.length;i++) tot+=on[i];
  var conf=beats.length?(sum/beats.length)/Math.max(1e-9,tot/on.length):0;
  return {bpm:60/(P*hopSec),beats:beats,conf:conf,on:on,hopSec:hopSec,span:span,start:n0/sr};
}
