/* ---------- the beat grid you chose → positions on the timeline ---------- */
function strengthAt(res,sec){ var i=Math.round(sec/res.hopSec), b=0; for(var d=-1;d<=1;d++){ var v=res.on[i+d]||0; if(v>b) b=v; } return b; }
function gridFor(res,st){
  var b=res.beats.slice();
  if(st.mult===.5){
    var e=0,o=0; b.forEach(function(t,i){ if(i%2) o+=strengthAt(res,t); else e+=strengthAt(res,t); });
    var par=o>e?1:0; b=b.filter(function(t,i){ return i%2===par; });
  }else if(st.mult===2){
    var d=[]; b.forEach(function(t,i){ d.push(t); if(i<b.length-1) d.push((t+b[i+1])/2); }); b=d;
  }
  var N=st.every, s=Math.min(st.start,N>1?N-1:3), out=[];
  b.forEach(function(t,i){ if(i>=s&&(i-s)%N===0) out.push(t); });
  return out;
}
function toTimeline(src,secs){
  var c=src.clip, spd=c.speed||1, out=[];
  secs.forEach(function(t){ var tl=c.start+t/spd; if(tl>=c.start+.02&&tl<c.start+c.duration-.02) out.push(tl); });
  return out;
}
function cutTargets(src){
  var sel=selection().filter(function(x){ return x.clip!==src.clip&&x.track.kind!=="audio"&&x.clip.kind!=="adjustment"&&!x.track.locked; });
  if(sel.length) return sel;
  var tr=project.tracks.find(function(t){ return t.kind==="video"&&!t.locked&&t.clips.some(function(c){ return c.kind!=="adjustment"; }); });
  return tr?tr.clips.filter(function(c){ return c.kind!=="adjustment"; }).map(function(c){ return {track:tr,clip:c}; }):[];
}

/* ---------- actions ---------- */
function allBeatMarkers(){ return (project.markers||[]).filter(function(m){ return m.beat; }); }
function clearBeats(){
  var n=allBeatMarkers().length; if(!n){ say("There are no beat markers"); return 0; }
  transact("Clear beat markers",function(){ project.markers=(project.markers||[]).filter(function(m){ return !m.beat; }); });
  say(n+" beat marker"+(n===1?"":"s")+" removed"); return n;
}
function addBeatMarkers(src,secs,every){
  var times=toTimeline(src,secs); if(!times.length){ say("No beats fall inside this clip"); return 0; }
  if(times.length>1500){ say("That would be "+times.length+" markers: choose “every 2” or “every 4” beats"); return 0; }
  transact("Add beat markers",function(){
    project.markers=(project.markers||[]).filter(function(m){ return !m.beat; });
    times.forEach(function(t,j){
      var bar=(every>1||j%4===0)?String(every>1?j+1:Math.floor(j/4)+1):"";
      project.markers.push({id:mkid("marker"),time:t,label:"Beat "+(j+1),color:bar?"#ffb454":"#ff8040",beat:true,bar:bar});
    });
  });
  say(times.length+" beat marker"+(times.length===1?"":"s")+" added"); return times.length;
}
function cutToBeats(src,secs){
  var times=toTimeline(src,secs), targets=cutTargets(src);
  if(!window.amiyoCut||!window.amiyoCut.run){ say("The cut engine isn't available"); return 0; }
  if(!targets.length){ say("No video clips to cut: add or select the footage you want cut"); return 0; }
  if(!times.length){ say("No beats fall inside this clip"); return 0; }
  var ids=new Set(targets.map(function(x){ return x.clip.id; })), tracks=[]; targets.forEach(function(x){ if(tracks.indexOf(x.track)<0) tracks.push(x.track); });
  var n=window.amiyoCut.run("Cut to the beat",function(){
    var ctx=window.amiyoCut.newCtx(), cnt=0;
    times.slice().sort(function(a,b){ return b-a; }).forEach(function(t){
      tracks.forEach(function(tr){ tr.clips.slice().forEach(function(c){ if(ids.has(c.id)&&window.amiyoCut.cutOne(tr,c,t,ctx)) cnt++; }); });
    });
    window.amiyoCut.finish(ctx); return cnt;
  });
  say(n?"Cut on "+n+" beat"+(n===1?"":"s"):"Nothing to cut: no beat lands inside those clips"); return n;
}

/* ---------- dialog ---------- */
var st=document.createElement("style"); st.id="amiyo-beats-css";
st.textContent=".bd-big{font:700 34px/1.1 var(--font-mono,monospace);color:#fff}.bd-sub{font-size:12px;color:var(--muted);margin-top:4px;line-height:1.5}.bd-h{font-size:10px;color:var(--muted);margin:14px 0 6px;letter-spacing:.04em;text-transform:uppercase}"+
".bd-seg{display:flex;gap:6px;flex-wrap:wrap}.bd-seg .chip.on{background:var(--accent);border-color:var(--accent);color:#1a0c03;font-weight:700}.bd-note{font-size:11.5px;color:#ffd479;background:#2a2210;border:1px solid #5a4818;border-radius:8px;padding:7px 9px;margin-top:8px}"+
".bd-err{color:#ff91a0;font-size:12.5px;line-height:1.5}.bd-spin{display:inline-block;width:14px;height:14px;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:bdspin .8s linear infinite;vertical-align:-2px;margin-right:8px}@keyframes bdspin{to{transform:rotate(360deg)}}";
document.head.appendChild(st);

async function openDialog(src){
  src=src||pickSource();
  if(!src){ say("Select a music or video clip first (or put music on an audio track)"); return; }
  var S={src:src,res:null,err:"",busy:true,mult:1,every:1,start:0};
  openModal("Beat detection",'<div id="bdBody"></div>');
  var body=$("bdBody"); if(!body) return;
  function chips(attr,vals,cur,fmt){ return '<div class="bd-seg" role="group">'+vals.map(function(v){ return '<button type="button" class="chip'+(v===cur?" on":"")+'" '+attr+'="'+v+'" aria-pressed="'+(v===cur)+'">'+fmt(v)+'</button>'; }).join("")+'</div>'; }
  function draw(){
    var h='<div class="bd-sub" style="margin:0 0 10px">Listening to <b>'+esc(nameOf(S.src.clip))+'</b> · '+esc(S.src.track.name)+'</div>';
    if(S.busy) h+='<div><span class="bd-spin"></span>Finding the beat…</div><div class="bd-sub">Longer music takes a few seconds. Keep this window open.</div>';
    else if(S.err) h+='<div class="bd-err">'+esc(S.err)+'</div><div class="mini-row" style="margin-top:12px"><button class="chip" id="bdClose">Close</button></div>';
    else{
      var r=S.res, secs=gridFor(r,S), tl=toTimeline(S.src,secs), bpm=r.bpm*S.mult, tg=cutTargets(S.src);
      var q=r.conf>=2.2?"strong beat":r.conf>=1.5?"clear enough":"weak beat";
      h+='<div class="bd-big">≈ '+bpm.toFixed(1)+' <span style="font-size:14px;font-weight:500;color:var(--muted)">BPM</span></div>'+
         '<div class="bd-sub">'+r.beats.length+' beats found · '+q+(r.truncated?' · only the first 10 minutes were checked':'')+'</div>';
      if(r.conf<1.5) h+='<div class="bd-note">The beat is hard to hear here. Try ½× or 2×, or pick a part of the song with clear drums.</div>';
      h+='<div class="bd-h">Tempo feels like</div>'+chips("data-mult",[.5,1,2],S.mult,function(v){ return v===.5?"½× slower":v===2?"2× faster":"As found"; });
      h+='<div class="bd-h">Use every</div>'+chips("data-every",[1,2,4],S.every,function(v){ return v===1?"beat":v+" beats"; });
      h+='<div class="bd-h">Start on beat</div>'+chips("data-start",[0,1,2,3],S.start,function(v){ return String(v+1); });
      h+='<div class="bd-sub" style="margin-top:12px"><b>'+tl.length+'</b> beat'+(tl.length===1?"":"s")+' inside this clip'+(tg.length?' · cut would split <b>'+tg.length+'</b> clip'+(tg.length===1?"":"s")+' on “'+esc(tg[0].track.name)+'”':' · no footage to cut yet')+'</div>';
      var nb=allBeatMarkers().length;
      h+='<div class="mini-row" style="margin-top:12px"><button class="chip" id="bdMark" style="background:var(--accent);color:#1a0c03;font-weight:700"'+(tl.length?"":" disabled")+'>＋ Add beat markers</button><button class="chip" id="bdCut"'+(tl.length&&tg.length?"":" disabled")+'>✂ Cut video to the beat</button></div>'+
         '<div class="mini-row" style="margin-top:8px">'+(nb?'<button class="chip danger" id="bdClear">Clear '+nb+' beat marker'+(nb===1?"":"s")+'</button>':'')+'<button class="chip" id="bdClose">Close</button></div>';
    }
    body.innerHTML=h;
  }
  body.onclick=function(e){
    var t=e.target.closest("button"); if(!t) return;
    if(t.dataset.mult){ S.mult=parseFloat(t.dataset.mult); draw(); }
    else if(t.dataset.every){ S.every=parseInt(t.dataset.every,10); if(S.start>=S.every&&S.every>1) S.start=0; draw(); }
    else if(t.dataset.start){ S.start=parseInt(t.dataset.start,10); draw(); }
    else if(t.id==="bdClose") closeModal();
    else if(t.id==="bdMark"){ if(addBeatMarkers(S.src,gridFor(S.res,S),S.every)){ closeModal(); } }
    else if(t.id==="bdCut"){ if(cutToBeats(S.src,gridFor(S.res,S))) closeModal(); }
    else if(t.id==="bdClear"){ clearBeats(); draw(); }
  };
  draw();
  try{ S.res=await analyze(src.clip); }catch(e){ S.err=(e&&e.message)||"Couldn't analyze this clip."; }
  S.busy=false; if($("bdBody")===body) draw();
}

