    if(vx==null) vx=anchorX();
    if(t==null) t=(ts.scrollLeft+vx-labelW())/getTimelinePx();
    var from=timelineZoom;
    if(Math.abs(Math.log(target/from))<.002){ goal=null; setNow(target,vx,t); return; }
    var calm=false; try{ calm=matchMedia("(prefers-reduced-motion:reduce)").matches; }catch(e){window.__swl&&window.__swl(e)}
    if(instant||calm||amiyoClipCount()>80||__zc>9){ goal=null; setNow(target,vx,t); hud(); return; }   /* Pro step 1: when a rebuild is slow, jump instead of animating 9 rebuilds */
    var t0=performance.now(), D=150;
