  function lockAnchor(){ try{ var vx=anchorX(); __zl={vx:vx,t:(ts.scrollLeft+vx-labelW())/getTimelinePx()}; }catch(e){ __zl=null; } }
  function flushSlider(){ __zr=0; if(__zv==null) return; var v=__zv; __zv=null; if(__zl) zoomTo(v,__zl.vx,__zl.t,true); else zoomTo(v,null,null,true); }
