/* ==================== Script 230 id="amiyo-export8-step06-frame-name" ==================== */
/* Export plan 2026-11b, step 6 (still frame): one file name and one "is anything showing here?" check for every way of saving a frame (the Frame button and Ctrl+Shift+S, Ctrl+Shift+E and the Export dialog, Pr tools > Export frame).
   Before, the three named files three different ways (name-frame-00-05-250.png, name-frame-00-00-05-f08.png, Name_00-00-05-08.png) and the first and third turned a name in Bengali, Hindi, Arabic... into underscores. */
(function(){ "use strict";
  window.amiyoFrameFileName=function(ext,t){
    t=(typeof t==="number"&&isFinite(t))?t:(typeof currentTime==="number"?currentTime:0);
    var fps=(project.settings&&project.settings.fps)||30, s=Math.max(0,Math.floor(t)), fr=Math.min(Math.max(0,Math.round(fps)-1),Math.round((t-s)*fps));
    var tc=[Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(function(n){ return String(n).padStart(2,"0"); }).join("-")+"-f"+String(fr).padStart(2,"0");
    var nm=String((project.metadata&&project.metadata.name)||"amiyo-edit").replace(/[\\\/:*?"<>|\u0000-\u001f]+/g,"-").replace(/^[\s.]+|[\s.]+$/g,"").slice(0,100)||"amiyo-edit";
    return nm+"-frame-"+tc+"."+ext;
  };
  window.amiyoSomethingAtPlayhead=function(){
    var t=(typeof currentTime==="number")?currentTime:0;
    for(var i=0;i<project.tracks.length;i++){ var tr=project.tracks[i]; if(tr.kind==="audio"||tr.hidden) continue;
      for(var j=0;j<tr.clips.length;j++){ var c=tr.clips[j]; if(!c.off&&t>=c.start-1e-6&&t<c.start+c.duration-1e-6) return true; } }
    return false;
  };
})();

