/* export step 16: after saving, one plain report: loudness, loudest point, and a warning when the sound was too loud and got clipped */
function report(r){
  var db=function(v){ return v>1e-5?(20*Math.log10(v)).toFixed(1):"−∞"; }, h="";
  if(r.lufs!=null||r.peak>0) h+='<p style="margin:6px 0 0;font-size:12px;color:var(--muted)">'+(r.lufs!=null?'Loudness <b>'+r.lufs.toFixed(1)+' LUFS</b> · ':'')+'Loudest point <b>'+db(Math.min(r.peak,1))+' dBFS</b></p>';
  if(r.target&&r.missed) h+='<p style="margin:6px 0 0;font-size:12px;color:#ffd479">The sound is too quiet or too short to measure, so the loudness was not changed.</p>';
  else if(r.target&&r.limited==="boost"&&r.lufs!=null) h+='<p style="margin:6px 0 0;font-size:12px;color:#ffd479">This sound is very quiet. The most it can be raised is +24 dB, which gives '+r.lufs.toFixed(1)+' LUFS. Record or gain it up first.</p>';
  else if(r.target&&r.limited&&r.lufs!=null) h+='<p style="margin:6px 0 0;font-size:12px;color:#ffd479">The target is '+r.target+' LUFS but the loudest point stops this at '+r.lufs.toFixed(1)+' LUFS. A quieter, steadier mix can go louder.</p>';
  else if(r.target&&r.lufs!=null) h+='<p style="margin:6px 0 0;font-size:12px;color:#7fd18b">Reached the '+r.target+' LUFS target.</p>';
  if(r.clipped>0) h+='<p style="margin:6px 0 0;font-size:12px;color:#ff91a0">⚠ '+r.clipped.toLocaleString()+' sample'+(r.clipped===1?' was':'s were')+' too loud and got cut off, which can sound harsh. Lower the volume, or turn on “Make the loudest point −1 dB”.</p>';
  return h;
}
async function start(){
  if(job) return; job={cancel:false};
  $("wvOpts").hidden=true; $("wvProg").hidden=false;
  $("wvBtns").innerHTML='<button class="chip" id="wvStop">Cancel</button>';
  $("wvStop").onclick=function(){ if(job) job.cancel=true; $("wvTxt").textContent="Stopping…"; };
  var iv=setInterval(function(){ var bd=$("modalBackdrop"); if(job&&bd&&(bd.style.display==="none"||bd.style.display==="")) job.cancel=true; },300);
  function ui(t,p){ var a=$("wvTxt"), b=$("wvBar"); if(a) a.textContent=t; if(b) b.style.width=Math.round(clampv(p,0,1)*100)+"%"; }
  try{
    var res=await run(ui); clearInterval(iv); job=null; if(!$("wvDone")) return;
    download(res.blob); say("Audio saved: "+fname());
    var canShare=false, file=null; try{ file=new File([res.blob],fname(),{type:res.blob.type||"audio/wav"}); canShare=!!(navigator.canShare&&navigator.canShare({files:[file]})); }catch(e){window.__swl&&window.__swl(e)}
    $("wvProg").hidden=true; var d=$("wvDone"); d.hidden=false;
    d.innerHTML='<p style="margin:0 0 4px"><b>'+esc(fname())+'</b></p><p style="margin:0;font-size:12px;color:var(--muted)">'+mb(res.blob.size)+' · '+tc(res.dur)+(res.silent?' · '+res.silent+' clip'+(res.silent===1?'':'s')+' had no readable sound':'')+(Math.abs(res.gain-1)>.001?' · '+(res.gain>1?'raised':'lowered')+' by '+Math.abs(20*Math.log10(res.gain)).toFixed(1)+' dB':'')+'</p>'+report(res);
    $("wvBtns").innerHTML='<button class="chip" id="wvAgain" style="background:var(--accent);color:#1a0c03;font-weight:700">Save again</button>'+(canShare?'<button class="chip" id="wvShare">Share…</button>':'')+'<button class="chip" id="wvClose">Done</button>';
    $("wvAgain").onclick=function(){ download(res.blob); }; if($("wvShare")) $("wvShare").onclick=function(){ navigator.share({files:[file],title:fname()}).catch(function(){}); }; $("wvClose").onclick=function(){ closeModal(); };
  }catch(e){
    clearInterval(iv); var cancelled=job&&job.cancel; job=null;
    if(cancelled||(e&&e.message==="cancelled")){ say("Audio export cancelled"); try{ closeModal(); }catch(x){window.__swl&&window.__swl(x)} return; }
    if(!$("wvDone")){ say("Audio export failed: "+(e&&e.message||e)); return; }
    $("wvProg").hidden=true; $("wvDone").hidden=false; $("wvDone").innerHTML='<p style="margin:0;color:#ff91a0">'+esc(e&&e.message||"Something went wrong.")+'</p>';
    $("wvBtns").innerHTML='<button class="chip" id="wvBack" style="background:var(--accent);color:#1a0c03;font-weight:700">Back</button><button class="chip" id="wvClose">Close</button>';
    $("wvBack").onclick=open; $("wvClose").onclick=function(){ closeModal(); };
  }
}
