/* Step 53: Zoom to selected clip (Shift+Z) + shared helpers for the next steps */
(function(){try{
  var X=window.amiyoX=window.amiyoX||{};
  var shortcuts=X.shortcuts=X.shortcuts||[];
  X.sel=function(){ try{ var c=window.AMIYO_STUDIO_CORE; if(c&&c.selectedClips){ var l=c.selectedClips(); if(l&&l.length) return l; } }catch(e){window.__swl&&window.__swl(e)}
    var out=[]; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.id===selectedClipId||c.selected) out.push({track:t,clip:c}); }); }); return out; };
  X.say=function(m,t){ try{ toast(m,t||2800); }catch(e){window.__swl&&window.__swl(e)} };
  X.addShortcut=function(k,d){ for(var i=0;i<shortcuts.length;i++) if(shortcuts[i][0]===k) return; shortcuts.push([k,d]); };
  /* shortcut list shows up in the Keyboard Shortcuts window */
  if(!X._modalWrapped){ X._modalWrapped=true; var om=window.openModal;
    if(typeof om==="function") window.openModal=function(title,html){ var r=om.apply(this,arguments);
      try{ if(title==="Keyboard Shortcuts"&&shortcuts.length){ var b=document.getElementById("modalBody"); var d=document.createElement("div"); d.id="amiyoXKeys"; d.style.cssText="margin-top:6px";
        d.innerHTML='<div style="font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-bottom:6px">More shortcuts</div><div class="codebox" style="white-space:normal">'+shortcuts.map(function(r){ return '<div style="display:flex;justify-content:space-between;gap:10px;padding:3px 0;border-bottom:1px solid var(--line)"><span>'+r[1]+'</span><span style="color:var(--accent);font-family:ui-monospace,monospace">'+r[0]+'</span></div>'; }).join("")+'</div>'; b.appendChild(d); } }catch(e){window.__swl&&window.__swl(e)}
      return r; };
  }
  /* ---- Zoom to selected clip ---- */
  X.zoomToClip=function(){
    var l=X.sel(); if(!l.length) return X.say("Select a clip on the timeline first");
    var s=Infinity,e=0; l.forEach(function(x){ s=Math.min(s,x.clip.start); e=Math.max(e,x.clip.start+x.clip.duration); });
    var dur=Math.max(0.05,e-s), ts=document.getElementById("timelineScroll"); if(!ts) return;
    var avail=Math.max(200,ts.clientWidth-labelW()-40), pps=avail*0.9/dur;
    var z=Math.round(Math.min(AZ_MAX,Math.max(AZ_MIN,pps/6.4*100)));
    timelineZoom=z; var zs=document.getElementById("timelineZoom"); if(zs) zs.value=z;
    renderTimeline();
    ts.scrollLeft=Math.max(0,timeToPx(s)-avail*0.05);
    X.say("Zoomed to "+(l.length>1?l.length+" clips":"the clip")+" ("+dur.toFixed(2)+" s)");
  };
  X.addShortcut("Shift+Z","Zoom timeline to the selected clip");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey) return;
    if(ev.shiftKey&&ev.code==="KeyZ"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.zoomToClip(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Zoom timeline to selected clip","amiyoX.zoomToClip()"]]); };
  window.AMIYO_EDITOR_BUILD="step53-zoomclip";
}catch(e){console.warn("step53",e)}})();

