/* Step 54: Play selected clip only (Shift+P) - plays through the clip and stops at its end */
(function(){try{
  var X=window.amiyoX; if(!X) return; var iv=null;
  function stop(){ if(iv){ clearInterval(iv); iv=null; } }
  X.playClip=function(){
    if(iv){ stop(); try{ pause(); }catch(e){window.__swl&&window.__swl(e)} return X.say("Stopped"); }
    var l=X.sel(); if(!l.length) return X.say("Select a clip on the timeline first");
    var s=Infinity,e=0; l.forEach(function(x){ s=Math.min(s,x.clip.start); e=Math.max(e,x.clip.start+x.clip.duration); });
    try{ pause(); }catch(er){window.__swl&&window.__swl(er)}
    setCurrentTime(s);
    setTimeout(function(){
      play();
      X.say("Playing the clip - Shift+P again to stop",1800);
      iv=setInterval(function(){
        if(!isPlaying){ stop(); return; }
        if(currentTime>=e-0.02){ stop(); pause(); setCurrentTime(e); }
      },30);
    },60);
  };
  X.addShortcut("Shift+P","Play the selected clip only (press again to stop)");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey) return;
    if(ev.shiftKey&&ev.code==="KeyP"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.playClip(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Play selected clip only","amiyoX.playClip()"]]); };
  window.AMIYO_EDITOR_BUILD="step54-playclip";
}catch(e){console.warn("step54",e)}})();

