/* ==================== Script 236 id="amiyo-step56" ==================== */
/* Step 56: Select all clips to the right / left of the playhead (Shift+. and Shift+,) */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  X.selectSide=function(dir){
    var t0=currentTime, hit=[];
    project.tracks.forEach(function(t){ if(t.locked) return; t.clips.forEach(function(c){ var s=c.start,e=c.start+c.duration;
      if(dir>0?(e>t0+0.001):(s<t0-0.001)) hit.push({t:t,c:c}); }); });
    project.tracks.forEach(function(t){ t.clips.forEach(function(c){ c.selected=false; }); });
    if(!hit.length){ selectedClipId=null; renderAll(); return X.say(dir>0?"No clips after the playhead":"No clips before the playhead"); }
    hit.forEach(function(h){ h.c.selected=true; });
    hit.sort(function(a,b){ return a.c.start-b.c.start; });
    selectedClipId=hit[0].c.id; try{ selectedTrackId=hit[0].t.id; }catch(e){window.__swl&&window.__swl(e)}
    renderAll(); X.say(hit.length+" clip"+(hit.length>1?"s":"")+" selected "+(dir>0?"to the right of":"to the left of")+" the playhead");
  };
  X.addShortcut("Shift+.","Select every clip from the playhead to the right");
  X.addShortcut("Shift+,","Select every clip up to the playhead (left)");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey||!ev.shiftKey) return;
    if(ev.code==="Period"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.selectSide(1); }
    else if(ev.code==="Comma"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.selectSide(-1); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Select clips right of playhead","amiyoX.selectSide(1)"],["Select clips left of playhead","amiyoX.selectSide(-1)"]]); };
  window.AMIYO_EDITOR_BUILD="step56-selectside";
}catch(e){console.warn("step56",e)}})();

