  function say(t){ var e=$("gifInfo"); if(e) e.textContent=t; }
  function show(id,on){ var e=$(id); if(e) e.style.display=on?"":"none"; }
  function setBar(v){ var e=$("gifBar"); if(e) e.style.width=v; }
  /* export step 17: closing the dialog while the GIF is being made now stops it (before, it kept working out of sight and the playhead jumped around with no way to cancel) */
