/* ==================== Script 241 id="amiyo-step61" ==================== */
/* Step 61: Voice enhance - EQ (clean-up, presence, air) + compressor, per audio clip, live in playback, export and WAV */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var LEVELS={1:{name:"Light",hp:70,mud:-1.5,pres:2,air:1,th:-20,ratio:2,make:1.5},2:{name:"Standard",hp:80,mud:-2.5,pres:3.5,air:2,th:-24,ratio:3,make:3},3:{name:"Strong",hp:100,mud:-3.5,pres:5,air:3,th:-28,ratio:4.5,make:5}};
  X.voiceLevels=LEVELS;
  /* build the chain in any (real or offline) context: returns {input,output,nodes} */
  X.voiceChain=function(ctx,level){
    var L=LEVELS[level]||LEVELS[2], n=[];
    function bq(type,f,q,g){ var b=ctx.createBiquadFilter(); b.type=type; b.frequency.value=f; if(q!=null) b.Q.value=q; if(g!=null) b.gain.value=g; n.push(b); return b; }
    var hp=bq("highpass",L.hp,0.7), mud=bq("peaking",250,1,L.mud), pres=bq("peaking",3200,1,L.pres), air=bq("highshelf",9000,null,L.air);
    var comp=ctx.createDynamicsCompressor(); comp.threshold.value=L.th; comp.knee.value=18; comp.ratio.value=L.ratio; comp.attack.value=0.006; comp.release.value=0.16; n.push(comp);
    var mk=ctx.createGain(); mk.gain.value=Math.pow(10,L.make/20); n.push(mk);
    hp.connect(mud); mud.connect(pres); pres.connect(air); air.connect(comp); comp.connect(mk);
    return {input:hp,output:mk,nodes:n};
  };
  function allClips(){ var o=[]; project.tracks.forEach(function(t){ if(t.kind==="audio") t.clips.forEach(function(c){ o.push(c); }); }); return o; }
  var live=new Map();   /* clipId -> {level,chain} */
  function teardown(id){ var r=live.get(id); if(!r) return; try{ r.chain.nodes.forEach(function(n){ try{ n.disconnect(); }catch(e){window.__swl&&window.__swl(e)} }); }catch(e){window.__swl&&window.__swl(e)} live.delete(id); }
  function sync(c){
    try{
      var p=trackPanners.get(c.id); if(!p) return; var want=c.voiceFx||0, r=live.get(c.id);
      if((r?r.level:0)===want) return;
      var ac=p.context; teardown(c.id); p.disconnect();
      if(want){ var ch=X.voiceChain(ac,want); p.connect(ch.input); ch.output.connect(ac.destination); if(typeof audioDestination!=="undefined"&&audioDestination) ch.output.connect(audioDestination); live.set(c.id,{level:want,chain:ch}); }
      else{ p.connect(ac.destination); if(typeof audioDestination!=="undefined"&&audioDestination) p.connect(audioDestination); }
    }catch(e){ console.warn("voice sync",e); }
  }
  X._voiceLive=live;
  var prevEnsure=window.ensureAudioElement;
  window.ensureAudioElement=async function(clip){ var el=await prevEnsure.apply(this,arguments); if(el&&clip&&clip.voiceFx) sync(clip); return el; };
  var prevUAP=window.updateAudioPlayback;
  window.updateAudioPlayback=async function(){ var r=await prevUAP.apply(this,arguments); allClips().forEach(function(c){ if(c.voiceFx||live.has(c.id)) sync(c); }); return r; };
  X.syncVoice=function(){ allClips().forEach(sync); };

  X.setVoice=async function(level){
    var l=X.sel(); if(!l.length) return X.say("Select an audio clip (or a video clip with sound) first");
    var targets=[], detached=0;
    for(var i=0;i<l.length;i++){ var x=l[i], c=x.clip;
      if(x.track.kind==="audio"){ targets.push(c.id); continue; }
      var a=project.assets&&project.assets[c.assetId];
      if(x.track.kind==="video"&&a&&a.type==="video"){
        if(!c.audioDetached&&typeof window.amiyoDetachAudio==="function"){ selectedClipId=c.id; project.tracks.forEach(function(t){ t.clips.forEach(function(k){ k.selected=(k.id===c.id); }); }); window.amiyoDetachAudio(); detached++; var n=X.sel(); if(n.length&&n[0].track.kind==="audio") targets.push(n[0].clip.id); }
        else if(c.audioDetached) targets.push(c.audioDetached);
      }
    }
    if(!targets.length) return X.say("Voice enhance works on audio clips and on videos that have sound");
    window.transact(level?"Voice enhance: "+LEVELS[level].name:"Voice enhance off",function(){ allClips().forEach(function(c){ if(targets.indexOf(c.id)>=0){ if(level) c.voiceFx=level; else delete c.voiceFx; } }); });
    for(var j=0;j<targets.length;j++){ var cc=allClips().filter(function(k){ return k.id===targets[j]; })[0]; if(cc){ try{ await ensureAudioElement(cc); }catch(e){window.__swl&&window.__swl(e)} sync(cc); } }
    try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)} decorate();
    X.say(level?("Voice enhance "+LEVELS[level].name+" on "+targets.length+" clip"+(targets.length>1?"s":"")+(detached?" (sound split from video)":"")):"Voice enhance off",2200);
  };
  X.voiceDialog=function(){
    var l=X.sel(); if(!l.length) return X.say("Select an audio clip (or a video clip with sound) first");
    var cur=0; var f=l[0]; if(f.track.kind==="audio") cur=f.clip.voiceFx||0;
    function chip(v,t){ return '<button type="button" class="chip" data-vf="'+v+'" style="'+(v===cur?"outline:2px solid var(--accent)":"")+'">'+t+'</button>'; }
    openModal("Voice enhance",'<div style="font-size:12px;color:var(--muted);margin-bottom:10px;line-height:1.45">Cleans up speech: removes low rumble and boominess, adds clarity and brightness, and evens out loud and quiet words with a compressor. It plays live, and it is included in your video export and the audio-only WAV.</div>'
      +'<div class="mini-row">'+chip(0,"Off")+chip(1,"Light")+chip(2,"Standard")+chip(3,"Strong")+'</div>'
      +'<div id="vfNote" style="font-size:11.5px;color:var(--muted);margin:10px 0">'+(f.track.kind==="audio"?"":"This clip is a video: its sound will be split onto its own audio track first (Undo puts it back).")+'</div>'
      +'<div class="mini-row"><button class="chip" id="vfHear" type="button" style="background:var(--accent);color:#1a0c03;font-weight:700">Close and listen</button></div>');
    document.querySelectorAll("[data-vf]").forEach(function(b){ b.onclick=async function(){ await X.setVoice(Number(b.dataset.vf)); document.querySelectorAll("[data-vf]").forEach(function(o){ o.style.outline=(o===b)?"2px solid var(--accent)":"none"; }); }; });
    document.getElementById("vfHear").onclick=function(){ closeModal(); setTimeout(function(){ if(X.playClip) X.playClip(); },80); };
  };
  /* timeline badge */
  var css=document.createElement("style"); css.textContent=".clip .x-voice{position:absolute;left:4px;top:3px;font-size:10px;line-height:14px;padding:0 4px;border-radius:5px;background:rgba(0,0,0,.6);border:1px solid rgba(255,165,120,.55);z-index:3;pointer-events:none}"; document.head.appendChild(css);
  var busy=false,q=0;
  function decorate(){ q=0; busy=true; try{ var tr=document.getElementById("tracks"); if(!tr){ busy=false; return; } var map={}; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ map[c.id]=c; }); });
    tr.querySelectorAll(".clip[data-clip]").forEach(function(el){ var c=map[el.dataset.clip], b=el.querySelector(".x-voice");
      if(c&&c.voiceFx){ if(!b){ b=document.createElement("span"); b.className="x-voice"; el.appendChild(b); } var t="🎙 "+LEVELS[c.voiceFx].name; if(b.textContent!==t) b.textContent=t; } else if(b) b.remove(); }); }catch(e){window.__swl&&window.__swl(e)} busy=false; }
  var trk=document.getElementById("tracks"); if(trk) new MutationObserver(function(){ if(busy||q) return; q=requestAnimationFrame(decorate); }).observe(trk,{childList:true,subtree:true}); decorate();
  X.addShortcut("Shift+E","Voice enhance (EQ + compressor) for the selected clip");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey) return;
    if(ev.shiftKey&&ev.code==="KeyE"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.voiceDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Voice enhance…","amiyoX.voiceDialog()"],["Voice enhance: Standard","amiyoX.setVoice(2)"],["Voice enhance: off","amiyoX.setVoice(0)"]]); };
  window.AMIYO_EDITOR_BUILD="step61-voice";
}catch(e){console.warn("step61",e)}})();

