/* ==================== Script 243 id="amiyo-step63" ==================== */
/* Step 63: Command palette that works - fuzzy search, Up/Down + Enter, shortcut hints, recent commands, and every step's commands included */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var KEYS={"split selected clip":"S","delete selected clips":"Del","ripple delete":"Shift+Del","duplicate selected clips":"Ctrl+D","add marker":"M","project inspector":"","toggle safe zones":"",
    "split all tracks at playhead":"Shift+S","ripple delete before playhead":"Shift+Q","ripple delete after playhead":"Shift+W","zoom timeline to selected clip":"Shift+Z","play selected clip only":"Shift+P",
    "add / edit clip note":"Shift+N","select clips right of playhead":"Shift+.","select clips left of playhead":"Shift+,","copy playhead timecode":"Shift+C","voice enhance…":"Shift+E","colour label…":"Shift+L","select clips by colour label…":"Shift+L","export as gif…":""};
  X.cmdKeys=KEYS; X.cmdKey=function(label,keys){ KEYS[String(label).toLowerCase()]=keys; };
  var RKEY="amiyo.palette.recent.v1";
  function lsGet(){ try{ var a=JSON.parse(localStorage.getItem(RKEY)||"[]"); return Array.isArray(a)?a:[]; }catch(e){ return []; } }
  function lsSet(a){ try{ localStorage.setItem(RKEY,JSON.stringify(a.slice(0,8))); }catch(e){window.__swl&&window.__swl(e)} }
  function esc(s){ return String(s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  /* run a command string like  name()  name("x")  obj.method()  obj.method(2)  -  never evaluates code */
  var RE=/^\s*([A-Za-z_$][\w$]*)(?:\.([A-Za-z_$][\w$]*))?\(\s*(?:'([^']*)'|"([^"]*)"|(-?\d+(?:\.\d+)?)|(true|false))?\s*\)\s*;?\s*$/;
  X.runCommandString=function(s){
    var m=RE.exec(String(s)); if(!m) throw new Error("Unknown command");
    var root=window[m[1]], fn=m[2]?(root&&root[m[2]]):root, self=m[2]?root:window;
    if(typeof fn!=="function") throw new Error("Command not available: "+m[1]+(m[2]?"."+m[2]:""));
    var arg=m[3]!==undefined?m[3]:m[4]!==undefined?m[4]:m[5]!==undefined?Number(m[5]):m[6]!==undefined?(m[6]==="true"):undefined;
    return arg!==undefined?fn.call(self,arg):fn.call(self);
  };
  function cmds(){
    var raw=[]; try{ raw=window.commandList()||[]; }catch(e){window.__swl&&window.__swl(e)}
    var seen={}, out=[]; raw.forEach(function(c){ if(!c||!c[0]||!c[1]) return; var k=String(c[0]).toLowerCase(); if(seen[k]) return; seen[k]=1; out.push({name:String(c[0]),run:String(c[1]),key:KEYS[k]||""}); });
    return out;
  }
  X.paletteCommands=cmds;
  /* score: every word must match; word-start beats substring beats scattered letters */
  function score(name,q){
    if(!q) return 1; var n=name.toLowerCase(), total=0, toks=q.toLowerCase().split(/\s+/).filter(Boolean);
    for(var i=0;i<toks.length;i++){ var t=toks[i], p=n.indexOf(t), s=0;
      if(p>=0){ s=(p===0||/[\s\-—:/(…]/.test(n.charAt(p-1)))?6:3; }
      else{ var j=0; for(var k=0;k<n.length&&j<t.length;k++) if(n.charAt(k)===t.charAt(j)) j++; if(j===t.length) s=1; else return 0; }
      total+=s; }
    return total-name.length/200;
  }
  function hl(name,q){
    var h=esc(name); if(!q) return h; var toks=q.toLowerCase().split(/\s+/).filter(Boolean), low=name.toLowerCase(), mark=new Array(name.length);
    toks.forEach(function(t){ var p=low.indexOf(t); if(p>=0) for(var i=p;i<p+t.length;i++) mark[i]=1; });
    var o="", on=false; for(var i=0;i<name.length;i++){ var ch=esc(name.charAt(i)); if(mark[i]&&!on){ o+="<mark>"; on=true; } if(!mark[i]&&on){ o+="</mark>"; on=false; } o+=ch; } if(on) o+="</mark>"; return o;
  }
  var css=document.createElement("style");
  css.textContent="#xpWrap{display:flex;flex-direction:column;gap:8px}#xpIn{width:100%;box-sizing:border-box;min-height:44px;font-size:16px}"
   +"#xpList{max-height:min(52vh,420px);overflow:auto;display:flex;flex-direction:column;gap:4px;overscroll-behavior:contain}"
   +"#xpList .xp-h{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);padding:6px 4px 2px}"
   +"#xpList button.xp{display:flex;align-items:center;justify-content:space-between;gap:10px;text-align:left;width:100%;min-height:44px;padding:8px 12px;border-radius:9px;border:1px solid var(--line);background:#12161b;color:var(--text,#fff);cursor:pointer;font:13px system-ui}"
   +"#xpList button.xp[aria-selected=true]{border-color:var(--accent);background:#2a1a0f;box-shadow:inset 3px 0 0 var(--accent)}#xpList mark{background:rgba(255,184,84,.32);color:inherit;border-radius:3px;padding:0 1px}"
   +"#xpList kbd,#xpFoot kbd{font:600 11px ui-monospace,monospace;padding:2px 6px;border-radius:5px;background:#0b0e12;border:1px solid var(--line);color:var(--accent);white-space:nowrap}#xpFoot{font-size:11px;color:var(--muted);display:flex;gap:10px;flex-wrap:wrap;align-items:center}";
  document.head.appendChild(css);
  window.openCommandPalette=function(){
    var all=cmds(), act=0, shown=[];
    openModal("Command palette",'<div id="xpWrap"><input id="xpIn" type="search" class="search" autocomplete="off" spellcheck="false" placeholder="Type to find a command (e.g. split, label, gif)…" role="combobox" aria-expanded="true" aria-controls="xpList" aria-label="Search commands"><div id="xpList" role="listbox" aria-label="Commands"></div>'
      +'<div id="xpFoot"><span><kbd>↑</kbd> <kbd>↓</kbd> move</span><span><kbd>Enter</kbd> run</span><span><kbd>Esc</kbd> close</span><span id="xpCount" style="margin-left:auto"></span></div></div>');
    var inp=document.getElementById("xpIn"), list=document.getElementById("xpList"), cnt=document.getElementById("xpCount");
    function row(c,q,i){ return '<button type="button" class="xp" role="option" id="xp'+i+'" data-i="'+i+'" aria-selected="'+(i===act)+'"><span>'+hl(c.name,q)+'</span>'+(c.key?'<kbd>'+esc(c.key)+'</kbd>':'')+'</button>'; }
    function render(){
      var q=inp.value.trim(), html="", i=0; shown=[];
      if(!q){
        var rec=lsGet().map(function(n){ return all.filter(function(c){ return c.name===n; })[0]; }).filter(Boolean);
        if(rec.length){ html+='<div class="xp-h">Recent</div>'; rec.forEach(function(c){ shown.push(c); html+=row(c,"",i++); }); html+='<div class="xp-h">All commands</div>'; }
        all.forEach(function(c){ shown.push(c); html+=row(c,"",i++); });
      } else {
        all.map(function(c){ return {c:c,s:score(c.name,q)}; }).filter(function(x){ return x.s>0; }).sort(function(a,b){ return b.s-a.s; }).forEach(function(x){ shown.push(x.c); html+=row(x.c,q,i++); });
      }
      if(act>=shown.length) act=Math.max(0,shown.length-1);
      list.innerHTML=html||'<div style="color:var(--muted);font-size:12.5px;padding:10px">No command matches “'+esc(q)+'”. Try a shorter word.</div>';
      cnt.textContent=shown.length+" command"+(shown.length===1?"":"s"); paint(false);
    }
    function paint(scroll){
      var bs=list.querySelectorAll("button.xp"); for(var i=0;i<bs.length;i++) bs[i].setAttribute("aria-selected",String(i===act));
      if(bs[act]){ inp.setAttribute("aria-activedescendant",bs[act].id); if(scroll) bs[act].scrollIntoView({block:"nearest"}); } else inp.removeAttribute("aria-activedescendant");
    }
    function go(i){ var c=shown[i]; if(!c) return; var r=lsGet().filter(function(n){ return n!==c.name; }); r.unshift(c.name); lsSet(r);
      closeModal(); setTimeout(function(){ try{ Promise.resolve(X.runCommandString(c.run)).catch(function(e){ X.say((e&&e.message)||"Command failed"); }); }catch(e){ X.say((e&&e.message)||"Command failed"); } },40); }
    inp.addEventListener("input",function(){ act=0; render(); list.scrollTop=0; });
    inp.addEventListener("keydown",function(e){
      var k=e.key;
      if(k==="ArrowDown"){ e.preventDefault(); if(shown.length){ act=(act+1)%shown.length; paint(true); } }
      else if(k==="ArrowUp"){ e.preventDefault(); if(shown.length){ act=act<=0?shown.length-1:act-1; paint(true); } }
      else if(k==="PageDown"){ e.preventDefault(); act=Math.min(shown.length-1,act+6); paint(true); }
      else if(k==="PageUp"){ e.preventDefault(); act=Math.max(0,act-6); paint(true); }
      else if(k==="Enter"){ e.preventDefault(); go(act); }
      e.stopPropagation();
    });
    list.addEventListener("click",function(e){ var b=e.target.closest("button.xp"); if(b) go(+b.dataset.i); });
    list.addEventListener("mousemove",function(e){ var b=e.target.closest("button.xp"); if(b&&+b.dataset.i!==act){ act=+b.dataset.i; paint(false); } });
    render(); inp.focus();
  };
  X.addShortcut("Ctrl+K","Command palette: search and run any command (↑ ↓ Enter)");
  window.AMIYO_EDITOR_BUILD="step63-palette";
}catch(e){console.warn("step63",e)}})();

