    var L=["Project: "+S.name,"Size: "+S.w+" × "+S.h+" at "+S.fps+" fps","Length: "+tc(S.end)+" ("+S.end.toFixed(1)+" s)","Clips: "+S.clips+" ("+Object.keys(S.kinds).map(function(k){ return S.kinds[k]+" "+k; }).join(", ")+")","Tracks:"];
    S.tracks.forEach(function(r){ L.push("  "+(r.t.name||r.t.kind)+" — "+r.n+" clip"+(r.n===1?"":"s")+", "+tc(r.cov)+" used"+(r.t.locked?" (locked)":"")); });
    L.push("Media: "+S.assets+" file"+(S.assets===1?"":"s")+", "+mb(S.size)+(S.unused?", "+S.unused+" unused":"")+(S.missing?", "+S.missing+" missing":""),"Markers: "+S.markers+" · Notes: "+S.notes);
