/* ==================== Script 250 id="amiyo-step70" ==================== */
/* Step 70: Arrange clips (Shift+A) - line the selected clips up end to end (slideshows), optionally with one duration for every picture/title, a gap, and ordering by timeline or name */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function nm(c){ var a=project.assets&&project.assets[c.assetId]; return c.name||(a&&a.name)||c.text||""; }
  function stillish(c,t){ var a=project.assets&&project.assets[c.assetId]; return c.kind==="image"||c.kind==="text"||c.kind==="caption"||(a&&a.type==="image")||(!c.assetId&&t.kind!=="audio"); }
  function picked(){ var l=X.sel(); return l; }
  X.arrangeClips=function(o){
    var l=picked(); if(l.length<2) return X.say("Select two or more clips on the same track first");
    var tr=l[0].track; if(!l.every(function(x){ return x.track===tr; })) return X.say("Select clips from one track only. Arranging across tracks would break the sync");
    if(tr.locked) return X.say("That track is locked. Unlock it first");
    var items=l.map(function(x){ return x.clip; }), sel={}; items.forEach(function(c){ sel[c.id]=1; });
    var oldStart=Math.min.apply(null,items.map(function(c){ return c.start; })), oldEnd=Math.max.apply(null,items.map(function(c){ return c.start+c.duration; }));
    items.sort(o.order==="name"?function(a,b){ return nm(a).localeCompare(nm(b),undefined,{numeric:true}); }:function(a,b){ return a.start-b.start; });
    var gap=Math.max(0,Math.min(30,+o.gap||0)), dur=o.setDur?Math.max(0.2,Math.min(120,+o.dur||3)):0;
    window.transact("Arrange "+items.length+" clips",function(){
      var t=oldStart; items.forEach(function(c){ if(dur&&stillish(c,tr)) c.duration=dur; c.start=r3(t); t+=c.duration+gap; });
      var newEnd=t-gap, delta=newEnd-oldEnd;
      if(o.ripple&&Math.abs(delta)>0.0005) tr.clips.forEach(function(k){ if(!sel[k.id]&&k.start>=oldEnd-0.001) k.start=Math.max(0,r3(k.start+delta)); });
      tr.clips.sort(function(a,b){ return a.start-b.start; });
    });
    X.say(items.length+" clips lined up"+(dur?", pictures and titles "+dur+" s each":""),2600);
  };
  X.arrangeDialog=function(){
    var l=picked(); if(l.length<2) return X.say("Select two or more clips on the same track first");
    var tr=l[0].track; if(!l.every(function(x){ return x.track===tr; })) return X.say("Select clips from one track only. Arranging across tracks would break the sync",3400);
    var still=l.filter(function(x){ return stillish(x.clip,tr); }).length, between=0, a0=Math.min.apply(null,l.map(function(x){ return x.clip.start; })), a1=Math.max.apply(null,l.map(function(x){ return x.clip.start+x.clip.duration; })), ids={}; l.forEach(function(x){ ids[x.clip.id]=1; });
    tr.clips.forEach(function(k){ if(!ids[k.id]&&k.start<a1&&k.start+k.duration>a0) between++; });
    openModal("Arrange clips",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">Lines up the '+l.length+' selected clips one after another starting where the first one begins. Good for photo slideshows.</div>'
      +'<div style="display:flex;gap:6px;margin-bottom:10px"><label style="flex:1;display:flex;gap:6px;align-items:center;font-size:13px"><input type="radio" name="xao" value="time" checked style="width:20px;height:20px"> Keep timeline order</label><label style="flex:1;display:flex;gap:6px;align-items:center;font-size:13px"><input type="radio" name="xao" value="name" style="width:20px;height:20px"> Sort by name</label></div>'
      +'<label style="display:flex;gap:8px;align-items:center;font-size:13px;margin:8px 0"><input id="xaSet" type="checkbox" '+(still?'checked':'disabled')+' style="width:20px;height:20px"> Show each picture / title for</label>'
      +'<input id="xaDur" type="number" min="0.2" max="120" step="0.1" value="3" inputmode="decimal" aria-label="Seconds per picture or title" style="min-height:44px;font-size:16px"'+(still?'':' disabled')+'><div style="font-size:11px;color:var(--muted);margin:3px 0 8px">seconds ('+still+' of '+l.length+' clips are pictures or titles; video and audio keep their own length)</div>'
      +'<label class="field" for="xaGap">Gap between clips (seconds)</label><input id="xaGap" type="number" min="0" max="30" step="0.1" value="0" inputmode="decimal" style="min-height:44px;font-size:16px">'
      +'<label style="display:flex;gap:8px;align-items:center;margin:12px 0 4px;font-size:13px"><input id="xaRip" type="checkbox" checked style="width:20px;height:20px"> Move later clips on this track along</label>'
      +(between?'<div style="font-size:11.5px;color:#ffb454;margin:6px 0">'+between+' other clip'+(between>1?'s sit':' sits')+' in between; they stay where they are.</div>':'')
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px"><button class="topbtn" id="xaNo" type="button">Cancel</button><button class="topbtn primary" id="xaGo" type="button">Arrange</button></div>');
    function go(){ var o={order:(document.querySelector('input[name=xao]:checked')||{}).value,setDur:document.getElementById("xaSet").checked,dur:document.getElementById("xaDur").value,gap:document.getElementById("xaGap").value,ripple:document.getElementById("xaRip").checked}; closeModal(); X.arrangeClips(o); }
    document.getElementById("xaGo").onclick=go; document.getElementById("xaNo").onclick=closeModal;
    ["xaDur","xaGap"].forEach(function(id){ document.getElementById(id).addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); }); });
  };
  X.addShortcut("Shift+A","Arrange selected clips end to end (slideshow)");
  X.cmdKey&&X.cmdKey("Arrange clips end to end…","Shift+A");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey) return;
    if(ev.shiftKey&&ev.code==="KeyA"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.arrangeDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Arrange clips end to end…","amiyoX.arrangeDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step70-arrange";
}catch(e){console.warn("step70",e)}})();

