/* ==================== Script 251 id="amiyo-step71" ==================== */
/* Step 71: Copy / paste clip attributes - copy the look, position, sound or animation of one clip and paste it onto others.
   Shift+K opens the window; Ctrl+Alt+C copies, Ctrl+Alt+V pastes everything ticked. One Undo step per paste. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var GROUPS=[
    {id:"pic",name:"Picture",desc:"filter, effects, colour, LUT, crop, chroma key",keys:["filter","filterAmt","opacity","effects","lut","cgLook","look","colorWheels","chromaKey","crop","trackMatte"],visual:true},
    {id:"pos",name:"Position and size",desc:"x, y, scale, rotation, fit, flip",keys:["x","y","scale","rotation","fit","flipX","flipY"],visual:true},
    {id:"snd",name:"Sound",desc:"volume, fades, voice enhance, equalizer, volume keyframes",keys:["volume","fadeIn","fadeOut","voiceFx","eqFx","deessFx","cleanFx","roomFx","volumeKeyframes","soundCategory"],sound:true},
    {id:"anim",name:"Animation",desc:"keyframes and animation preset",keys:["keyframes","anim"],visual:true}
  ];
  var on={pic:true,pos:true,snd:true,anim:true};
  var copied=null;                                   /* {name, kind, data:{key:value|undefined}} */
  X.attrGroups=GROUPS;
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  function clone(v){ return v===undefined?undefined:JSON.parse(JSON.stringify(v)); }
  function nameOf(x){ var c=x.clip, a=project.assets&&project.assets[c.assetId]; return String(c.name||(a&&a.name)||c.text||c.kind||"Clip").slice(0,40); }
  function first(list){ return list.slice().sort(function(a,b){ return a.clip.start-b.clip.start; })[0]; }
  X.copyAttrs=function(quiet){
    var l=X.sel(); if(!l.length){ X.say("Select the clip to copy from"); return false; }
    var f=first(l), data={};
    GROUPS.forEach(function(g){ g.keys.forEach(function(k){ data[k]=clone(f.clip[k]); }); });
    copied={name:nameOf(f),kind:f.track.kind,data:data};
    if(!quiet) X.say("Copied attributes from “"+copied.name+"”"+(l.length>1?" (the first of "+l.length+" selected)":""),2400);
    return true;
  };
  function applicable(g,x){ var k=x.track.kind; if(g.sound) return k==="audio"||k==="video"; return k!=="audio"&&k!=="caption"; }
  X.pasteAttrs=function(){
    if(!copied){ X.say("Copy attributes from a clip first (Ctrl+Alt+C)"); return 0; }
    var l=X.sel().filter(function(x){ return !x.track.locked; }); if(!l.length){ X.say("Select the clips to paste onto (locked tracks are skipped)"); return 0; }
    var groups=GROUPS.filter(function(g){ return on[g.id]; }); if(!groups.length){ X.say("Tick at least one thing to paste"); return 0; }
    var ids={}; l.forEach(function(x){ ids[x.clip.id]={track:x.track.kind}; });
    var changed=0, skipped=0;
    window.transact("Paste attributes",function(){
      project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(!ids[c.id]) return; var did=false;
        groups.forEach(function(g){ if(!applicable(g,{track:t,clip:c})) return;
          g.keys.forEach(function(k){ var v=copied.data[k];
            if(v===undefined){ if(k in c){ delete c[k]; did=true; } }
            else if(JSON.stringify(c[k])!==JSON.stringify(v)){ c[k]=clone(v); did=true; } }); });
        if(did) changed++; else skipped++; }); });
    });
    try{ if(window.amiyoInvalidateInspector) window.amiyoInvalidateInspector(); }catch(e){window.__swl&&window.__swl(e)}
    try{ if(X.syncVoice) X.syncVoice(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(changed?("Pasted onto "+changed+" clip"+(changed>1?"s":"")+(skipped?" ("+skipped+" already matched or did not apply)":"")):"Nothing changed — those clips already match, or the ticked groups do not apply to them",2600);
    return changed;
  };
  X.attrDialog=function(){
    var l=X.sel(), n=l.length;
    function render(){
      var rows=GROUPS.map(function(g){ return '<label style="display:flex;align-items:flex-start;gap:10px;min-height:44px;padding:6px 4px;border-bottom:1px solid var(--line)"><input type="checkbox" data-ag="'+g.id+'" '+(on[g.id]?"checked":"")+' style="margin-top:3px"><span><b style="font-size:13px">'+g.name+'</b><br><span style="font-size:11px;color:var(--muted)">'+g.desc+'</span></span></label>'; }).join("");
      var body='<div style="font-size:12px;color:var(--muted);margin-bottom:8px;line-height:1.45">Copy how one clip looks and sounds, then paste it onto other clips. Timing and the picture or audio itself are never changed.</div>'
        +'<div id="xaStatus" style="font-size:12px;margin:0 0 8px;padding:8px 10px;border-radius:8px;background:#151310;border:1px solid var(--line)">'+(copied?'Copied from <b>'+esc(copied.name)+'</b>':'Nothing copied yet')+'</div>'+rows
        +'<div class="mini-row" style="margin-top:12px"><button class="chip" id="xaCopy" type="button"'+(n?'':' disabled')+'>Copy from selected clip</button><button class="chip" id="xaPaste" type="button" style="background:var(--accent);color:#1a0c03;font-weight:700"'+((copied&&n)?'':' disabled')+'>Paste onto '+(n||0)+' clip'+(n===1?'':'s')+'</button></div>'
        +'<div style="font-size:11px;color:var(--muted);margin-top:10px">Shortcuts: <kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>C</kbd> copy, <kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>V</kbd> paste.</div>';
      openModal("Clip attributes",body);
      document.querySelectorAll("[data-ag]").forEach(function(b){ b.onchange=function(){ on[b.dataset.ag]=b.checked; }; });
      var c=document.getElementById("xaCopy"), p=document.getElementById("xaPaste");
      if(c) c.onclick=function(){ if(X.copyAttrs(true)){ n=X.sel().length; render(); } };
      if(p) p.onclick=function(){ closeModal(); setTimeout(X.pasteAttrs,40); };
    }
    render();
  };
  X.addShortcut("Shift+K","Copy / paste clip attributes (look, size, sound, animation)");
  X.addShortcut("Ctrl+Alt+C","Copy attributes of the selected clip");
  X.addShortcut("Ctrl+Alt+V","Paste attributes onto the selected clips");
  X.cmdKey&&X.cmdKey("Clip attributes…","Shift+K"); X.cmdKey&&X.cmdKey("Copy clip attributes","Ctrl+Alt+C"); X.cmdKey&&X.cmdKey("Paste clip attributes","Ctrl+Alt+V");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.shiftKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.altKey&&ev.code==="KeyK"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.attrDialog(); return; }
    if(ev.ctrlKey&&ev.altKey&&!ev.shiftKey&&ev.code==="KeyC"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.copyAttrs(); return; }
    if(ev.ctrlKey&&ev.altKey&&!ev.shiftKey&&ev.code==="KeyV"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.pasteAttrs(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Clip attributes…","amiyoX.attrDialog()"],["Copy clip attributes","amiyoX.copyAttrs()"],["Paste clip attributes","amiyoX.pasteAttrs()"]]); };
  window.AMIYO_EDITOR_BUILD="step71-attrs";
}catch(e){console.warn("step71",e)}})();

;
/* ==================== Script 252 id="amiyo-step72" ==================== */
/* Step 72: Rename clips (F2) - give one clip a name, or name many at once with numbering ({n}, {nn}, {name}).
   Names show on the timeline, in the Inspector and in Find clips. Leave the name empty to go back to the file name. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  function srcName(c){ var a=project.assets&&project.assets[c.assetId]; return String((a&&a.name)||c.text||c.kind||"Clip").replace(/\.[A-Za-z0-9]{2,4}$/,""); }
  function ordered(){ var order={}; project.tracks.forEach(function(t,i){ order[t.id]=i; });
    return X.sel().slice().sort(function(a,b){ return (a.clip.start-b.clip.start)||(order[a.track.id]-order[b.track.id]); }); }
  function pad(n,w){ n=String(n); while(n.length<w) n="0"+n; return n; }
  /* build the new names without changing anything */
  X.renamePlan=function(pattern,startAt){
    var l=ordered(), p=String(pattern==null?"":pattern).trim(), s=parseInt(startAt,10); if(!isFinite(s)) s=1;
    var multi=l.length>1, hasTok=/\{(n|nn|name)\}/.test(p);
    return l.map(function(x,i){
      if(!p) return {id:x.clip.id,name:""};
      var nm=p.replace(/\{nn\}/g,pad(s+i,2)).replace(/\{n\}/g,String(s+i)).replace(/\{name\}/g,srcName(x.clip));
      if(multi&&!hasTok) nm=nm+" "+(s+i);
      return {id:x.clip.id,name:nm.slice(0,60)};
    });
  };
  X.renameClips=function(pattern,startAt){
    var plan=X.renamePlan(pattern,startAt); if(!plan.length){ X.say("Select a clip to rename"); return 0; }
    var map={}; plan.forEach(function(r){ map[r.id]=r.name; }); var changed=0;
    window.transact(plan.length>1?"Rename clips":"Rename clip",function(){
      project.tracks.forEach(function(t){ if(t.locked) return; t.clips.forEach(function(c){ if(!(c.id in map)) return; var nm=map[c.id];
        if(nm){ if(c.name!==nm){ c.name=nm; changed++; } } else if("name" in c){ delete c.name; changed++; } }); });
    });
    X.say(changed?(changed===1?"Renamed":"Renamed "+changed+" clips"):"No names changed (locked tracks are skipped)",2200); return changed;
  };
  X.renameDialog=function(){
    var l=ordered(); if(!l.length) return X.say("Select a clip to rename");
    var multi=l.length>1, cur=multi?"":String(l[0].clip.name||"");
    openModal(multi?"Rename "+l.length+" clips":"Rename clip",
      '<label class="field" for="xrName" style="display:block;margin-bottom:4px">'+(multi?"Name pattern":"Name")+'</label>'
      +'<input id="xrName" type="text" maxlength="60" value="'+esc(cur)+'" placeholder="'+esc(multi?"Scene {n}":srcName(l[0].clip))+'" style="width:100%;box-sizing:border-box;min-height:44px;font-size:16px" autocomplete="off">'
      +(multi?'<div style="display:flex;gap:10px;align-items:center;margin-top:10px"><label class="field" for="xrStart" style="margin:0">Start at</label><input id="xrStart" type="number" min="0" step="1" value="1" style="width:90px;min-height:44px"></div>'
        +'<div style="font-size:11.5px;color:var(--muted);margin-top:8px;line-height:1.5">Use <b>{n}</b> for 1, 2, 3…, <b>{nn}</b> for 01, 02…, and <b>{name}</b> for the file name. With no token, numbers are added at the end. Clips are numbered in timeline order.</div>':'')
      +'<div id="xrPrev" aria-live="polite" style="font-size:12px;margin:10px 0;padding:8px 10px;border-radius:8px;background:#151310;border:1px solid var(--line);min-height:20px"></div>'
      +'<div class="mini-row"><button class="chip" id="xrGo" type="button" style="background:var(--accent);color:#1a0c03;font-weight:700">Rename</button><button class="chip" id="xrNo" type="button">Cancel</button></div>');
    var inp=document.getElementById("xrName"), st=document.getElementById("xrStart"), pv=document.getElementById("xrPrev");
    function prev(){ var p=X.renamePlan(inp.value,st?st.value:1), show=p.slice(0,3).map(function(r){ return esc(r.name||"(file name)"); });
      pv.innerHTML=(inp.value.trim()?'Will become: ':'Clears the name: ')+'<b>'+show.join('</b>, <b>')+'</b>'+(p.length>3?' … +'+(p.length-3)+' more':''); }
    function go(){ var v=inp.value, s=st?st.value:1; closeModal(); X.renameClips(v,s); }
    inp.addEventListener("input",prev); if(st) st.addEventListener("input",prev); prev();
    [inp,st].forEach(function(el){ if(el) el.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); }); });
    document.getElementById("xrGo").onclick=go; document.getElementById("xrNo").onclick=closeModal;
    setTimeout(function(){ inp.focus(); inp.select(); },40);
  };
  X.addShortcut("F2","Rename the selected clip(s)");
  X.cmdKey&&X.cmdKey("Rename clips…","F2");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.key==="F2"&&!ev.ctrlKey&&!ev.metaKey&&!ev.altKey&&!ev.shiftKey){ ev.preventDefault(); ev.stopImmediatePropagation(); X.renameDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Rename clips…","amiyoX.renameDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step72-rename";
}catch(e){console.warn("step72",e)}})();

;
/* ==================== Script 253 id="amiyo-step73" ==================== */
/* Step 73: Insert time (Shift+T) - open up a gap of N seconds at the playhead on every track.
   Clips under the playhead are cut in two, everything to the right moves later, markers move with it. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var memo=2, moveMarkers=true;
  function lockedBlock(t){ for(var i=0;i<project.tracks.length;i++){ var tr=project.tracks[i]; if(!tr.locked) continue;
      for(var j=0;j<tr.clips.length;j++){ if(tr.clips[j].start+tr.clips[j].duration>t+0.001) return tr; } } return null; }
  X.insertTime=function(seconds,withMarkers){
    var d=Number(seconds); if(!isFinite(d)||d<=0){ X.say("Enter how many seconds to insert"); return false; }
    d=Math.min(3600,Math.round(d*1000)/1000);
    var t=currentTime;
    var lk=lockedBlock(t); if(lk){ X.say("Unlock “"+lk.name+"” first, so every track stays in sync"); return false; }
    var moved=0, cut=0, mk=0;
    window.transact("Insert "+d+" s",function(){
      project.tracks.forEach(function(tr){
        var add=[];
        tr.clips.forEach(function(c){
          var end=c.start+c.duration;
          if(c.start>=t-0.03){ c.start+=d; moved++; }
          else if(end>t+0.03){
            var right=JSON.parse(JSON.stringify(c)); right.id=uid("clip"); right.selected=false;
            var elapsed=t-c.start, srcDur=(c.outPoint!=null?c.outPoint:c.duration)-(c.inPoint||0), ratio=c.duration?elapsed/c.duration:0;
            right.inPoint=(c.inPoint||0)+srcDur*ratio; right.start=t+d; right.duration=end-t;
            c.duration=elapsed; c.outPoint=right.inPoint; c.transitionOut=null; right.transitionIn=null;
            if(right.linkId) right.linkId=null; if(right.groupId) right.groupId=null;
            add.push(right); cut++;
          }
        });
        add.forEach(function(r){ tr.clips.push(r); }); tr.clips.sort(function(a,b){ return a.start-b.start; });
      });
      if(withMarkers!==false&&project.markers) project.markers.forEach(function(m){ if(m.time>=t-0.001){ m.time+=d; mk++; } });
    });
    X.say("Inserted "+d+" s at the playhead"+(cut?" · "+cut+" clip"+(cut>1?"s":"")+" cut":"")+(moved?" · "+moved+" moved":""),2800);
    return true;
  };
  X.insertTimeDialog=function(){
    if(getProjectDuration()<=0) return X.say("Add something to the timeline first");
    openModal("Insert time",
      '<div style="font-size:12px;color:var(--muted);margin-bottom:10px;line-height:1.5">Opens an empty gap at the playhead ('+currentTime.toFixed(2)+' s) on every track. Clips under the playhead are cut in two and everything after it moves later.</div>'
      +'<label class="field" for="xiSec" style="display:block;margin-bottom:4px">Seconds to insert</label>'
      +'<input id="xiSec" type="number" min="0.1" max="3600" step="0.5" value="'+memo+'" inputmode="decimal" style="width:120px;min-height:44px;font-size:16px">'
      +'<div class="mini-row" style="margin-top:8px">'+[1,2,5,10].map(function(s){ return '<button class="chip" type="button" data-xis="'+s+'">'+s+' s</button>'; }).join("")+'</div>'
      +'<label style="display:flex;align-items:center;gap:8px;min-height:44px;margin-top:6px"><input type="checkbox" id="xiMk" '+(moveMarkers?"checked":"")+'> Move markers after the playhead too</label>'
      +'<div class="mini-row" style="margin-top:8px"><button class="chip" id="xiGo" type="button" style="background:var(--accent);color:#1a0c03;font-weight:700">Insert</button><button class="chip" id="xiNo" type="button">Cancel</button></div>');
    var inp=document.getElementById("xiSec");
    function go(){ var v=Number(inp.value), mk=document.getElementById("xiMk").checked; if(!(v>0)){ inp.focus(); return; } memo=v; moveMarkers=mk; closeModal(); X.insertTime(v,mk); }
    document.querySelectorAll("[data-xis]").forEach(function(b){ b.onclick=function(){ inp.value=b.dataset.xis; inp.focus(); }; });
    inp.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); });
    document.getElementById("xiGo").onclick=go; document.getElementById("xiNo").onclick=closeModal;
    setTimeout(function(){ inp.focus(); inp.select(); },40);
  };
  X.addShortcut("Shift+T","Insert time (a gap) at the playhead on every track");
  X.cmdKey&&X.cmdKey("Insert time at playhead…","Shift+T");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.shiftKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.altKey&&ev.code==="KeyT"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.insertTimeDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Insert time at playhead…","amiyoX.insertTimeDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step73-inserttime";
}catch(e){console.warn("step73",e)}})();

;
/* ==================== Script 254 id="amiyo-step74" ==================== */
/* Step 74: Track controls window (Shift+O) - see every track at once, flip Mute / Solo / Lock / Hide per track,
   and use one-tap bulk actions: unlock all, unmute all, show all, clear solo, solo or isolate the selected clip's track. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  function selTrack(){ var l=X.sel(); if(l.length) return l[0].track; if(selectedTrackId){ var t=project.tracks.filter(function(x){ return x.id===selectedTrackId; })[0]; if(t) return t; } return null; }
  var ACTIONS={
    unlock:{label:"Unlock all tracks",run:function(t){ t.locked=false; },test:function(t){ return t.locked; }},
    unmute:{label:"Unmute all tracks",run:function(t){ t.muted=false; },test:function(t){ return t.muted; }},
    show:{label:"Show all tracks",run:function(t){ t.hidden=false; },test:function(t){ return t.hidden; }},
    clearsolo:{label:"Clear solo",run:function(t){ t.solo=false; },test:function(t){ return t.solo; }}
  };
  X.trackBulk=function(action){
    var n=0;
    if(ACTIONS[action]){ var A=ACTIONS[action];
      if(!project.tracks.some(A.test)){ X.say("Nothing to do: no track is "+({unlock:"locked",unmute:"muted",show:"hidden",clearsolo:"soloed"})[action]); return 0; }
      window.transact(A.label,function(){ project.tracks.forEach(function(t){ if(A.test(t)){ A.run(t); n++; } }); });
      X.say(A.label+": "+n+" track"+(n>1?"s":""),2200); return n;
    }
    var st=selTrack(); if(!st){ X.say("Select a clip or a track first"); return 0; }
    if(action==="solo"){
      window.transact("Solo track",function(){ project.tracks.forEach(function(t){ var want=(t.id===st.id); if(t.kind==="audio"&&t.solo!==want){ t.solo=want; n++; } }); if(st.kind!=="audio") st.solo=false; });
      X.say(st.kind==="audio"?"Soloed “"+st.name+"” (other audio tracks are silent)":"Solo only affects audio tracks — select an audio clip",2800); return n;
    }
    if(action==="lockothers"){
      window.transact("Lock other tracks",function(){ project.tracks.forEach(function(t){ var want=(t.id!==st.id); if(t.locked!==want){ t.locked=want; n++; } }); });
      X.say("Only “"+st.name+"” can be edited now",2600); return n;
    }
    if(action==="hideothers"){
      window.transact("Hide other tracks",function(){ project.tracks.forEach(function(t){ if(t.kind!=="video"&&t.kind!=="graphics"&&t.kind!=="text"&&t.kind!=="caption") return; var want=(t.id!==st.id); if(t.hidden!==want){ t.hidden=want; n++; } }); });
      X.say("Showing only “"+st.name+"” (audio tracks are not hidden)",2600); return n;
    }
    X.say("Unknown track action"); return 0;
  };
  var FLAGS=[["muted","M","Mute"],["solo","S","Solo"],["locked","🔒","Lock"],["hidden","👁","Hide"]];
  X.tracksDialog=function(){
    function body(){
      var st=selTrack(), rows=project.tracks.map(function(t,i){
        var chips=FLAGS.map(function(f){ var on=!!t[f[0]], dis=(f[0]==="solo"&&t.kind!=="audio"); return '<button type="button" class="chip" data-xt="'+i+':'+f[0]+'" aria-pressed="'+on+'" aria-label="'+f[2]+' '+esc(t.name)+'"'+(dis?' disabled':'')+' style="min-width:44px;min-height:40px;'+(on?'background:var(--accent);color:#1a0c03;font-weight:700':'')+(dis?';opacity:.35':'')+'">'+f[1]+'</button>'; }).join("");
        return '<div style="display:flex;align-items:center;gap:6px;padding:6px 0;border-bottom:1px solid var(--line);'+(st&&st.id===t.id?'background:rgba(255,122,61,.08)':'')+'"><div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(t.name)+'</div><div style="font-size:10.5px;color:var(--muted)">'+esc(t.kind)+' · '+t.clips.length+' clip'+(t.clips.length===1?'':'s')+(st&&st.id===t.id?' · selected':'')+'</div></div>'+chips+'</div>'; }).join("");
      var bulk=[["unlock","Unlock all"],["unmute","Unmute all"],["show","Show all"],["clearsolo","Clear solo"],["solo","Solo selected"],["lockothers","Lock others"],["hideothers","Hide others"]].map(function(a){ return '<button type="button" class="chip" data-xb="'+a[0]+'">'+a[1]+'</button>'; }).join("");
      return '<div style="font-size:12px;color:var(--muted);margin-bottom:6px">Tap M mute · S solo (audio) · 🔒 lock · 👁 hide. Locked tracks cannot be edited.</div>'+rows+'<div class="mini-row" style="margin-top:12px">'+bulk+'</div>';
    }
    function bind(){
      document.querySelectorAll("[data-xt]").forEach(function(b){ b.onclick=function(){ var p=b.dataset.xt.split(":"), t=project.tracks[+p[0]]; if(!t) return; t[p[1]]=!t[p[1]]; scheduleAutosave(); renderAll(); paint(); }; });
      document.querySelectorAll("[data-xb]").forEach(function(b){ b.onclick=function(){ X.trackBulk(b.dataset.xb); paint(); }; });
    }
    function paint(){ var el=document.getElementById("modalBody"); if(!el||!document.querySelector("[data-xt],[data-xb]")) return; var f=document.activeElement&&document.activeElement.dataset&&(document.activeElement.dataset.xt||document.activeElement.dataset.xb);
      el.innerHTML=body(); bind(); if(f){ var n=el.querySelector('[data-xt="'+f+'"],[data-xb="'+f+'"]'); if(n) n.focus(); } }
    openModal("Track controls",body()); bind();
  };
  X.addShortcut("Shift+O","Track controls: mute, solo, lock, hide and bulk actions");
  X.cmdKey&&X.cmdKey("Track controls…","Shift+O");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.shiftKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.altKey&&ev.code==="KeyO"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.tracksDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([
    ["Track controls…","amiyoX.tracksDialog()"],["Unlock all tracks","amiyoX.trackBulk('unlock')"],["Unmute all tracks","amiyoX.trackBulk('unmute')"],["Show all tracks","amiyoX.trackBulk('show')"],
    ["Clear solo","amiyoX.trackBulk('clearsolo')"],["Solo selected clip's track","amiyoX.trackBulk('solo')"],["Lock all other tracks","amiyoX.trackBulk('lockothers')"],["Hide all other tracks","amiyoX.trackBulk('hideothers')"]]); };
  window.AMIYO_EDITOR_BUILD="step74-trackctl";
}catch(e){console.warn("step74",e)}})();

