/* ==================== Script 255 id="amiyo-step75" ==================== */
/* Step 75: Jump between edit points and markers - Alt+Right / Alt+Left go to the next / previous cut on any visible track,
   Alt+Shift+Right / Alt+Shift+Left go to the next / previous marker. The timeline scrolls to follow the playhead. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function pts(kind){
    var o={};
    if(kind==="marker"){ (project.markers||[]).forEach(function(m){ o[Math.round(m.time*1000)]=1; }); }
    else { o[0]=1; project.tracks.forEach(function(t){ if(t.hidden) return; t.clips.forEach(function(c){ o[Math.round(c.start*1000)]=1; o[Math.round((c.start+c.duration)*1000)]=1; }); }); }
    return Object.keys(o).map(function(k){ return +k/1000; }).sort(function(a,b){ return a-b; });
  }
  X.jumpPoint=function(dir,kind){
    var l=pts(kind), now=Math.round(currentTime*1000)/1000, t=null, i;
    if(!l.length||(kind==="marker"&&!(project.markers||[]).length)) return X.say("No markers yet. Add one with the marker button",2200);
    if(dir>0){ for(i=0;i<l.length;i++) if(l[i]>now+0.0005){ t=l[i]; break; } }
    else { for(i=l.length-1;i>=0;i--) if(l[i]<now-0.0005){ t=l[i]; break; } }
    if(t==null) return X.say(dir>0?"No more "+(kind==="marker"?"markers":"edit points")+" ahead":"Already at the first "+(kind==="marker"?"marker":"edit point"),1600);
    setCurrentTime(t);
    var ts=document.getElementById("timelineScroll"); if(ts){ var x=timeToPx(t); if(x<ts.scrollLeft||x>ts.scrollLeft+ts.clientWidth-labelW()-20) ts.scrollLeft=Math.max(0,x-ts.clientWidth/3); }
    X.say((kind==="marker"?"Marker at ":"Edit point at ")+t.toFixed(2)+" s",1200);
  };
  X.addShortcut("Alt+Right / Alt+Left","Jump to the next / previous edit point");
  X.addShortcut("Alt+Shift+Right / Left","Jump to the next / previous marker");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(!ev.altKey||ev.ctrlKey||ev.metaKey) return;
    var d=ev.code==="ArrowRight"?1:ev.code==="ArrowLeft"?-1:0; if(!d) return;
    ev.preventDefault(); ev.stopImmediatePropagation(); X.jumpPoint(d,ev.shiftKey?"marker":"cut");
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([
    ["Next edit point","amiyoX.jumpPoint(1,'cut')"],["Previous edit point","amiyoX.jumpPoint(-1,'cut')"],["Next marker","amiyoX.jumpPoint(1,'marker')"],["Previous marker","amiyoX.jumpPoint(-1,'marker')"]]); };
  window.AMIYO_EDITOR_BUILD="step75-jumppoints";
}catch(e){console.warn("step75",e)}})();

