/* ==================== Script 256 id="amiyo-step76" ==================== */
/* Step 76: Loop the In-Out range - set In (I) and Out (O), then press Alt+L (or the "Loop I-O" button) and playback
   repeats just that stretch. Saved with the project. Without both points set, it tells you what is missing. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var last=-1, btn=null;
  function io(){ var r=window.amiyoGetIO?window.amiyoGetIO():{}; return (r&&r.i!=null&&r.o!=null&&r.o>r.i)?r:null; }
  function paint(){ if(btn){ var on=!!project.settings.loopRange; btn.classList.toggle("tool-active",on); btn.setAttribute("aria-pressed",on?"true":"false"); } }
  X.toggleLoopRange=function(){
    var r=io(), on=!project.settings.loopRange;
    if(on&&!r) return X.say("Set both an In point (I) and an Out point (O) first",2800);
    project.settings.loopRange=on; try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} paint();
    X.say(on?"Looping "+r.i.toFixed(2)+" to "+r.o.toFixed(2)+" s":"Range loop off",2000);
    if(on&&!isPlaying&&(currentTime<r.i||currentTime>=r.o)) setCurrentTime(r.i);
  };
  function watch(){
    try{
      if(isPlaying&&project.settings.loopRange){
        var r=io();
        if(!r){ project.settings.loopRange=false; paint(); }
        else if(last>=0&&last<r.o&&currentTime>=r.o){ var p=window.play; pause(); setCurrentTime(r.i); p(); }
      }
      last=currentTime;
    }catch(e){window.__swl&&window.__swl(e)}
    if(isPlaying) requestAnimationFrame(watch); else setTimeout(function(){ requestAnimationFrame(watch); },150);   /* step 60: only per-frame while playing */
  }
  requestAnimationFrame(watch);
  var out=document.getElementById("setOutBtn");
  if(out&&!document.getElementById("loopRangeBtn")){
    btn=document.createElement("button"); btn.type="button"; btn.className="toolbtn"; btn.id="loopRangeBtn";
    btn.textContent="Loop I–O"; btn.title="Loop between the In and Out points (Alt+L)"; btn.onclick=X.toggleLoopRange;
    out.insertAdjacentElement("afterend",btn); paint();
  }
  X.addShortcut("Alt+L","Loop between the In and Out points on / off");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyL"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.toggleLoopRange(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Loop In-Out range on / off","amiyoX.toggleLoopRange()"]]); };
  window.AMIYO_EDITOR_BUILD="step76-looprange";
}catch(e){console.warn("step76",e)}})();

