/* ==================== Script 257 id="amiyo-step77" ==================== */
/* Step 77: Trim to playhead - Q trims the start of the selected clip(s) up to the playhead, W trims the end back to it
   (nothing selected: every unlocked clip under the playhead). The content stays in sync: source in/out points and
   keyframes move with the cut. One Undo step. Ctrl+Q / Ctrl+W are left to the browser. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function targets(t){
    var l=X.sel().filter(function(x){ return !x.track.locked; });
    if(!l.length){ project.tracks.forEach(function(tr){ if(tr.locked||tr.hidden) return; tr.clips.forEach(function(c){ if(c.start<t&&c.start+c.duration>t) l.push({track:tr,clip:c}); }); }); }
    return l.filter(function(x){ return t>x.clip.start+0.04&&t<x.clip.start+x.clip.duration-0.04; });
  }
  function shiftKf(list,d){
    if(!list||!list.length) return list;
    var out=[],carry=null; list.forEach(function(k){ var n=Object.assign({},k); n.t=r3(k.t-d); if(n.t<0){ carry=n; } else out.push(n); });
    if(carry){ carry.t=0; if(!out.length||out[0].t>0) out.unshift(carry); }
    return out;
  }
  X.trimToPlayhead=function(side){
    var t=r3(currentTime), l=targets(t);
    if(!l.length) return X.say(X.sel().length?"Put the playhead inside the selected clip first":"No clip under the playhead to trim",2400);
    window.transact(side==="start"?"Trim start to playhead":"Trim end to playhead",function(){
      l.forEach(function(x){
        var c=x.clip, el=t-c.start, ratio=el/c.duration, srcDur=(c.outPoint!=null&&c.inPoint!=null)?c.outPoint-c.inPoint:null;
        if(side==="start"){
          if(srcDur!=null) c.inPoint=r3(c.inPoint+srcDur*ratio);
          c.start=t; c.duration=r3(c.duration-el);
          if(c.keyframes) c.keyframes=shiftKf(c.keyframes,el);
          if(c.volumeKeyframes) c.volumeKeyframes=shiftKf(c.volumeKeyframes,el);
        } else {
          if(srcDur!=null) c.outPoint=r3(c.inPoint+srcDur*ratio);
          c.duration=r3(el);
        }
        if(c.fadeIn) c.fadeIn=Math.min(c.fadeIn,c.duration*0.9); if(c.fadeOut) c.fadeOut=Math.min(c.fadeOut,c.duration*0.9);
      });
    });
    X.say((side==="start"?"Start":"End")+" trimmed on "+l.length+" clip"+(l.length>1?"s":""),1800);
  };
  X.addShortcut("Q / W","Trim the start / end of the selected clip to the playhead");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey||ev.shiftKey) return;
    if(ev.code==="KeyQ"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.trimToPlayhead("start"); }
    else if(ev.code==="KeyW"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.trimToPlayhead("end"); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Trim start to playhead","amiyoX.trimToPlayhead('start')"],["Trim end to playhead","amiyoX.trimToPlayhead('end')"]]); };
  window.AMIYO_EDITOR_BUILD="step77-trimplayhead";
}catch(e){console.warn("step77",e)}})();

