/* ==================== Script 258 id="amiyo-step78" ==================== */
/* Step 78: Fades for many clips at once (Shift+B) - set the fade in and fade out seconds, then apply them to every
   selected clip in one Undo step. Choose which clips: all selected, only sound, or only picture. 0 clears a fade. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r2(v){ return Math.round(v*100)/100; }
  function isSnd(x){ return x.track.kind==="audio"; }
  X.applyFades=function(o){
    var l=X.sel().filter(function(x){ return !x.track.locked; });
    if(o.who==="sound") l=l.filter(isSnd); else if(o.who==="picture") l=l.filter(function(x){ return !isSnd(x); });
    if(!l.length) return X.say("No matching unlocked clips selected",2400);
    var fi=Math.max(0,Math.min(30,+o.fin||0)), fo=Math.max(0,Math.min(30,+o.fout||0));
    window.transact("Fades on "+l.length+" clips",function(){
      l.forEach(function(x){ var c=x.clip, cap=c.duration*0.45;
        if(o.setIn) c.fadeIn=r2(Math.min(fi,cap)); if(o.setOut) c.fadeOut=r2(Math.min(fo,cap)); });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say("Fades set on "+l.length+" clip"+(l.length>1?"s":"")+(l.some(function(x){ return Math.max(o.setIn?fi:0,o.setOut?fo:0)>x.clip.duration*0.45; })?" (short clips got shorter fades)":""),2800);
  };
  X.fadesDialog=function(){
    var l=X.sel(); if(!l.length) return X.say("Select one or more clips first");
    var s=l.filter(isSnd).length, p=l.length-s, c0=l[0].clip;
    openModal("Fades for selected clips",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+l.length+' clip'+(l.length>1?'s':'')+' selected ('+p+' picture, '+s+' sound). A fade can take at most 45% of a clip.</div>'
      +'<label style="display:flex;gap:8px;align-items:center;font-size:13px;margin:6px 0"><input id="xfIn" type="checkbox" checked style="width:20px;height:20px"> Fade in (seconds)</label>'
      +'<input id="xfInV" type="number" min="0" max="30" step="0.1" value="'+(c0.fadeIn||0.5)+'" inputmode="decimal" aria-label="Fade in seconds" style="min-height:44px;font-size:16px">'
      +'<label style="display:flex;gap:8px;align-items:center;font-size:13px;margin:10px 0 6px"><input id="xfOut" type="checkbox" checked style="width:20px;height:20px"> Fade out (seconds)</label>'
      +'<input id="xfOutV" type="number" min="0" max="30" step="0.1" value="'+(c0.fadeOut||0.5)+'" inputmode="decimal" aria-label="Fade out seconds" style="min-height:44px;font-size:16px">'
      +'<label class="field" for="xfWho" style="margin-top:10px">Apply to</label><select id="xfWho" style="min-height:44px;font-size:16px"><option value="all">All selected clips</option><option value="sound"'+(s?'':' disabled')+'>Sound clips only</option><option value="picture"'+(p?'':' disabled')+'>Picture clips only</option></select>'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xfNo" type="button">Cancel</button><button class="topbtn primary" id="xfGo" type="button">Apply</button></div>');
    function go(){ var o={fin:document.getElementById("xfInV").value,fout:document.getElementById("xfOutV").value,setIn:document.getElementById("xfIn").checked,setOut:document.getElementById("xfOut").checked,who:document.getElementById("xfWho").value}; closeModal(); X.applyFades(o); }
    document.getElementById("xfGo").onclick=go; document.getElementById("xfNo").onclick=closeModal;
    ["xfInV","xfOutV"].forEach(function(id){ document.getElementById(id).addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); }); });
  };
  X.addShortcut("Shift+B","Set fade in / out on all selected clips");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey||!ev.shiftKey) return;
    if(ev.code==="KeyB"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.fadesDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Fades for selected clips…","amiyoX.fadesDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step78-fades";
}catch(e){console.warn("step78",e)}})();

;
/* ==================== Script 259 id="amiyo-step79" ==================== */
/* Step 79: Volume for many clips at once (Shift+M) - set one level, raise or lower by a percentage, or mute / unmute
   every selected clip. Mute remembers the old level (and volume keyframes) so Unmute puts them back. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r2(v){ return Math.round(v*100)/100; }
  function cl(v){ return Math.max(0,Math.min(1,v)); }
  X.applyVolume=function(o){
    var l=X.sel().filter(function(x){ return !x.track.locked; });
    if(!l.length) return X.say("Select unlocked clips first",2200);
    var n=0, kfLeft=0, pct=+o.pct||0;
    window.transact("Volume on "+l.length+" clips",function(){
      l.forEach(function(x){
        var c=x.clip, v=c.volume==null?1:c.volume;
        if(o.mode==="mute"){ if(!c.muteBackup){ c.muteBackup={v:v,kf:c.volumeKeyframes?JSON.parse(JSON.stringify(c.volumeKeyframes)):null}; c.volume=0; if(c.volumeKeyframes) c.volumeKeyframes=c.volumeKeyframes.map(function(k){ return Object.assign({},k,{v:0}); }); n++; } }
        else if(o.mode==="unmute"){ if(c.muteBackup){ c.volume=c.muteBackup.v; if(c.muteBackup.kf) c.volumeKeyframes=c.muteBackup.kf; delete c.muteBackup; n++; } }
        else if(o.mode==="adjust"){ var f=1+pct/100; c.volume=r2(cl(v*f)); if(c.volumeKeyframes) c.volumeKeyframes=c.volumeKeyframes.map(function(k){ return Object.assign({},k,{v:r2(cl((k.v==null?1:k.v)*f))}); }); delete c.muteBackup; n++; }
        else { c.volume=r2(cl(pct/100)); if(c.volumeKeyframes&&c.volumeKeyframes.length) kfLeft++; delete c.muteBackup; n++; }
      });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(!n?(o.mode==="unmute"?"None of those clips were muted":"Already muted"):(o.mode==="mute"?"Muted ":o.mode==="unmute"?"Unmuted ":"Volume changed on ")+n+" clip"+(n>1?"s":"")+(kfLeft?" ("+kfLeft+" with volume keyframes still follow them)":""),3000);
  };
  X.volumeDialog=function(){
    var l=X.sel(); if(!l.length) return X.say("Select one or more clips first");
    var avg=Math.round(100*l.reduce(function(a,x){ return a+(x.clip.volume==null?1:x.clip.volume); },0)/l.length), muted=l.filter(function(x){ return x.clip.muteBackup; }).length;
    openModal("Volume for selected clips",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+l.length+' clip'+(l.length>1?'s':'')+' selected, average volume '+avg+'%'+(muted?', '+muted+' muted':'')+'.</div>'
      +'<label class="field" for="xvMode">What to do</label><select id="xvMode" style="min-height:44px;font-size:16px"><option value="set">Set every clip to</option><option value="adjust">Raise or lower by</option><option value="mute">Mute</option><option value="unmute">Unmute (restore old level)</option></select>'
      +'<div id="xvRow" style="margin-top:10px"><label class="field" for="xvPct" id="xvLbl">Level (%)</label><input id="xvPct" type="number" min="0" max="100" step="1" value="'+avg+'" inputmode="numeric" style="min-height:44px;font-size:16px"></div>'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xvNo" type="button">Cancel</button><button class="topbtn primary" id="xvGo" type="button">Apply</button></div>');
    var mode=document.getElementById("xvMode"), pct=document.getElementById("xvPct");
    mode.onchange=function(){ var m=mode.value; document.getElementById("xvRow").style.display=(m==="mute"||m==="unmute")?"none":"";
      document.getElementById("xvLbl").textContent=m==="adjust"?"Change by (%, negative lowers)":"Level (%)"; pct.min=m==="adjust"?-100:0; pct.value=m==="adjust"?-20:avg; };
    function go(){ var o={mode:mode.value,pct:pct.value}; closeModal(); X.applyVolume(o); }
    document.getElementById("xvGo").onclick=go; document.getElementById("xvNo").onclick=closeModal;
    pct.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); });
  };
  X.addShortcut("Shift+M","Volume, mute or unmute for all selected clips");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey||!ev.shiftKey) return;
    if(ev.code==="KeyM"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.volumeDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Volume for selected clips…","amiyoX.volumeDialog()"],["Mute selected clips","amiyoX.applyVolume({mode:'mute'})"],["Unmute selected clips","amiyoX.applyVolume({mode:'unmute'})"]]); };
  window.AMIYO_EDITOR_BUILD="step79-clipvolume";
}catch(e){console.warn("step79",e)}})();

