/* ==================== Script 260 id="amiyo-step80" ==================== */
/* Step 80: Speed for many clips at once (Shift+Y) - set one speed on every selected video / audio clip. The source part
   each clip uses stays the same, so lengths change; optionally clips after each one on its track move along so
   nothing overlaps or leaves a hole. One Undo step. Pictures, titles and locked tracks are skipped. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function ok(x){ var c=x.clip, a=project.assets&&project.assets[c.assetId]; return !x.track.locked&&a&&a.type!=="image"&&c.kind!=="text"&&c.kind!=="caption"&&c.kind!=="adjustment"; }
  X.applySpeed=function(v,ripple){
    v=Math.max(0.1,Math.min(8,+v)); if(!isFinite(v)) return X.say("Type a speed between 0.1 and 8",2400);
    var l=X.sel().filter(ok); if(!l.length) return X.say("Select video or audio clips on unlocked tracks first",2600);
    var skipped=X.sel().length-l.length, byTrack=new Map();
    l.forEach(function(x){ if(!byTrack.has(x.track)) byTrack.set(x.track,[]); byTrack.get(x.track).push(x.clip); });
    window.transact("Speed "+v+"× on "+l.length+" clips",function(){
      byTrack.forEach(function(list,tr){
        list.sort(function(a,b){ return a.start-b.start; });
        list.forEach(function(k){
          var src=k.duration*(k.speed||1), nd=Math.max(0.05,r3(src/v)), dl=nd-k.duration, s=k.start;
          k.speed=v; k.duration=nd; k.outPoint=r3((k.inPoint||0)+src);
          if(k.fadeIn) k.fadeIn=Math.min(k.fadeIn,nd*0.45); if(k.fadeOut) k.fadeOut=Math.min(k.fadeOut,nd*0.45);
          if(ripple&&Math.abs(dl)>0.0005) tr.clips.forEach(function(o){ if(o!==k&&o.start>=s+0.0005) o.start=Math.max(0,r3(o.start+dl)); });
        });
        tr.clips.sort(function(a,b){ return a.start-b.start; });
      });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say("Speed "+v+"× on "+l.length+" clip"+(l.length>1?"s":"")+(skipped?" ("+skipped+" skipped: pictures, titles or locked)":""),3200);
  };
  X.speedDialog=function(){
    var l=X.sel().filter(ok); if(!l.length) return X.say("Select video or audio clips first");
    var sp=l[0].clip.speed||1, same=l.every(function(x){ return Math.abs((x.clip.speed||1)-sp)<0.001; });
    openModal("Speed for selected clips",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+l.length+' video / audio clip'+(l.length>1?'s':'')+(same?' at '+sp+'×':' at different speeds')+'. To keep a video and its voice in sync, select both.</div>'
      +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px">'+[0.25,0.5,0.75,1,1.5,2,4].map(function(v){ return '<button type="button" class="chip xsp" data-v="'+v+'" style="min-height:44px;min-width:52px">'+v+'×</button>'; }).join("")+'</div>'
      +'<label class="field" for="xsV">Speed (0.1 to 8)</label><input id="xsV" type="number" min="0.1" max="8" step="0.05" value="'+sp+'" inputmode="decimal" style="min-height:44px;font-size:16px">'
      +'<label style="display:flex;gap:8px;align-items:center;margin:12px 0 4px;font-size:13px"><input id="xsR" type="checkbox" checked style="width:20px;height:20px"> Move later clips on each track along</label>'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xsNo" type="button">Cancel</button><button class="topbtn primary" id="xsGo" type="button">Apply</button></div>');
    var inp=document.getElementById("xsV");
    [].forEach.call(document.querySelectorAll(".xsp"),function(b){ b.onclick=function(){ inp.value=b.dataset.v; }; });
    function go(){ var v=inp.value, r=document.getElementById("xsR").checked; closeModal(); X.applySpeed(v,r); }
    document.getElementById("xsGo").onclick=go; document.getElementById("xsNo").onclick=closeModal;
    inp.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); });
  };
  X.addShortcut("Shift+Y","Set one speed on all selected video / audio clips");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey||!ev.shiftKey) return;
    if(ev.code==="KeyY"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.speedDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Speed for selected clips…","amiyoX.speedDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step80-batchspeed";
}catch(e){console.warn("step80",e)}})();

