/* ==================== Script 261 id="amiyo-step81" ==================== */
/* Step 81: Reverse or shuffle the order of the selected clips (Alt+R reverses) - the clips on one track swap places
   but the gaps between them keep their pattern, so the whole stretch stays the same length. Refused when another clip
   sits inside the stretch or the track is locked. One Undo step. Shuffle is in the Ctrl+K palette. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  X.reorderClips=function(how){
    var l=X.sel(); if(l.length<2) return X.say("Select two or more clips on one track first",2400);
    var tr=l[0].track; if(!l.every(function(x){ return x.track===tr; })) return X.say("Select clips from one track only",2600);
    if(tr.locked) return X.say("That track is locked. Unlock it first",2400);
    var items=l.map(function(x){ return x.clip; }).sort(function(a,b){ return a.start-b.start; }), sel={}; items.forEach(function(c){ sel[c.id]=1; });
    var s0=items[0].start, s1=Math.max.apply(null,items.map(function(c){ return c.start+c.duration; }));
    if(tr.clips.some(function(k){ return !sel[k.id]&&k.start<s1-0.001&&k.start+k.duration>s0+0.001; })) return X.say("Another clip sits between them. Select it too, or move it away first",3400);
    for(var i=1;i<items.length;i++) if(items[i].start<items[i-1].start+items[i-1].duration-0.001) return X.say("These clips overlap each other, so they can't be reordered",3000);
    var gaps=[]; for(i=0;i<items.length-1;i++) gaps.push(Math.max(0,items[i+1].start-(items[i].start+items[i].duration)));
    var order;
    if(how==="shuffle"){ order=items.slice(); for(i=order.length-1;i>0;i--){ var j=Math.floor(Math.random()*(i+1)), t=order[i]; order[i]=order[j]; order[j]=t; } }
    else order=items.slice().reverse();
    if(order.every(function(c,k){ return c===items[k]; })) return X.say("Already in that order",1800);
    window.transact((how==="shuffle"?"Shuffle ":"Reverse ")+items.length+" clips",function(){
      var t=s0; order.forEach(function(c,k){ c.start=r3(t); t+=c.duration+(k<gaps.length?gaps[how==="shuffle"?k:gaps.length-1-k]:0); });
      tr.clips.sort(function(a,b){ return a.start-b.start; });
    });
    X.say((how==="shuffle"?"Shuffled ":"Reversed ")+items.length+" clips",2000);
  };
  X.addShortcut("Alt+R","Reverse the order of the selected clips on a track");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyR"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.reorderClips("reverse"); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Reverse order of selected clips","amiyoX.reorderClips('reverse')"],["Shuffle order of selected clips","amiyoX.reorderClips('shuffle')"]]); };
  window.AMIYO_EDITOR_BUILD="step81-reorder";
}catch(e){console.warn("step81",e)}})();

