/* ==================== Script 262 id="amiyo-step82" ==================== */
/* Step 82: Select by type and invert the selection (Shift+X) - one window with a button for every kind of clip
   (video, picture, sound, title, caption, adjustment) showing how many there are, plus "Invert selection".
   Locked tracks are left out, so a following batch action never touches them. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var TYPES=[["video","Video"],["picture","Picture"],["sound","Sound"],["title","Title"],["caption","Caption"],["adjust","Adjustment"]];
  function typeOf(t,c){
    if(c.kind==="text") return "title"; if(c.kind==="caption") return "caption"; if(c.kind==="adjustment") return "adjust";
    var a=project.assets&&project.assets[c.assetId], ty=a&&a.type;
    if(ty==="image") return "picture"; if(ty==="audio"||t.kind==="audio") return "sound"; if(ty==="video") return "video";
    return t.kind==="audio"?"sound":(c.assetId?"video":"title");
  }
  function all(){ var o=[]; project.tracks.forEach(function(t){ if(t.locked) return; t.clips.forEach(function(c){ o.push({t:t,c:c}); }); }); return o; }
  function isSel(c){ return c.selected||c.id===selectedClipId; }
  function apply(hit,msg){
    project.tracks.forEach(function(t){ t.clips.forEach(function(c){ c.selected=false; }); });
    if(!hit.length){ selectedClipId=null; renderAll(); return X.say(msg||"Nothing to select",2200); }
    hit.sort(function(a,b){ return a.c.start-b.c.start; });
    hit.forEach(function(x){ x.c.selected=true; }); selectedClipId=hit[0].c.id; try{ selectedTrackId=hit[0].t.id; }catch(e){window.__swl&&window.__swl(e)}
    renderAll(); X.say(hit.length+" clip"+(hit.length>1?"s":"")+" selected",1800);
  }
  X.selectType=function(key){ apply(all().filter(function(x){ return typeOf(x.t,x.c)===key; }),"No clips of that type on unlocked tracks"); };
  X.invertSelection=function(){ apply(all().filter(function(x){ return !isSel(x.c); }),"Everything was selected, so nothing is left"); };
  X.selectDialog=function(){
    var n={}; TYPES.forEach(function(t){ n[t[0]]=0; }); all().forEach(function(x){ n[typeOf(x.t,x.c)]++; });
    openModal("Select clips",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">Pick a type to select every clip of that kind. Locked tracks are skipped.</div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap">'+TYPES.map(function(t){ return '<button type="button" class="chip xst" data-k="'+t[0]+'"'+(n[t[0]]?'':' disabled')+' style="min-height:44px;padding:0 14px">'+t[1]+' ('+n[t[0]]+')</button>'; }).join("")+'</div>'
      +'<div style="display:flex;gap:8px;justify-content:space-between;margin-top:14px"><button class="topbtn" id="xsiInv" type="button">Invert selection</button><button class="topbtn" id="xsiNo" type="button">Close</button></div>');
    [].forEach.call(document.querySelectorAll(".xst"),function(b){ b.onclick=function(){ closeModal(); X.selectType(b.dataset.k); }; });
    document.getElementById("xsiInv").onclick=function(){ closeModal(); X.invertSelection(); }; document.getElementById("xsiNo").onclick=closeModal;
  };
  X.addShortcut("Shift+X","Select all clips of one type, or invert the selection");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey||!ev.shiftKey) return;
    if(ev.code==="KeyX"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.selectDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Select clips by type…","amiyoX.selectDialog()"],["Invert selection","amiyoX.invertSelection()"]]); };
  window.AMIYO_EDITOR_BUILD="step82-selecttype";
}catch(e){console.warn("step82",e)}})();

