/* ==================== Script 263 id="amiyo-step83" ==================== */
/* Step 83: Markers from clips (Alt+M) - drops a marker at the start of every selected clip (nothing selected: every
   clip on visible tracks), named after the clip. Places that already have a marker are skipped. One Undo step.
   Handy for chapters, beat cuts and checking where each shot begins. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function nm(c){ var a=project.assets&&project.assets[c.assetId]; return String(c.name||(a&&a.name)||c.text||"Clip").replace(/\.[a-z0-9]{2,4}$/i,"").slice(0,40); }
  X.markersFromClips=function(){
    var l=X.sel(), scope=l.length?"selected":"all";
    if(!l.length){ project.tracks.forEach(function(t){ if(t.hidden) return; t.clips.forEach(function(c){ l.push({track:t,clip:c}); }); }); }
    if(!l.length) return X.say("There are no clips yet",2000);
    project.markers=project.markers||[];
    var have=project.markers.map(function(m){ return m.time; }), seen={}, add=[];
    l.sort(function(a,b){ return a.clip.start-b.clip.start; }).forEach(function(x){
      var t=r3(x.clip.start), k=Math.round(t*20);
      if(seen[k]) return; seen[k]=1;
      if(have.some(function(h){ return Math.abs(h-t)<0.05; })) return;
      add.push({id:uid("marker"),time:t,label:nm(x.clip),color:"#ff8040"});
    });
    if(!add.length) return X.say("Every clip start already has a marker",2400);
    window.transact("Markers from "+add.length+" clips",function(){ add.forEach(function(m){ project.markers.push(m); }); project.markers.sort(function(a,b){ return a.time-b.time; }); });
    try{ renderMarkerStrip(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(add.length+" marker"+(add.length>1?"s":"")+" added at "+(scope==="selected"?"selected":"all")+" clip starts",2800);
  };
  X.addShortcut("Alt+M","Add a marker at the start of every selected clip (or every clip)");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyM"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.markersFromClips(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Add markers at clip starts","amiyoX.markersFromClips()"]]); };
  window.AMIYO_EDITOR_BUILD="step83-clipmarkers";
}catch(e){console.warn("step83",e)}})();

