/* ==================== Script 264 id="amiyo-step84" ==================== */
/* Step 84: Batch tools window (Alt+B, or the "Batch" button in the top bar) - every tool from steps 75 to 83 in one list
   with its shortcut and a Run button, so none of them has to be remembered. Tools that need clips selected say so. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var TOOLS=[
    ["Next / previous edit point","Alt+→  Alt+←","",function(){ X.jumpPoint(1,"cut"); },"Next cut"],
    ["Next / previous marker","Alt+Shift+→  ←","",function(){ X.jumpPoint(1,"marker"); },"Next marker"],
    ["Loop In–Out range","Alt+L","needs In and Out",function(){ X.toggleLoopRange(); },"Toggle"],
    ["Trim start to playhead","Q","",function(){ X.trimToPlayhead("start"); },"Run"],
    ["Trim end to playhead","W","",function(){ X.trimToPlayhead("end"); },"Run"],
    ["Fades for many clips","Shift+B","select clips",function(){ X.fadesDialog(); },"Open"],
    ["Volume / mute for many clips","Shift+M","select clips",function(){ X.volumeDialog(); },"Open"],
    ["Speed for many clips","Shift+Y","select clips",function(){ X.speedDialog(); },"Open"],
    ["Reverse clip order","Alt+R","select 2+ on a track",function(){ X.reorderClips("reverse"); },"Run"],
    ["Shuffle clip order","palette","select 2+ on a track",function(){ X.reorderClips("shuffle"); },"Run"],
    ["Select by type / invert","Shift+X","",function(){ X.selectDialog(); },"Open"],
    ["Markers at clip starts","Alt+M","",function(){ X.markersFromClips(); },"Run"]
  ].filter(function(t){ return true; });
  X.batchTools=TOOLS;
  function esc(s){ return String(s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  X.batchDialog=function(){
    var n=X.sel().length;
    openModal("Batch tools",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:8px">'+(n?n+' clip'+(n>1?'s':'')+' selected.':'No clips selected.')+' Each tool also works from its shortcut or the Ctrl+K palette.</div>'
      +'<div style="display:flex;flex-direction:column;gap:6px;max-height:60vh;overflow:auto">'+TOOLS.map(function(t,i){
        return '<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;border:1px solid var(--line);border-radius:10px"><div style="flex:1;min-width:0"><div style="font-size:13px">'+esc(t[0])+'</div><div style="font-size:11px;color:var(--muted)">'+esc(t[1])+(t[2]?' · '+esc(t[2]):'')+'</div></div><button type="button" class="chip xbt" data-i="'+i+'" style="min-height:44px;min-width:64px">'+esc(t[4])+'</button></div>'; }).join("")+'</div>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="topbtn" id="xbNo" type="button">Close</button></div>');
    [].forEach.call(document.querySelectorAll(".xbt"),function(b){ b.onclick=function(){ var f=TOOLS[+b.dataset.i][3]; closeModal(); setTimeout(f,0); }; });
    document.getElementById("xbNo").onclick=closeModal;
  };
  function addBtn(){
    var sc=document.getElementById("shortcutsBtn"); if(!sc||document.getElementById("batchBtn")) return;
    var b=document.createElement("button"); b.type="button"; b.id="batchBtn"; b.className="topbtn"; b.textContent="🧰 Batch"; b.title="Batch tools (Alt+B)"; b.onclick=X.batchDialog;
    sc.insertAdjacentElement("afterend",b);
  }
  addBtn();
  X.addShortcut("Alt+B","Open the Batch tools window");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyB"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.batchDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Batch tools…","amiyoX.batchDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step84-batchtools";
}catch(e){console.warn("step84",e)}})();

