/* ==================== Script 265 id="amiyo-step85" ==================== */
/* Step 85: Exact length for many clips (Alt+D) - type a length in seconds and every selected clip gets it. Pictures, titles
   and captions can be any length; video and sound clips stop at the end of their source file. Optionally the clips after
   each one on its track move along. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function asset(c){ return project.assets&&project.assets[c.assetId]; }
  function isMedia(c){ var a=asset(c); return a&&(a.type==="video"||a.type==="audio")&&a.duration>0; }
  X.setClipLength=function(sec,ripple){
    sec=+sec; if(!(sec>=0.05&&sec<=3600)) return X.say("Type a length between 0.05 and 3600 seconds",2600);
    var l=X.sel().filter(function(x){ return !x.track.locked; }); if(!l.length) return X.say("Select clips on unlocked tracks first",2400);
    var byTrack=new Map(), clamped=0, changed=0;
    l.forEach(function(x){ if(!byTrack.has(x.track)) byTrack.set(x.track,[]); byTrack.get(x.track).push(x.clip); });
    window.transact("Length "+sec+" s on "+l.length+" clips",function(){
      byTrack.forEach(function(list,tr){
        list.sort(function(a,b){ return a.start-b.start; });
        list.forEach(function(k){
          var want=sec, sp=k.speed||1;
          if(isMedia(k)){ var room=(asset(k).duration-(k.inPoint||0))/sp; if(want>room+0.001){ want=r3(room); clamped++; } }
          want=Math.max(0.05,r3(want)); var dl=want-k.duration; if(Math.abs(dl)<0.0005) return;
          var s=k.start; k.duration=want; if(isMedia(k)||k.outPoint!=null) k.outPoint=r3((k.inPoint||0)+want*sp);
          if(k.fadeIn) k.fadeIn=Math.min(k.fadeIn,want*0.45); if(k.fadeOut) k.fadeOut=Math.min(k.fadeOut,want*0.45);
          changed++;
          if(ripple) tr.clips.forEach(function(o){ if(o!==k&&o.start>=s+0.0005) o.start=Math.max(0,r3(o.start+dl)); });
        });
        tr.clips.sort(function(a,b){ return a.start-b.start; });
      });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(changed?changed+" clip"+(changed>1?"s":"")+" set to "+sec+" s"+(clamped?" ("+clamped+" stopped at the end of their file)":""):"Those clips already have that length",3000);
  };
  X.lengthDialog=function(){
    var l=X.sel().filter(function(x){ return !x.track.locked; }); if(!l.length) return X.say("Select one or more clips first");
    var d=r3(l[0].clip.duration);
    openModal("Exact length for selected clips",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+l.length+' clip'+(l.length>1?'s':'')+' selected. Video and sound clips cannot run past the end of their file.</div>'
      +'<label class="field" for="xlV">Length (seconds)</label><input id="xlV" type="number" min="0.05" max="3600" step="0.1" value="'+d+'" inputmode="decimal" style="min-height:44px;font-size:16px">'
      +'<label style="display:flex;gap:8px;align-items:center;margin:12px 0 4px;font-size:13px"><input id="xlR" type="checkbox" checked style="width:20px;height:20px"> Move later clips on each track along</label>'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xlNo" type="button">Cancel</button><button class="topbtn primary" id="xlGo" type="button">Apply</button></div>');
    var inp=document.getElementById("xlV"); setTimeout(function(){ try{ inp.select(); }catch(e){window.__swl&&window.__swl(e)} },30);
    function go(){ var v=inp.value, r=document.getElementById("xlR").checked; closeModal(); X.setClipLength(v,r); }
    document.getElementById("xlGo").onclick=go; document.getElementById("xlNo").onclick=closeModal;
    inp.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); });
  };
  X.addShortcut("Alt+D","Set an exact length on all selected clips");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyD"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.lengthDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Exact length for selected clips…","amiyoX.lengthDialog()"]]); };
  window.AMIYO_EDITOR_BUILD="step85-cliplength";
}catch(e){console.warn("step85",e)}})();

