/* ==================== Script 266 id="amiyo-step86" ==================== */
/* Step 86: Swap two clips (Alt+S) - select exactly two clips and they trade places. On one track the later clip moves
   to where the earlier one began and the gap between them is kept. On two tracks they trade start times. Refused if
   a track is locked or the swap would land on top of another clip. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function hits(tr,self,s,d,skip){ return tr.clips.some(function(k){ return k!==self&&k!==skip&&k.start<s+d-0.001&&k.start+k.duration>s+0.001; }); }
  X.swapClips=function(){
    var l=X.sel(); if(l.length!==2) return X.say("Select exactly two clips to swap",2400);
    var A=l[0], B=l[1]; if(A.clip.start>B.clip.start){ var t=A; A=B; B=t; }
    if(A.track.locked||B.track.locked) return X.say("A track holding these clips is locked",2400);
    var a=A.clip, b=B.clip, ns;
    if(A.track===B.track){
      if(b.start<a.start+a.duration-0.001) return X.say("These clips overlap, so they can't be swapped",2800);
      var gap=b.start-(a.start+a.duration), nb=a.start, na=r3(a.start+b.duration+gap);
      if(A.track.clips.some(function(k){ return k!==a&&k!==b&&k.start<Math.max(a.start+a.duration,b.start+b.duration,na+a.duration)-0.001&&k.start+k.duration>a.start+0.001; })) return X.say("Another clip sits between them. Move it away first",3200);
      ns=function(){ b.start=r3(nb); a.start=na; A.track.clips.sort(function(x,y){ return x.start-y.start; }); };
    } else {
      var sa=a.start, sb=b.start;
      if(hits(B.track,b,sa,b.duration,null)||hits(A.track,a,sb,a.duration,null)) return X.say("Swapping would put a clip on top of another one",3000);
      ns=function(){ a.start=sb; b.start=sa; A.track.clips.sort(function(x,y){ return x.start-y.start; }); B.track.clips.sort(function(x,y){ return x.start-y.start; }); };
    }
    window.transact("Swap clips",ns);
    X.say("Clips swapped",1800);
  };
  X.addShortcut("Alt+S","Swap the two selected clips");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyS"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.swapClips(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Swap two selected clips","amiyoX.swapClips()"]]); };
  window.AMIYO_EDITOR_BUILD="step86-swap";
}catch(e){console.warn("step86",e)}})();

;
/* ==================== Script 267 id="amiyo-step87" ==================== */
/* Step 87: Move clips to the track above / below (Alt+Up / Alt+Down) - every selected clip jumps to the nearest unlocked
   track of the same kind in that direction, keeping its time. If any clip would land on top of another clip, or there is
   no track that way, nothing moves and it says why. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  X.moveToTrack=function(dir){
    var l=X.sel(); if(!l.length) return X.say("Select one or more clips first",2200);
    if(l.some(function(x){ return x.track.locked; })) return X.say("A selected clip is on a locked track",2400);
    var T=project.tracks, plan=[], srcOf=new Map();
    for(var i=0;i<l.length;i++){
      var x=l[i], idx=T.indexOf(x.track), j=idx+dir, dest=null;
      while(j>=0&&j<T.length){ if(T[j].kind===x.track.kind&&!T[j].locked){ dest=T[j]; break; } j+=dir; }
      if(!dest) return X.say("No "+x.track.kind+" track "+(dir<0?"above":"below")+" for “"+(x.clip.name||"a clip")+"”. Add one first",3200);
      plan.push({clip:x.clip,from:x.track,to:dest});
    }
    var moving={}; plan.forEach(function(p){ moving[p.clip.id]=1; });
    var bad=plan.some(function(p){
      var c=p.clip; return p.to.clips.some(function(k){ return !moving[k.id]&&k.start<c.start+c.duration-0.001&&k.start+k.duration>c.start+0.001; })
        || plan.some(function(q){ return q!==p&&q.to===p.to&&q.clip.start<c.start+c.duration-0.001&&q.clip.start+q.clip.duration>c.start+0.001; });
    });
    if(bad) return X.say("That would put a clip on top of another one on the "+(dir<0?"upper":"lower")+" track",3200);
    window.transact("Move clips "+(dir<0?"up":"down")+" a track",function(){
      plan.forEach(function(p){ p.from.clips=p.from.clips.filter(function(k){ return k!==p.clip; }); });
      plan.forEach(function(p){ p.to.clips.push(p.clip); });
      plan.forEach(function(p){ p.to.clips.sort(function(a,b){ return a.start-b.start; }); });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(plan.length+" clip"+(plan.length>1?"s":"")+" moved "+(dir<0?"up":"down")+" to “"+plan[0].to.name+"”"+(new Set(plan.map(function(p){ return p.to; })).size>1?" and others":""),2400);
  };
  X.addShortcut("Alt+Up / Alt+Down","Move the selected clips to the track above / below");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(!ev.altKey||ev.ctrlKey||ev.metaKey||ev.shiftKey) return;
    var d=ev.code==="ArrowUp"?-1:ev.code==="ArrowDown"?1:0; if(!d) return;
    ev.preventDefault(); ev.stopImmediatePropagation(); X.moveToTrack(d);
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Move clips to the track above","amiyoX.moveToTrack(-1)"],["Move clips to the track below","amiyoX.moveToTrack(1)"]]); };
  window.AMIYO_EDITOR_BUILD="step87-movetrack";
}catch(e){console.warn("step87",e)}})();

;
/* ==================== Script 268 id="amiyo-step88" ==================== */
/* Step 88: The Batch tools window can now take new tools. Every tool is one row (name, shortcut, what it needs, a Run
   button) in X.batchTools, and X.addBatchTool(...) adds a row without touching the window code - later steps use it.
   This step also puts the three tools that were built after the window (Exact length, Swap, Move to track above /
   below) into the list, so nothing you have built is missing from it. */
(function(){try{
  var X=window.amiyoX; if(!X||!X.batchTools) return;
  X.addBatchTool=function(name,keys,needs,fn,label){
    var T=X.batchTools; for(var i=0;i<T.length;i++) if(T[i][0]===name) return;
    T.push([name,keys,needs||"",fn,label||"Run"]);
  };
  X.addBatchTool("Exact length for many clips","Alt+D","select clips",function(){ X.lengthDialog(); },"Open");
  X.addBatchTool("Swap two selected clips","Alt+S","select exactly 2",function(){ X.swapClips(); },"Run");
  X.addBatchTool("Move clips to the track above","Alt+↑","select clips",function(){ X.moveToTrack(-1); },"Run");
  X.addBatchTool("Move clips to the track below","Alt+↓","select clips",function(){ X.moveToTrack(1); },"Run");
  window.AMIYO_EDITOR_BUILD="step88-batchlist";
}catch(e){console.warn("step88",e)}})();

;
/* ==================== Script 269 id="amiyo-step89" ==================== */
/* Step 89: Align selected clips to the playhead (Alt+A) - choose Start, End or Centre: every selected clip is moved so that
   edge sits exactly on the playhead. Clips keep their length. Refused (nothing moves) if a track is locked, a clip would
   start before 0:00, or clips would land on top of each other or of an unselected clip. One Undo step. Also in Batch tools. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  X.alignToPlayhead=function(mode){
    var l=X.sel(); if(!l.length) return X.say("Select one or more clips first",2200);
    if(l.some(function(x){ return x.track.locked; })) return X.say("A selected clip is on a locked track",2400);
    var t=currentTime, plan=[], moving={};
    l.forEach(function(x){ moving[x.clip.id]=1; });
    l.forEach(function(x){
      var d=x.clip.duration, ns=mode==="end"?t-d:mode==="center"?t-d/2:t; ns=r3(ns);
      plan.push({x:x,ns:ns,d:d});
    });
    if(plan.some(function(p){ return p.ns<-0.0005; })) return X.say("That would put a clip before 0:00. Move the playhead later",3000);
    var bad=plan.some(function(p){
      return p.x.track.clips.some(function(k){ return !moving[k.id]&&k.start<p.ns+p.d-0.001&&k.start+k.duration>p.ns+0.001; })
        || plan.some(function(q){ return q!==p&&q.x.track===p.x.track&&q.ns<p.ns+p.d-0.001&&q.ns+q.d>p.ns+0.001; });
    });
    if(bad) return X.say("Clips would land on top of each other. Select one clip per track, or move the playhead",3600);
    if(plan.every(function(p){ return Math.abs(p.x.clip.start-p.ns)<0.0005; })) return X.say("Already aligned there",1800);
    window.transact("Align "+plan.length+" clip"+(plan.length>1?"s":"")+" to playhead ("+(mode||"start")+")",function(){
      plan.forEach(function(p){ p.x.clip.start=Math.max(0,p.ns); });
      var seen=new Set(); plan.forEach(function(p){ if(seen.has(p.x.track)) return; seen.add(p.x.track); p.x.track.clips.sort(function(a,b){ return a.start-b.start; }); });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(plan.length+" clip"+(plan.length>1?"s":"")+" aligned: "+(mode==="end"?"end":mode==="center"?"centre":"start")+" at the playhead",2400);
  };
  X.alignDialog=function(){
    var n=X.sel().length; if(!n) return X.say("Select one or more clips first",2200);
    openModal("Align to playhead",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+n+' clip'+(n>1?'s':'')+' selected. Move the playhead where you want them, then pick which edge goes there.</div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="chip xal" data-m="start" style="min-height:44px;padding:0 14px">Start here</button><button type="button" class="chip xal" data-m="center" style="min-height:44px;padding:0 14px">Centre here</button><button type="button" class="chip xal" data-m="end" style="min-height:44px;padding:0 14px">End here</button></div>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="topbtn" id="xalNo" type="button">Close</button></div>');
    [].forEach.call(document.querySelectorAll(".xal"),function(b){ b.onclick=function(){ closeModal(); X.alignToPlayhead(b.dataset.m); }; });
    document.getElementById("xalNo").onclick=closeModal;
  };
  X.addShortcut("Alt+A","Align the selected clips to the playhead (start, centre or end)");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyA"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.alignDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Align clips to playhead…","amiyoX.alignDialog()"],["Align clip starts to playhead","amiyoX.alignToPlayhead('start')"],["Align clip ends to playhead","amiyoX.alignToPlayhead('end')"]]); };
  if(X.addBatchTool) X.addBatchTool("Align clips to the playhead","Alt+A","select clips",function(){ X.alignDialog(); },"Open");
  window.AMIYO_EDITOR_BUILD="step89-align";
}catch(e){console.warn("step89",e)}})();

;
/* ==================== Script 270 id="amiyo-step90" ==================== */
/* Step 90: Snap clip starts to a grid (Alt+G) - pick a grid (1 frame, 0.1, 0.25, 0.5, 1, 5 seconds, or your own number) and
   every selected clip's start moves to the nearest grid line. Lengths stay the same. A clip that would land on another
   clip tries the other neighbouring line, and is left where it is if neither fits; the message counts what was left.
   Locked tracks are skipped. One Undo step. Also in Batch tools. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  X._grid=X._grid||0.5;
  X.snapToGrid=function(step){
    step=+step; if(!(step>=0.01&&step<=600)) return X.say("Type a grid between 0.01 and 600 seconds",2600);
    X._grid=step;
    var all=X.sel(); if(!all.length) return X.say("Select one or more clips first",2200);
    var l=all.filter(function(x){ return !x.track.locked; }), lockedN=all.length-l.length;
    if(!l.length) return X.say("Every selected clip is on a locked track",2400);
    l.sort(function(a,b){ return a.clip.start-b.clip.start; });
    var pos=new Map(); project.tracks.forEach(function(t){ t.clips.forEach(function(c){ pos.set(c,c.start); }); });
    var plan=[], left=0, same=0;
    function free(tr,c,s){ return !tr.clips.some(function(k){ if(k===c) return false; var ks=pos.get(k); return ks<s+c.duration-0.001&&ks+k.duration>s+0.001; }); }
    l.forEach(function(x){
      var c=x.clip, q=c.start/step, near=Math.max(0,r3(Math.round(q)*step));
      if(Math.abs(near-c.start)<0.0005){ same++; return; }
      var alt=r3((Math.round(q)===Math.floor(q)?Math.ceil(q):Math.floor(q))*step);
      var pick=null; if(free(x.track,c,near)) pick=near; else if(alt>=0&&Math.abs(alt-c.start)>=0.0005&&free(x.track,c,alt)) pick=alt;
      if(pick===null){ left++; return; }
      pos.set(c,pick); plan.push({c:c,tr:x.track,s:pick});
    });
    if(!plan.length) return X.say(same&&!left?"Those clips are already on the grid":"No clip could move without landing on another clip",2800);
    window.transact("Snap "+plan.length+" clip start"+(plan.length>1?"s":"")+" to "+step+" s grid",function(){
      var seen=new Set(); plan.forEach(function(p){ p.c.start=p.s; seen.add(p.tr); });
      seen.forEach(function(t){ t.clips.sort(function(a,b){ return a.start-b.start; }); });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(plan.length+" clip start"+(plan.length>1?"s":"")+" snapped to the "+step+" s grid"+(left?" ("+left+" left, no room)":"")+(lockedN?" ("+lockedN+" on locked tracks skipped)":""),3200);
  };
  X.gridDialog=function(){
    var n=X.sel().length; if(!n) return X.say("Select one or more clips first",2200);
    var fps=(project.settings&&project.settings.fps)||30, f=r3(1/fps);
    var P=[[f,"1 frame"],[0.1,"0.1 s"],[0.25,"0.25 s"],[0.5,"0.5 s"],[1,"1 s"],[5,"5 s"]];
    openModal("Snap starts to a grid",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+n+' clip'+(n>1?'s':'')+' selected. Each start moves to the nearest grid line (0:00 is the first line). Lengths do not change.</div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap">'+P.map(function(p){ return '<button type="button" class="chip xgp" data-v="'+p[0]+'" style="min-height:44px;padding:0 14px">'+p[1]+'</button>'; }).join("")+'</div>'
      +'<label class="field" for="xgV" style="margin-top:12px">Or type a grid (seconds)</label><input id="xgV" type="number" min="0.01" max="600" step="0.01" value="'+X._grid+'" inputmode="decimal" style="min-height:44px;font-size:16px">'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xgNo" type="button">Cancel</button><button class="topbtn primary" id="xgGo" type="button">Snap</button></div>');
    var inp=document.getElementById("xgV");
    function go(v){ closeModal(); X.snapToGrid(v); }
    [].forEach.call(document.querySelectorAll(".xgp"),function(b){ b.onclick=function(){ go(b.dataset.v); }; });
    document.getElementById("xgGo").onclick=function(){ go(inp.value); }; document.getElementById("xgNo").onclick=closeModal;
    inp.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(inp.value); } e.stopPropagation(); });
  };
  X.addShortcut("Alt+G","Snap the selected clips' starts to a time grid");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyG"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.gridDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Snap clip starts to a grid…","amiyoX.gridDialog()"]]); };
  if(X.addBatchTool) X.addBatchTool("Snap clip starts to a grid","Alt+G","select clips",function(){ X.gridDialog(); },"Open");
  window.AMIYO_EDITOR_BUILD="step90-grid";
}catch(e){console.warn("step90",e)}})();

;
/* ==================== Script 271 id="amiyo-step91" ==================== */
/* Step 91: Disable and enable clips without deleting them (Alt+E). A disabled clip stays on the timeline (greyed and striped)
   but is hidden in the preview and silent in playback and in every export (video, WAV). Alt+E flips the selected clips:
   if any selected clip is on, all are switched off; if all are already off, all are switched on. "Enable every clip" turns
   everything back on. Locked tracks are skipped. One Undo step. Saved with the project. Also in Batch tools. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  var st=document.createElement("style"); st.id="amiyo-off-css";
  st.textContent=".clip.x-off{opacity:.4!important;filter:grayscale(1)!important;background-image:repeating-linear-gradient(135deg,rgba(0,0,0,.4) 0 6px,transparent 6px 12px)!important}";
  document.head.appendChild(st);
  function mark(){
    try{
      var m={}; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.off) m[c.id]=1; }); });
      [].forEach.call(document.querySelectorAll("#tracks .clip"),function(el){ var o=!!m[el.dataset.clip]; el.classList.toggle("x-off",o); if(o&&el.title.indexOf("(disabled)")<0) el.title=(el.title?el.title+" ":"")+"(disabled)"; });
    }catch(e){window.__swl&&window.__swl(e)}
  }
  var rt=window.renderTracks; if(typeof rt==="function") window.renderTracks=function(){ var r=rt.apply(this,arguments); mark(); return r; };
  function refresh(){ try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)} try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} mark(); }
  X.setClipsEnabled=function(mode){
    var pool;
    if(mode==="all"){ pool=[]; project.tracks.forEach(function(t){ if(t.locked) return; t.clips.forEach(function(c){ if(c.off) pool.push({track:t,clip:c}); }); }); if(!pool.length) return X.say("No clip is disabled",2000); }
    else{
      var all=X.sel(); if(!all.length) return X.say("Select one or more clips first",2200);
      pool=all.filter(function(x){ return !x.track.locked; }); if(!pool.length) return X.say("Every selected clip is on a locked track",2400);
    }
    var turnOff=mode==="all"?false:mode==="off"?true:mode==="on"?false:pool.some(function(x){ return !x.clip.off; });
    var n=0;
    window.transact((turnOff?"Disable ":"Enable ")+pool.length+" clip"+(pool.length>1?"s":""),function(){
      pool.forEach(function(x){ if(turnOff){ if(!x.clip.off){ x.clip.off=true; n++; } } else if(x.clip.off){ delete x.clip.off; n++; } });
    });
    refresh();
    X.say(n?n+" clip"+(n>1?"s":"")+(turnOff?" disabled (still on the timeline, hidden and silent)":" enabled"):"Nothing changed",2800);
  };
  X.addShortcut("Alt+E","Disable / enable the selected clips");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyE"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.setClipsEnabled("toggle"); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Disable / enable selected clips","amiyoX.setClipsEnabled('toggle')"],["Enable every clip","amiyoX.setClipsEnabled('all')"]]); };
  if(X.addBatchTool){
    X.addBatchTool("Disable / enable selected clips","Alt+E","select clips",function(){ X.setClipsEnabled("toggle"); },"Run");
    X.addBatchTool("Enable every clip","palette","",function(){ X.setClipsEnabled("all"); },"Run");
  }
  window.addEventListener("amiyo-booted",function(){ setTimeout(mark,300); },{once:true}); setTimeout(mark,600);
  window.AMIYO_EDITOR_BUILD="step91-disable";
}catch(e){console.warn("step91",e)}})();

;
/* ==================== Script 272 id="amiyo-step92" ==================== */
/* Step 92: Export the clip list as a CSV file (Alt+C). One row per clip: track, clip name, type, source file, start / end /
   length in seconds and as timecode, speed, volume, disabled, locked. Choose every clip or only the selected ones. Opens in
   Excel, Sheets or Numbers. Names that start with = + - @ are protected so a spreadsheet will not run them as a formula. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function tc(s){ s=Math.max(0,s); var h=Math.floor(s/3600), m=Math.floor(s%3600/60), x=s-h*3600-m*60; return h+":"+(m<10?"0":"")+m+":"+(x<10?"0":"")+x.toFixed(3); }
  function cell(v){
    v=v==null?"":String(v); if(/^[=+\-@\t\r]/.test(v)) v="'"+v;
    return /[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;
  }
  function typeOf(t,c){
    if(c.kind==="text") return "title"; if(c.kind==="caption"||t.kind==="caption") return "caption"; if(c.kind==="adjustment") return "adjustment"; if(c.kind==="graphic") return "graphic";
    var a=project.assets&&project.assets[c.assetId], ty=a&&a.type;
    return ty==="image"?"picture":ty==="audio"?"sound":ty==="video"?"video":(t.kind==="audio"?"sound":t.kind||"clip");
  }
  X.clipListCsv=function(onlySel){
    var selIds={}; if(onlySel) X.sel().forEach(function(x){ selIds[x.clip.id]=1; });
    var rows=[];
    project.tracks.forEach(function(t,ti){ t.clips.forEach(function(c){
      if(onlySel&&!selIds[c.id]) return;
      var a=project.assets&&project.assets[c.assetId];
      rows.push({ti:ti,t:t,c:c,a:a});
    }); });
    rows.sort(function(p,q){ return p.c.start-q.c.start||p.ti-q.ti; });
    var head=["#","Track","Track type","Clip","Type","Source file","Start (s)","End (s)","Length (s)","Start timecode","End timecode","Speed","Volume","Disabled","Track locked"];
    var out=[head.map(cell).join(",")];
    rows.forEach(function(r,i){
      var c=r.c, end=c.start+c.duration;
      var nm=c.name||(r.a&&r.a.name)||c.text||"";
      out.push([i+1,r.t.name,r.t.kind,String(nm).replace(/\s+/g," ").slice(0,120),typeOf(r.t,c),r.a?r.a.name:"",r3(c.start),r3(end),r3(c.duration),tc(c.start),tc(end),
        c.speed==null?1:r3(c.speed),c.volume==null?1:r3(c.volume),c.off?"yes":"no",r.t.locked?"yes":"no"].map(cell).join(","));
    });
    return {text:"\uFEFF"+out.join("\r\n")+"\r\n",count:rows.length};
  };
  X.exportClipCsv=function(onlySel){
    var r=X.clipListCsv(!!onlySel);
    if(!r.count) return X.say(onlySel?"Select one or more clips first":"There are no clips to list yet",2400);
    var base=String((project.metadata&&project.metadata.name)||"amiyo-edit").replace(/[^\w\- ]+/g,"_").trim()||"amiyo-edit";
    try{
      var a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([r.text],{type:"text/csv;charset=utf-8"}));
      a.download=base+(onlySel?"-selected-clips":"-clips")+".csv"; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){ URL.revokeObjectURL(a.href); },4000);
      X.say("Clip list saved: "+r.count+" clip"+(r.count>1?"s":"")+" ("+a.download+")",3200);
    }catch(e){ X.say("Could not save the file: "+((e&&e.message)||e),4200); }
  };
  X.csvDialog=function(){
    var n=X.sel().length, tot=0; project.tracks.forEach(function(t){ tot+=t.clips.length; });
    if(!tot) return X.say("There are no clips to list yet",2400);
    openModal("Export clip list (CSV)",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">A spreadsheet file with one row per clip: track, name, type, source file, start, end, length, speed, volume and whether it is disabled.</div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="chip xcv" data-s="0" style="min-height:44px;padding:0 14px">All clips ('+tot+')</button><button type="button" class="chip xcv" data-s="1" style="min-height:44px;padding:0 14px"'+(n?'':' disabled')+'>Selected only ('+n+')</button></div>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="topbtn" id="xcvNo" type="button">Close</button></div>');
    [].forEach.call(document.querySelectorAll(".xcv"),function(b){ b.onclick=function(){ closeModal(); X.exportClipCsv(b.dataset.s==="1"); }; });
    document.getElementById("xcvNo").onclick=closeModal;
  };
  X.addShortcut("Alt+C","Export the clip list as a CSV file");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&ev.code==="KeyC"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.csvDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Export clip list (CSV)…","amiyoX.csvDialog()"]]); };
  if(X.addBatchTool) X.addBatchTool("Export clip list as CSV","Alt+C","",function(){ X.csvDialog(); },"Open");
  window.AMIYO_EDITOR_BUILD="step92-csv";
}catch(e){console.warn("step92",e)}})();

