/* ==================== Script 273 id="amiyo-step93" ==================== */
/* Step 93: Saved timeline views (Alt+V). A view remembers how the timeline is zoomed and where it is scrolled (sideways as a
   time, up and down as a track position). Save up to 12 per project - "Whole film", "Intro close-up", "Credits" - and jump
   back with one tap. Alt+Shift+V saves the current view at once. Views are saved with the project, rename or delete any
   time, and each one is also in the Ctrl+K palette. Changing the view does not touch the edit, so it adds no Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return; var MAX=12;
  function esc(s){ return String(s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  function list(){ if(!Array.isArray(project.timelineViews)) project.timelineViews=[]; return project.timelineViews; }
  function sc(){ return document.getElementById("timelineScroll"); }
  function r2(v){ return Math.round(v*100)/100; }
  function save(name){
    var s=sc(); if(!s) return X.say("The timeline is not ready yet",2200);
    var L=list(); if(L.length>=MAX) return X.say("A project holds "+MAX+" views. Delete one first",3000);
    var v={id:uid("view"),name:String(name||("View "+(L.length+1))).trim().slice(0,40)||("View "+(L.length+1)),zoom:Math.round(timelineZoom),left:r2(s.scrollLeft/getTimelinePx()),top:Math.round(s.scrollTop)};
    L.push(v); try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)}
    X.say("View “"+v.name+"” saved (zoom "+v.zoom+"%)",2600); return v;
  }
  X.saveView=function(name){ return save(name); };
  X.goView=function(id){
    var v=list().filter(function(x){ return x.id===id; })[0]; if(!v) return X.say("That view no longer exists",2400);
    var s=sc(); if(!s) return;
    timelineZoom=Math.min(AZ_MAX,Math.max(AZ_MIN,+v.zoom||timelineZoom));
    var zs=document.getElementById("timelineZoom"); if(zs) zs.value=timelineZoom;
    try{ renderTimeline(); }catch(e){window.__swl&&window.__swl(e)}
    s.scrollLeft=Math.max(0,(+v.left||0)*getTimelinePx()); s.scrollTop=Math.max(0,+v.top||0);
    X.say("View “"+v.name+"”",1600);
  };
  X.viewsDialog=function(){
    var L=list();
    openModal("Timeline views",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">A view is the zoom and scroll position of the timeline. Set the timeline how you like it, then save it.</div>'
      +'<button type="button" class="topbtn primary" id="xvSave" style="min-height:44px;width:100%"'+(L.length>=MAX?' disabled':'')+'>Save current view</button>'
      +'<div style="display:flex;flex-direction:column;gap:6px;margin-top:10px;max-height:50vh;overflow:auto">'
      +(L.length?L.map(function(v,i){ return '<div style="display:flex;align-items:center;gap:6px;padding:6px 8px;border:1px solid var(--line);border-radius:10px"><div style="flex:1;min-width:0"><div style="font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(v.name)+'</div><div style="font-size:11px;color:var(--muted)">zoom '+v.zoom+'% · from '+v.left+' s</div></div>'
        +'<button type="button" class="chip xvg" data-i="'+i+'" style="min-height:44px;min-width:56px">Go</button><button type="button" class="chip xvr" data-i="'+i+'" aria-label="Rename view" style="min-height:44px;min-width:44px">✎</button><button type="button" class="chip xvd" data-i="'+i+'" aria-label="Delete view" style="min-height:44px;min-width:44px">×</button></div>'; }).join(""):'<div style="font-size:12px;color:var(--muted);padding:8px">No saved views yet.</div>')
      +'</div><div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xvNo" type="button">Close</button></div>');
    document.getElementById("xvNo").onclick=closeModal;
    document.getElementById("xvSave").onclick=function(){
      Promise.resolve(window.amiyoAsk?window.amiyoAsk("Name this view","View "+(L.length+1),{okLabel:"Save"}):("View "+(L.length+1))).then(function(n){ if(n==null) return; save(n); X.viewsDialog(); });
    };
    [].forEach.call(document.querySelectorAll(".xvg"),function(b){ b.onclick=function(){ var v=L[+b.dataset.i]; closeModal(); if(v) X.goView(v.id); }; });
    [].forEach.call(document.querySelectorAll(".xvr"),function(b){ b.onclick=function(){ var v=L[+b.dataset.i]; if(!v) return;
      Promise.resolve(window.amiyoAsk?window.amiyoAsk("Rename view",v.name,{okLabel:"Rename"}):v.name).then(function(n){ if(n!=null&&String(n).trim()){ v.name=String(n).trim().slice(0,40); try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} } X.viewsDialog(); }); }; });
    [].forEach.call(document.querySelectorAll(".xvd"),function(b){ b.onclick=function(){ var i=+b.dataset.i; if(!L[i]) return; L.splice(i,1); try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} X.viewsDialog(); }; });
  };
  X.addShortcut("Alt+V","Timeline views: save and jump between zoom / scroll positions");
  X.addShortcut("Alt+Shift+V","Save the current timeline view");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&!ev.ctrlKey&&!ev.metaKey&&ev.code==="KeyV"){ ev.preventDefault(); ev.stopImmediatePropagation(); if(ev.shiftKey) save(); else X.viewsDialog(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){
    var base=oc.apply(this,arguments).concat([["Timeline views…","amiyoX.viewsDialog()"],["Save current timeline view","amiyoX.saveView()"]]);
    try{ list().forEach(function(v){ base.push(["Go to view: "+v.name,"amiyoX.goView('"+v.id+"')"]); }); }catch(e){window.__swl&&window.__swl(e)}
    return base; };
  if(X.addBatchTool) X.addBatchTool("Timeline views (save / go to)","Alt+V","",function(){ X.viewsDialog(); },"Open");
  window.AMIYO_EDITOR_BUILD="step93-views";
}catch(e){console.warn("step93",e)}})();

