/* ==================== Script 274 id="amiyo-step94" ==================== */
/* Step 94: Cut everything before or after the playhead, on all tracks at once (Alt+X opens it; Alt+, = cut before,
   Alt+. = cut after). Clips that cross the playhead are trimmed (picture, sound, fades and keyframes follow the cut),
   clips wholly on the cut side are removed, and transitions left dangling are cleared. "Close the gap" (on by default) moves
   what is left back to 0:00 when cutting before, and shifts the markers with it. Locked tracks are never touched; if a
   locked track has clips, the gap is not closed so nothing slips out of sync. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  if(X._cutRipple==null) X._cutRipple=true;
  function shiftKf(list,d){
    if(!list||!list.length) return list;
    var out=[],carry=null; list.forEach(function(k){ var n=Object.assign({},k); n.t=r3(k.t-d); if(n.t<0){ carry=n; } else out.push(n); });
    if(carry){ carry.t=0; if(!out.length||out[0].t>0) out.unshift(carry); }
    return out;
  }
  function tidyTransitions(tr){
    tr.clips.sort(function(a,b){ return a.start-b.start; });
    tr.clips.forEach(function(c,i){
      if(c.transitionIn){ var p=tr.clips[i-1]; if(!p||p.start+p.duration<=c.start+0.001) c.transitionIn=null; }
      if(c.transitionOut){ var n=tr.clips[i+1]; if(!n||n.start>=c.start+c.duration-0.001) c.transitionOut=null; }
    });
  }
  X.cutAtPlayhead=function(side,ripple){
    var t=r3(currentTime), SLIVER=0.04;
    if(side!=="before"&&side!=="after") return;
    if(side==="before"&&t<=0.01) return X.say("Move the playhead later. There is nothing before 0:00",2600);
    var lockedHas=project.tracks.some(function(tr){ return tr.locked&&tr.clips.length; });
    var rip=side==="before"&&ripple!==false&&!lockedHas;
    var plan=[], removed=0, trimmed=0, skipped=0;
    project.tracks.forEach(function(tr){
      if(tr.locked){ skipped+=tr.clips.length; return; }
      tr.clips.forEach(function(c){
        var s=c.start, e=c.start+c.duration;
        if(side==="before"){
          if(e<=t+SLIVER){ plan.push({tr:tr,c:c,a:"del"}); removed++; }
          else if(s<t-0.001){ plan.push({tr:tr,c:c,a:"trim"}); trimmed++; }
          else plan.push({tr:tr,c:c,a:"keep"});
        } else {
          if(s>=t-SLIVER){ plan.push({tr:tr,c:c,a:"del"}); removed++; }
          else if(e>t+0.001){ plan.push({tr:tr,c:c,a:"trim"}); trimmed++; }
        }
      });
    });
    if(!removed&&!trimmed) return X.say("Nothing to cut "+side+" the playhead",2400);
    var removedIds={};
    window.transact("Cut everything "+side+" the playhead",function(){
      plan.forEach(function(p){
        var c=p.c;
        if(p.a==="del"){ removedIds[c.id]=1; return; }
        if(p.a==="trim"){
          var el=t-c.start, ratio=el/c.duration, srcDur=(c.outPoint!=null&&c.inPoint!=null)?c.outPoint-c.inPoint:null;
          if(side==="before"){
            if(srcDur!=null) c.inPoint=r3(c.inPoint+srcDur*ratio);
            c.start=t; c.duration=r3(c.duration-el); c.transitionIn=null;
            if(c.keyframes) c.keyframes=shiftKf(c.keyframes,el);
            if(c.volumeKeyframes) c.volumeKeyframes=shiftKf(c.volumeKeyframes,el);
            if(c.fadeIn) c.fadeIn=0;
          } else {
            if(srcDur!=null) c.outPoint=r3(c.inPoint+srcDur*ratio);
            c.duration=r3(el); c.transitionOut=null;
            if(c.fadeOut) c.fadeOut=0;
          }
          if(c.fadeIn) c.fadeIn=Math.min(c.fadeIn,c.duration*0.9); if(c.fadeOut) c.fadeOut=Math.min(c.fadeOut,c.duration*0.9);
        }
      });
      project.tracks.forEach(function(tr){
        if(tr.locked) return;
        tr.clips=tr.clips.filter(function(c){ return !removedIds[c.id]; });
        if(rip) tr.clips.forEach(function(c){ c.start=Math.max(0,r3(c.start-t)); });
        tidyTransitions(tr);
      });
      if(rip&&Array.isArray(project.markers)){
        project.markers=project.markers.filter(function(m){ return m.time>=t-0.001; }).map(function(m){ m.time=Math.max(0,r3(m.time-t)); return m; });
      }
      if(removedIds[selectedClipId]) selectedClipId=null;
    });
    if(rip){ try{ setCurrentTime(0); }catch(e){window.__swl&&window.__swl(e)} }
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    try{ renderMarkerStrip(); }catch(e){window.__swl&&window.__swl(e)}
    X.say("Cut "+side+" the playhead: "+removed+" clip"+(removed===1?"":"s")+" removed, "+trimmed+" trimmed"+(rip?"; gap closed":(side==="before"&&lockedHas&&ripple!==false?"; gap not closed (a locked track has clips)":""))+(skipped?" ("+skipped+" on locked tracks left alone)":""),4200);
  };
  X.cutDialog=function(){
    var t=r3(currentTime);
    openModal("Cut at the playhead",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">Playhead at '+t.toFixed(2)+' s. Cuts every unlocked track at once. Undo brings everything back.</div>'
      +'<label style="display:flex;gap:8px;align-items:center;margin:0 0 12px;font-size:13px"><input id="xcR" type="checkbox"'+(X._cutRipple?' checked':'')+' style="width:20px;height:20px"> Close the gap (cut before only)</label>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="chip xcb" data-s="before" style="min-height:44px;padding:0 14px">Cut everything before</button><button type="button" class="chip xcb" data-s="after" style="min-height:44px;padding:0 14px">Cut everything after</button></div>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="topbtn" id="xcNo" type="button">Close</button></div>');
    [].forEach.call(document.querySelectorAll(".xcb"),function(b){ b.onclick=function(){ X._cutRipple=document.getElementById("xcR").checked; closeModal(); X.cutAtPlayhead(b.dataset.s,X._cutRipple); }; });
    document.getElementById("xcNo").onclick=closeModal;
  };
  X.addShortcut("Alt+X","Cut everything before / after the playhead on all tracks");
  X.addShortcut("Alt+, / Alt+.","Cut everything before / after the playhead (no window)");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(!ev.altKey||ev.ctrlKey||ev.metaKey||ev.shiftKey) return;
    if(ev.code==="KeyX"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.cutDialog(); }
    else if(ev.code==="Comma"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.cutAtPlayhead("before",X._cutRipple); }
    else if(ev.code==="Period"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.cutAtPlayhead("after"); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Cut at the playhead…","amiyoX.cutDialog()"],["Cut everything before the playhead","amiyoX.cutAtPlayhead('before')"],["Cut everything after the playhead","amiyoX.cutAtPlayhead('after')"]]); };
  if(X.addBatchTool){
    X.addBatchTool("Cut before / after the playhead","Alt+X","all tracks",function(){ X.cutDialog(); },"Open");
  }
  window.AMIYO_EDITOR_BUILD="step94-cutplayhead";
}catch(e){console.warn("step94",e)}})();

;
/* ==================== Script 275 id="amiyo-step95" ==================== */
/* Step 95: Batch tools window - search box and "ready / not ready" rows. Type a few letters (snap, cut, csv...) and only the
   matching tools stay. A tool that needs something you have not done yet (clips selected, exactly 2 clips, In and Out set)
   is dimmed and says what is missing, so you do not press Run and get an error. Tools still open the same way. */
(function(){try{
  var X=window.amiyoX; if(!X||!X.batchTools) return;
  function esc(s){ return String(s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  function io(){ try{ var r=window.amiyoGetIO&&window.amiyoGetIO(); return !!(r&&r.i!=null&&r.o!=null&&r.o>r.i); }catch(e){ return false; } }
  function missing(needs,n){
    needs=String(needs||"");
    if(needs==="select clips") return n>=1?"":"select clips first";
    if(needs==="select exactly 2") return n===2?"":"select exactly 2 clips";
    if(needs.indexOf("select 2+")===0) return n>=2?"":"select 2 or more clips";
    if(needs==="needs In and Out") return io()?"":"set In and Out first";
    return "";
  }
  X.toolMissing=missing;
  X.batchDialog=function(){
    var T=X.batchTools, n=X.sel().length;
    openModal("Batch tools",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:8px">'+(n?n+' clip'+(n>1?'s':'')+' selected.':'No clips selected.')+' '+T.length+' tools. Each also works from its shortcut or the Ctrl+K palette.</div>'
      +'<input id="xbQ" type="search" placeholder="Search tools (snap, cut, csv...)" autocomplete="off" style="width:100%;min-height:44px;font-size:16px;margin-bottom:8px;box-sizing:border-box">'
      +'<div id="xbList" style="display:flex;flex-direction:column;gap:6px;max-height:55vh;overflow:auto"></div>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="topbtn" id="xbNo" type="button">Close</button></div>');
    var box=document.getElementById("xbQ"), list=document.getElementById("xbList");
    function draw(){
      var q=box.value.trim().toLowerCase(), rows=[];
      T.forEach(function(t,i){
        if(q&&(t[0]+" "+t[1]+" "+t[2]).toLowerCase().indexOf(q)<0) return;
        var m=missing(t[2],n);
        rows.push('<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;border:1px solid var(--line);border-radius:10px;'+(m?'opacity:.55':'')+'"><div style="flex:1;min-width:0"><div style="font-size:13px">'+esc(t[0])+'</div><div style="font-size:11px;color:var(--muted)">'+esc(t[1])+(m?' · <b>'+esc(m)+'</b>':(t[2]?' · '+esc(t[2]):''))+'</div></div><button type="button" class="chip xbt" data-i="'+i+'" style="min-height:44px;min-width:64px">'+esc(t[4]||"Run")+'</button></div>');
      });
      list.innerHTML=rows.length?rows.join(""):'<div style="font-size:13px;color:var(--muted);padding:10px">No tool matches “'+esc(q)+'”.</div>';
      [].forEach.call(list.querySelectorAll(".xbt"),function(b){ b.onclick=function(){ var f=T[+b.dataset.i][3]; closeModal(); setTimeout(f,0); }; });
    }
    box.addEventListener("input",draw); box.addEventListener("keydown",function(e){ if(e.key==="Enter"){ var b=list.querySelector(".xbt"); if(b) b.click(); } e.stopPropagation(); });
    document.getElementById("xbNo").onclick=closeModal; draw();
  };
  var btn=document.getElementById("batchBtn"); if(btn) btn.onclick=X.batchDialog;
  window.AMIYO_EDITOR_BUILD="step95-batchsearch";
}catch(e){console.warn("step95",e)}})();

;
/* ==================== Script 276 id="amiyo-step96" ==================== */
/* Step 96: Align "One after another" - the old Align tool refused when selected clips on the same track would land on top of
   each other. Now the Align window has a fourth choice: the first clip of each track starts at the playhead and the others
   follow it with no gaps, in their old order. Refused only if a locked track is involved or the result would hit a clip you did
   not select. Also in the Batch window and the Ctrl+K palette. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X||!X.alignToPlayhead) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  X.alignChain=function(){
    var l=X.sel(); if(!l.length) return X.say("Select one or more clips first",2200);
    if(l.some(function(x){ return x.track.locked; })) return X.say("A selected clip is on a locked track",2400);
    var t=r3(currentTime), by=new Map(), moving={}, plan=[];
    l.forEach(function(x){ moving[x.clip.id]=1; if(!by.has(x.track)) by.set(x.track,[]); by.get(x.track).push(x.clip); });
    by.forEach(function(list,tr){ list.sort(function(a,b){ return a.start-b.start; }); var p=t; list.forEach(function(c){ plan.push({tr:tr,c:c,ns:r3(p),d:c.duration}); p+=c.duration; }); });
    var bad=plan.some(function(p){ return p.tr.clips.some(function(k){ return !moving[k.id]&&k.start<p.ns+p.d-0.001&&k.start+k.duration>p.ns+0.001; }); });
    if(bad) return X.say("The chain would run into a clip you did not select. Move the playhead or select that clip too",3800);
    if(plan.every(function(p){ return Math.abs(p.c.start-p.ns)<0.0005; })) return X.say("Already lined up there",1800);
    window.transact("Line up "+plan.length+" clip"+(plan.length>1?"s":"")+" from playhead",function(){
      plan.forEach(function(p){ p.c.start=p.ns; });
      by.forEach(function(list,tr){ tr.clips.sort(function(a,b){ return a.start-b.start; }); });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(plan.length+" clip"+(plan.length>1?"s":"")+" lined up one after another from the playhead",2600);
  };
  X.alignDialog=function(){
    var n=X.sel().length; if(!n) return X.say("Select one or more clips first",2200);
    var b='min-height:44px;padding:0 14px';
    openModal("Align to playhead",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+n+' clip'+(n>1?'s':'')+' selected. Move the playhead where you want them, then choose.</div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="chip xal" data-m="start" style="'+b+'">Start here</button><button type="button" class="chip xal" data-m="center" style="'+b+'">Centre here</button><button type="button" class="chip xal" data-m="end" style="'+b+'">End here</button><button type="button" class="chip xal" data-m="chain" style="'+b+'">One after another</button></div>'
      +'<div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="topbtn" id="xalNo" type="button">Close</button></div>');
    [].forEach.call(document.querySelectorAll(".xal"),function(x){ x.onclick=function(){ closeModal(); if(x.dataset.m==="chain") X.alignChain(); else X.alignToPlayhead(x.dataset.m); }; });
    document.getElementById("xalNo").onclick=closeModal;
  };
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Line up clips one after another from playhead","amiyoX.alignChain()"]]); };
  if(X.addBatchTool) X.addBatchTool("Line up clips one after another","palette","select clips",function(){ X.alignChain(); },"Run");
  window.AMIYO_EDITOR_BUILD="step96-alignchain";
}catch(e){console.warn("step96",e)}})();

