/* ==================== Script 277 id="amiyo-step97" ==================== */
/* Step 97: Snap clip LENGTHS to a grid. The Grid window (Alt+G) has a new tick box, "Snap lengths instead of starts". Each
   selected clip's length becomes the nearest whole number of grid steps (never shorter than one step). Video and sound clips
   stop at the end of their file; if the nearest length would hit the next clip, the next smaller one is tried, and a clip with
   no room is left alone. The message counts changed and left clips. Starts do not move. Locked tracks skipped. One Undo step. */
(function(){try{
  var X=window.amiyoX; if(!X||!X.snapToGrid) return;
  function r3(v){ return Math.round(v*1000)/1000; }
  function asset(c){ return project.assets&&project.assets[c.assetId]; }
  function isMedia(c){ var a=asset(c); return a&&(a.type==="video"||a.type==="audio")&&a.duration>0; }
  X.snapLengthsToGrid=function(step){
    step=+step; if(!(step>=0.01&&step<=600)) return X.say("Type a grid between 0.01 and 600 seconds",2600);
    X._grid=step;
    var all=X.sel(); if(!all.length) return X.say("Select one or more clips first",2200);
    var l=all.filter(function(x){ return !x.track.locked; }); if(!l.length) return X.say("Every selected clip is on a locked track",2400);
    l.sort(function(a,b){ return a.clip.start-b.clip.start; });
    var plan=[], left=0, same=0;
    l.forEach(function(x){
      var c=x.clip, sp=c.speed||1, max=Infinity;
      if(isMedia(c)) max=(asset(c).duration-(c.inPoint||0))/sp;
      var nxt=Infinity; x.track.clips.forEach(function(k){ if(k!==c&&k.start>=c.start+0.001&&k.start<nxt) nxt=k.start; });
      var room=Math.min(max+0.001,nxt-c.start+0.001), q=c.duration/step, n=Math.max(1,Math.round(q)), pick=null;
      for(;n>=1;n--){ var d=r3(n*step); if(d<=room){ pick=d; break; } }
      if(pick===null){ left++; return; }
      if(Math.abs(pick-c.duration)<0.0005){ same++; return; }
      plan.push({c:c,d:pick,sp:sp});
    });
    if(!plan.length) return X.say(same&&!left?"Those lengths are already on the grid":"No clip could change without hitting another clip or its file end",3000);
    window.transact("Snap "+plan.length+" clip length"+(plan.length>1?"s":"")+" to "+step+" s grid",function(){
      plan.forEach(function(p){ var c=p.c; c.duration=p.d; if(isMedia(c)||c.outPoint!=null) c.outPoint=r3((c.inPoint||0)+p.d*p.sp); });
    });
    try{ updateAudioPlayback(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(plan.length+" length"+(plan.length>1?"s":"")+" snapped to the "+step+" s grid"+(left?" ("+left+" left, no room)":""),3000);
  };
  X.gridDialog=function(){
    var n=X.sel().length; if(!n) return X.say("Select one or more clips first",2200);
    var fps=(project.settings&&project.settings.fps)||30, f=r3(1/fps);
    var P=[[f,"1 frame"],[0.1,"0.1 s"],[0.25,"0.25 s"],[0.5,"0.5 s"],[1,"1 s"],[5,"5 s"]];
    openModal("Snap to a grid",'<div style="font-size:12px;color:var(--muted);line-height:1.45;margin-bottom:10px">'+n+' clip'+(n>1?'s':'')+' selected. Starts (or lengths) move to the nearest grid step.</div>'
      +'<label style="display:flex;gap:8px;align-items:center;margin:0 0 10px;font-size:13px"><input id="xgL" type="checkbox"'+(X._gridLen?' checked':'')+' style="width:20px;height:20px"> Snap lengths instead of starts</label>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap">'+P.map(function(p){ return '<button type="button" class="chip xgp" data-v="'+p[0]+'" style="min-height:44px;padding:0 14px">'+p[1]+'</button>'; }).join("")+'</div>'
      +'<label class="field" for="xgV" style="margin-top:12px">Or type a grid (seconds)</label><input id="xgV" type="number" min="0.01" max="600" step="0.01" value="'+X._grid+'" inputmode="decimal" style="min-height:44px;font-size:16px">'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="topbtn" id="xgNo" type="button">Cancel</button><button class="topbtn primary" id="xgGo" type="button">Snap</button></div>');
    var inp=document.getElementById("xgV"), cb=document.getElementById("xgL");
    function go(v){ X._gridLen=cb.checked; closeModal(); if(X._gridLen) X.snapLengthsToGrid(v); else X.snapToGrid(v); }
    [].forEach.call(document.querySelectorAll(".xgp"),function(b){ b.onclick=function(){ go(b.dataset.v); }; });
    document.getElementById("xgGo").onclick=function(){ go(inp.value); }; document.getElementById("xgNo").onclick=closeModal;
    inp.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(inp.value); } e.stopPropagation(); });
  };
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Snap clip lengths to the grid","amiyoX.snapLengthsToGrid(amiyoX._grid)"]]); };
  if(X.addBatchTool) X.addBatchTool("Snap clip lengths to the grid","Alt+G","select clips",function(){ X._gridLen=true; X.gridDialog(); },"Open");
  window.AMIYO_EDITOR_BUILD="step97-gridlength";
}catch(e){console.warn("step97",e)}})();

