/* ==================== Script 278 id="amiyo-step98" ==================== */
/* Step 98: Find your disabled clips. "Select disabled clips" (Alt+Shift+E) selects every clip that is switched off, on all
   tracks, so you can turn them back on with Alt+E, delete them or look at them one by one. The Batch button in the top bar
   now shows how many clips are disabled (for example "🧰 Batch · 3 off"), and the number goes away when none are left.
   Also in the Batch window and the Ctrl+K palette. */
(function(){try{
  var X=window.amiyoX; if(!X||!X.setClipsEnabled) return;
  function offList(){ var o=[]; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.off) o.push({t:t,c:c}); }); }); return o; }
  X.selectDisabled=function(){
    var l=offList();
    project.tracks.forEach(function(t){ t.clips.forEach(function(c){ c.selected=false; }); });
    if(!l.length){ selectedClipId=null; try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)} return X.say("No clip is disabled",2000); }
    l.sort(function(a,b){ return a.c.start-b.c.start; });
    l.forEach(function(x){ x.c.selected=true; }); selectedClipId=l[0].c.id; try{ selectedTrackId=l[0].t.id; }catch(e){window.__swl&&window.__swl(e)}
    try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)}
    X.say(l.length+" disabled clip"+(l.length>1?"s":"")+" selected. Alt+E turns them back on",3000);
  };
  var baseLabel=null;
  function badge(){
    try{
      var b=document.getElementById("batchBtn"); if(!b) return;
      if(baseLabel===null) baseLabel=b.textContent.replace(/\s*·.*$/,"");
      var n=offList().length; b.textContent=baseLabel+(n?" · "+n+" off":"");
      b.title="Batch tools (Alt+B)"+(n?" - "+n+" disabled clip"+(n>1?"s":""):"");
    }catch(e){window.__swl&&window.__swl(e)}
  }
  var rt=window.renderTracks; if(typeof rt==="function") window.renderTracks=function(){ var r=rt.apply(this,arguments); badge(); return r; };
  setTimeout(badge,700); window.addEventListener("amiyo-booted",function(){ setTimeout(badge,400); },{once:true});
  X.addShortcut("Alt+Shift+E","Select every disabled clip");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.altKey&&ev.shiftKey&&!ev.ctrlKey&&!ev.metaKey&&ev.code==="KeyE"){ ev.preventDefault(); ev.stopImmediatePropagation(); X.selectDisabled(); }
  },true);
  var oc=window.commandList; if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Select disabled clips","amiyoX.selectDisabled()"]]); };
  if(X.addBatchTool) X.addBatchTool("Select disabled clips","Alt+Shift+E","",function(){ X.selectDisabled(); },"Run");
  window.AMIYO_EDITOR_BUILD="step98-finddisabled";
}catch(e){console.warn("step98",e)}})();

