    if(R.mic){ try{ var m=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}}); R.others.push(m); audio.push(m); }catch(e){ R.msg="Microphone was not allowed, so only the screen is recorded."; } }
