    var auto=[]; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.assetId===a.id) auto.push({t:t,c:c}); }); });   /* some import wrappers auto-place a 5 s clip: reuse or remove it so there is never a duplicate */
