/* ==================== Script 287 id="amiyo-step107-multicam-sync" ==================== */
/* Step 6 — Multicam: "Auto-sync by audio".
   Listens to the sound of each camera angle, finds where it lines up with Angle 1 (envelope cross-correlation, then a
   sample-accurate refinement) and moves each angle's clips (and anything linked to them) by that amount. One undo step. */
(function(){
"use strict";
var SR=8000, ENV=200, MAXSEC=90, SEARCH=60, MINOVER=8, MAXMB=150;
function say(m){ try{ (window.notify||window.toast)(m); }catch(e){window.__swl&&window.__swl(e)} }
function tick(){ return new Promise(function(r){ setTimeout(r,16); }); }

/* ---------- small FFT (radix-2, in place) ---------- */
function fft(re,im,inv){
  var n=re.length, i, j=0, k, t;
  for(i=1;i<n;i++){ var bit=n>>1; for(;j&bit;bit>>=1) j^=bit; j^=bit; if(i<j){ t=re[i];re[i]=re[j];re[j]=t; t=im[i];im[i]=im[j];im[j]=t; } }
  for(var len=2;len<=n;len<<=1){
    var ang=2*Math.PI/len*(inv?-1:1), wr=Math.cos(ang), wi=Math.sin(ang), half=len>>1;
    for(i=0;i<n;i+=len){
      var cr=1, ci=0;
      for(k=0;k<half;k++){
        var a=i+k, b=a+half, xr=re[b]*cr-im[b]*ci, xi=re[b]*ci+im[b]*cr;
        re[b]=re[a]-xr; im[b]=im[a]-xi; re[a]+=xr; im[a]+=xi;
        var nr=cr*wr-ci*wi; ci=cr*wi+ci*wr; cr=nr;
      }
    }
  }
  if(inv){ for(i=0;i<n;i++){ re[i]/=n; im[i]/=n; } }
}
function pow2(n){ var p=1; while(p<n) p<<=1; return p; }

/* ---------- loudness envelope: 5 ms steps, with the slow level removed so bursts and claps stand out ---------- */
function envelope(x){
  var step=Math.round(SR/ENV), n=Math.floor(x.length/step), e=new Float64Array(n), i, j;
  for(i=0;i<n;i++){ var s=0, o=i*step; for(j=0;j<step;j++) s+=Math.abs(x[o+j]); e[i]=Math.sqrt(s/step); }
  var w=ENV, pre=new Float64Array(n+1); for(i=0;i<n;i++) pre[i+1]=pre[i]+e[i];
  var out=new Float64Array(n), sq=0;
  for(i=0;i<n;i++){ var a=Math.max(0,i-w), b=Math.min(n,i+w+1), m=(pre[b]-pre[a])/(b-a); out[i]=e[i]-m; sq+=out[i]*out[i]; }
  var sd=Math.sqrt(sq/Math.max(1,n)); if(!(sd>1e-9)) return null;
  for(i=0;i<n;i++) out[i]/=sd;
  return out;
}
function pearson(a,b,lag){
  var k0=Math.max(0,-lag), k1=Math.min(b.length,a.length-lag), n=k1-k0; if(n<ENV*MINOVER) return {r:0,n:n};
  var ma=0, mb=0, k; for(k=k0;k<k1;k++){ ma+=a[k+lag]; mb+=b[k]; } ma/=n; mb/=n;
  var sab=0, saa=0, sbb=0; for(k=k0;k<k1;k++){ var x=a[k+lag]-ma, y=b[k]-mb; sab+=x*y; saa+=x*x; sbb+=y*y; }
  return {r:(saa>0&&sbb>0)?sab/Math.sqrt(saa*sbb):0,n:n};
}
/* when does the sound of B happen, relative to the same sound in A?  Returns seconds d: B at time t  ==  A at time t+d */
function offset(rawA,rawB){
  var ea=envelope(rawA), eb=envelope(rawB); if(!ea||!eb) return null;
  var size=pow2(ea.length+eb.length), ar=new Float64Array(size), ai=new Float64Array(size), br=new Float64Array(size), bi=new Float64Array(size), i;
  ar.set(ea); br.set(eb); fft(ar,ai,false); fft(br,bi,false);
  for(i=0;i<size;i++){ var re=ar[i]*br[i]+ai[i]*bi[i], im=ai[i]*br[i]-ar[i]*bi[i]; ar[i]=re; ai[i]=im; }
  fft(ar,ai,true);
  var L=SEARCH*ENV, best=-Infinity, bl=0, lag, sc=new Float64Array(2*L+1);
  for(lag=-L;lag<=L;lag++){
    var k0=Math.max(0,-lag), k1=Math.min(eb.length,ea.length-lag), n=k1-k0; if(n<ENV*MINOVER){ sc[lag+L]=-Infinity; continue; }
    var v=ar[(lag+size)%size]/n; sc[lag+L]=v; if(v>best){ best=v; bl=lag; }
  }
  if(best===-Infinity) return null;
  var second=-Infinity; for(lag=-L;lag<=L;lag++){ if(Math.abs(lag-bl)>ENV/2&&sc[lag+L]>second) second=sc[lag+L]; }
  var prom=(second>0)?best/second:99;
  var p=pearson(ea,eb,bl), d=bl/ENV;
  /* fine step: compare the raw waveforms within +-12 ms of the coarse answer */
  try{
    var S=Math.round(0.012*SR), t0=Math.max(0,-d)+0.3, W=Math.min(10,rawB.length/SR-t0-0.1,rawA.length/SR-(t0+d)-0.1);
    if(W>=2){
      var b0=Math.round(t0*SR), a0=Math.round((t0+d)*SR), N=Math.round(W*SR), bs=-Infinity, bsft=0, s, n2;
      for(s=-S;s<=S;s++){
        if(a0+s<0||a0+s+N>rawA.length) continue;
        var acc=0; for(n2=0;n2<N;n2+=2) acc+=rawB[b0+n2]*rawA[a0+n2+s];
        if(acc>bs){ bs=acc; bsft=s; }
      }
      d+=bsft/SR;
    }
  }catch(e){window.__swl&&window.__swl(e)}
  return {d:d,r:p.r,prom:prom,overlap:p.n/ENV};
}

/* ---------- reading the sound of a clip ---------- */
var cache=new Map();
async function decode(asset){
  if(cache.has(asset.id)) return cache.get(asset.id);
  var url=await ensureUrl(asset); if(!url) throw new Error("no file");
  var ab=await (await fetch(url)).arrayBuffer();
  var OAC=window.OfflineAudioContext||window.webkitOfflineAudioContext;
  var buf=await new OAC(1,1,SR).decodeAudioData(ab);
  var ch=buf.numberOfChannels, len=buf.length, mono=new Float32Array(len), c, i;
  for(c=0;c<ch;c++){ var d=buf.getChannelData(c); for(i=0;i<len;i++) mono[i]+=d[i]/ch; }
  cache.set(asset.id,mono); return mono;
}
async function rawFor(clip){
  var a=getAsset(clip.assetId); if(!a||(a.type!=="video"&&a.type!=="audio")) return {err:"has no sound"};
  if(a.size&&a.size>MAXMB*1048576) return {err:"is too large to analyse here ("+Math.round(a.size/1048576)+" MB)"};
  var mono; try{ mono=await decode(a); }catch(e){ return {err:"could not be read"}; }
  var from=Math.round(Math.max(0,clip.inPoint||0)*SR), to=Math.min(mono.length,from+MAXSEC*SR);
  if(to-from<SR*MINOVER) return {err:"is too short"};
  return {raw:mono.slice(from,to)};
}

/* ---------- running it ---------- */
var busy=false, msg="";
function setMsg(t){ msg=t; var el=document.getElementById("mcAutoMsg"); if(el) el.textContent=t; }
function tr(id){ return project.tracks.filter(function(t){ return t.id===id; })[0]; }
function firstClip(t){ return t&&t.clips.slice().sort(function(a,b){ return a.start-b.start; })[0]; }
async function run(){
  if(busy) return;
  var grp=(typeof multicamGroup7!=="undefined"?multicamGroup7:[]).map(tr).filter(Boolean);
  if(grp.length<2){ say("Add at least two angles first"); return; }
  busy=true; var btn=document.getElementById("mcAutoBtn"); if(btn) btn.disabled=true;
  var lines=[], moves=[];
  try{
    cache.clear();
    var refT=grp[0], refC=firstClip(refT);
    if(!refC){ setMsg("Angle 1 has no clip."); return; }
    setMsg("Reading Angle 1…"); await tick();
    var ref=await rawFor(refC);
    if(ref.err){ setMsg("Angle 1 ("+refT.name+") "+ref.err+". Auto-sync needs sound on every angle."); return; }
    for(var i=1;i<grp.length;i++){
      var t=grp[i], c=firstClip(t), label="Angle "+(i+1);
      if(!c){ lines.push(label+": no clip"); continue; }
      if((c.speed||1)!==1||(refC.speed||1)!==1){ lines.push(label+": skipped (speed is not 100%)"); continue; }
      setMsg("Listening to "+label+" ("+i+"/"+(grp.length-1)+")…"); await tick();
      var b=await rawFor(c); if(b.err){ lines.push(label+" "+b.err); continue; }
      await tick();
      var o=offset(ref.raw,b.raw);
      if(!o||o.r<0.3||(o.prom<1.35&&o.r<0.55)){ lines.push(label+": no matching sound found — sync it by hand"); continue; }
      var delta=(refC.start+o.d)-c.start;
      moves.push({track:t,delta:delta});
      lines.push(label+": moved "+(delta>=0?"+":"−")+Math.abs(delta).toFixed(3)+" s ("+(o.r>=0.5&&o.prom>=1.35?"good match":"weak match — please check")+")");
    }
    if(!moves.length){ setMsg(lines.join("  ·  ")||"Nothing to sync."); say("No angles could be synced"); return; }
    transact("Auto-sync multicam by audio",function(){
      var moved=new Set();
      moves.forEach(function(m){
        m.track.clips.forEach(function(c){ moved.add(c); });
        project.tracks.forEach(function(t2){ t2.clips.forEach(function(c2){ if(c2.linkId&&m.track.clips.some(function(c){ return c.linkId===c2.linkId; })) moved.add(c2); }); });
      });
      var byClip=new Map();
      moves.forEach(function(m){ m.track.clips.forEach(function(c){ byClip.set(c,m.delta); }); });
      moved.forEach(function(c){
        var d=byClip.get(c); if(d==null){ var m2=moves.filter(function(m){ return m.track.clips.some(function(k){ return k.linkId&&k.linkId===c.linkId; }); })[0]; d=m2?m2.delta:0; }
        c.start=Math.max(0,+(c.start+d).toFixed(4));
      });
    });
    setMsg(lines.join("  ·  ")); say("Angles synced by audio");
  }catch(e){
    setMsg("Auto-sync stopped: "+(e&&e.message||e)); try{ console.error(e); }catch(x){window.__swl&&window.__swl(x)}
  }finally{
    busy=false; cache.clear(); var b2=document.getElementById("mcAutoBtn"); if(b2) b2.disabled=false;
  }
}
function inject(){
  if(activePanel!=="multicam") return;
  var sync=document.getElementById("mcSyncBtn"); if(!sync||document.getElementById("mcAutoBtn")) return;
  var ready=(typeof multicamGroup7!=="undefined"&&multicamGroup7.length>=2);
  var wrap=document.createElement("div");
  wrap.innerHTML='<button type="button" class="chip" id="mcAutoBtn" '+(ready&&!busy?"":"disabled")+' style="width:100%;margin-top:6px;min-height:40px">🔊 Auto-sync by audio</button>'+
   '<div id="mcAutoMsg" role="status" style="font-size:10px;color:var(--muted);margin-top:4px;line-height:1.5">'+(msg?"":"Matches the sound of each angle to Angle 1 (a clap or any shared noise works best). Angle 1 stays where it is.")+'</div>';
  sync.parentNode.insertBefore(wrap.children[1],sync.nextSibling);
  sync.parentNode.insertBefore(wrap.children[0],sync.nextSibling);
  var m=document.getElementById("mcAutoMsg"); if(m&&msg) m.textContent=msg;
  document.getElementById("mcAutoBtn").onclick=run;
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){ var r=prev.apply(this,arguments); try{ inject(); }catch(e){ try{ console.error(e); }catch(x){window.__swl&&window.__swl(x)} } return r; };
window.amiyoSyncCore={offset:offset,envelope:envelope};
try{ window.AMIYO_EDITOR_BUILD="step107-multicam-audio-sync"; }catch(e){window.__swl&&window.__swl(e)}
try{ if(activePanel==="multicam") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

