/* ==================== Script 288 id="amiyo-step108-media" ==================== */
/* Step 7 — Media panel: real picture thumbnails (video frame, photo, audio waveform) that are made one at a time, kept on the
   device and never leave a live <video> in every tile; plus duplicate detection (on import, and a "Find duplicates" scan with
   a one-tap merge that re-points clips to the copy you keep). */
(function(){
"use strict";
var TW=192, TH=108, TICK=function(ms){ return new Promise(function(r){ setTimeout(r,ms||16); }); };
function say(m){ try{ (window.notify||window.toast)(m); }catch(e){window.__swl&&window.__swl(e)} }
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }

/* ================= thumbnails ================= */
var mem=new Map(), failed=new Set(), queued=new Set(), queue=[], running=false, db=null;
function sig(a){ return (a.size||0)+"|"+(a.name||""); }
function openDb(){
  if(db) return db;
  db=new Promise(function(res){
    try{ var r=indexedDB.open("amiyo-thumbs",1); r.onupgradeneeded=function(){ r.result.createObjectStore("t"); }; r.onsuccess=function(){ res(r.result); }; r.onerror=function(){ res(null); }; r.onblocked=function(){ res(null); }; }catch(e){ res(null); }
  });
  return db;
}
async function dbGet(id){ try{ var d=await openDb(); if(!d) return null; return await new Promise(function(res){ var q=d.transaction("t","readonly").objectStore("t").get(id); q.onsuccess=function(){ res(q.result||null); }; q.onerror=function(){ res(null); }; }); }catch(e){ return null; } }
async function dbPut(id,v){ try{ var d=await openDb(); if(!d) return; d.transaction("t","readwrite").objectStore("t").put(v,id); }catch(e){window.__swl&&window.__swl(e)} }
function once(el,ev,ms){
  return new Promise(function(res){
    var done=false, t=setTimeout(function(){ fin(false); },ms||6000);
    function fin(v){ if(done) return; done=true; clearTimeout(t); el.removeEventListener(ev,ok); el.removeEventListener("error",bad); res(v); }
    function ok(){ fin(true); } function bad(){ fin(false); }
    el.addEventListener(ev,ok); el.addEventListener("error",bad);
  });
}
function cover(src,sw,sh){
  var c=document.createElement("canvas"); c.width=TW; c.height=TH; var x=c.getContext("2d");
  x.fillStyle="#1d1a15"; x.fillRect(0,0,TW,TH);
  var k=Math.max(TW/sw,TH/sh), dw=sw*k, dh=sh*k; x.drawImage(src,(TW-dw)/2,(TH-dh)/2,dw,dh);
  return c;
}
function luma(c){ try{ var d=c.getContext("2d").getImageData(0,0,TW,TH).data, s=0, n=0; for(var i=0;i<d.length;i+=64){ s+=d[i]*.3+d[i+1]*.59+d[i+2]*.11; n++; } return s/n; }catch(e){ return 99; } }
async function videoThumb(a){
  var url=assetUrl(a.id); if(!url) return null;
  var v=document.createElement("video"); v.muted=true; v.playsInline=true; v.preload="auto"; v.src=url;
  try{
    if(!(await once(v,"loadeddata",7000))) return null;
    var dur=isFinite(v.duration)?v.duration:(a.duration||1), c=null, tries=[Math.min(Math.max(.1,dur*.1),3),Math.min(dur*.4,12)];
    for(var i=0;i<tries.length;i++){
      v.currentTime=tries[i]; if(!(await once(v,"seeked",6000))) break;
      if(!v.videoWidth) break; c=cover(v,v.videoWidth,v.videoHeight);
      if(luma(c)>10) break;                      /* skip black opening frames */
    }
    return c?c.toDataURL("image/jpeg",.72):null;
  }finally{ try{ v.removeAttribute("src"); v.load(); }catch(e){window.__swl&&window.__swl(e)} }
}
async function imageThumb(a){
  var url=assetUrl(a.id); if(!url) return null;
  var im=new Image(); im.src=url;
  try{ await im.decode(); }catch(e){ if(!(await once(im,"load",6000))) return null; }
  if(!im.naturalWidth) return null;
  var d=cover(im,im.naturalWidth,im.naturalHeight).toDataURL("image/jpeg",.75); im.src=""; return d;
}
async function audioThumb(a){
  if(a.size&&a.size>80*1048576) return null;
  var b=ASSET_BLOBS.get(a.id); if(!b){ var url=assetUrl(a.id); if(!url) return null; b=await (await fetch(url)).blob(); }
  var OAC=window.OfflineAudioContext||window.webkitOfflineAudioContext, buf=await new OAC(1,1,8000).decodeAudioData(await b.arrayBuffer());
  var ch=buf.getChannelData(0), N=48, step=Math.max(1,Math.floor(ch.length/N)), peaks=[], mx=1e-6, i, j;
  for(i=0;i<N;i++){ var m=0; for(j=i*step;j<Math.min(ch.length,(i+1)*step);j+=4){ var v=Math.abs(ch[j]); if(v>m) m=v; } peaks.push(m); if(m>mx) mx=m; }
  var c=document.createElement("canvas"); c.width=TW; c.height=TH; var x=c.getContext("2d");
  x.fillStyle="#2b1e17"; x.fillRect(0,0,TW,TH); x.fillStyle="#ff945f"; var bw=TW/N;
  peaks.forEach(function(p,k){ var h=Math.max(3,(p/mx)*(TH-24)); x.fillRect(k*bw+1,(TH-h)/2,bw-2,h); });
  return c.toDataURL("image/jpeg",.8);
}
function paint(id,url){
  document.querySelectorAll('.asset[data-asset="'+id+'"] .thumb').forEach(function(th){
    var old=th.querySelector(".amt,.amt-ph,video,img:not(.amt)"); var im=document.createElement("img"); im.className="amt"; im.alt=""; im.src=url;
    if(old&&old.parentNode===th) th.replaceChild(im,old); else th.insertBefore(im,th.firstChild);
  });
}
async function make(a){
  var rec=await dbGet(a.id);
  if(rec&&rec.sig===sig(a)&&rec.u){ mem.set(a.id,rec.u); paint(a.id,rec.u); return; }
  if(typeof amiyoAssetMissing==="function"&&amiyoAssetMissing(a.id)) return;
  var u=null; try{ u=a.type==="video"?await videoThumb(a):a.type==="image"?await imageThumb(a):a.type==="audio"?await audioThumb(a):null; }catch(e){ u=null; }
  if(!u){ failed.add(a.id); return; }
  mem.set(a.id,u); paint(a.id,u); dbPut(a.id,{u:u,sig:sig(a)});
}
async function pump(){
  if(running) return; running=true;
  try{ while(queue.length){ var id=queue.shift(), a=project.assets[id]; queued.delete(id); if(a&&!mem.has(id)) { try{ await make(a); }catch(e){window.__swl&&window.__swl(e)} await TICK(40); } } }
  finally{ running=false; }
}
function want(a){ if(mem.has(a.id)||failed.has(a.id)||queued.has(a.id)) return; queued.add(a.id); queue.push(a.id); setTimeout(pump,0); }
var origThumb=window.thumbHTML;
window.thumbHTML=function(a){
  var base=""; try{ base=origThumb(a); }catch(e){ base=""; }
  var m=base.match(/<button[^>]*asset-add[\s\S]*?<\/button>/), btn=m?m[0]:"";
  var u=mem.get(a.id); if(!u) want(a);
  var icon=a.type==="audio"?"🎵":a.type==="video"?"🎬":"🖼";
  return (u?'<img class="amt" src="'+u+'" alt="">':'<span class="amt-ph" aria-hidden="true">'+icon+'</span>')+btn;
};
(function css(){
  var s=document.createElement("style"); s.id="amiyo-media-css";
  s.textContent=".thumb .amt{width:100%;height:100%;object-fit:cover;display:block}.thumb .amt-ph{font-size:24px;opacity:.45;animation:amtp 1.4s ease-in-out infinite}@keyframes amtp{50%{opacity:.15}}"+
   ".thumb[data-dup]::before{content:attr(data-dup);position:absolute;left:4px;top:4px;z-index:2;background:#ff9f1c;color:#1a1208;font-size:10px;font-weight:800;padding:2px 6px;border-radius:99px}"+
   "#mtDup .mt-row{display:flex;align-items:center;gap:8px;padding:6px 0;border-top:1px solid var(--line);font-size:11px}#mtDup .mt-row img{width:44px;height:25px;object-fit:cover;border-radius:4px;flex:none;background:#000}"+
   "#mtDup .mt-row span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media (prefers-reduced-motion:reduce){.thumb .amt-ph{animation:none}}";
  document.head.appendChild(s);
})();

/* ================= duplicates ================= */
async function fpOf(blob){
  var n=blob.size, sl=[blob.slice(0,65536)];
  if(n>131072){ var m=Math.floor(n/2)-32768; sl.push(blob.slice(m,m+65536)); sl.push(blob.slice(n-65536)); } else if(n>65536) sl.push(blob.slice(65536));
  var h=0x811c9dc5;
  for(var k=0;k<sl.length;k++){ var u=new Uint8Array(await sl[k].arrayBuffer()); for(var i=0;i<u.length;i++){ h^=u[i]; h=Math.imul(h,16777619)>>>0; } }
  return n+"-"+h.toString(16);
}
async function blobOf(a){
  var b=ASSET_BLOBS.get(a.id); if(b) return b;
  var url=assetUrl(a.id); if(!url) return null;
  try{ return await (await fetch(url)).blob(); }catch(e){ return null; }
}
async function assetFp(a){
  if(a.fp) return a.fp;
  var b=await blobOf(a); if(!b) return null;
  var f=await fpOf(b); a.fp=f; return f;
}
var origImport=window.importFiles;
window.importFiles=async function(files){
  var list=[].slice.call(files||[]), fps=new Map(), before=new Set(Object.keys(project.assets));
  try{
    var existing=Object.values(project.assets), dups=[];
    for(var i=0;i<list.length;i++){
      var f=list[i], t=(typeof mediaType==="function")?mediaType(f):null;
      var cand=existing.filter(function(a){ return a.size===f.size&&(!t||a.type===t); }); if(!cand.length) continue;
      var fp=await fpOf(f); fps.set(f,fp);
      for(var j=0;j<cand.length;j++){ if((await assetFp(cand[j]))===fp){ dups.push({file:f,of:cand[j]}); break; } }
    }
    if(dups.length){
      var names=dups.slice(0,3).map(function(d){ return "“"+d.file.name+"”"; }).join(", ")+(dups.length>3?" and "+(dups.length-3)+" more":"");
      var ok=await window.amiyoOk((dups.length===1?"This file is":"These "+dups.length+" files are")+" already in your media: "+names+".\nImport "+(dups.length===1?"it":"them")+" again anyway?",{okLabel:"Import anyway"});
      if(!ok){ list=list.filter(function(f){ return !dups.some(function(d){ return d.file===f; }); }); say(dups.length+(dups.length===1?" duplicate skipped":" duplicates skipped")); if(!list.length) return; }
    }
  }catch(e){ try{ console.warn("duplicate check",e); }catch(x){window.__swl&&window.__swl(x)} }
  var r=await origImport.call(this,list);
  try{ Object.values(project.assets).forEach(function(a){ if(before.has(a.id)||a.fp) return; var f=list.filter(function(f){ return f.name===a.name&&f.size===a.size; })[0]; if(f&&fps.get(f)) a.fp=fps.get(f); }); }catch(e){window.__swl&&window.__swl(e)}
  return r;
};

var dup=null, busy=false;          /* dup = {groups:[[assetId,...]], msg} */
function usesMap(){ var u={}; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.assetId) u[c.assetId]=(u[c.assetId]||0)+1; }); }); return u; }
function keeper(ids,u){
  var order=Object.keys(project.assets);
  return ids.slice().sort(function(x,y){
    var ax=project.assets[x], ay=project.assets[y];
    return ((u[y]||0)-(u[x]||0))||((ay.favorite?1:0)-(ax.favorite?1:0))||(order.indexOf(x)-order.indexOf(y));
  })[0];
}
async function scan(){
  if(busy) return; busy=true; setMsg("Checking your media…");
  try{
    var all=Object.values(project.assets), by=new Map();
    all.forEach(function(a){ var k=a.type+"|"+(a.size||0); if(!by.has(k)) by.set(k,[]); by.get(k).push(a); });
    var groups=[], n=0, total=0; by.forEach(function(arr){ if(arr.length>1) total+=arr.length; });
    for(const arr of by.values()){
      if(arr.length<2) continue; var fp=new Map();
      for(const a of arr){ var f=null; try{ f=await assetFp(a); }catch(e){window.__swl&&window.__swl(e)} n++; if(n%4===0){ setMsg("Checking your media… "+n+"/"+total); await TICK(); } if(!f) continue; if(!fp.has(f)) fp.set(f,[]); fp.get(f).push(a.id); }
      fp.forEach(function(ids){ if(ids.length>1) groups.push(ids); });
    }
    dup={groups:groups,msg:groups.length?"":"No duplicates found — every file is different."};
  }catch(e){ dup={groups:[],msg:"Could not finish checking: "+(e&&e.message||e)}; }
  finally{ busy=false; }
  try{ renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
  if(dup&&dup.groups.length) say(dup.groups.length+(dup.groups.length===1?" set":" sets")+" of duplicates found");
}
function setMsg(t){ var el=document.getElementById("mtScanMsg"); if(el) el.textContent=t; }
async function merge(){
  if(!dup||!dup.groups.length) return;
  var u=usesMap(), live=dup.groups.map(function(g){ return g.filter(function(id){ return project.assets[id]; }); }).filter(function(g){ return g.length>1; });
  var extra=live.reduce(function(s,g){ return s+g.length-1; },0); if(!extra){ dup=null; renderLeftPanel(); return; }
  var ok=await window.amiyoOk("Merge duplicates? "+extra+(extra===1?" extra copy":" extra copies")+" will be removed. Clips that use a copy are moved to the one you keep. You can undo this.",{okLabel:"Merge"}); if(!ok) return;
  transact("Merge duplicate media",function(){
    live.forEach(function(g){
      var keepId=keeper(g,u), keep=project.assets[keepId], others=g.filter(function(id){ return id!==keepId; });
      project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(others.indexOf(c.assetId)>=0) c.assetId=keepId; }); });
      others.forEach(function(id){
        var o=project.assets[id]; if(!o) return;
        (o.tags||[]).forEach(function(tg){ keep.tags=keep.tags||[]; if(keep.tags.indexOf(tg)<0) keep.tags.push(tg); });
        if(o.favorite) keep.favorite=true; if(!keep.binId&&o.binId) keep.binId=o.binId;
        delete project.assets[id];
      });
    });
  });
  try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)}
  dup=null; say(extra+(extra===1?" duplicate merged":" duplicates merged")); try{ renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
}
function card(){
  if(!dup) return "";
  var u=usesMap(), rows=dup.groups.map(function(g){
    var ids=g.filter(function(id){ return project.assets[id]; }); if(ids.length<2) return "";
    var k=keeper(ids,u), a=project.assets[k], th=mem.get(k);
    return '<div class="mt-row">'+(th?'<img src="'+th+'" alt="">':'<span style="flex:none;width:44px;text-align:center">'+(a.type==="audio"?"🎵":"🎬")+'</span>')+'<span><b>'+esc(a.name)+'</b><br>'+ids.length+' copies · keeps “'+esc(a.name)+'”'+(u[k]?' (used on the timeline)':'')+'</span></div>';
  }).join("");
  var n=dup.groups.length;
  return '<div class="panel-card" id="mtDup"><h3 style="margin:0 0 6px;font-size:12px">Duplicate media</h3>'+
    (n?'<div style="font-size:10px;color:var(--muted);margin-bottom:4px">'+n+(n===1?' set of identical files':' sets of identical files')+' (orange badges on the tiles).</div>'+rows+
       '<div class="mini-row" style="margin-top:8px;gap:6px"><button type="button" class="chip" id="mtMerge" style="min-height:38px">Merge duplicates</button><button type="button" class="chip" id="mtClose" style="min-height:38px">Dismiss</button></div>'
     :'<div style="font-size:11px;color:var(--muted)">'+esc(dup.msg||"")+'</div><div class="mini-row" style="margin-top:8px"><button type="button" class="chip" id="mtClose" style="min-height:38px">OK</button></div>')+'</div>';
}
function inject(){
  if(activePanel!=="media") return;
  var lp=document.getElementById("leftPanel"); if(!lp) return;
  var grid=lp.querySelector(".asset-grid"); if(!grid||lp.querySelector("#mtFind")) return;
  var bar=lp.querySelector(".md-bar")||lp.querySelector(".panel-card");
  var row=document.createElement("div"); row.className="md-row mini-row"; row.style.cssText="gap:6px;margin-top:6px;flex-wrap:wrap;align-items:center";
  row.innerHTML='<button type="button" class="chip" id="mtFind" style="min-height:38px">🔍 Find duplicates</button><span id="mtScanMsg" role="status" style="font-size:10.5px;color:var(--muted)"></span>';
  if(bar) bar.appendChild(row);
  document.getElementById("mtFind").onclick=function(){ if(Object.keys(project.assets).length<2){ say("You need at least two files to compare"); return; } scan(); };
  if(dup){ var w=document.createElement("div"); w.innerHTML=card(); if(w.firstChild) grid.parentNode.insertBefore(w.firstChild,grid);
    var mg=document.getElementById("mtMerge"); if(mg) mg.onclick=merge; var cl=document.getElementById("mtClose"); if(cl) cl.onclick=function(){ dup=null; renderLeftPanel(); };
    var u=usesMap(); dup.groups.forEach(function(g){ var ids=g.filter(function(id){ return project.assets[id]; }); if(ids.length<2) return; ids.forEach(function(id){ var th=lp.querySelector('.asset[data-asset="'+id+'"] .thumb'); if(th) th.setAttribute("data-dup","×"+ids.length); }); });
  }
}
var prev=window.bindLeftPanel;
window.bindLeftPanel=function(){ var r=prev.apply(this,arguments); try{ inject(); }catch(e){ try{ console.warn("Media dup",e); }catch(x){window.__swl&&window.__swl(x)} } return r; };
window.amiyoMedia={fpOf:fpOf,keeper:keeper};
try{ window.AMIYO_EDITOR_BUILD="step108-media"; }catch(e){window.__swl&&window.__swl(e)}
try{ if(activePanel==="media") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)}
})();

;
/* ==================== Script 289 id="amiyo-step109-backgrounds" ==================== */
/* Step 8 — Backgrounds: gradient or solid canvas background, 8 built-in gradients, and your own gradients that you can save,
   re-use and delete. Applies to the preview AND the export (same canvas). Undo works. Saved gradients live on this device. */
(function(){
"use strict";
var KEY="amiyoSavedGradients", MAXSAVED=24;
var BUILT=[
 {n:"Sunset",t:"linear",a:135,c:["#ff7a3d","#c2185b"]},{n:"Ocean",t:"linear",a:160,c:["#91380b","#dd5612"]},
 {n:"Forest",t:"linear",a:150,c:["#0f3d2e","#5fbf7a"]},{n:"Midnight",t:"linear",a:180,c:["#05060a","#6a3f2a"]},
 {n:"Peach",t:"linear",a:120,c:["#ffd1a6","#ff8fa3"]},{n:"Violet",t:"linear",a:135,c:["#3a1c71","#d76d77","#ffaf7b"]},
 {n:"Spotlight",t:"radial",a:0,c:["#3b4252","#0b0c0e"]},{n:"Aurora",t:"radial",a:0,c:["#6ee7b7","#9b3c0d"]}
];
var draft={t:"linear",a:135,c:["#ff9d6c","#3a251b"]};
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
function okHex(h){return /^#[0-9a-fA-F]{6}$/.test(h||"");}
function clean(g){
  if(!g||typeof g!=="object"||!Array.isArray(g.c)) return null;
  var c=g.c.filter(okHex).slice(0,3); if(c.length<2) return null;
  return {t:g.t==="radial"?"radial":"linear",a:Math.max(0,Math.min(360,+g.a||0)),c:c};
}
function css(g){
  var s=g.c.join(",");
  return g.t==="radial"?"radial-gradient(circle,"+s+")":"linear-gradient("+g.a+"deg,"+s+")";
}
function loadSaved(){ try{ var r=JSON.parse(localStorage.getItem(KEY)||"[]"); return Array.isArray(r)?r.map(function(x){var g=clean(x); if(g) g.n=String(x.n||"Custom").slice(0,24); return g;}).filter(Boolean):[]; }catch(e){ return []; } }
function storeSaved(l){ try{ localStorage.setItem(KEY,JSON.stringify(l.slice(0,MAXSAVED))); return true; }catch(e){ try{toast("Could not save: this browser blocks storage");}catch(_){window.__swl&&window.__swl(_)} return false; } }
function cur(){ return clean(project.settings&&project.settings.bgGradient); }

/* ---- canvas painting (preview + export share this canvas) ---- */
function paint(g,W,H){
  var f;
  if(g.t==="radial"){ f=ctx.createRadialGradient(W/2,H/2,0,W/2,H/2,Math.hypot(W,H)/2); }
  else{
    var r=g.a*Math.PI/180, dx=Math.sin(r), dy=-Math.cos(r), len=Math.abs(W*dx)+Math.abs(H*dy);
    f=ctx.createLinearGradient(W/2-dx*len/2,H/2-dy*len/2,W/2+dx*len/2,H/2+dy*len/2);
  }
  g.c.forEach(function(col,i){ f.addColorStop(g.c.length===1?0:i/(g.c.length-1),col); });
  ctx.fillStyle=f; ctx.fillRect(0,0,W,H);
}
var prevPlaceholder=window.drawPlaceholder;
window.drawPlaceholder=function(text,sub){
  var g=cur();
  if(!g) return prevPlaceholder.apply(this,arguments);
  paint(g,canvas.width,canvas.height);
  if(text){ ctx.fillStyle="#f9c9b1"; ctx.font="600 26px system-ui"; ctx.textAlign="center"; ctx.fillText(text,canvas.width/2,canvas.height/2-10); }
  if(sub){ ctx.fillStyle="#778394"; ctx.font="14px system-ui"; ctx.fillText(sub,canvas.width/2,canvas.height/2+20); }
};

/* ---- changing the project ---- */
function refresh(){ try{scheduleAutosave();}catch(e){window.__swl&&window.__swl(e)} try{renderPreviewFrame();}catch(e){window.__swl&&window.__swl(e)} try{ if(activePanel==="backgrounds") renderLeftPanel(); }catch(e){window.__swl&&window.__swl(e)} }
function applyGrad(g,label){
  g=clean(g); if(!g) return;
  transact("Background: "+label,function(){ project.settings.bgGradient={t:g.t,a:g.a,c:g.c.slice()}; });
  refresh(); try{toast(label+" background applied");}catch(e){window.__swl&&window.__swl(e)}
}
function applySolid(hex){
  if(!okHex(hex)) return;
  transact("Background: solid colour",function(){ project.settings.background=hex; project.settings.bgGradient=null; });
  refresh();
}

/* ---- the panel ---- */
function sw(g,extra){ return '<span style="display:block;height:34px;border-radius:7px;border:1px solid var(--line);background:'+css(g)+';'+(extra||'')+'"></span>'; }
function render(){
  var g=cur(), saved=loadSaved();
  var h='<div class="panel-card"><h3 style="margin:0 0 8px;font-size:12px">Canvas background</h3>'+
   '<div style="display:flex;gap:8px;align-items:center"><span style="flex:1">'+(g?sw(g):'<span style="display:block;height:34px;border-radius:7px;border:1px solid var(--line);background:'+esc(project.settings.background||"#080b10")+'"></span>')+'</span>'+
   '<input type="color" id="bgSolid" aria-label="Solid background colour" value="'+esc(okHex(project.settings.background)?project.settings.background:"#080b10")+'" style="width:44px;height:34px;padding:0;border:0;background:none">'+
   '</div><div style="font-size:10px;color:var(--muted);margin-top:6px">'+(g?"Gradient background. Pick a colour to go back to solid.":"Solid colour background.")+'</div></div>';
  h+='<div class="panel-card"><h3 style="margin:0 0 8px;font-size:12px">Gradients</h3><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px">';
  BUILT.forEach(function(b,i){ h+='<button type="button" class="chip bgb" data-b="'+i+'" style="padding:4px;min-height:52px;text-align:left">'+sw(b)+'<span style="font-size:10px">'+esc(b.n)+'</span></button>'; });
  h+='</div></div>';
  h+='<div class="panel-card" id="bgBuilder"><h3 style="margin:0 0 8px;font-size:12px">Make your own</h3><div id="bgPrev">'+sw(draft,"height:56px")+'</div>'+
   '<div class="mini-row" style="margin-top:8px;gap:6px;align-items:center">'+
   draft.c.map(function(c,i){return '<input type="color" class="bgc" data-i="'+i+'" aria-label="Colour '+(i+1)+'" value="'+c+'" style="width:44px;height:34px;padding:0;border:0;background:none">';}).join("")+
   (draft.c.length<3?'<button type="button" class="chip" id="bgAddStop" style="min-height:34px">+ colour</button>':'<button type="button" class="chip" id="bgDelStop" style="min-height:34px">− colour</button>')+
   '<select id="bgType" class="search" style="width:auto;min-height:34px"><option value="linear"'+(draft.t==="linear"?" selected":"")+'>Linear</option><option value="radial"'+(draft.t==="radial"?" selected":"")+'>Radial</option></select></div>'+
   '<div id="bgAngRow" style="margin-top:8px;'+(draft.t==="radial"?"display:none":"")+'"><label class="field" style="font-size:10px">Angle <span id="bgAngV">'+draft.a+'</span>°</label><input type="range" id="bgAng" min="0" max="360" value="'+draft.a+'" style="width:100%"></div>'+
   '<div class="mini-row" style="margin-top:8px;gap:6px"><button type="button" class="chip" id="bgApply" style="flex:1;min-height:36px">Apply</button><button type="button" class="chip" id="bgSave" style="flex:1;min-height:36px">Save gradient</button></div></div>';
  h+='<div class="panel-card"><h3 style="margin:0 0 8px;font-size:12px">My gradients ('+saved.length+')</h3>';
  if(!saved.length) h+='<div style="font-size:11px;color:var(--muted)">Nothing saved yet. Build one above and tap Save gradient.</div>';
  else{ h+='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px">'; saved.forEach(function(s,i){
    h+='<div style="position:relative"><button type="button" class="chip bgs" data-s="'+i+'" style="width:100%;padding:4px;min-height:52px;text-align:left">'+sw(s)+'<span style="font-size:10px">'+esc(s.n)+'</span></button>'+
       '<button type="button" class="bgdel" data-s="'+i+'" aria-label="Delete '+esc(s.n)+'" style="position:absolute;top:2px;right:2px;width:26px;height:26px;border-radius:50%;background:rgba(0,0,0,.6);color:#fff;font-size:13px">✕</button></div>'; });
    h+='</div>'; }
  return h+'</div>';
}
function bind(){
  var lp=document.getElementById("leftPanel"); if(!lp) return;
  function $q(s){return lp.querySelector(s);}
  function upd(){ $q("#bgPrev").innerHTML=sw(draft,"height:56px"); var v=$q("#bgAngV"); if(v) v.textContent=draft.a; }
  $q("#bgSolid").onchange=function(e){ applySolid(e.target.value); };
  lp.querySelectorAll(".bgb").forEach(function(b){ b.onclick=function(){ var g=BUILT[+b.dataset.b]; draft={t:g.t,a:g.a,c:g.c.slice()}; applyGrad(g,g.n); }; });
  lp.querySelectorAll(".bgc").forEach(function(i){ i.oninput=function(){ draft.c[+i.dataset.i]=i.value; upd(); }; });
  $q("#bgType").onchange=function(e){ draft.t=e.target.value; $q("#bgAngRow").style.display=draft.t==="radial"?"none":""; upd(); };
  $q("#bgAng").oninput=function(e){ draft.a=+e.target.value; upd(); };
  var add=$q("#bgAddStop"), del=$q("#bgDelStop");
  if(add) add.onclick=function(){ draft.c.splice(1,0,"#ffffff"); renderLeftPanel(); };
  if(del) del.onclick=function(){ draft.c.splice(1,1); renderLeftPanel(); };
  $q("#bgApply").onclick=function(){ applyGrad(draft,"custom"); };
  $q("#bgSave").onclick=function(){
    var l=loadSaved(); if(l.length>=MAXSAVED){ try{toast("You can save up to "+MAXSAVED+" gradients. Delete one first.");}catch(e){window.__swl&&window.__swl(e)} return; }
    var n=0; l.forEach(function(s){ var m=/^Custom (\d+)$/.exec(s.n); if(m) n=Math.max(n,+m[1]); });
    var g=clean(draft); g.n="Custom "+(n+1); l.unshift(g);
    if(storeSaved(l)){ try{toast("Saved as "+g.n);}catch(e){window.__swl&&window.__swl(e)} renderLeftPanel(); }
  };
  lp.querySelectorAll(".bgs").forEach(function(b){ b.onclick=function(){ var g=loadSaved()[+b.dataset.s]; if(g){ draft={t:g.t,a:g.a,c:g.c.slice()}; applyGrad(g,g.n); } }; });
  lp.querySelectorAll(".bgdel").forEach(function(b){ b.onclick=function(e){ e.stopPropagation(); var l=loadSaved(); l.splice(+b.dataset.s,1); if(storeSaved(l)) renderLeftPanel(); }; });
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  if(activePanel==="backgrounds"){ document.getElementById("leftPanel").innerHTML=render(); try{bind();}catch(e){ try{console.error(e);}catch(_){window.__swl&&window.__swl(_)} } return; }
  return prev.apply(this,arguments);
};
function addNav(){
  var nav=document.getElementById("nav"); if(!nav||document.getElementById("navBgBtn9")) return;
  var b=document.createElement("button"); b.className="navbtn"; b.id="navBgBtn9"; b.dataset.panel="backgrounds";
  b.innerHTML='<span class="dot"></span>Backgrounds';
  b.addEventListener("click",function(){ activePanel="backgrounds"; nav.querySelectorAll(".navbtn").forEach(function(x){x.classList.toggle("active",x===b);}); renderLeftPanel(); });
  var anchor=nav.querySelector('[data-panel="color"]'); if(anchor&&anchor.nextSibling) nav.insertBefore(b,anchor.nextSibling); else nav.appendChild(b);
}
addNav(); setTimeout(addNav,400);
try{ window.AMIYO_EDITOR_BUILD="step109-backgrounds"; }catch(e){window.__swl&&window.__swl(e)}
try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
})();

