/* ==================== Script 290 id="amiyo-step110-settings-presets" ==================== */
/* Step 9 — Project settings: one-tap presets for resolution, frame rate and background colour.
   Presets fill the fields; nothing changes until you press Save settings. The aspect box now really saves. */
(function(){
"use strict";
var RES=[["720p",1280,720],["1080p",1920,1080],["4K",3840,2160],["Vertical",1080,1920],["Square",1080,1080],["4:5",1080,1350],["4:3",1440,1080]];
var FPS=[24,25,30,50,60];
var BG=["#000000","#080b10","#2e211a","#0f3d2e","#3a1c71","#c2185b","#ff7a3d","#ffffff","#f5f6f8","#00b140"];
var ASP=[["16:9",16/9],["9:16",9/16],["1:1",1],["4:5",.8],["4:3",4/3]];
function g(id){return document.getElementById(id);}
function nearest(w,h){ var r=w/h,b=ASP[0]; ASP.forEach(function(a){ if(Math.abs(a[1]-r)<Math.abs(b[1]-r)) b=a; }); return b[0]; }
function chipCss(on){ return "min-height:34px;padding:0 10px;"+(on?"outline:2px solid var(--accent,#ff9d6c);":""); }
function build(){
  var S=project.settings, bg=/^#[0-9a-fA-F]{6}$/.test(S.background||"")?S.background.toLowerCase():"#080b10", pend=null;
  var card=document.createElement("div"); card.className="panel-card"; card.id="setPresets";
  card.innerHTML='<h3 style="margin:0 0 6px;font-size:12px">Resolution</h3><div class="mini-row" id="spRes" style="flex-wrap:wrap;gap:6px"></div>'+
   '<div id="spWarn" style="font-size:10px;color:var(--warn,#f5b942);margin:4px 0;display:none">Large sizes can be slow or fail to export on phones. Try 1080p if it stutters.</div>'+
   '<h3 style="margin:10px 0 6px;font-size:12px">Frame rate</h3><div class="mini-row" id="spFps" style="flex-wrap:wrap;gap:6px"></div>'+
   '<h3 style="margin:10px 0 6px;font-size:12px">Background colour</h3><div class="mini-row" id="spBg" style="flex-wrap:wrap;gap:6px"></div>'+
   '<div id="spNote" style="font-size:10px;color:var(--muted);margin-top:6px">Tap a preset, then Save settings.</div>';
  function num(id){return Number(g(id).value)||0;}
  function mark(){
    var w=num("setW"),h=num("setH"),f=num("setFps");
    card.querySelectorAll("[data-r]").forEach(function(b){ var r=RES[+b.dataset.r]; b.style.cssText=chipCss(r[1]===w&&r[2]===h); });
    card.querySelectorAll("[data-f]").forEach(function(b){ b.style.cssText=chipCss(+b.dataset.f===f); });
    card.querySelectorAll("[data-b]").forEach(function(b){ var on=b.dataset.b===(pend||bg); b.style.cssText="width:30px;height:30px;padding:0;border-radius:50%;border:1px solid var(--line);background:"+b.dataset.b+";"+(on?"outline:2px solid var(--accent,#ff9d6c);outline-offset:2px;":""); });
    card.querySelector("#spWarn").style.display=(w>1920||h>1920)?"block":"none";
    var sa=document.getElementById("setAspect"); if(sa&&w&&h) sa.value=nearest(w,h);
  }
  RES.forEach(function(r,i){ var b=document.createElement("button"); b.type="button"; b.className="chip"; b.dataset.r=i; b.textContent=r[0]; b.title=r[1]+" × "+r[2];
    b.onclick=function(){ g("setW").value=r[1]; g("setH").value=r[2]; mark(); }; card.querySelector("#spRes").appendChild(b); });
  FPS.forEach(function(f){ var b=document.createElement("button"); b.type="button"; b.className="chip"; b.dataset.f=f; b.textContent=f+" fps";
    b.onclick=function(){ g("setFps").value=f; mark(); }; card.querySelector("#spFps").appendChild(b); });
  BG.forEach(function(c){ var b=document.createElement("button"); b.type="button"; b.dataset.b=c; b.setAttribute("aria-label","Background "+c); b.title=c;
    b.onclick=function(){ pend=c; card.querySelector("#spNote").textContent="Background "+c+" will apply when you Save settings."+(S.bgGradient?" This replaces the gradient.":""); mark(); }; card.querySelector("#spBg").appendChild(b); });
  ["setW","setH","setFps"].forEach(function(id){ var e=g(id); if(e) e.addEventListener("input",mark); });
  var save=g("saveSettings");
  if(save) save.addEventListener("click",function(){
    var w=num("setW"),h=num("setH"),f=num("setFps");
    if(w<64||h<64||w>7680||h>7680||f<1||f>120){ try{toast("Check the numbers: size 64–7680, frame rate 1–120");}catch(e){window.__swl&&window.__swl(e)} }
    S.aspect=nearest(w||1280,h||720);
    if(pend){ S.background=pend; S.bgGradient=null; }
    try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)}
  });
  mark(); return card;
}
var prev=window.openModal;
window.openModal=function(title,html){
  var r=prev.apply(this,arguments);
  if(title==="Project Settings"){ try{ var body=g("modalBody"), first=body&&body.querySelector(".fieldrow"); if(first&&!g("setPresets")) body.insertBefore(build(),first); }catch(e){ try{console.error(e);}catch(_){window.__swl&&window.__swl(_)} } }
  return r;
};
try{ window.AMIYO_EDITOR_BUILD="step110-settings-presets"; }catch(e){window.__swl&&window.__swl(e)}
})();

