/* ==================== Script 292 id="amiyo-step112-problems" ==================== */
/* Step 1 (new plan) — Problems log: errors the editor used to swallow are now kept (last 60) and shown in Help → Problems log,
   with a Copy report button and a count badge on the Help tab. Nothing is shown as a pop-up; it never slows editing. */
(function(){
"use strict";
var KEY="amiyoProblemsLog", MAX=60, log=[], busy=false;
try{ var old=JSON.parse(sessionStorage.getItem(KEY)||"[]"); if(Array.isArray(old)) log=old.slice(-MAX); }catch(e){}
function save(){ try{ sessionStorage.setItem(KEY,JSON.stringify(log)); }catch(e){} }
function add(kind,msg,where){
  if(busy) return; busy=true;
  try{
    msg=String(msg||"unknown").replace(/\s+/g," ").slice(0,300);
    var last=log[log.length-1];
    if(last&&last.m===msg&&last.k===kind){ last.n=(last.n||1)+1; last.t=Date.now(); }
    else{ log.push({k:kind,m:msg,w:where?String(where).slice(0,120):"",t:Date.now(),n:1}); if(log.length>MAX) log.shift(); }
    save(); badge();
  }catch(e){} finally{ busy=false; }
}
window.addEventListener("error",function(e){
  if(e&&e.target&&e.target!==window&&e.target.tagName){ add("load","Could not load "+(e.target.tagName||"")+" "+(e.target.src||e.target.href||"").slice(0,100)); return; }
  add("error",(e&&e.message)||"script error",e&&e.lineno?("line "+e.lineno):"");
},true);
window.addEventListener("unhandledrejection",function(e){ var r=e&&e.reason; add("promise",(r&&(r.message||r))||"rejected"); });
try{
  var ce=console.error;
  console.error=function(){ try{ add("console",Array.prototype.slice.call(arguments).map(function(a){ return a&&a.message?a.message:(typeof a==="object"?"[object]":String(a)); }).join(" ")); }catch(e){} return ce.apply(this,arguments); };
}catch(e){}
function esc(s){ return String(s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function ago(t){ var s=Math.max(0,Math.round((Date.now()-t)/1000)); return s<60?s+"s ago":s<3600?Math.round(s/60)+" min ago":Math.round(s/3600)+" h ago"; }
function badge(){
  var b=document.getElementById("navHelpBtn10"); if(!b) return;
  var s=b.querySelector(".prob-badge");
  if(!log.length){ if(s) s.remove(); return; }
  if(!s){ s=document.createElement("span"); s.className="prob-badge"; s.style.cssText="margin-left:6px;background:var(--bad,#d9534f);color:#fff;border-radius:9px;padding:0 6px;font-size:10px;line-height:16px;display:inline-block"; s.setAttribute("aria-label","problems logged"); b.appendChild(s); }
  s.textContent=String(log.length);
}
function report(){
  var lines=["AMIYO editor problems report","build: "+(window.AMIYO_EDITOR_BUILD||"?"),"time: "+new Date().toISOString(),"browser: "+(navigator.userAgent||"").slice(0,140),""];
  log.forEach(function(x){ lines.push("["+x.k+"] "+x.m+(x.n>1?" (x"+x.n+")":"")+(x.w?" — "+x.w:"")+" · "+new Date(x.t).toISOString()); });
  if(!log.length) lines.push("No problems logged.");
  return lines.join("\n");
}
function card(){
  var h='<div class="panel-card" id="prLog"><h3 style="margin:0 0 6px;font-size:12px">Problems log</h3>'+
   '<div style="font-size:10px;color:var(--muted);margin-bottom:6px">Errors the editor met while running. Empty is good. Send the report if something misbehaves.</div>';
  if(!log.length) h+='<div style="font-size:12px">✅ No problems logged in this session.</div>';
  else h+='<div style="max-height:200px;overflow:auto;font-size:11px">'+log.slice().reverse().map(function(x){
    return '<div style="border-top:1px solid var(--line,#333);padding:4px 0"><b>'+esc(x.k)+'</b>'+(x.n>1?' ×'+x.n:'')+' · '+esc(ago(x.t))+'<div style="word-break:break-word;opacity:.85">'+esc(x.m)+(x.w?' ('+esc(x.w)+')':'')+'</div></div>'; }).join("")+'</div>';
  h+='<div style="display:flex;gap:6px;margin-top:8px"><button type="button" class="chip" id="prCopy" style="min-height:40px;flex:1">Copy report</button><button type="button" class="chip" id="prClear" style="min-height:40px;flex:1"'+(log.length?"":" disabled")+'>Clear</button></div><div id="prMsg" role="status" style="font-size:11px;margin-top:4px"></div></div>';
  return h;
}
function mount(){
  var lp=document.getElementById("leftPanel"); if(!lp||lp.querySelector("#prLog")) return;
  lp.insertAdjacentHTML("beforeend",card());
  var msg=lp.querySelector("#prMsg");
  lp.querySelector("#prCopy").onclick=function(){
    var txt=report();
    function done(ok){ msg.textContent=ok?"Report copied.":"Could not copy. Select the text and copy it by hand."; if(!ok){ var ta=document.createElement("textarea"); ta.value=txt; ta.style.cssText="width:100%;height:120px;margin-top:6px"; ta.setAttribute("aria-label","Problems report"); msg.appendChild(ta); ta.select(); } }
    try{ if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(txt).then(function(){done(true);},function(){done(false);}); return; } }catch(e){}
    done(false);
  };
  lp.querySelector("#prClear").onclick=function(){ log=[]; save(); badge(); var o=lp.querySelector("#prLog"); if(o){ o.outerHTML=card(); lp.querySelector("#prLog"); mountHandlers(); } };
  function mountHandlers(){ var l2=document.getElementById("leftPanel"); if(l2){ var c=l2.querySelector("#prLog"); if(c) c.remove(); mount(); } }
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  var r=prev.apply(this,arguments);
  try{ if(activePanel==="help") mount(); }catch(e){}
  return r;
};
setTimeout(badge,800); setTimeout(badge,2500);
window.amiyoProblems={list:function(){return log.slice();},report:report,add:function(m){add("note",m);}};
try{ window.AMIYO_EDITOR_BUILD="step112-problems-log"; }catch(e){}
})();

;
/* ==================== Script 293 id="amiyo-step113-undo-limit" ==================== */
/* Step 2 (new plan) — Undo history: ONE step limit you can see and change.
   Before: some actions kept 80 steps, some 120, and many were never counted, so the only real limit was the memory budget.
   Now: a single step cap (30 / 60 / 120 / 250, default 120) is applied to every action, on top of the memory budget.
   Help -> "Undo history" shows the steps in use, the memory used, and how many old steps were dropped. */
(function(){
"use strict";
var KEY="amiyoUndoCap", OPTS=[30,60,120,250], DEF=120;
function getCap(){ return typeof window.amiyoUndoCapValue==="function"?window.amiyoUndoCapValue():DEF; }
function enforce(){
  try{ if(typeof window.amiyoCapHistory==="function") window.amiyoCapHistory(); }
  catch(e){ try{ console.error("undo cap",e); }catch(_){window.__swl&&window.__swl(_)} }
}
var pu=window.updateUndoRedo;
if(typeof pu==="function"){
  window.updateUndoRedo=function(){ enforce(); return pu.apply(this,arguments); };
}
var pa=window.scheduleAutosave;
if(typeof pa==="function"){
  window.scheduleAutosave=function(){ enforce(); return pa.apply(this,arguments); };
}
function mb(b){ return (b/1048576).toFixed(1); }
function card(){
  var st={steps:0,position:0,bytes:0,budget:0,dropped:0};
  try{ if(typeof window.amiyoHistoryStats==="function") st=window.amiyoHistoryStats(); }catch(e){window.__swl&&window.__swl(e)}
  var cap=getCap();
  var opts=OPTS.map(function(n){ return '<option value="'+n+'"'+(n===cap?" selected":"")+'>'+n+' steps'+(n===DEF?" (default)":"")+'</option>'; }).join("");
  return '<div class="panel-card" id="uhCard"><h3 style="margin:0 0 6px;font-size:12px">Undo history</h3>'+
   '<div style="font-size:10px;color:var(--muted);margin-bottom:6px">Each undo step stores a copy of the project. A lower limit uses less memory, which helps on phones.</div>'+
   '<div style="font-size:12px;line-height:1.7">Steps kept: <b>'+st.steps+'</b> of '+cap+'<br>Memory used: <b>'+mb(st.bytes)+' MB</b> of '+mb(st.budget)+' MB<br>Old steps dropped: <b>'+((st.dropped||0)+(window.__amiyoCapDropped||0))+'</b></div>'+
   '<label for="uhCap" style="display:block;font-size:11px;margin-top:8px">Undo limit</label>'+
   '<select id="uhCap" class="search" style="width:100%;min-height:40px">'+opts+'</select>'+
   '<div id="uhMsg" role="status" style="font-size:11px;margin-top:4px"></div></div>';
}
function mount(){
  var lp=document.getElementById("leftPanel"); if(!lp) return;
  var old=lp.querySelector("#uhCard"); if(old) old.remove();
  lp.insertAdjacentHTML("beforeend",card());
  var sel=lp.querySelector("#uhCap"), msg=lp.querySelector("#uhMsg");
  sel.onchange=function(){
    var v=parseInt(sel.value,10);
    try{ localStorage.setItem(KEY,String(v)); }catch(e){ msg.textContent="Could not save the setting on this device. It applies until you reload."; }
    var before=(project.history&&project.history.entries||[]).length;
    enforce();
    try{ updateUndoRedo(); }catch(e){window.__swl&&window.__swl(e)}
    var lost=Math.max(0,before-((project.history&&project.history.entries)||[]).length);
    mount();
    var m2=document.getElementById("uhMsg");
    if(m2) m2.textContent=lost?("Limit set to "+v+". "+lost+" oldest step"+(lost>1?"s were":" was")+" dropped."):("Limit set to "+v+".");
  };
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  var r=prev.apply(this,arguments);
  try{ if(activePanel==="help") mount(); }catch(e){ try{ console.error(e); }catch(_){window.__swl&&window.__swl(_)} }
  return r;
};
try{ window.amiyoUndoCap={get:getCap,enforce:enforce}; window.AMIYO_EDITOR_BUILD="step116-speech-timing"; }catch(e){window.__swl&&window.__swl(e)}
})();

