/* ==================== Script 296 id="amiyo-step127-timeline-speed" ==================== */
/* =========================================================================
   Editor step 127 (list step 4): timeline speed on long projects
   Before: every clip drawn on a big timeline asked the browser to compute CSS (labelW) twice, the length of the
   project was re-added up over every clip on every playback frame, and finding the selected clip walked every clip.
   Now: label width is remembered for a moment, the project length and the selected clip are remembered during
   playback / repeated lookups, and each is checked so an edit is never missed. Nothing is drawn differently.
   ========================================================================= */
(function(){
"use strict";
var now=function(){ return (window.performance&&performance.now)?performance.now():Date.now(); };
var stats={labelHits:0,labelMiss:0,durHits:0,durMiss:0,clipHits:0,clipMiss:0};

/* label width: a CSS read that was repeated for every clip */
var oLW=window.labelW, lw=0, lwT=-1e9;
if(typeof oLW==="function"){
  window.labelW=function(){ var t=now(); if(t-lwT<400&&lw){ stats.labelHits++; return lw; } stats.labelMiss++; lw=oLW.apply(this,arguments); lwT=t; return lw; };
  var drop=function(){ lwT=-1e9; };
  window.addEventListener("resize",drop); window.addEventListener("orientationchange",drop);
}

/* project length: only remembered while playing, when it is asked for on every frame */
var oPD=window.getProjectDuration, pdV=0, pdT=-1e9, pdP=null;
if(typeof oPD==="function"){
  window.getProjectDuration=function(){
    var playing=false; try{ playing=!!isPlaying; }catch(e){window.__swl&&window.__swl(e)}
    var t=now();
    if(playing&&pdP===project&&t-pdT<250){ stats.durHits++; return pdV; }
    stats.durMiss++; pdV=oPD.apply(this,arguments); pdT=playing?t:-1e9; pdP=project; return pdV;
  };
}

/* selected clip: remember where it was found and confirm it is still there before using it */
var oGC=window.getClip, gc=null;
if(typeof oGC==="function"){
  window.getClip=function(){
    var id=null; try{ id=selectedClipId; }catch(e){window.__swl&&window.__swl(e)}
    if(id!=null&&gc&&gc.id===id&&gc.p===project){
      var tr=gc.track;
      if(tr&&tr.clips&&tr.clips[gc.i]===gc.clip&&project.tracks[gc.ti]===tr){ stats.clipHits++; return {track:tr,clip:gc.clip}; }
    }
    stats.clipMiss++;
    var r=oGC.apply(this,arguments);
    if(r&&id!=null){ gc={id:id,p:project,track:r.track,clip:r.clip,i:r.track.clips.indexOf(r.clip),ti:project.tracks.indexOf(r.track)}; } else gc=null;
    return r;
  };
}
window.AMIYO_TL_SPEED={stats:stats,reset:function(){ for(var k in stats) stats[k]=0; }};
try{ window.AMIYO_EDITOR_BUILD="step127-timeline-speed"; }catch(e){window.__swl&&window.__swl(e)}
})();

