    sub.textContent="Captions for \u201c"+String((clip&&clip.name)||(function(){ try{ var a=getAsset(clip.assetId); return a&&a.name; }catch(e){ return ""; } })()||"clip").slice(0,40)+"\u201d will be written in this language. Tap one to start.";
    var q=document.createElement("input"); q.type="search"; q.placeholder="Search a language"; q.setAttribute("aria-label","Search a language"); q.autocomplete="off";
    q.style.cssText="width:100%;box-sizing:border-box;margin-top:8px;min-height:40px;padding:0 10px;border-radius:8px;border:1px solid var(--border,#3a352c);background:var(--panel3,#222);color:inherit;font-size:13px";
