      var n=document.createElement("div"); n.textContent=L[1]; n.style.cssText="font-size:13px;font-weight:600";
      var s=document.createElement("div"); s.textContent=(sel?"Last used \u00b7 ":"")+L[2]; s.style.cssText="font-size:10.5px;color:var(--muted,#a8a092)";
