    var chk=document.createElement("input"); chk.type="checkbox"; chk.checked=!!st.translate; chk.style.cssText="margin-top:2px;width:18px;height:18px;flex:none";
    var trt=document.createElement("span"); trt.textContent="Translate the speech into English captions (ignored when the language is English)";
    tr.appendChild(chk); tr.appendChild(trt);
    var ft=document.createElement("div"); ft.style.cssText="padding:8px 12px 12px;border-top:1px solid var(--border,#3a352c);display:flex;gap:8px;align-items:center";
    var note=document.createElement("div"); note.style.cssText="flex:1;font-size:10.5px;line-height:1.4;color:var(--muted,#a8a092)";
