st.lang=loadLang(); st.review=true; try{ st.review=localStorage.getItem("amiyo.caption.review")!=="0"; }catch(e){} try{ st.translate=localStorage.getItem("amiyo.caption.translate")==="1"; }catch(e){}
var pipe=null,pipeKey="";
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
