/* ---------- pure parts (tested separately) ---------- */
var JUNK=/^\s*[\[(\u266a*].*[\])\u266a*]\s*$/;
function splitSeg(text,a,b,maxW){
  text=String(text||"").replace(/\s+/g," ").trim();
  if(!text||JUNK.test(text)||!(b>a)) return [];
  var w=text.split(" "), n=Math.ceil(w.length/maxW), per=Math.ceil(w.length/n), out=[], total=w.length, at=a;
  for(var i=0;i<w.length;i+=per){ var part=w.slice(i,i+per), d=(b-a)*part.length/total; out.push({text:part.join(" "),start:at,end:at+d}); at+=d; }
  return out;
}
function fixSegs(raw,len){
  var out=[];
  raw.forEach(function(s){ var a=Math.max(0,+s.a||0), b=(s.b==null||!isFinite(s.b))?Math.min(len,a+3):Math.min(len,+s.b); if(b-a<.3) b=Math.min(len,a+.3); splitSeg(s.t,a,b,8).forEach(function(x){ out.push(x); }); });
  out.sort(function(x,y){ return x.start-y.start; });
  for(var i=0;i<out.length;i++){ var nx=out[i+1]; if(nx&&out[i].end>nx.start-.02) out[i].end=Math.max(out[i].start+.2,nx.start-.02); }
  return out;
}
window.__amiyoAutoCapTest={splitSeg:splitSeg,fixSegs:fixSegs};

/* ---------- audio ---------- */
async function readAudio(clip){
  var a=getAsset(clip.assetId);
  if(!a||(a.type!=="video"&&a.type!=="audio")) throw new Error("Select a video or audio clip that has sound.");
  if(a.size&&a.size>300*1048576) throw new Error("That file is too large to read here ("+Math.round(a.size/1048576)+" MB).");
  var url=await ensureUrl(a); if(!url) throw new Error("The media file for this clip is missing. Import it again.");
  var OAC=window.OfflineAudioContext||window.webkitOfflineAudioContext; if(!OAC) throw new Error("This browser cannot read audio for analysis.");
  var ab=await (await fetch(url)).arrayBuffer(), buf;
  try{ buf=await new OAC(1,1,SR).decodeAudioData(ab); }catch(e){ throw new Error("The sound of this file could not be read."); }
  var sp=clip.speed||1, from=Math.round(Math.max(0,clip.inPoint||0)*SR), want=Math.round(clip.duration*sp*SR);
  var to=Math.min(buf.length,from+want,from+MAXMIN*60*SR);
  if(to-from<SR) throw new Error("This clip is too short to find speech in.");
  var mono=new Float32Array(to-from), ch=buf.numberOfChannels;
  for(var c=0;c<ch;c++){ var d=buf.getChannelData(c); for(var i=0;i<mono.length;i++) mono[i]+=d[from+i]/ch; }
  return {mono:mono,speed:sp,cut:(from+want>to)};
}
function rms(x){ var s=0; for(var i=0;i<x.length;i+=4) s+=x[i]*x[i]; return Math.sqrt(s/Math.max(1,x.length/4)); }

/* ---------- model ---------- */
async function getPipe(key){
  if(pipe&&pipeKey===key) return pipe;
  st.msg="Loading the speech model… the first time this downloads it."; st.pct=0; paint();
  var T=await import(LIB);
  T.env.allowLocalModels=false; T.env.useBrowserCache=true;
  try{ T.env.backends.onnx.wasm.numThreads=1; }catch(e){window.__swl&&window.__swl(e)}
  pipe=await T.pipeline("automatic-speech-recognition",MODELS[key][0],{progress_callback:function(p){
    if(p&&p.status==="progress"&&isFinite(p.progress)){ st.pct=p.progress; st.msg="Downloading the speech model… "+Math.round(p.progress)+"%"; paint(); }
    else if(p&&p.status==="ready"){ st.msg="Speech model ready."; paint(); }
  }});
  pipeKey=key; return pipe;
}

/* ---------- main ---------- */
function pickClip(){
  var f=null; try{ f=getClip(); }catch(e){window.__swl&&window.__swl(e)}
  if(f&&f.clip&&f.clip.assetId) return f.clip;
  for(var i=0;i<project.tracks.length;i++){ var t=project.tracks[i]; if(t.kind==="caption"||t.kind==="text") continue;
    for(var k=0;k<t.clips.length;k++){ var c=t.clips[k]; if(c.assetId&&currentTime>=c.start&&currentTime<c.start+c.duration) return c; } }
  return null;
}
async function run(){
  if(st.busy||st.asking) return;
  var C=window.AMIYO_CAPTIONS; if(!C||!C.mk||!C.track){ st.msg="The Captions panel is not ready. Reload the editor."; st.bad=true; paint(); return; }
  var clip=pickClip(); if(!clip){ st.msg="Tap a video or audio clip on the timeline first."; st.bad=true; paint(); return; }
  st.asking=true; st.bad=false; paint();
  var lang=null; try{ lang=await askLang(clip); }catch(e){ window.__swl&&window.__swl(e); }
  st.asking=false;
  if(!lang){ st.msg="Cancelled. Nothing was added."; st.bad=false; paint(); return; }
  st.lang=lang; saveLang(lang);
  st.busy=true; st.cancel=false; st.bad=false; st.pct=0; paint();
  try{
    st.msg="Reading the sound of “"+(clip.name||"clip")+"”…"; paint();
    var au=await readAudio(clip), mkey=effModel(lang), p=await getPipe(mkey), multi=!MODELS[mkey][2];
    var step=PIECE*SR, n=Math.ceil(au.mono.length/step), raw=[], lenSec=au.mono.length/SR;
    for(var i=0;i<n;i++){
      if(st.cancel) throw new Error("Cancelled. Nothing was added.");
      st.pct=i/n*100; st.msg="Listening… "+Math.round(i/n*100)+"% (piece "+(i+1)+" of "+n+")"; paint();
      var sl=au.mono.slice(i*step,Math.min(au.mono.length,(i+1)*step));
      if(sl.length<SR*.5||rms(sl)<.003) continue;   /* silence: skip, it only makes the model invent words */
      var opt={return_timestamps:true,chunk_length_s:PIECE}; if(multi){ opt.task=(st.translate&&lang!=="english")?"translate":"transcribe"; if(lang!=="auto") opt.language=lang; }
      var out=await p(sl,opt), off=i*PIECE;
      if(out&&out.chunks&&out.chunks.length) out.chunks.forEach(function(c){ var ts=c.timestamp||[0,null]; raw.push({t:c.text,a:off+(ts[0]||0),b:ts[1]==null?null:off+ts[1]}); });
      else if(out&&out.text) raw.push({t:out.text,a:off,b:off+sl.length/SR});
      await new Promise(function(r){ setTimeout(r,0); });
    }
    var segs=fixSegs(raw,lenSec);
    if(!segs.length) throw new Error("No speech was recognised. Check the sound is clear, or try the Better model.");
    var tr=C.track(); if(!tr) throw new Error("The caption track is locked. Unlock it and try again.");
    var sp=au.speed, c0=clip.start, c1=clip.start+clip.duration, removed=0;
    transact("Auto captions",function(){
      if(st.replace){ var before=tr.clips.length; tr.clips=tr.clips.filter(function(x){ return x.start+x.duration<=c0+.01||x.start>=c1-.01; }); removed=before-tr.clips.length; }
      segs.forEach(function(s){ var a=c0+s.start/sp, d=Math.max(.3,(s.end-s.start)/sp); var nc=C.mk(s.text,a,d); applyScriptFont(nc); tr.clips.push(nc); });
      tr.clips.sort(function(x,y){ return x.start-y.start; }); try{ selectedTrackId=tr.id; }catch(e){window.__swl&&window.__swl(e)}
    });
    st.pct=100; st.msg=segs.length+" captions added"+(lang==="auto"?(st.translate?" (translated to English)":""):" ("+langLabel(lang)+(st.translate&&lang!=="english"?" \u2192 English":"")+")")+(removed?" ("+removed+" old ones replaced)":"")+(au.cut?". Only the first "+MAXMIN+" minutes were used.":".")+" Read them through: speech models can mishear names. Undo removes them all.";
    say(segs.length+" captions added",4500);
    if(st.review&&!window.__dirRunning){ setTimeout(openReview,350); }
  }catch(e){
    var m=String((e&&e.message)||e); st.bad=!/^Cancelled/.test(m);
    if(/fetch|network|import|Failed to load|load failed/i.test(m)) m="The speech model could not be downloaded. Check your internet connection, then try again. ("+m.slice(0,90)+")";
    st.msg=m; try{ if(st.bad&&window.amiyoReportError) window.amiyoReportError("Auto-captions failed",e,{quiet:true}); }catch(x){window.__swl&&window.__swl(x)}
  }
  st.busy=false; paint();
}

/* ---------- review box: read the new captions, fix words, delete lines, save as ONE undo step ---------- */
