  var old=document.getElementById("acRevDlg"); if(old) old.remove();
  var ov=document.createElement("div"); ov.id="acRevDlg"; ov.setAttribute("role","dialog"); ov.setAttribute("aria-modal","true"); ov.setAttribute("aria-label","Review captions");
