  var box=document.createElement("div"); box.tabIndex=-1;
  box.style.cssText="background:var(--panel,#17140f);color:var(--text,#f3efe6);border:1px solid var(--border,#3a352c);border-radius:14px;width:min(520px,100%);max-height:min(90vh,720px);display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.6);font-family:inherit;outline:none";
  var hd=document.createElement("div"); hd.style.cssText="padding:14px 16px 8px";
  var h=document.createElement("div"); h.style.cssText="font-size:15px;font-weight:700"; h.textContent="Review captions ("+clips.length+")";
  var sub=document.createElement("div"); sub.style.cssText="font-size:11.5px;line-height:1.5;color:var(--muted,#a8a092);margin-top:4px"; sub.textContent="Speech models can mishear names and rare words. Fix any line, tap the time to jump there, or remove a line. Nothing changes until you tap Save.";
  hd.appendChild(h); hd.appendChild(sub);
