  if(withMedia&&bytes>200*1048576&&window.amiyoOk&&!(await window.amiyoOk("This project has "+mb(bytes)+" of media. Packing it into one file can run out of memory on a phone. Continue anyway?",{okLabel:"Try anyway"}))) return;
