   (L.length?L.map(function(t){ return row(t,true); }).join(""):'<div style="font-size:11px;color:var(--muted)">None yet. Set up a project the way you like it (size, tracks, titles), then save it here to reuse it.</div>')+'</div>'+
   '<div class="panel-card"><h3 style="margin:0 0 6px;font-size:12px">Starters</h3>'+STARTERS.map(function(t){ return row(t,false); }).join("")+'</div></div>';
