addBtn(); setTimeout(addBtn,600);

/* ---------- selection tools ---------- */
var EPS=.001;
function clearSel(){ project.tracks.forEach(function(t){ t.clips.forEach(function(c){ c.selected=false; }); }); }
function curSel(){ var o=[]; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.id===selectedClipId||c.selected) o.push({track:t,clip:c}); }); }); return o; }
function unlocked(){ return project.tracks.filter(function(t){ return !t.locked&&!t.hidden; }); }
function applySel(list,label){
  clearSel();
  if(!list.length){ say("Nothing to select there."); try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)} return 0; }
  list.forEach(function(x){ x.clip.selected=true; });
  selectedClipId=list[0].clip.id; selectedTrackId=list[0].track.id;
  try{ renderAll(); }catch(e){window.__swl&&window.__swl(e)}
  say(label+": "+list.length+" clip"+(list.length===1?"":"s")+" selected"); return list.length;
}
function all(tracks){ var o=[]; tracks.forEach(function(t){ t.clips.forEach(function(c){ o.push({track:t,clip:c}); }); }); return o; }
function ref(dir){ var f=getClip(); if(f) return {t:dir>0?f.clip.start:f.clip.start+f.clip.duration,track:f.track,sel:true}; return {t:currentTime,track:null,sel:false}; }
function selDir(dir,allTracks){
  var r=ref(dir), tracks=allTracks||!r.track?unlocked():[r.track];
  var list=all(tracks).filter(function(x){ return dir>0?x.clip.start>=r.t-EPS:x.clip.start+x.clip.duration<=r.t+EPS; });
  return applySel(list,(dir>0?"Select forward":"Select backward")+(allTracks||!r.track?" (all tracks)":" (this track)"));
}
function selTrack(){ var f=getClip(), t=f?f.track:project.tracks.find(function(x){ return x.id===selectedTrackId; }); if(!t){ say("Tap a clip or a track first."); return 0; } return applySel(t.clips.map(function(c){ return {track:t,clip:c}; }),"Whole track “"+t.name+"”"); }
function invert(){ var cur=new Set(curSel().map(function(x){ return x.clip.id; })); return applySel(all(unlocked()).filter(function(x){ return !cur.has(x.clip.id); }),"Inverted selection"); }
api.add({id:"sel-fwd",group:"Select",title:"Select forward on this track",desc:"Everything on the selected clip's track from that clip to the end. With nothing selected, from the playhead.",run:function(){ selDir(1,false); }});
api.add({id:"sel-fwd-all",group:"Select",title:"Select forward on all tracks",desc:"Every clip that starts at or after the selected clip (or playhead), on every unlocked track. Handy before moving or deleting a whole section.",run:function(){ selDir(1,true); }});
api.add({id:"sel-back",group:"Select",title:"Select backward on this track",desc:"Everything before the selected clip's end (or the playhead) on its track.",run:function(){ selDir(-1,false); }});
api.add({id:"sel-back-all",group:"Select",title:"Select backward on all tracks",desc:"Every clip that ends at or before the selected clip (or playhead), on all unlocked tracks.",run:function(){ selDir(-1,true); }});
api.add({id:"sel-track",group:"Select",title:"Select whole track",desc:"All clips on the selected clip's track.",run:selTrack});
api.add({id:"sel-invert",group:"Select",title:"Invert selection",desc:"Select what is not selected, on unlocked tracks.",run:invert});
api.selected=curSel; api.clearSel=clearSel; api.say=say;
api.selection={forward:selDir.bind(null,1),backward:selDir.bind(null,-1),track:selTrack,invert:invert};
