/* ==================== Script 309 id="amiyo-step137-layouts" ==================== */
/* =========================================================================
   Editor step 137 (round 5, step 2 of 10): SPLIT-SCREEN LAYOUTS
   Before: putting clips side by side meant setting position, size and crop by hand for each one.
   Now: new Layouts tab. Select two or more clips (or put clips on separate tracks at the playhead) and tap a
   layout: side by side, stacked, three across, one big + two small, 2×2 grid, or picture-in-picture.
   Each clip is scaled to fill its box and cropped to it. Optional thin gap. Reset puts them back.
   One undo step. (The crop limit was raised from 49% to 98% so boxes on the right/bottom can be cropped.)
   ========================================================================= */
(function(){
"use strict";
var G=.006, st={gap:true};
var LAYS=[
 {id:"h2",n:"Side by side",c:[[0,0,.5,1],[.5,0,1,1]]},
 {id:"v2",n:"Stacked",c:[[0,0,1,.5],[0,.5,1,1]]},
 {id:"h3",n:"Three across",c:[[0,0,1/3,1],[1/3,0,2/3,1],[2/3,0,1,1]]},
 {id:"big",n:"Big + two",c:[[0,0,2/3,1],[2/3,0,1,.5],[2/3,.5,1,1]]},
 {id:"g4",n:"2×2 grid",c:[[0,0,.5,.5],[.5,0,1,.5],[0,.5,.5,1],[.5,.5,1,1]]},
 {id:"pip",n:"Picture-in-picture",c:[[0,0,1,1],[.67,.65,.97,.95]],pip:true}
];
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
function lp(){ return document.getElementById("leftPanel"); }
function say(m){ try{ toast(m,4200); }catch(e){window.__swl&&window.__swl(e)} }
function visual(x){
  if(!x||!x.clip||x.clip.kind==="text"||x.clip.kind==="adjustment"||x.track.kind!=="video"||x.track.hidden) return false;
  var a=project.assets&&project.assets[x.clip.assetId]; return !!a&&(a.type==="video"||a.type==="image");
}
function targets(){
  var list=[]; try{ var c=window.AMIYO_STUDIO_CORE; var s=c&&c.selectedClips&&c.selectedClips(); if(s&&s.length) list=s; }catch(e){window.__swl&&window.__swl(e)}
  list=list.filter(visual);
  if(list.length<2){
    var at=[]; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ var x={track:t,clip:c}; if(visual(x)&&currentTime>=c.start-.001&&currentTime<c.start+c.duration-.001) at.push(x); }); });
    if(at.length>=2) list=at;
  }
  return list;
}
function geom(cell,clip,pip){
  var W=project.settings.width||1280, H=project.settings.height||720, a=project.assets[clip.assetId]||{};
  var ar=(a.width&&a.height)?a.width/a.height:16/9, g=(st.gap&&!pip)?G:0;
  var x0=cell[0]+(cell[0]>0?g:0), y0=cell[1]+(cell[1]>0?g:0), x1=cell[2]-(cell[2]<1?g:0), y1=cell[3]-(cell[3]<1?g:0);
  var cw=x1-x0, ch=y1-y0, s=Math.max(ch,cw*(W/H)/ar);
  return {x:(x0+x1)/2,y:(y0+y1)/2,scale:s,crop:(x0>0||y0>0||x1<1||y1<1)?{l:x0,t:y0,r:1-x1,b:1-y1}:null};
}
function apply(L){
  var t=targets();
  if(t.length<2){ say("Select two or more clips (Ctrl-click), or put clips on separate video tracks at the playhead."); return; }
  var n=Math.min(t.length,L.c.length), cleared=0;
  window.transact("Layout: "+L.n,function(){
    for(var i=0;i<n;i++){
      var c=t[i].clip, g=geom(L.c[i],c,L.pip&&i===1);
      if((c.keyframes&&c.keyframes.length)||c.anim){ cleared++; c.keyframes=[]; c.anim=null; c.stab=null; }
      c.fit="cover"; c.x=g.x; c.y=g.y; c.scale=g.scale; c.rotation=0; c.crop=g.crop;
    }
  });
  say(L.n+" applied to "+n+" clip"+(n===1?"":"s")+"."+(t.length>L.c.length?" "+(t.length-L.c.length)+" extra clip"+(t.length-L.c.length===1?" was":"s were")+" left as is.":"")+(n<L.c.length?" Add "+(L.c.length-n)+" more clip"+(L.c.length-n===1?"":"s")+" to fill the empty box"+(L.c.length-n===1?"":"es")+".":"")+(cleared?" Animations on "+cleared+" clip"+(cleared===1?"":"s")+" were removed.":""));
  paint();
}
function reset(){
  var t=targets(); if(!t.length){ var f=null; try{ f=getClip(); }catch(e){window.__swl&&window.__swl(e)} if(f&&visual(f)) t=[f]; }
  if(!t.length){ say("Select the clips to reset."); return; }
  window.transact("Reset layout",function(){ t.forEach(function(x){ var c=x.clip; c.crop=null; c.x=.5; c.y=.5; c.scale=1; c.rotation=0; c.fit="contain"; }); });
  say("Layout reset on "+t.length+" clip"+(t.length===1?"":"s")+"."); paint();
}
function thumb(cv,L){
  var g=cv.getContext("2d"), w=cv.width, h=cv.height; g.clearRect(0,0,w,h); g.fillStyle="#1d1d22"; g.fillRect(0,0,w,h);
  var cols=["#ff7a3d","#ff864a","#5bd68a","#c77dff"];
  L.c.forEach(function(c,i){ var x=c[0]*w+1, y=c[1]*h+1, ww=(c[2]-c[0])*w-2, hh=(c[3]-c[1])*h-2; g.globalAlpha=L.pip&&i===0?.35:.9; g.fillStyle=cols[i%4]; g.fillRect(x,y,ww,hh); g.globalAlpha=1; g.fillStyle="#0a0908"; g.font="bold 11px system-ui"; g.textAlign="center"; g.textBaseline="middle"; g.fillText(String(i+1),x+ww/2,y+hh/2); });
}
function render(){
  var el=lp(); if(!el) return; var t=targets();
  el.innerHTML='<div class="panel-card" id="layRoot"><h3 style="margin:0 0 4px;font-size:12px">Layouts</h3>'+
   '<div style="font-size:10.5px;color:var(--muted);line-height:1.5">Put clips side by side or in a grid. Select two or more clips (Ctrl-click) or stack clips on separate tracks at the playhead, then tap a layout. Box 1 gets the first clip in track order.</div>'+
   '<div id="layInfo" role="status" aria-live="polite" style="font-size:11px;margin-top:8px;color:'+(t.length>=2?"#9be0b4":"var(--warn,#f0c36a)")+'">'+(t.length>=2?t.length+" clips ready":"Need 2 or more clips (found "+t.length+")")+'</div>'+
   '<label style="display:flex;gap:8px;align-items:center;min-height:36px;font-size:11.5px;margin-top:6px"><input type="checkbox" id="layGap"'+(st.gap?" checked":"")+'> Thin gap between boxes</label>'+
   '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:6px">'+LAYS.map(function(L){ return '<button type="button" class="chip" data-lay="'+L.id+'" aria-label="Apply layout '+esc(L.n)+'" style="display:flex;flex-direction:column;gap:4px;padding:5px;min-height:64px"><canvas width="120" height="68" data-pv="'+L.id+'" style="width:100%;height:auto;border-radius:6px"></canvas><span style="font-size:10.5px">'+esc(L.n)+'</span></button>'; }).join("")+'</div>'+
   '<button type="button" class="chip" id="layReset" style="min-height:42px;width:100%;margin-top:10px;color:#ff91a0">Reset layout on these clips</button></div>';
  el.querySelectorAll("canvas[data-pv]").forEach(function(cv){ var L=LAYS.filter(function(x){ return x.id===cv.dataset.pv; })[0]; if(L) thumb(cv,L); });
}
function paint(){ if(activePanel==="layouts"){ try{ render(); }catch(e){window.__swl&&window.__swl(e)} } }
function bind(){
  var el=lp(); if(!el||el.__layBound) return; el.__layBound=true;
  el.addEventListener("click",function(e){
    if(activePanel!=="layouts") return; var b=e.target.closest&&e.target.closest("button"); if(!b) return;
    try{
      if(b.dataset.lay){ var L=LAYS.filter(function(x){ return x.id===b.dataset.lay; })[0]; if(L) apply(L); }
      else if(b.id==="layReset") reset();
    }catch(err){ say("That layout could not be applied: "+((err&&err.message)||err)); try{ window.amiyoReportError&&window.amiyoReportError("A layout could not be applied",err,{quiet:true}); }catch(x){window.__swl&&window.__swl(x)} }
  });
  el.addEventListener("change",function(e){ if(activePanel==="layouts"&&e.target.id==="layGap") st.gap=e.target.checked; });
}
var prev=window.renderLeftPanel;
window.renderLeftPanel=function(){
  if(activePanel!=="layouts") return prev.apply(this,arguments);
  try{ bind(); render(); }
  catch(err){ var el=lp(); if(el) el.innerHTML='<div class="panel-card" role="alert"><h3 style="margin:0 0 6px;font-size:12px;color:var(--danger)">Layouts could not load</h3><div style="font-size:11px;color:var(--muted)">'+esc((err&&err.message)||err)+'</div></div>'; try{ window.amiyoReportError&&window.amiyoReportError("The Layouts panel could not load",err,{quiet:true}); }catch(x){window.__swl&&window.__swl(x)} }
};
var pi=window.renderInspector;
window.renderInspector=function(){ var r=pi.apply(this,arguments); try{ if(activePanel==="layouts"){ var n=targets().length, i=document.getElementById("layInfo"); if(i){ i.textContent=n>=2?n+" clips ready":"Need 2 or more clips (found "+n+")"; i.style.color=n>=2?"#9be0b4":"var(--warn,#f0c36a)"; } } }catch(e){window.__swl&&window.__swl(e)} return r; };
function ensureNav(){
  var nav=document.getElementById("nav"); if(!nav||document.getElementById("navLayoutsBtn")) return;
  var b=document.createElement("button"); b.className="navbtn"; b.id="navLayoutsBtn"; b.type="button"; b.dataset.panel="layouts"; b.innerHTML='<span class="dot"></span>Layouts';
  b.addEventListener("click",function(){ activePanel="layouts"; nav.querySelectorAll(".navbtn").forEach(function(x){ x.classList.toggle("active",x===b); }); renderLeftPanel(); });
  nav.appendChild(b);
}
var ra=window.renderAll; window.renderAll=function(){ var r=ra.apply(this,arguments); try{ ensureNav(); }catch(e){window.__swl&&window.__swl(e)} return r; };
ensureNav(); setTimeout(ensureNav,250);
window.AMIYO_LAYOUTS={list:LAYS,geom:geom,apply:apply};
try{ window.AMIYO_EDITOR_BUILD="step137-layouts"; }catch(e){window.__swl&&window.__swl(e)}
})();

