  g.strokeStyle="rgba(255,255,255,.08)"; g.lineWidth=1; g.fillStyle="rgba(255,255,255,.4)"; g.font="9px system-ui";
  [-24,-12,0,12].forEach(function(d){ g.beginPath(); g.moveTo(0,Y(d)); g.lineTo(w,Y(d)); g.strokeStyle=d===0?"rgba(255,255,255,.25)":"rgba(255,255,255,.08)"; g.stroke(); g.fillText((d>0?"+":"")+d+" dB",3,Y(d)-2); });
  [100,1000,10000].forEach(function(f){ var x=Math.log(f/20)/Math.log(1000)*w; g.beginPath(); g.moveTo(x,0); g.lineTo(x,h); g.strokeStyle="rgba(255,255,255,.08)"; g.stroke(); g.fillText(f>=1000?(f/1000)+"k":String(f),x+3,h-3); });
