  ids.forEach(function(id){ var c=clipById(id); if(!c) return; var e=norm(c.eqFx)||{p:"custom",g:[0,0,0,0,0],hp:0,lp:0}; e.g[i]=v; e.p="custom"; c.eqFx=e; });
