/* ---- helpers ---- */
function find(id){ var r=null; if(!id) return null; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.id===id) r={clip:c,track:t}; }); }); return r; }
function say(m,t){ try{ X.say(m,t||3200); }catch(e){window.__swl&&window.__swl(e)} }
