/* ==================== Script 314 id="amiyo-step142-subtitles" ==================== */
/* =========================================================================
   Editor step 142 (round 5, step 7 of 10): SUBTITLE (SRT / VTT) IMPORT AND EDITING
   Before: the Captions tab could list captions and edit their words, but import added a second copy every time,
   line breaks were lost, you could not change a caption's start or end time as numbers, and there was nothing
   to fix a subtitle file that is out of sync or has overlaps.
   Now: a Subtitle editor (Captions tab > "Subtitle editor", Tools > Clip Extras, or Shift+H):
   - Import .srt / .vtt with a preview: add to or replace the current captions, shift the time, stretch for a
     different frame rate. Keeps two-line captions, strips formatting tags, handles non-UTF-8 files.
   - Edit every caption: start and end time as numbers, the words (several lines), split, merge, delete, add.
   - Find & replace, shift or stretch all timings, fix overlaps, extend very short captions, remove empty ones.
   - Problem check: overlaps, empty, too short, too fast to read. Show only problems.
   - Export .srt or .vtt that keeps line breaks and has correct times.
   Every change is one undo step.
   ========================================================================= */
(function(){
"use strict";
var CAPS=window.AMIYO_CAPS; if(!CAPS||!CAPS.mkClip){ try{ console.warn("step142: captions panel API missing"); }catch(e){window.__swl&&window.__swl(e)} return; }
var PAGE=30, MAXCUES=5000, S={page:0,q:"",prob:false,imp:null};
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
function say(m,t){ try{ toast(m,t||3200); }catch(e){window.__swl&&window.__swl(e)} }
function clone(o){ return JSON.parse(JSON.stringify(o)); }
function caps(){ var r=[]; project.tracks.forEach(function(t){ if(t.kind==="caption") t.clips.forEach(function(c){ r.push({t:t,c:c}); }); }); r.sort(function(a,b){ return a.c.start-b.c.start; }); return r; }
function find(id){ var r=null; caps().forEach(function(x){ if(x.c.id===id) r=x; }); return r; }
function sortAll(){ project.tracks.forEach(function(t){ if(t.kind==="caption") t.clips.sort(function(a,b){ return a.start-b.start; }); }); }
function pad(n,w){ n=String(n); while(n.length<w) n="0"+n; return n; }
function fmt(s,sep){ var ms=Math.max(0,Math.round(s*1000)), h=Math.floor(ms/3600000), m=Math.floor(ms%3600000/60000), x=Math.floor(ms%60000/1000); return pad(h,2)+":"+pad(m,2)+":"+pad(x,2)+(sep||".")+pad(ms%1000,3); }
function ptime(str){
  var s=String(str).trim().replace(",","."); if(!s) return NaN;
  var p=s.split(":"); if(p.length>3||p.some(function(x){ return !/^\d+(\.\d+)?$/.test(x.trim()); })) return NaN;
  p=p.map(Number); return p.length===3?p[0]*3600+p[1]*60+p[2]:p.length===2?p[0]*60+p[1]:p[0];
}

/* ---- reading a subtitle file ---- */
function cleanText(t){
  return String(t).replace(/<\/?[A-Za-z][^<>]*>|<\d+:\d+[:.\d]*>/g,"").replace(/\{\\[^}]*\}/g,"").replace(/&nbsp;/g," ").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&amp;/g,"&")
    .split("\n").map(function(l){ return l.replace(/\s+/g," ").trim(); }).filter(Boolean).join("\n");
}
function parseSubs(txt){
  txt=String(txt).replace(/^\uFEFF/,"").replace(/\r\n?/g,"\n");
  var out=[], skipped=0, re=/(?:(\d+):)?(\d+):(\d+)(?:[.,](\d+))?\s*-->\s*(?:(\d+):)?(\d+):(\d+)(?:[.,](\d+))?/;
  function sec(h,m,s,f){ return (+h||0)*3600+(+m)*60+(+s)+(f?Number("0."+f):0); }
  var blocks=txt.split(/\n{2,}/);
  for(var b=0;b<blocks.length;b++){
    var lines=blocks[b].split("\n"), tis=[];
    for(var i=0;i<lines.length;i++){ if(re.test(lines[i])) tis.push(i); }
    if(!tis.length) continue;
    /* step 14 fix: a file with no blank line between cues used to become ONE caption with the next cue's number and times inside its text. Every timing line now starts its own cue. */
    for(var k=0;k<tis.length;k++){
      var ti=tis[k], m=lines[ti].match(re), end=k+1<tis.length?tis[k+1]:lines.length;
      if(k+1<tis.length&&end-1>ti&&/^\s*\d+\s*$/.test(lines[end-1])) end--;   /* the next cue's number */
      var a=sec(m[1],m[2],m[3],m[4]), e=sec(m[5],m[6],m[7],m[8]), body=cleanText(lines.slice(ti+1,end).join("\n"));
      if(!body||!isFinite(a)||!isFinite(e)||e<=a){ skipped++; continue; }
      out.push({start:a,end:e,text:body});
      if(out.length>=MAXCUES) break;
    }
    if(out.length>=MAXCUES) break;
  }
  return {cues:out,skipped:skipped};
}
async function readFileText(file){
  var ab=await file.arrayBuffer();
  try{ return new TextDecoder("utf-8",{fatal:true}).decode(ab); }
  catch(e){ try{ return new TextDecoder("windows-1252").decode(ab); }catch(x){ return new TextDecoder().decode(ab); } }
}

/* ---- writing ---- */
function exportRows(){
  var rows=caps().filter(function(x){ return String(x.c.text||"").trim(); });
  if(!rows.length){ project.tracks.forEach(function(t){ if(t.kind==="text") t.clips.forEach(function(c){ if(String(c.text||"").trim()) rows.push({t:t,c:c}); }); }); rows.sort(function(a,b){ return a.c.start-b.c.start; }); }
  return rows;
}
/* export step 9: a blank line inside a caption ends the caption in an SRT/VTT file, so players dropped the rest of the text (or the whole next cue). Blank lines are now removed; VTT also gets & and < written safely. */
function cueText(t){ return String(t==null?"":t).replace(/\r/g,"").split("\n").map(function(l){ return l.replace(/\s+$/,""); }).filter(function(l){ return l.length; }).join("\n"); }
function byTime(rows){ return rows.slice().sort(function(x,y){ return x.c.start-y.c.start; }); }   /* step 14: cues must be in time order in the file, also when they come from several caption tracks */
function buildSrt(rows){ return byTime(rows).map(function(x,i){ return (i+1)+"\n"+fmt(x.c.start,",")+" --> "+fmt(x.c.start+x.c.duration,",")+"\n"+cueText(x.c.text).replace(/-->/g,"->")+"\n"; }).join("\n"); }   /* round 2 step 3: a literal --> inside a caption broke some players */
function buildVtt(rows){ return "WEBVTT\n\n"+byTime(rows).map(function(x){ return fmt(x.c.start,".")+" --> "+fmt(x.c.start+x.c.duration,".")+"\n"+cueText(x.c.text).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/-->/g,"--&gt;")+"\n"; }).join("\n"); }
function download(text,ext){
  var blob=new Blob([text],{type:"text/plain;charset=utf-8"}), u=URL.createObjectURL(blob), a=document.createElement("a");
  a.href=u; a.download=(project.metadata&&project.metadata.name||"amiyo")+"."+ext; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){ URL.revokeObjectURL(u); },1500);
}
function doExport(ext){
  var rows=exportRows(); if(!rows.length){ say("There are no captions to export yet"); return; }
  download(ext==="vtt"?buildVtt(rows):buildSrt(rows),ext); say(rows.length+" captions exported as ."+ext);
}
window.exportCaptions=function(){ doExport("srt"); };

/* ---- checking ---- */
function problems(rows){
  var res={}, byTrack={};
  rows.forEach(function(x){ (byTrack[x.t.id]=byTrack[x.t.id]||[]).push(x); });
  rows.forEach(function(x){
    var c=x.c, p=[], txt=String(c.text||"").trim(), d=c.duration;
    if(!txt||txt==="…") p.push("empty");
    else{ if(d<.7) p.push("very short"); var cps=txt.replace(/\s+/g,"").length/Math.max(.05,d); if(cps>20) p.push("reads fast ("+Math.round(cps)+" letters/s)"); }
    res[c.id]=p;
  });
  Object.keys(byTrack).forEach(function(k){ var l=byTrack[k]; for(var i=0;i<l.length-1;i++){ if(l[i+1].c.start<l[i].c.start+l[i].c.duration-.01){ res[l[i].c.id].push("overlaps next"); } } });
  return res;
}

/* ---- the changes ---- */
function lockedMsg(){ say("That caption track is locked — unlock it first",3600); }
function tx(label,fn){ window.transact(label,function(){ fn(); sortAll(); }); }
function setTime(id,which,str){
  var hit=find(id); if(!hit) return; if(hit.t.locked){ lockedMsg(); renderList(); return; }
  var v=ptime(str); if(!isFinite(v)||v<0){ say("Type a time like 00:01:05.500 or 65.5",3400); renderList(); return; }
  tx("Edit caption time",function(){ var c=hit.c, end=c.start+c.duration; if(which==="start"){ c.start=v; c.duration=Math.max(.05,end-v); } else c.duration=Math.max(.05,v-c.start); });
}
function setText(id,v){ var hit=find(id); if(!hit) return; if(hit.t.locked){ lockedMsg(); renderList(); return; } v=String(v).replace(/\r/g,""); if((hit.c.text||"")!==v) tx("Edit caption",function(){ hit.c.text=v; }); }
function del(id){ var hit=find(id); if(!hit) return; if(hit.t.locked){ lockedMsg(); return; } tx("Delete caption",function(){ hit.t.clips=hit.t.clips.filter(function(c){ return c.id!==id; }); if(selectedClipId===id) selectedClipId=null; }); }
function splitCap(id){
  var hit=find(id); if(!hit) return; if(hit.t.locked){ lockedMsg(); return; }
  var c=hit.c, words=String(c.text||"").trim().split(/\s+/).filter(Boolean);
  if(words.length<2){ say("A caption needs at least two words to split",3400); return; }
  var t=currentTime, inside=(t>c.start+.1&&t<c.start+c.duration-.1), at=inside?t:c.start+c.duration/2, frac=(at-c.start)/c.duration;
  var k=Math.max(1,Math.min(words.length-1,Math.round(words.length*frac))), end=c.start+c.duration, nid=null;
  tx("Split caption",function(){
    var r=clone(c); r.id=uid("cap"); r.text=words.slice(k).join(" "); r.start=at; r.duration=end-at; nid=r.id;
    c.text=words.slice(0,k).join(" "); c.duration=at-c.start; hit.t.clips.push(r);
  });
  say(inside?"Split at the playhead":"Split in the middle (put the playhead inside the caption to choose the spot)",3200);
}
function mergeNext(id){
  var all=caps(), i=-1; all.forEach(function(x,k){ if(x.c.id===id) i=k; });
  if(i<0) return; var a=all[i], b=null; for(var k=i+1;k<all.length;k++){ if(all[k].t===a.t){ b=all[k]; break; } }
  if(!b){ say("There is no next caption on this track to join",3200); return; }
  if(a.t.locked){ lockedMsg(); return; }
  tx("Join captions",function(){ a.c.text=(String(a.c.text||"").trim()+" "+String(b.c.text||"").trim()).trim(); a.c.duration=Math.max(a.c.duration,b.c.start+b.c.duration-a.c.start); a.t.clips=a.t.clips.filter(function(c){ return c.id!==b.c.id; }); });
}
function addCap(){
  var t=CAPS.captionTrack(); if(!t) return;
  var start=currentTime, moved=true, g=0;
  while(moved&&g++<500){ moved=false; t.clips.forEach(function(c){ if(start<c.start+c.duration-.001&&start+2.5>c.start+.001){ start=c.start+c.duration; moved=true; } }); }
  var nid=null; tx("Add caption",function(){ var c=CAPS.mkClip("New caption",start,2.5); t.clips.push(c); nid=c.id; });
  S.q=""; S.prob=false; var i=0; caps().forEach(function(x,k){ if(x.c.id===nid) i=k; }); S.page=Math.floor(i/PAGE); renderList(); say("Caption added at "+fmt(start));
}
function retime(factor,offset,after){
  var rows=caps().filter(function(x){ return !x.t.locked&&(!after||x.c.start>=currentTime-.001); });
  if(!rows.length){ say(after?"No captions after the playhead":"There are no captions yet",3200); return; }
  if(!isFinite(factor)||factor<=0||!isFinite(offset)){ say("Type a number for the shift and a stretch above 0",3400); return; }
  var mn=Math.min.apply(null,rows.map(function(x){ return x.c.start*factor+offset; }));
  if(mn<-.0005){ say("That would move the first caption before 0:00. Use a smaller shift.",4200); return; }
  tx("Shift caption timing",function(){ rows.forEach(function(x){ x.c.start=Math.round((x.c.start*factor+offset)*1000)/1000; x.c.duration=Math.max(.05,Math.round(x.c.duration*factor*1000)/1000); }); });
  say(rows.length+" captions retimed"); renderList();
}
function replaceAll(a,b,cs){
  if(!a){ say("Type the words to find first",3200); return; }
  var re=new RegExp(a.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),cs?"g":"gi"), n=0, rows=caps().filter(function(x){ return !x.t.locked&&re.test(String(x.c.text||"")); });
  re.lastIndex=0;
  if(!rows.length){ say("No caption contains “"+a+"”",3400); return; }
  tx("Find and replace in captions",function(){ rows.forEach(function(x){ x.c.text=String(x.c.text).replace(re,function(){ n++; return b; }); }); });
  say(n+" replaced in "+rows.length+" caption"+(rows.length===1?"":"s")); renderList();
}
function fixOverlaps(){
  var n=0, byT={}; caps().forEach(function(x){ if(!x.t.locked) (byT[x.t.id]=byT[x.t.id]||[]).push(x); });
  var todo=[]; Object.keys(byT).forEach(function(k){ var l=byT[k]; for(var i=0;i<l.length-1;i++){ if(l[i+1].c.start<l[i].c.start+l[i].c.duration-.01) todo.push([l[i].c,l[i+1].c.start]); } });
  if(!todo.length){ say("No overlapping captions found",3000); return; }
  tx("Fix caption overlaps",function(){ todo.forEach(function(p){ p[0].duration=Math.max(.1,Math.round((p[1]-.02-p[0].start)*1000)/1000); n++; }); });
  say(n+" overlap"+(n===1?"":"s")+" fixed"); renderList();
}
function extendShort(){
  var byT={}; caps().forEach(function(x){ if(!x.t.locked) (byT[x.t.id]=byT[x.t.id]||[]).push(x); });
  var todo=[]; Object.keys(byT).forEach(function(k){ var l=byT[k]; l.forEach(function(x,i){ var c=x.c; if(String(c.text||"").trim()&&c.duration<1){ var lim=l[i+1]?l[i+1].c.start-.02:Infinity, nd=Math.min(1,lim-c.start); if(nd>c.duration+.01) todo.push([c,nd]); } }); });
  if(!todo.length){ say("No short captions have room to grow",3200); return; }
  tx("Lengthen short captions",function(){ todo.forEach(function(p){ p[0].duration=Math.round(p[1]*1000)/1000; }); });
  say(todo.length+" short caption"+(todo.length===1?"":"s")+" lengthened to 1 s"); renderList();
}
function removeEmpty(){
  var rows=caps().filter(function(x){ return !x.t.locked&&!String(x.c.text||"").trim(); });
  if(!rows.length){ say("No empty captions found",3000); return; }
  var ids={}; rows.forEach(function(x){ ids[x.c.id]=1; });
  tx("Remove empty captions",function(){ project.tracks.forEach(function(t){ if(t.kind==="caption"&&!t.locked) t.clips=t.clips.filter(function(c){ return !ids[c.id]; }); }); });
  say(rows.length+" empty caption"+(rows.length===1?"":"s")+" removed"); renderList();
}

/* ---- import with preview ---- */
var picker=null;
function pickFile(){
  if(!picker){ picker=document.createElement("input"); picker.type="file"; picker.accept=".srt,.vtt,.txt,text/vtt,text/plain,application/x-subrip"; picker.style.display="none"; document.body.appendChild(picker); }
  picker.value=""; picker.onchange=function(){ if(picker.files&&picker.files[0]) importFile(picker.files[0]); }; picker.click();
}
async function importFile(file){
  try{
    if(file.size>5*1048576) throw new Error("That file is over 5 MB.");
    var r=parseSubs(await readFileText(file));
    if(!r.cues.length) throw new Error("No captions were found. Use an .srt or .vtt file.");
    if(!document.getElementById("subRoot")) open();
    var have=caps(), same=0; if(have.length){ var key={}; have.forEach(function(x){ key[Math.round(x.c.start*10)+"|"+String(x.c.text||"").replace(/\s+/g," ").trim()]=1; }); r.cues.forEach(function(q){ if(key[Math.round(q.start*10)+"|"+q.text.replace(/\s+/g," ")]) same++; }); }
    S.imp={name:file.name,cues:r.cues,skipped:r.skipped,mode:(have.length&&same>=r.cues.length*.5)?"replace":"add",dup:same,offset:0,stretch:1};
    renderImp();
  }catch(e){ say("Could not import: "+((e&&e.message)||e),4500); }
}
function applyImport(){
  var I=S.imp; if(!I) return;
  var off=Number((document.getElementById("subOff")||{}).value||0), st=Number((document.getElementById("subStr")||{}).value||1);
  var mode=((document.querySelector('input[name="subMode"]:checked'))||{}).value||I.mode;
  if(!isFinite(off)||!isFinite(st)||st<=0){ say("Check the shift and stretch numbers",3400); return; }
  var t=CAPS.captionTrack(); if(!t) return;
  var made=0, cut=0;
  tx("Import subtitles",function(){
    if(mode==="replace") project.tracks.forEach(function(tr){ if(tr.kind==="caption"&&!tr.locked) tr.clips=[]; });
    I.cues.forEach(function(q){
      var a=q.start*st+off, b=q.end*st+off; if(b<=.05){ cut++; return; } if(a<0) a=0;
      var c=CAPS.mkClip(q.text,Math.round(a*1000)/1000,Math.max(.1,Math.round((b-a)*1000)/1000)); t.clips.push(c); made++;
    });
    selectedTrackId=t.id;
  });
  S.imp=null; S.page=0; S.q=""; S.prob=false;
  say(made+" captions "+(mode==="replace"?"imported (old ones replaced)":"added")+(cut?", "+cut+" skipped (before 0:00)":"")+". Check them and use the problem check.",5000);
  try{ CAPS.render&&CAPS.render(); }catch(e){window.__swl&&window.__swl(e)}
  renderImp(); renderList();
}
function renderImp(){
  var box=document.getElementById("subImp"); if(!box) return; var I=S.imp;
  if(!I){ box.innerHTML=""; return; }
  var first=I.cues[0].start, last=I.cues[I.cues.length-1].end, have=caps().length;
  box.innerHTML='<div class="panel-card" style="margin:8px 0;padding:10px"><div style="font-size:12px;font-weight:600">'+esc(I.name)+'</div>'+
   '<div style="font-size:11px;color:var(--muted);line-height:1.5;margin:4px 0 6px">'+I.cues.length+' captions from '+fmt(first)+' to '+fmt(last)+(I.skipped?' · '+I.skipped+' unreadable block'+(I.skipped===1?'':'s')+' skipped':'')+'. “'+esc(I.cues[0].text.split("\n")[0].slice(0,50))+'…”</div>'+
   (have?'<div style="font-size:12px;margin-bottom:4px"><label style="display:flex;gap:8px;align-items:center;min-height:34px"><input type="radio" name="subMode" value="add"'+(I.mode==="add"?" checked":"")+'> Add to the '+have+' captions already here</label>'+
     '<label style="display:flex;gap:8px;align-items:center;min-height:34px"><input type="radio" name="subMode" value="replace"'+(I.mode==="replace"?" checked":"")+'> Replace them'+(I.dup?' <span style="color:var(--muted)">(this file looks like one already imported)</span>':'')+'</label></div>':'')+
   '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11px"><label>Shift (seconds)<input id="subOff" type="number" step="0.1" value="0" class="search" style="width:100%"></label>'+
   '<label>Stretch (× speed)<input id="subStr" type="number" step="0.0001" min="0.1" max="10" value="1" class="search" style="width:100%"></label></div>'+
   '<div style="font-size:10px;color:var(--muted);margin:4px 0 8px;line-height:1.45">Shift moves every caption later (+) or earlier (−). Stretch fixes a frame-rate mismatch: 25 fps file on 23.976 fps video → 1.0427; 23.976 → 25 fps → 0.9590.</div>'+
   '<div class="mini-row"><button type="button" class="chip" data-sa="impok" style="min-height:44px;background:var(--accent);color:#1a0c03;font-weight:700">Import</button><button type="button" class="chip" data-sa="impno" style="min-height:44px">Cancel</button></div></div>';
}

/* ---- the window ---- */
function rowHtml(x,n,prob){
  var c=x.c, p=prob[c.id]||[];
  return '<div class="sub-row" data-id="'+esc(c.id)+'" style="padding:8px;border-bottom:1px solid var(--line-soft)">'+
   '<div style="display:grid;grid-template-columns:24px 1fr 1fr;gap:6px;align-items:center"><span style="font-size:10px;color:var(--muted)">'+n+'</span>'+
   '<input data-sf="start" type="text" inputmode="decimal" value="'+fmt(c.start)+'" aria-label="Start time of caption '+n+'" style="min-width:0;font-family:var(--font-mono,monospace);font-size:11px;padding:6px">'+
   '<input data-sf="end" type="text" inputmode="decimal" value="'+fmt(c.start+c.duration)+'" aria-label="End time of caption '+n+'" style="min-width:0;font-family:var(--font-mono,monospace);font-size:11px;padding:6px"></div>'+
   '<textarea data-sf="text" rows="'+Math.min(4,Math.max(2,String(c.text||"").split("\n").length))+'" aria-label="Words of caption '+n+'" style="width:100%;margin-top:6px;font-size:12px;box-sizing:border-box">'+esc(c.text||"")+'</textarea>'+
   '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:4px"><button type="button" class="chip" data-sa="jump" style="min-height:36px" aria-label="Go to caption '+n+'">▶ Go</button><button type="button" class="chip" data-sa="split" style="min-height:36px">✂ Split</button><button type="button" class="chip" data-sa="merge" style="min-height:36px">⤓ Join next</button><button type="button" class="chip" data-sa="del" style="min-height:36px;color:#ff91a0">Delete</button>'+
   (p.length?'<span style="font-size:10.5px;color:var(--warn,#f0c36a)">⚠ '+esc(p.join(", "))+'</span>':'')+'</div></div>';
}
function renderList(){
  var box=document.getElementById("subList"); if(!box) return;
  var all=caps(), prob=problems(all), q=S.q.trim().toLowerCase(), pc=0;
  all.forEach(function(x){ if((prob[x.c.id]||[]).length) pc++; });
  var rows=[]; all.forEach(function(x,i){ if(S.prob&&!(prob[x.c.id]||[]).length) return; if(q&&String(x.c.text||"").toLowerCase().indexOf(q)<0) return; rows.push([x,i+1]); });
  var pages=Math.max(1,Math.ceil(rows.length/PAGE)); S.page=Math.max(0,Math.min(pages-1,S.page));
  var show=rows.slice(S.page*PAGE,S.page*PAGE+PAGE);
  var sum=document.getElementById("subSum"); if(sum) sum.textContent=all.length+" caption"+(all.length===1?"":"s")+(pc?" · "+pc+" with problems":(all.length?" · no problems found":""));
  box.innerHTML=(show.length?show.map(function(r){ return rowHtml(r[0],r[1],prob); }).join(""):'<div style="padding:14px;font-size:12px;color:var(--muted)">'+(all.length?(S.prob&&!pc?"No problems found. 🎉":"No caption matches."):"There are no captions yet. Import a subtitle file or add one.")+'</div>')+
   (pages>1?'<div class="mini-row" style="padding:8px;justify-content:center;align-items:center"><button type="button" class="chip" data-sa="prev" '+(S.page?"":"disabled")+' style="min-height:38px">‹ Prev</button><span style="font-size:11px;color:var(--muted)">Page '+(S.page+1)+' of '+pages+'</span><button type="button" class="chip" data-sa="next" '+(S.page<pages-1?"":"disabled")+' style="min-height:38px">Next ›</button></div>':"");
}
function body(){
  return '<div id="subRoot"><div class="mini-row" style="flex-wrap:wrap;gap:6px"><button type="button" class="chip" data-sa="import" style="min-height:42px">⇩ Import SRT / VTT</button><button type="button" class="chip" data-sa="srt" style="min-height:42px">⇧ Export SRT</button><button type="button" class="chip" data-sa="vtt" style="min-height:42px">⇧ Export VTT</button><button type="button" class="chip" data-sa="add" style="min-height:42px">＋ Add at playhead</button></div>'+
   '<div id="subImp"></div>'+
   '<div style="display:flex;gap:8px;align-items:center;margin:10px 0 4px"><input id="subQ" type="search" class="search" placeholder="Search captions…" style="flex:1;min-width:0" aria-label="Search captions"><label style="display:flex;gap:6px;align-items:center;font-size:11.5px;white-space:nowrap"><input type="checkbox" id="subProb"> Problems only</label></div>'+
   '<div id="subSum" role="status" style="font-size:11px;color:var(--muted);margin-bottom:4px"></div>'+
   '<div id="subList" style="max-height:46vh;overflow:auto;border:1px solid var(--line-soft);border-radius:8px"></div>'+
   '<details style="margin-top:10px"><summary style="cursor:pointer;font-size:12px;min-height:34px">Shift or stretch all timings</summary><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11px;margin-top:6px"><label>Shift (seconds)<input id="rtOff" type="number" step="0.1" value="0" class="search" style="width:100%"></label><label>Stretch (× speed)<input id="rtStr" type="number" step="0.0001" min="0.1" value="1" class="search" style="width:100%"></label></div><label style="display:flex;gap:8px;align-items:center;font-size:11.5px;min-height:34px;margin-top:4px"><input type="checkbox" id="rtAfter"> Only captions after the playhead</label><button type="button" class="chip" data-sa="retime" style="min-height:42px;margin-top:4px">Apply timing</button></details>'+
   '<details style="margin-top:6px"><summary style="cursor:pointer;font-size:12px;min-height:34px">Find and replace</summary><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px"><input id="frA" class="search" placeholder="Find" aria-label="Find"><input id="frB" class="search" placeholder="Replace with" aria-label="Replace with"></div><label style="display:flex;gap:8px;align-items:center;font-size:11.5px;min-height:34px"><input type="checkbox" id="frCase"> Match upper / lower case</label><button type="button" class="chip" data-sa="replace" style="min-height:42px">Replace all</button></details>'+
   '<details style="margin-top:6px"><summary style="cursor:pointer;font-size:12px;min-height:34px">Clean up</summary><div class="mini-row" style="flex-wrap:wrap;gap:6px;margin-top:6px"><button type="button" class="chip" data-sa="fixov" style="min-height:42px">Fix overlaps</button><button type="button" class="chip" data-sa="ext" style="min-height:42px">Lengthen short ones</button><button type="button" class="chip" data-sa="rmempty" style="min-height:42px">Remove empty</button></div><div style="font-size:10.5px;color:var(--muted);margin-top:6px;line-height:1.45">Problems checked: empty, shorter than 0.7 s, faster than 20 letters per second, and overlapping the next caption.</div></details></div>';
}
function bind(){
  var root=document.getElementById("subRoot"); if(!root) return;
  root.addEventListener("click",function(e){
    var b=e.target.closest&&e.target.closest("button[data-sa]"); if(!b||b.disabled) return;
    var a=b.dataset.sa, row=b.closest(".sub-row"), id=row&&row.dataset.id;
    try{
      if(a==="import") pickFile(); else if(a==="srt") doExport("srt"); else if(a==="vtt") doExport("vtt"); else if(a==="add") addCap();
      else if(a==="impok") applyImport(); else if(a==="impno"){ S.imp=null; renderImp(); }
      else if(a==="jump"){ var h=find(id); if(h){ selectedClipId=h.c.id; selectedTrackId=h.t.id; currentTime=h.c.start+.01; try{ if(isPlaying) pause(); }catch(x){window.__swl&&window.__swl(x)} try{ renderAll(); }catch(x){window.__swl&&window.__swl(x)} say("Playhead at "+fmt(h.c.start),1800); } }
      else if(a==="split") splitCap(id); else if(a==="merge") mergeNext(id); else if(a==="del") del(id);
      else if(a==="prev"){ S.page--; renderList(); } else if(a==="next"){ S.page++; renderList(); }
      else if(a==="retime") retime(Number(document.getElementById("rtStr").value),Number(document.getElementById("rtOff").value),document.getElementById("rtAfter").checked);
      else if(a==="replace") replaceAll(document.getElementById("frA").value,document.getElementById("frB").value,document.getElementById("frCase").checked);
      else if(a==="fixov") fixOverlaps(); else if(a==="ext") extendShort(); else if(a==="rmempty") removeEmpty();
    }catch(err){ say("That did not work: "+((err&&err.message)||err),4500); try{ window.amiyoReportError&&window.amiyoReportError("The subtitle editor hit a problem",err,{quiet:true}); }catch(x){window.__swl&&window.__swl(x)} }
  });
  root.addEventListener("change",function(e){
    var t=e.target, f=t.dataset&&t.dataset.sf, row=t.closest&&t.closest(".sub-row"); 
    if(t.id==="subProb"){ S.prob=t.checked; S.page=0; renderList(); return; }
    if(!f||!row) return;
    try{ if(f==="text") setText(row.dataset.id,t.value); else setTime(row.dataset.id,f,t.value); renderList(); }catch(err){ say("That did not work: "+((err&&err.message)||err),4500); }
  });
  root.addEventListener("input",function(e){ if(e.target.id==="subQ"){ S.q=e.target.value; S.page=0; renderList(); } });
}
function open(){
  S.page=0; S.q=""; S.prob=false; S.imp=null;
  openModal("Subtitle editor",body()); bind(); renderList();
}
window.AMIYO_SUBS={open:open,parse:parseSubs,build:buildSrt,buildVtt:buildVtt,fmt:fmt,ptime:ptime,import:importFile};

/* ---- take over the old, simple import so every entry point gets the preview ---- */
window.importCaptionFile=function(file){ importFile(file); };

/* ---- shortcut, command palette ---- */
if(window.amiyoX){
  var X=window.amiyoX; X.subtitleEditor=open;
  X.addShortcut&&X.addShortcut("Shift+H","Subtitle editor: import, edit times and words, fix and export SRT / VTT");
  document.addEventListener("keydown",function(ev){
    var a=document.activeElement, t=a&&a.tagName; if(t==="INPUT"||t==="TEXTAREA"||t==="SELECT"||(a&&a.isContentEditable)) return;
    if(ev.ctrlKey||ev.metaKey||ev.altKey) return;
    if(ev.shiftKey&&ev.code==="KeyH"){ ev.preventDefault(); ev.stopImmediatePropagation(); open(); }
  },true);
}
var oc=window.commandList;
if(typeof oc==="function") window.commandList=function(){ return oc.apply(this,arguments).concat([["Subtitle editor…","AMIYO_SUBS.open()"],["Import subtitles (SRT / VTT)…","AMIYO_SUBS.open()"]]); };
try{ window.AMIYO_EDITOR_BUILD="step142-subtitles"; }catch(e){window.__swl&&window.__swl(e)}
})();

