var rt=window.renderTracks;
if(typeof rt==="function") window.renderTracks=function(){ var r=rt.apply(this,arguments); hook(); return r; };
hook();
function release(){
  var d=D; D=null; hideGuide();
  if(!d||!d.moved||d.mode!=="left"||d.ip==null) return;
  /* Undo of a start-trim must bring the in-point back too */
  requestAnimationFrame(function(){ try{
    var ents=project.history&&project.history.entries||[], i0=project.history.index;
    for(var i=i0;i>=Math.max(0,i0-2);i--){ var en=ents[i]; if(!en||!en.before||!en.before.tracks) continue;
      if(en.label!=="Trim start"&&en.label!=="Snap") continue;
      var tr=en.before.tracks.find(function(t){ return t.id===d.track; }), cl=tr&&tr.clips.find(function(c){ return c.id===d.id; });
      if(cl&&Math.abs(cl.start-d.s)<.0005){ cl.inPoint=d.ip; break; } }
  }catch(e){window.__swl&&window.__swl(e)} });
}
window.addEventListener("pointerup",release,true);
window.addEventListener("pointercancel",release,true);

/* ---------- snap settings window ---------- */
var OPTS=[["playhead","Playhead","the red line at the current time"],["edges","Clip edges","start and end of every other clip"],["markers","Markers",""],["io","In / Out points",""],["start","Start of timeline","time 0:00"]];
function settingsHtml(){
  return '<div style="font-size:12px;color:var(--muted);line-height:1.5;margin-bottom:8px">Snapping pulls a clip to a nearby point while you drag or trim it, and shows a green line. Hold Ctrl / Cmd while dragging to snap to nothing.</div>'+
    '<div style="font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)">Pull strength</div><div class="sn-sens" id="snSens">'+
    [[6,"Low"],[10,"Normal"],[16,"High"]].map(function(r){ return '<button type="button" data-px="'+r[0]+'" class="'+(cfg.px===r[0]?"on":"")+'">'+r[1]+'</button>'; }).join("")+'</div>'+
    '<div style="font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)">Snap to</div>'+
    OPTS.map(function(o){ return '<label class="sn-row"><input type="checkbox" data-k="'+o[0]+'"'+(cfg[o[0]]?" checked":"")+'><span>'+esc(o[1])+(o[2]?'<small>'+esc(o[2])+'</small>':'')+'</span></label>'; }).join("")+
    '<label class="sn-row"><input type="checkbox" id="snMaster"'+(snapOn()?" checked":"")+'><span>Snapping on<small>same as the 🧲 Snap button</small></span></label>';
}
function openSettings(){
  window.openModal("Snap settings",settingsHtml());
  var b=$("modalBody"); if(!b) return;
  b.onclick=function(e){ var t=e.target&&e.target.closest?e.target.closest("[data-px]"):null; if(!t) return; cfg.px=+t.getAttribute("data-px"); saveCfg(); D&&(D.targets=null); [].forEach.call(b.querySelectorAll("[data-px]"),function(x){ x.classList.toggle("on",x===t); }); };
  b.onchange=function(e){ var t=e.target; if(!t||!t.type) return;
    if(t.id==="snMaster"){ if(t.checked!==snapOn()&&$("snapToggle")) $("snapToggle").click(); return; }
    var k=t.getAttribute("data-k"); if(k){ cfg[k]=!!t.checked; saveCfg(); } };
}
(function(){
  var sb=$("snapToggle"); if(!sb) return;
  sb.addEventListener("contextmenu",function(e){ e.preventDefault(); openSettings(); });
  if(!$("snapCfgBtn")){ var g=document.createElement("button"); g.type="button"; g.className="toolbtn"; g.id="snapCfgBtn"; g.textContent="⚙"; g.title="Snap settings"; g.setAttribute("aria-label","Snap settings"); g.onclick=openSettings; sb.parentNode.insertBefore(g,sb.nextSibling); }
})();

/* ---------- zoom ---------- */
function scroller(){ return $("timelineScroll"); }
function setZoomVal(z){ timelineZoom=Math.round(Math.min(AZ_MAX,Math.max(AZ_MIN,z))); var s=$("timelineZoom"); if(s) s.value=timelineZoom; }
var Z={prev:null,set:null};
function zoomRange(s,e,pad){
  var ts=scroller(); if(!ts) return false;
  var dur=Math.max(.05,e-s), avail=Math.max(200,ts.clientWidth-labelW()-40), z=avail*(1-2*pad)/dur/6.4*100;
  if(typeof window.amiyoZoomTo==="function"){      /* the zoom module keeps the % readout and slider in step */
    window.amiyoZoomTo(z,labelW()+(ts.clientWidth-labelW())/2,(s+e)/2,true); return true;
  }
  setZoomVal(z); renderTimeline();
  ts.scrollLeft=Math.max(0,timeToPx((s+e)/2)-(ts.clientWidth-labelW())/2);
  return true;
}
function selRange(){
  var X=window.amiyoX, l=X&&X.sel?X.sel():[]; if(!l.length) return null;
  var s=Infinity,e=0; l.forEach(function(x){ s=Math.min(s,x.clip.start); e=Math.max(e,x.clip.start+x.clip.duration); });
  return {s:s,e:e,n:l.length};
}
