    var S=selClip(); if(!S||S.clip.assetId&&!S.clip.kind){ toast("First select the text or sticker clip that should follow something"); return; }
    mkOverlay("Tap the spot in the picture to follow",function(e){ var r=viewCanvas.getBoundingClientRect(), u=(e.clientX-r.left)/r.width, v=(e.clientY-r.top)/r.height;
      if(u<0||u>1||v<0||v>1) return; overlay.onpointerdown=null; overlay.addEventListener("pointerdown",function(ev){ ev.stopPropagation(); cancel=true; },true); say("Starting…"); track(S.clip,u,v).catch(function(err){ console.warn(err); toast("Tracking stopped"); done(); }); });
