    var hint=document.createElement("div"); hint.textContent="Tap the backdrop colour to remove (tap here to cancel)"; hint.style.cssText="margin-top:8px;padding:7px 12px;border-radius:999px;background:#14120f;color:#ffe6bd;border:1px solid #ffb454;font:600 12px system-ui,sans-serif;max-width:90%;text-align:center;pointer-events:none";
