      var r=viewCanvas.getBoundingClientRect(), u=(e.clientX-r.left)/r.width, v=(e.clientY-r.top)/r.height; if(u<0||u>1||v<0||v>1){ stopPick(); return; }
      stopPick(); var k=S.clip.chromaKey, was=k.enabled; k.enabled=false;
