      var kc=rgbOf(k.color), ki=(kc[1]>=kc[0]&&kc[1]>=kc[2])?1:((kc[2]>=kc[0]&&kc[2]>=kc[1])?2:0), o1=(ki+1)%3, o2=(ki+2)%3;
      var W=[.299,.587,.114], amt=Math.max(0,Math.min(100,k.spAmt||0))/100, rng=Math.max(0,Math.min(100,k.spRange==null?50:k.spRange))/100,
          comp=Math.max(0,Math.min(100,k.spComp||0))/100, des=Math.max(0,Math.min(100,k.spDesat||0))/100,
          sat=1+(k.ccSat||0)/100, lum=1+(k.ccLum||0)/200, hue=k.ccHue||0, M=hue?hueMat(hue):null, doSp=spillOn(k), doCc=ccOn(k);
