    DEF.forEach(function(f,ix){ if(ix===4) h+='<label class="field" style="font-weight:700;margin-top:8px">Colour correction (the person)</label>'; h+='<label class="field">'+f[1]+' <span id="'+f[0]+'V" style="opacity:.7">'+val(f)+'</span> <span style="opacity:.5;font-weight:400">'+f[5]+'</span></label><input id="'+f[0]+'" type="range" min="'+f[2]+'" max="'+f[3]+'" step="1" value="'+val(f)+'">'; });
    box.innerHTML=h; anchor.parentNode.insertBefore(box,anchor.nextSibling);
    function redraw(){ try{ scheduleAutosave(); }catch(e){ window.__swl&&window.__swl(e); } try{ renderPreviewFrame(); }catch(e){ window.__swl&&window.__swl(e); } }
