    for(y=0;y<h;y++){ var row=y*w; sum=0; for(k=-r;k<=r;k++) sum+=a[row+Math.min(w-1,Math.max(0,k))];
      for(x=0;x<w;x++){ o[row+x]=sum/n; sum+=a[row+Math.min(w-1,x+r+1)]-a[row+Math.max(0,x-r)]; } }
    tmp=a; a=o; o=tmp; BB=o;
