      var tmp=F32("tmp",N), bR=F32("bR",N), bG=F32("bG",N), bB=F32("bB",N), bW=F32("bW",N), fR=F32("fR",N), fG=F32("fG",N), fB=F32("fB",N), fW=F32("fW",N), cv=F32("cv",N);
