    var box=document.createElement("div"); box.id="ck167"; box.style.cssText="margin:8px 0 6px;padding-bottom:8px;border-bottom:1px solid var(--line,#ffffff22)";
    box.innerHTML='<label class="field">Key settings: copy and presets</label>'+
      '<div class="mini-row"><button type="button" class="chip" id="ksCopy" style="min-height:38px">Copy this clip\'s settings</button><button type="button" class="chip" id="ksPaste" style="min-height:38px"'+(cb?"":" disabled")+'>Paste here</button></div>'+
      '<div class="mini-row" style="margin-top:6px"><button type="button" class="chip" id="ksTrack" style="min-height:38px">Apply to all clips on this track</button></div>'+
      '<div class="mini-row" style="margin-top:6px;flex-direction:column;align-items:flex-start;gap:4px"><label style="font-size:10px;display:flex;align-items:center;gap:5px"><input type="checkbox" id="ksPl" '+(inc.plate?"checked":"")+'/> Also copy clean plate</label><label style="font-size:10px;display:flex;align-items:center;gap:5px"><input type="checkbox" id="ksGm" '+(inc.gm?"checked":"")+'/> Also copy garbage matte</label></div>'+
      '<label class="field" style="margin-top:8px">My presets</label>'+
      (names.length?'<select id="ksSel" style="width:100%;min-height:36px">'+names.map(function(n){ return '<option value="'+esc(n)+'">'+esc(n)+'</option>'; }).join("")+'</select><div class="mini-row" style="margin-top:6px"><button type="button" class="chip" id="ksApply" style="min-height:38px">Apply preset</button><button type="button" class="chip" id="ksDel" style="min-height:38px">Delete</button></div>':'<div style="font-size:10.5px;color:var(--muted);margin:2px 0 4px">No presets yet.</div>')+
      '<div class="mini-row" style="margin-top:6px"><button type="button" class="chip" id="ksSave" style="min-height:38px">💾 Save current as preset</button></div>';
