/* ==================== Script 340 id="amiyo-gs2-step09-moving-bg" ==================== */
/* GREEN SCREEN plan 2, Step 9 of 10: MOVING BACKGROUNDS.
   Chroma Key (Inspector) > "Moving background" (shown once Replace background is not Off). MOTION: slow zoom in, slow zoom out, or a drift left / right / up / down across the whole clip,
   smooth at the start and end. AMOUNT (5-50 %) says how far it moves; a drift also enlarges the picture a little so no edge shows. The motion is applied on top of your own Scale / Position,
   in the preview and in the export, and your saved Scale / Position are never changed.
   TIMELINE CLIP AS BACKGROUND: Replace background > "Timeline clip" - choose any other video or picture clip from the timeline; it plays in step with that clip (same moment, trim and speed) behind the person.
   If that clip is deleted the background turns black until you choose another. Undo works. Old projects are unchanged (Motion None). */
(function(){
  var prev=window.__amiyoApplyChromaKey;
  function findClip(id){ for(var i=0;i<project.tracks.length;i++){ var t=project.tracks[i]; for(var j=0;j<(t.clips||[]).length;j++) if(t.clips[j].id===id) return {clip:t.clips[j],track:t,ti:i}; } return null; }
  function ease(p){ return p<=0?0:p>=1?1:p*p*(3-2*p); }
  function motion(bg,clip){
    var m=bg.motion; if(!m||!m.type||m.type==="none") return null;
    var a=Math.max(.05,Math.min(.5,(m.amount==null?15:m.amount)/100)), d=clip.duration||1, p=ease((currentTime-clip.start)/d), base=(bg.scale==null?100:bg.scale)/100, bx=bg.x||0, by=bg.y||0, r={scale:base*100,x:bx,y:by};
    switch(m.type){
      case "zoomin": r.scale=base*(1+a*p)*100; break;
      case "zoomout": r.scale=base*(1+a*(1-p))*100; break;
      case "left": r.scale=base*(1+a)*100; r.x=bx+(.5-p)*a*100; break;
      case "right": r.scale=base*(1+a)*100; r.x=bx+(p-.5)*a*100; break;
      case "up": r.scale=base*(1+a)*100; r.y=bx*0+by+(.5-p)*a*100; break;
      case "down": r.scale=base*(1+a)*100; r.y=by+(p-.5)*a*100; break;
      default: return null; }
    return r;
  }
  window.__amiyoApplyChromaKey=function(src,trackId,clip){
    var k=clip&&clip.chromaKey, bg=k&&k.enabled&&k.bg;
    if(!bg||!bg.mode||bg.mode==="off") return prev.apply(this,arguments);
    var isClip=bg.mode==="clip", mo=null; try{ mo=motion(bg,clip); }catch(e){ window.__swl&&window.__swl(e); }
    if(!isClip&&!mo) return prev.apply(this,arguments);
    var o={mode:bg.mode,assetId:bg.assetId,scale:bg.scale,x:bg.x,y:bg.y,color:bg.color};
    try{
      if(isClip){ var s=bg.clipId&&findClip(bg.clipId), a=s&&s.clip.assetId&&project.assets[s.clip.assetId];
        if(a&&(a.type==="video"||a.type==="image")&&s.clip.id!==clip.id){ bg.mode=a.type; bg.assetId=a.id; } else { bg.mode="color"; bg.color="#000000"; } }
      if(mo){ bg.scale=mo.scale; bg.x=mo.x; bg.y=mo.y; }
      return prev.apply(this,arguments);
    } finally {
      bg.mode=o.mode; if(o.assetId===undefined) delete bg.assetId; else bg.assetId=o.assetId;
      if(o.scale===undefined) delete bg.scale; else bg.scale=o.scale; if(o.x===undefined) delete bg.x; else bg.x=o.x; if(o.y===undefined) delete bg.y; else bg.y=o.y;
      if(o.color===undefined) delete bg.color; else bg.color=o.color;
    }
  };
  function sel(){ var e=document.querySelector(".clip.selected"); if(!e) return null; var f=findClip(e.dataset.clip); return f?f.clip:null; }
  function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
  function change(label,fn){ var c=sel(); if(!c) return; var id=c.id;
    transact(label,function(){ var f=findClip(id); if(!f||!f.clip.chromaKey) return; var kk=f.clip.chromaKey; kk.bg=kk.bg||{mode:"off"}; fn(kk.bg,kk); });
    try{ renderInspector(); }catch(e){ window.__swl&&window.__swl(e); } try{ renderPreviewFrame(); }catch(e){ window.__swl&&window.__swl(e); } }
  function srcList(self){ var out=[]; project.tracks.forEach(function(t,i){ if(t.kind!=="video") return; (t.clips||[]).forEach(function(c){ var a=c.assetId&&project.assets[c.assetId]; if(c.id===self||!a||(a.type!=="video"&&a.type!=="image")) return; out.push({id:c.id,label:(t.name||("Video "+(i+1)))+" · "+(a.name||"clip")+" · "+Math.floor(c.start/60)+":"+("0"+Math.floor(c.start%60)).slice(-2)}); }); }); return out; }
  var MOTIONS=[["none","None (still)"],["zoomin","Slow zoom in"],["zoomout","Slow zoom out"],["left","Drift left"],["right","Drift right"],["up","Drift up"],["down","Drift down"]];
  function mount(){
    var g=document.getElementById("chromaGroup"); if(!g||document.getElementById("ck9")) return; var c=sel(); if(!c||!c.chromaKey||!c.chromaKey.bg) return;
    var bg=c.chromaKey.bg, mode=bg.mode||"off"; if(mode==="off") return; var m=bg.motion||{type:"none",amount:15}, h="";
    if(mode==="clip"){ var L=srcList(c.id);
      h+='<label class="field" style="font-weight:700">Timeline clip as background</label><select id="ck9Src" style="width:100%;min-height:36px"><option value="">'+(L.length?"Choose a clip…":"No other video or picture clips on the timeline")+'</option>'+L.map(function(x){ return '<option value="'+x.id+'"'+(bg.clipId===x.id?" selected":"")+'>'+esc(x.label)+'</option>'; }).join("")+'</select>'+
        '<div style="font-size:10px;color:var(--muted);margin-top:4px">It plays in step with that clip behind the person. If the clip is removed the background turns black.</div>'; }
    h+='<label class="field" style="font-weight:700;margin-top:8px">Moving background</label><select id="ck9Mo" style="width:100%;min-height:36px">'+MOTIONS.map(function(x){ return '<option value="'+x[0]+'"'+((m.type||"none")===x[0]?" selected":"")+'>'+x[1]+'</option>'; }).join("")+'</select>';
    if(m.type&&m.type!=="none") h+='<label class="field">Amount <span id="ck9AV" style="opacity:.7">'+(m.amount==null?15:m.amount)+'</span>%</label><input id="ck9A" type="range" min="5" max="50" value="'+(m.amount==null?15:m.amount)+'" style="width:100%">';
    var box=document.createElement("div"); box.id="ck9"; box.style.cssText="margin-top:10px;padding-top:8px;border-top:1px solid var(--line,#ffffff22)"; box.innerHTML=h;
    var a=document.getElementById("ck153"); if(a&&a.parentNode===g) g.insertBefore(box,a.nextSibling); else g.appendChild(box);
    var sc=box.querySelector("#ck9Src"); if(sc) sc.onchange=function(e){ var v=e.target.value; change("Background clip",function(b){ b.clipId=v||null; }); };
    box.querySelector("#ck9Mo").onchange=function(e){ var v=e.target.value; change("Background motion",function(b){ b.motion={type:v,amount:(b.motion&&b.motion.amount)||15}; }); };
    var sl=box.querySelector("#ck9A"); if(sl){ sl.oninput=function(e){ var v=Number(e.target.value); (bg.motion=bg.motion||{type:"none"}).amount=v; box.querySelector("#ck9AV").textContent=v; try{ scheduleAutosave(); }catch(x){} try{ renderPreviewFrame(); }catch(x){} }; }
  }
  var pri=window.renderInspector; window.renderInspector=function(){ pri.apply(this,arguments); try{ mount(); }catch(e){ window.__swl&&window.__swl(e); } };
  window.__amiyoGs2=window.__amiyoGs2||{}; window.__amiyoGs2.step=9;
})();

