/* ==================== Script 341 id="amiyo-gs2-step10-speed" ==================== */
/* GREEN SCREEN plan 2, Step 10 of 10: SPEED MODES + HELP.
   Chroma Key (Inspector) > "Key speed": DRAFT (fast: the key is made at a small size and the slow extras - Flicker fix, Core fill, Light wrap, Shadow, Match person - are skipped
   in the preview only), NORMAL (as before) and HIGH (the key is made at a larger size for the cleanest edges; slower). Draft is for editing only: an EXPORT never uses Draft, it always runs
   every effect at full quality (High exports a little larger and slower). A small line shows how long the last key frame took, and suggests Draft if the preview is slow.
   "Green screen help" explains all ten steps in plain words. Old projects are unchanged (Normal). Undo works. */
(function(){
  var prev=window.__amiyoApplyChromaKey, ema=0, MODE=null;
  window.__amiyoKeyCap=function(def){ var m=MODE||"normal", ex=!!window.__amiyoExporting;
    if(ex) return m==="high"?Math.max(def,1280):def; if(m==="draft") return Math.min(def,320); if(m==="high") return Math.max(def,1024); return def; };
  var SKIP=["tsmooth","lw","sh","coreFill"];
  window.__amiyoApplyChromaKey=function(src,trackId,clip){
    var k=clip&&clip.chromaKey; if(!k||!k.enabled) return prev.apply(this,arguments);
    var m=k.speedMode==="draft"||k.speedMode==="high"?k.speedMode:"normal", saved=null, cm=k.cm, t0=performance.now(), was=MODE;
    MODE=m;
    try{
      if(m==="draft"&&!window.__amiyoExporting){ saved={}; SKIP.forEach(function(f){ saved[f]=k[f]; k[f]=(f==="lw"||f==="sh")?undefined:0; }); if(cm) k.cm={amount:0}; }
      return prev.apply(this,arguments);
    } finally {
      if(saved){ SKIP.forEach(function(f){ if(saved[f]===undefined) delete k[f]; else k[f]=saved[f]; }); if(cm) k.cm=cm; }
      MODE=was;
      if(!window.__amiyoExporting){ var dt=performance.now()-t0; ema=ema?ema*.8+dt*.2:dt; var e=document.getElementById("ck10T"); if(e) e.textContent=line(m); }
    }
  };
  function line(m){ var ms=Math.round(ema); return "Last key frame: about "+ms+" ms"+(ms>70&&m!=="draft"?" - the preview may stutter; try Draft while editing.":""); }
  function findClip(id){ for(var i=0;i<project.tracks.length;i++){ var t=project.tracks[i]; for(var j=0;j<(t.clips||[]).length;j++) if(t.clips[j].id===id) return t.clips[j]; } return null; }
  function sel(){ var e=document.querySelector(".clip.selected"); return e?findClip(e.dataset.clip):null; }
  function change(label,fn){ var c=sel(); if(!c) return; var id=c.id;
    transact(label,function(){ var cl=findClip(id); if(cl&&cl.chromaKey) fn(cl.chromaKey); });
    try{ renderInspector(); }catch(e){ window.__swl&&window.__swl(e); } try{ renderPreviewFrame(); }catch(e){ window.__swl&&window.__swl(e); } }
  var HELP='<div style="font-size:12.5px;line-height:1.55;max-height:60vh;overflow:auto">'+
   '<p>Green screen in 10 steps. Select a video clip, open <b>Chroma Key</b> in the Inspector and turn it on. Every item below is off or neutral until you use it, and Undo works for all of them.</p>'+
   '<p><b>1 Protect colours / Extra key colours</b> - colours that must never be removed (a green shirt) and more colours to remove (a second screen colour).</p>'+
   '<p><b>2 Core fill</b> - fills see-through holes inside the person (bright shirt, glasses glare).</p>'+
   '<p><b>3 Flicker fix</b> - calms shimmering edges on video by blending with the previous frame where nothing moved.</p>'+
   '<p><b>4 Clean plate</b> - move to a moment when the screen is empty and save it; uneven lighting and stains are removed.</p>'+
   '<p><b>5 Moving garbage mattes</b> - a mask outside the person; add keyframes so it follows them.</p>'+
   '<p><b>6 Before / After</b> - split view in the preview to compare with and without the key.</p>'+
   '<p><b>7 Copy, presets, whole track</b> - copy settings to another clip, save your own presets, or apply to every clip on the track.</p>'+
   '<p><b>8 Edge colour fix</b> - repaints the colour of edge pixels (different from spill).</p>'+
   '<p><b>9 Moving background</b> - slow zoom or drift, and another timeline clip can be the background.</p>'+
   '<p><b>10 Key speed</b> - Draft while editing, Normal, High for the cleanest edges. Exports never use Draft.</p>'+
   '<p><b>Tips:</b> use Output view (Alpha / Status) to check the matte; pink in Status means half-removed edge pixels.</p></div>';
  function mount(){
    var g=document.getElementById("chromaGroup"); if(!g||document.getElementById("ck10")) return; var c=sel(); if(!c||!c.chromaKey) return;
    var m=c.chromaKey.speedMode||"normal", box=document.createElement("div"); box.id="ck10"; box.style.cssText="margin:8px 0 6px;padding-bottom:8px;border-bottom:1px solid var(--line,#ffffff22)";
    function chip(v,t){ return '<button type="button" class="chip" data-m="'+v+'" style="min-height:36px'+(m===v?';outline:2px solid #ffb454':'')+'">'+t+'</button>'; }
    box.innerHTML='<label class="field">Key speed</label><div class="mini-row">'+chip("draft","Draft")+chip("normal","Normal")+chip("high","High")+'</div>'+
      '<div style="font-size:10px;color:var(--muted);margin-top:4px">Draft is fast and only for editing. Exports always use full quality.</div><div id="ck10T" style="font-size:10px;color:var(--muted);margin-top:2px">'+(ema?line(m):"")+'</div>'+
      '<div class="mini-row" style="margin-top:6px"><button type="button" class="chip" id="ck10H" style="min-height:36px">❓ Green screen help</button></div>';
    var a=document.getElementById("ck167")||document.getElementById("ck154"); if(a&&a.parentNode===g) g.insertBefore(box,a); else { var h3=g.querySelector("h3"); g.insertBefore(box,h3?h3.nextSibling:g.firstChild); }
    [].forEach.call(box.querySelectorAll("button[data-m]"),function(b){ b.onclick=function(){ var v=b.getAttribute("data-m"); change("Key speed: "+b.textContent,function(kk){ if(v==="normal") delete kk.speedMode; else kk.speedMode=v; }); }; });
    box.querySelector("#ck10H").onclick=function(){ try{ openModal("Green screen help",HELP); }catch(e){ window.__swl&&window.__swl(e); } };
  }
  var pri=window.renderInspector; window.renderInspector=function(){ pri.apply(this,arguments); try{ mount(); }catch(e){ window.__swl&&window.__swl(e); } };
  window.__amiyoGsHelp=function(){ openModal("Green screen help",HELP); }; window.__amiyoGs2=window.__amiyoGs2||{}; window.__amiyoGs2.step=10; try{ window.AMIYO_EDITOR_BUILD="gs2-step10-speed"; }catch(e){}
})();

