/* ==================== Script 342 id="amiyo-gs2-step11-pro" ==================== */
/* GREEN SCREEN in PROFESSIONAL EDITING: a "Green Screen" group in the Professional Editing panel (search works too: type "key", "green", "alpha"). Every button works on the selected clip and is one
   Undo step: Key on/off, Relaxed / Balanced / Aggressive, Alpha view, Status view, Before / After, Core fill, Flicker fix, Draft / Normal / High speed, background Zoom in / Zoom out / Drift,
   Copy / Paste key settings, Apply to track, and Green screen help. Buttons that are switched on glow orange like the other pro tools. */
(function(){
  var DEF={enabled:false,color:"#00ff00",tolerance:38,softness:18,spillSuppress:true};
  var PRE={relaxed:{tolerance:26,softness:30,choke:0,edgeBlur:1},balanced:{tolerance:38,softness:18,choke:0,edgeBlur:0},aggressive:{tolerance:62,softness:12,choke:2,edgeBlur:0}};
  function cur(){ try{ var f=getClip(); return f&&f.clip?f.clip:null; }catch(e){ return null; } }
  function K(){ var c=cur(); return c&&c.chromaKey?c.chromaKey:null; }
  function find(id){ for(var i=0;i<project.tracks.length;i++){ var t=project.tracks[i]; for(var j=0;j<(t.clips||[]).length;j++) if(t.clips[j].id===id) return t.clips[j]; } return null; }
  function eligible(c){ var a=c&&c.assetId&&project.assets[c.assetId]; return !!(a&&(a.type==="video"||a.type==="image")); }
  function mut(label,fn){ var c=cur(); if(!c) return toast("Select a clip on the timeline first"); if(!eligible(c)) return toast("Green screen works on video and picture clips");
    var id=c.id; transact(label,function(){ var cl=find(id); if(!cl) return; cl.chromaKey=cl.chromaKey||JSON.parse(JSON.stringify(DEF)); fn(cl.chromaKey,cl); });
    try{ renderInspector(); }catch(e){ window.__swl&&window.__swl(e); } try{ scheduleAutosave(); }catch(e){} try{ renderPreviewFrame(); }catch(e){ window.__swl&&window.__swl(e); } }
  var api={
    key:function(){ mut("Chroma key on/off",function(k){ k.enabled=!k.enabled; }); },
    preset:function(n){ mut("Key strength: "+n,function(k){ var p=PRE[n]; for(var f in p) k[f]=p[f]; k.spillSuppress=true; k.ycc=true; k.enabled=true; }); },
    alpha:function(){ mut("Alpha view",function(k){ k.matte=!k.matte; if(k.matte) k.view="composite"; k.enabled=true; }); },
    status:function(){ mut("Status view",function(k){ k.view=k.view==="status"?"composite":"status"; k.matte=false; k.enabled=true; }); },
    compare:function(){ mut("Before / After",function(k){ var on=k.cmp&&k.cmp.mode&&k.cmp.mode!=="off"; k.cmp={mode:on?"off":"v",pos:(k.cmp&&k.cmp.pos)||50}; k.enabled=true; }); },
    core:function(){ mut("Core fill",function(k){ k.coreFill=k.coreFill>0?0:60; }); },
    flicker:function(){ mut("Flicker fix",function(k){ k.tsmooth=k.tsmooth>0?0:50; }); },
    speed:function(m){ mut("Key speed: "+m,function(k){ if(m==="normal") delete k.speedMode; else k.speedMode=m; }); },
    motion:function(t){ var k=K(); if(!k||!k.bg||!k.bg.mode||k.bg.mode==="off") return toast("Turn on Replace background first (Chroma Key in the Inspector)");
      mut("Background motion",function(kk){ var on=kk.bg.motion&&kk.bg.motion.type===t; kk.bg.motion={type:on?"none":t,amount:(kk.bg.motion&&kk.bg.motion.amount)||15}; }); },
    copy:function(){ var c=cur(); var g=window.__amiyoGs2&&window.__amiyoGs2.keys; if(!c||!c.chromaKey) return toast("Select a keyed clip first"); if(g&&g.copy(c.id)) toast("Key settings copied. Select another clip and press Paste Key.",3500); },
    paste:function(){ var c=cur(), g=window.__amiyoGs2&&window.__amiyoGs2.keys; if(!c) return toast("Select a clip first"); if(g&&g.paste(c.id)){ try{ renderInspector(); }catch(e){} toast("Key settings pasted",2500); } else toast("Copy key settings from a keyed clip first"); },
    track:function(){ var c=cur(), g=window.__amiyoGs2&&window.__amiyoGs2.keys; if(!c||!c.chromaKey) return toast("Select a keyed clip first"); var n=g?g.applyTrack(c.id):0; toast(n?("Applied to "+n+" more clip"+(n>1?"s":"")+" on this track"):"No other video clips on this track",3000); },
    help:function(){ if(window.__amiyoGsHelp) window.__amiyoGsHelp(); }
  };
  window.__amiyoGsPro=api;
})();

