/* ==================== Script 343 id="amiyo-gs2-step12-badge" ==================== */
/* Small polish: a "DRAFT KEY" badge sits on the preview while any keyed clip under the playhead uses Draft key speed (so you do not judge edge quality from a draft). It is a label on the page, never part of the picture, and never exported.
   "Auto Colour" in Professional Editing > Green Screen runs Auto-detect backdrop on the selected clip. */
(function(){
  function badge(){ var cv=document.getElementById("previewCanvas")||document.querySelector("canvas"); if(!cv||!cv.parentNode) return null; var p=cv.parentNode, b=document.getElementById("gsDraftBadge");
    if(!b){ try{ if(getComputedStyle(p).position==="static") p.style.position="relative"; }catch(e){} b=document.createElement("div"); b.id="gsDraftBadge"; b.textContent="DRAFT KEY";
      b.style.cssText="position:absolute;top:8px;left:8px;z-index:5;padding:2px 8px;border-radius:999px;background:rgba(0,0,0,.6);color:#ffb454;border:1px solid #ffb45488;font:700 10px/16px system-ui,sans-serif;letter-spacing:.06em;pointer-events:none;display:none"; b.setAttribute("aria-hidden","true"); p.appendChild(b); } return b; }
  function draftNow(){ try{ if(window.__amiyoExporting) return false; var t=currentTime; for(var i=0;i<project.tracks.length;i++){ var cl=project.tracks[i].clips||[]; for(var j=0;j<cl.length;j++){ var c=cl[j], k=c.chromaKey; if(k&&k.enabled&&k.speedMode==="draft"&&t>=c.start&&t<c.start+c.duration) return true; } } }catch(e){} return false; }
  function upd(){ try{ var b=badge(); if(b) b.style.display=draftNow()?"block":"none"; }catch(e){ window.__swl&&window.__swl(e); } }
  var rp=window.renderPreviewFrame; if(typeof rp==="function") window.renderPreviewFrame=function(){ var r=rp.apply(this,arguments); upd(); return r; };
  setInterval(upd,700);
  if(window.__amiyoGsPro) window.__amiyoGsPro.auto=function(){ var c=null; try{ var f=getClip(); c=f&&f.clip; }catch(e){} if(!c) return toast("Select a clip on the timeline first");
    if(!c.chromaKey||!c.chromaKey.enabled) return toast("Turn the key on first (Key On/Off)"); try{ renderInspector(); }catch(e){} var b=document.getElementById("ckAuto"); if(b) b.click(); else toast("Open Chroma Key in the Inspector once, then try again"); };
})();

