  window.amiyoNeedsStack=function(c){ return on(c)||(pn?pn.apply(this,arguments):false); };
  function asp(c){ var a=null; try{ a=getAsset(c.assetId); }catch(e){window.__swl&&window.__swl(e)} return a&&a.width&&a.height?a.width/a.height:null; }
  function pasp(){ return (project.settings.width||1280)/(project.settings.height||720); }
  function cur(){ var f=null; try{ f=getClip(); }catch(e){window.__swl&&window.__swl(e)} if(f&&f.clip) return f; var e=document.querySelector(".clip.selected"); if(!e) return null; var id=e.dataset.clip;
    for(var i=0;i<project.tracks.length;i++){ var t=project.tracks[i]; for(var j=0;j<t.clips.length;j++) if(t.clips[j].id===id) return {track:t,clip:t.clips[j]}; } return null; }
  function redraw(){ try{ scheduleAutosave(); }catch(e){window.__swl&&window.__swl(e)} try{ renderPreviewFrame(); }catch(e){window.__swl&&window.__swl(e)} }
  function fitScale(c){ var a=asp(c); if(a==null) return 1; var W=project.settings.width||1280, H=project.settings.height||720; return Math.min(1,(H/W)*a); }
  function bars(c){ var a=asp(c); if(a==null) return null; if(c.fit==="cover") return false; var W=project.settings.width||1280, H=project.settings.height||720, ks=c.scale||1, dw=W*ks, dh=dw/a; return dw<W*.99||dh<H*.99; }
  function info(c){ var a=asp(c); if(a==null) return ""; if(c.fit==="cover") return "This clip is set to fill the frame, so no bars show. Tap \"Fit clip inside frame\" to see the blur.";
    if(bars(c)) return "Bars are showing, so the blur will fill them.";
    if(Math.abs(a/pasp()-1)<.03) return "This clip has the same shape as the project, so there are no bars to blur.";
    return "This clip is zoomed to the frame width and cropped. Tap \"Fit clip inside frame\" so the bars appear and the blur can fill them."; }
  function mount(){
    var f=cur(); if(!f||!f.clip||f.track.kind!=="video"||!f.clip.assetId) return; var insp=document.getElementById("inspector"); if(!insp||document.getElementById("bgBlurGroup")) return;
    var c=f.clip, k=c.bgBlur||{enabled:false,amount:50,dim:25};
    var g=document.createElement("div"); g.className="group"; g.id="bgBlurGroup";
    g.innerHTML='<h3>Background blur <label style="float:right;font-size:10px;font-weight:400"><input type="checkbox" id="bbOn" '+(k.enabled?"checked":"")+'/> Enabled</label></h3>'+
      '<label class="field">Blur amount <span id="bbAV" style="opacity:.7">'+(k.amount==null?50:k.amount)+'</span></label><input id="bbA" type="range" min="5" max="100" step="1" value="'+(k.amount==null?50:k.amount)+'">'+
      '<label class="field">Darken <span id="bbDV" style="opacity:.7">'+(k.dim==null?25:k.dim)+'%</span></label><input id="bbD" type="range" min="0" max="70" step="1" value="'+(k.dim==null?25:k.dim)+'">'+
      '<div class="mini-row" style="margin-top:6px"><button type="button" class="chip" id="bbFit" style="min-height:38px">Fit clip inside frame</button><button type="button" class="chip" id="bbAll" style="min-height:38px">Turn on for all clips that leave bars</button></div>'+
      '<div id="bbInfo" style="font-size:10px;color:var(--muted);margin-top:6px;line-height:1.5">'+esc2(info(c))+'</div>'+
      '<div style="font-size:10px;color:var(--muted);margin-top:4px;line-height:1.5">Fills the empty bars with a blurred copy of this clip. It does not cut the person out. Use it on the main clip, not on overlays.</div>';
    insp.appendChild(g);
    function ensure(){ if(!c.bgBlur) c.bgBlur={enabled:false,amount:50,dim:25}; return c.bgBlur; }
    function T(label,fn){ if(typeof window.transact==="function") window.transact(label,fn); else fn(); redraw(); }
    g.querySelector("#bbOn").onchange=function(e){ var v=e.target.checked; T("Background blur",function(){ ensure().enabled=v; if(v){ var ar=asp(c); if(ar!=null&&Math.abs(ar/pasp()-1)>=.03&&bars(c)===false){ c.fit="contain"; c.x=.5; c.y=.5; c.scale=fitScale(c); } } }); try{ renderInspector(); }catch(x){window.__swl&&window.__swl(x)} };
    g.querySelector("#bbA").oninput=function(e){ ensure().amount=Number(e.target.value); g.querySelector("#bbAV").textContent=c.bgBlur.amount; redraw(); };
    g.querySelector("#bbD").oninput=function(e){ ensure().dim=Number(e.target.value); g.querySelector("#bbDV").textContent=c.bgBlur.dim+"%"; redraw(); };
    g.querySelector("#bbFit").onclick=function(){ T("Fit clip inside frame",function(){ c.fit="contain"; c.x=.5; c.y=.5; c.scale=fitScale(c); ensure().enabled=true; }); try{ renderInspector(); }catch(x){window.__swl&&window.__swl(x)} };
    g.querySelector("#bbAll").onclick=function(){ var n=0; T("Background blur on clips with bars",function(){ var p=pasp(); project.tracks.forEach(function(t){ if(t.kind!=="video"||t.locked) return;
      t.clips.forEach(function(cl){ if(!cl.assetId) return; var a=asp(cl); if(a==null||Math.abs(a/p-1)<.03) return; if(!cl.bgBlur) cl.bgBlur={enabled:false,amount:50,dim:25}; cl.bgBlur.enabled=true; cl.fit="contain"; cl.x=.5; cl.y=.5; cl.scale=fitScale(cl); n++; }); }); });
      try{ toast(n?("Background blur turned on for "+n+" clip"+(n>1?"s":"")+". Undo reverses it."):"No clips found that leave bars",4000); }catch(x){window.__swl&&window.__swl(x)} try{ renderInspector(); }catch(x){window.__swl&&window.__swl(x)} };
  }
  function esc2(s){ return String(s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  var pri=window.renderInspector; window.renderInspector=function(){ var r=pri.apply(this,arguments); try{ mount(); }catch(e){ try{ console.error("Background blur panel",e); }catch(x){window.__swl&&window.__swl(x)} } return r; };
  window.__amiyoBgBlur={on:on,paint:bg,fitScale:fitScale,bars:bars};
