/* ==================== Script 348 id="amiyo-step156-snap" ==================== */
/* Step 7 of the new plan (file step156): CUTS THAT DO NOT CLIP WORDS.
   Weak spot found when re-checking steps 4-6: "Edit by words" and "Edit by captions" cut at TIMES THAT ARE ESTIMATES, so a cut could land in the
   middle of a word and leave a click or a clipped syllable. Now both cards have "Snap cuts to quiet moments" (on by default, remembered in the
   project). Before cutting, the editor listens to the sound under each cut edge and moves the edge, by at most 0.12 s, to the quietest nearby
   moment (a gap between words). It only moves an edge when that spot is clearly quieter (3 dB or more). If the sound cannot be read (very
   large file, no audio, no video clip under the edge) the original times are used. The sound is read once per file and only a small loudness
   curve is kept in memory. Which sound is checked: the video clip under the edge, otherwise the audio clip. */
(function(){
  var HOP=.01, WIN=.12, GAIN=3, cache={}, order=[];
  function on(){ var s=project&&project.settings; return !(s&&s.snapCuts===false); }
  window.amiyoSnapOn=on;
  window.amiyoSnapRow=function(){ return '<label style="display:flex;align-items:center;gap:6px;font-size:11px;margin-top:8px;min-height:32px"><input type="checkbox" class="snap-chk" style="width:18px;height:18px"'+(on()?" checked":"")+'> Snap cuts to quiet moments <span style="opacity:.6">(keeps words whole)</span></label>'; };
  document.addEventListener("change",function(e){ var t=e.target; if(!t||!t.classList||!t.classList.contains("snap-chk")) return; try{ project.settings.snapCuts=!!t.checked; try{ scheduleAutosave(); }catch(x){window.__swl&&window.__swl(x)} }catch(x){window.__swl&&window.__swl(x)}
    document.querySelectorAll(".snap-chk").forEach(function(c){ c.checked=!!t.checked; }); });
  /* pure: loudness curve (dB per 10 ms) of a mono signal */
  function envelope(x,sr){ var fl=Math.max(1,Math.round(sr*HOP)), n=Math.floor(x.length/fl), db=new Float32Array(n);
    for(var i=0;i<n;i++){ var s=0, o=i*fl; for(var k=0;k<fl;k++){ var v=x[o+k]; s+=v*v; } db[i]=10*Math.log10(s/fl+1e-10); }
    var sm=new Float32Array(n); for(var j=0;j<n;j++){ var a=db[Math.max(0,j-1)], b=db[j], c=db[Math.min(n-1,j+1)]; sm[j]=(a+b+c)/3; } return sm; }
  /* pure: nearest clearly-quieter moment (source seconds) */
  function snapTime(env,s){ var n=env.length; if(!n) return s; var c=Math.max(0,Math.min(n-1,Math.round(s/HOP))), lo=Math.max(0,c-Math.round(WIN/HOP)), hi=Math.min(n-1,c+Math.round(WIN/HOP)), best=c, bs=env[c];
    for(var i=lo;i<=hi;i++){ var sc=env[i]+15*Math.abs(i-c)*HOP; if(sc<bs-1e-6){ bs=sc; best=i; } }
    if(env[best]>env[c]-GAIN) return s; return best*HOP; }
  async function envFor(asset){
    if(cache[asset.id]) return cache[asset.id];
    if(asset.size&&asset.size>200*1048576) return null;
    var OAC=window.OfflineAudioContext||window.webkitOfflineAudioContext; if(!OAC) return null;
    var url=await ensureUrl(asset); if(!url) return null;
    var SR=16000, buf; try{ var ab=await (await fetch(url)).arrayBuffer(); buf=await new OAC(1,1,SR).decodeAudioData(ab); }catch(e){ return null; }
    if(buf.length>SR*60*60) return null;
    var mono=new Float32Array(buf.length), ch=buf.numberOfChannels; for(var c=0;c<ch;c++){ var d=buf.getChannelData(c); for(var i=0;i<mono.length;i++) mono[i]+=d[i]/ch; }
    var env=envelope(mono,SR); cache[asset.id]=env; order.push(asset.id); while(order.length>3) delete cache[order.shift()]; return env; }
  function clipAt(t){ var pick=null;
    ["video","audio"].forEach(function(kind){ if(pick) return; project.tracks.forEach(function(tr){ if(pick||tr.kind!==kind||tr.locked||tr.muted||tr.hidden&&kind==="video") return;
      tr.clips.forEach(function(c){ if(!pick&&c.assetId&&t>=c.start-1e-6&&t<=c.start+c.duration+1e-6) pick=c; }); }); }); return pick; }
  async function snapOne(t){ var c=clipAt(t); if(!c) return t; var a=null; try{ a=getAsset(c.assetId); }catch(e){window.__swl&&window.__swl(e)} if(!a||(a.type!=="video"&&a.type!=="audio")) return t;
    var env=await envFor(a); if(!env) return t; var sp=c.speed||1, ip=c.inPoint||0, s=ip+(t-c.start)*sp, s2=snapTime(env,s), t2=c.start+(s2-ip)/sp;
    t2=Math.max(c.start,Math.min(c.start+c.duration,t2)); return Math.abs(t2-t)<=WIN/Math.min(1,sp)+1e-6?t2:t; }
  window.amiyoSnapRanges=async function(R){
    if(!on()) return R; var out=[];
    try{ for(var i=0;i<R.length;i++){ var a=await snapOne(R[i][0]), b=await snapOne(R[i][1]); var prev=out.length?out[out.length-1][1]+.02:-Infinity;
        if(a<prev||b-a<.04){ a=R[i][0]; b=R[i][1]; } out.push([a,b]); }
    }catch(e){ try{ console.warn("Snap cuts",e); }catch(x){window.__swl&&window.__swl(x)} return R; }
    for(var j=0;j<out.length-1;j++) if(out[j][1]>out[j+1][0]) return R;
    return out; };
  window.__amiyoSnap={envelope:envelope,snapTime:snapTime,setEnv:function(id,env){ cache[id]=env; }};
})();

