/* ==================== Script 350 id="amiyo-step160-quiet-ui" ==================== */
(function(){
"use strict";
var Q=window.amiyoQuiet;
function esc(s){ return String(s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function card(){
  var h='<details id="prQuiet" style="margin-top:8px"><summary style="font-size:12px;cursor:pointer;min-height:32px">Quiet errors ('+Q.list().length+' kinds, '+Q.total()+' times)</summary>'+
   '<div style="font-size:10px;color:var(--muted);margin:4px 0">Small errors the editor skipped over on purpose. Most are harmless. Copy this list when something misbehaves.</div>';
  if(!Q.list().length) h+='<div style="font-size:11px">None so far.</div>';
  else h+='<div style="max-height:180px;overflow:auto;font-size:11px">'+Q.list().sort(function(a,b){return b.n-a.n;}).map(function(x){
    return '<div style="border-top:1px solid var(--line,#333);padding:3px 0"><b>'+esc(x.k)+'</b> ×'+x.n+'<div style="word-break:break-word;opacity:.85">'+esc(x.m)+(x.w?' ('+esc(x.w)+')':'')+'</div></div>'; }).join("")+'</div>';
  h+='<button type="button" class="chip" id="prQuietCopy" style="min-height:40px;margin-top:6px;width:100%">Copy quiet errors</button><div id="prQuietMsg" role="status" style="font-size:11px;margin-top:4px"></div></details>';
  return h;
}
function text(){ return "AMIYO quiet errors ("+Q.list().length+" kinds, "+Q.total()+" times)\n"+Q.list().map(function(x){ return "["+x.k+"] "+x.m+" x"+x.n+(x.w?" — "+x.w:""); }).join("\n"); }
function mount(){
  var pl=document.getElementById("prLog"); if(!pl||pl.querySelector("#prQuiet")) return;
  pl.insertAdjacentHTML("beforeend",card());
  var b=pl.querySelector("#prQuietCopy"), msg=pl.querySelector("#prQuietMsg");
  b.onclick=function(){
    var t=text();
    function fail(){ msg.textContent="Could not copy. Select the text and copy it by hand."; var ta=document.createElement("textarea"); ta.value=t; ta.style.cssText="width:100%;height:120px;margin-top:6px"; ta.setAttribute("aria-label","Quiet errors"); msg.appendChild(ta); ta.select(); }
    try{ if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(function(){ msg.textContent="Copied."; },fail); return; } }catch(x){}
    fail();
  };
}
var prev=window.renderLeftPanel;
if(typeof prev==="function"){
  window.renderLeftPanel=function(){ var r=prev.apply(this,arguments); try{ if(activePanel==="help") setTimeout(mount,0); }catch(x){} return r; };
}

window.amiyoQuiet.report=text;
})();

