/* ==================== Script 351 id="amiyo-step161-preflight" ==================== */
/* Step 2 (build plan 2): Export pre-flight. The old check only looked for missing records. It now also finds clips whose media file is gone
   (they would export blank), an empty timeline, picture tracks that are all hidden and audio that is all muted. Plain-language messages with times.
   If any of the important ones apply, Export asks first ("Export anyway" / "Go back"). */
(function(){
"use strict";
function mmss(s){ s=Math.max(0,Math.round(s||0)); var m=Math.floor(s/60), x=s%60; return m+":"+(x<10?"0":"")+x; }
function esc(t){ return String(t).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function nm(id){ var a=project.assets&&project.assets[id]; return (a&&a.name)||"a file"; }
var wrapped=function(r){
  r=r||{ok:true,issues:[],warnings:[]};
  try{
    var issues=(r.issues||[]).filter(function(x){ return String(x).indexOf("Missing asset for clip")!==0; });
    var warnings=(r.warnings||[]).slice(), imp=[], gone={}, order=[], nClips=0, lost=0;
    var vTracks=0, vHidden=0, aTracks=0, aMuted=0;
    project.tracks.forEach(function(t){
      var hasClip=t.clips&&t.clips.length;
      if(hasClip){
        if(t.kind==="video"||t.kind==="overlay"){ vTracks++; if(t.hidden) vHidden++; }
        if(t.kind==="audio"){ aTracks++; if(t.muted) aMuted++; }
      }
      (t.clips||[]).forEach(function(c){
        nClips++;
        if(c.assetId&&!window.getAsset(c.assetId)){ lost++; return; }
        if(c.assetId&&!c.off&&!t.hidden&&window.amiyoAssetMissing&&window.amiyoAssetMissing(c.assetId)){
          if(!gone[c.assetId]){ gone[c.assetId]=[]; order.push(c.assetId); }
          gone[c.assetId].push(mmss(c.start));
        }
      });
    });
    if(lost) issues.push(lost+(lost===1?" clip has":" clips have")+" lost its media record. Delete "+(lost===1?"it":"them")+" or import the file again.");
    if(project.tracks.length&&!nClips) issues.push("The timeline is empty. Add a clip before exporting.");
    order.slice(0,5).forEach(function(id){ imp.push("Media missing: "+nm(id)+" (at "+gone[id].slice(0,3).join(", ")+(gone[id].length>3?" ...":"")+") will export blank. Import the file again to relink it."); });
    if(order.length>5) imp.push("And "+(order.length-5)+" more files are missing.");
    if(vTracks&&vHidden===vTracks) imp.push("Every picture track is hidden, so the video will be blank.");
    if(aTracks&&aMuted===aTracks){   /* export step 3: sound from clips on the video track still plays, so only say "silent" when there is none */
      var vSound=project.tracks.some(function(t){ return t.kind==="video"&&!t.muted&&!t.hidden&&(t.clips||[]).some(function(c){ var a=getAsset(c.assetId); return !c.off&&a&&a.type==="video"&&(c.volume==null?1:c.volume)>0; }); });
      imp.push(vSound?"Every audio track is muted, so the music and voice-over will be missing. Sound from the video clips is still included.":"Every audio track is muted, so the export will be silent.");
    }
    imp.forEach(function(x){ if(warnings.indexOf(x)<0) warnings.unshift(x); });
    r.issues=issues; r.warnings=warnings; r.important=imp; r.ok=issues.length===0;
  }catch(e){ window.__swl&&window.__swl(e); }
  return r;
};
window.__s161QC=wrapped;
window.amiyoPreflight=function(){ return wrapped(null); };
var prevExp=window.exportProject;
if(typeof prevExp==="function"){
  window.exportProject=function(){
    var self=this, args=arguments;
    try{
      if(!window.__amiyoExporting){
        var q=wrapped(null);
        if(q.ok&&q.important&&q.important.length){
          window.openModal("BEFORE YOU EXPORT",'<p style="margin:0 0 6px">Heads up, this may not export the way you expect:</p><ul style="margin:0 0 10px;padding-left:18px">'+
            q.important.map(function(x){ return "<li>"+esc(x)+"</li>"; }).join("")+'</ul>'+
            '<div class="mini-row"><button type="button" class="chip" id="s161Go" style="min-height:44px">Export anyway</button><button type="button" class="chip" id="s161No" style="min-height:44px">Go back</button></div>');
          document.getElementById("s161No").onclick=function(){ window.closeModal(); };
          document.getElementById("s161Go").onclick=function(){ window.closeModal(); prevExp.apply(self,args); };
          return;
        }
      }
    }catch(e){ window.__swl&&window.__swl(e); }
    return prevExp.apply(this,arguments);
  };
}
try{ window.AMIYO_EDITOR_BUILD="step161-preflight"; }catch(e){}
})();

