/* ==================== Script 369 id="amiyo-plus-step1-render-scheduler" ==================== */
/* Plus Step 1: render scheduler. renderAll()/renderTracks() are wrapped 19 and 16 times by later features and are called from ~140 places,
   so dragging, sliders and trims rebuilt the whole editor many times a second. The first call runs at once; calls that arrive
   while the editor is still busy are merged into ONE follow-up call. The wait adapts to how slow the phone is. */
(function(){
  var stats=window.amiyoRenderStats={all:{run:0,merged:0,ms:0},tracks:{run:0,merged:0,ms:0}};
  function throttle(name,key,base){
    var orig=window[name]; if(typeof orig!=="function"||orig.__amiyoThr) return;
    var st=stats[key], last=0, gap=base, timer=0, running=false, pthis=null, pargs=null;
    function go(self,args){
      running=true; var t0=performance.now();
      try{ return orig.apply(self,args); }
      finally{ running=false; var d=performance.now()-t0; st.run++; st.ms+=d; last=performance.now(); gap=Math.min(450,Math.max(base,d*1.6)); }
    }
    function w(){
      if(running||window.__amiyoExporting) return orig.apply(this,arguments);
      var now=performance.now();
      if(!timer&&now-last>=gap) return go(this,arguments);
      pthis=this; pargs=arguments; st.merged++;
      if(!timer) timer=setTimeout(function(){ timer=0; try{ go(pthis,pargs); }catch(e){ try{ window.__swl&&window.__swl(e); }catch(x){} } },Math.max(0,gap-(now-last)));
    }
    w.__amiyoThr=true; w.flush=function(){ if(timer){ clearTimeout(timer); timer=0; go(pthis,pargs); } };
    window[name]=w;
  }
  function install(){ throttle("renderAll","all",60); throttle("renderTracks","tracks",50); }
  window.amiyoFlushRender=function(){ try{ window.renderTracks&&window.renderTracks.flush&&window.renderTracks.flush(); window.renderAll&&window.renderAll.flush&&window.renderAll.flush(); }catch(e){} };
  install();
  window.addEventListener("amiyo-booted",function(){ setTimeout(install,0); });
  window.addEventListener("load",function(){ setTimeout(install,1200); });
  /* never leave a screen half-updated when the user leaves the tab */
  document.addEventListener("visibilitychange",function(){ if(document.hidden) window.amiyoFlushRender(); });
  try{ window.AMIYO_EDITOR_BUILD="plus1-render-scheduler"; }catch(e){}
})();

