/* ==================== Script 370 id="amiyo-plus-step2-visible-only" ==================== */
/* Plus Step 2: the timeline only builds clips near the screen once a project has more than 12 clips (was 100), with a 1-screen margin
   (was 1.5). Picture strips are only painted for clips near the screen, and painted when you stop scrolling. */
(function(){
  var ts=document.getElementById("timelineScroll"); if(!ts) return; var t=0;
  ts.addEventListener("scroll",function(){
    clearTimeout(t); t=setTimeout(function(){ try{ if(typeof paintFilmstrips==="function"&&!window.__amiyoLite) paintFilmstrips(); }catch(e){ window.__swl&&window.__swl(e); } },180);
  },{passive:true});
  try{ window.AMIYO_EDITOR_BUILD="plus4-light-autosave"; }catch(e){}
})();

