/* ==================== Script 371 id="amiyo-plus-step5-ai-command-bar" ==================== */
/* Plus Step 5: "Ask AI" command bar. Type or speak a plain-English edit ("split here and delete", "speed up 2x", "mute", "add title Hello",
   "go to 1:30", "make it vertical"). Runs on this device, no account needed. Chains steps with "and" / "then". Every change can be undone. */
(function(){
  "use strict";
  var $=function(id){return document.getElementById(id)};
  function say(m,kind){ var n=$("aiCmdOut"); if(!n) return; n.textContent=m; n.style.color=kind==="bad"?"#ff91a0":kind==="ok"?"#5fd88a":"#948a79"; }
  function allClips(){ var o=[]; (project.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ o.push({track:t,clip:c}); }); }); return o; }
  function ensureClip(){
    var f=getClip(); if(f) return f;
    var t=currentTime, hits=allClips().filter(function(x){ return t>=x.clip.start-.001 && t<=x.clip.start+x.clip.duration+.001; });
    if(!hits.length) return null;
    var pri={video:0,image:1,audio:2,text:3}; hits.sort(function(a,b){ return (pri[a.track.kind]||9)-(pri[b.track.kind]||9); });
    selectedClipId=hits[0].clip.id; selectedTrackId=hits[0].track.id; return {track:hits[0].track,clip:hits[0].clip};
  }
  function needClip(){ var f=ensureClip(); if(!f) throw new Error("There is no clip at the playhead. Move the playhead onto a clip first."); return f; }
  function tx(label,fn){ window.transact(label,fn); }
  function parseTime(s){
    s=String(s).trim(); var m=s.match(/^(\d+):(\d{1,2})(?:\.(\d+))?$/); if(m) return (+m[1])*60+(+m[2])+(m[3]?+("0."+m[3]):0);
    m=s.match(/^(\d+(?:\.\d+)?)\s*(?:s|sec|secs|seconds?)?$/); return m?+m[1]:null;
  }
  var steps=[
    [/^(?:play|start|resume)\b/,function(){ if(!isPlaying) play(); return "Playing"; }],
    [/^(?:pause|stop|freeze)\b/,function(){ pause(); return "Paused"; }],
    [/^undo\b/,function(){ undo(); return "Undone"; }],
    [/^redo\b/,function(){ redo(); return "Redone"; }],
    /* "add title Fast cars" must add a title, not change speed: an explicit add/insert/create + text/title/heading/caption goes first */
    [/^(?:add|insert|new|create)\s+(?:a\s+|an\s+)?(?:text|title|heading|caption(?=\s+\S))\b(?!\s*(?:style|styles|look|font|design)\b)/,function(t,m,raw){
      var q=raw.match(/["\u201c]([^"\u201d]+)["\u201d]/), rest=raw.replace(/^[\s\S]*?\b(?:text|title|heading|caption)\b\s*/i,"").replace(/[.!?]+$/,"").trim(), txt=q?q[1]:rest.replace(/^(?:saying|that says|called|:)\s*/i,"").trim();
      addTextClip(txt||"Title"); return "Added text: "+(txt||"Title"); }],
    [/reframe|auto[- ]?frame|(?:follow|track) (?:the )?(?:face|subject|person)/,function(){ if(!window.amiyoReframe) throw new Error("Smart Reframe is not ready"); window.amiyoReframe.open(); return "Opened Smart Reframe"; }],
    [/highlight|best (?:moment|part|bit)|key moment/,function(){ if(!window.amiyoHighlights) throw new Error("Highlights are not ready"); window.amiyoHighlights.open(); return "Opened AI Highlights"; }],
    [/smart cut|tighten|jump cut|dead air|silence|pauses?\b|quiet parts?/,function(t){ if(!window.amiyoSmartCut) throw new Error("Smart Cut is not ready"); var k=/tight|aggressive|fast|jump/.test(t)?"tight":/gentle|light|careful|soft/.test(t)?"gentle":"balanced"; if(/smart cut|tighten/.test(t)&&!/gentle|tight\b|balanced/.test(t)){ window.amiyoSmartCut.open(); return "Opened Smart Cut"; } window.amiyoSmartCut.run(k,/right away|now|apply/.test(t)); return "Finding the pauses ("+k+")"; }],
    [/(?:caption|subtitle)s?\s*(?:style|look|font|design)|style\s*(?:my\s*)?(?:caption|subtitle)|caption styler|best caption/,function(){ if(!window.amiyoCaptionStyler) throw new Error("Caption Styler is not ready"); window.amiyoCaptionStyler.open(); return "Opened Caption Styler"; }],
    [/music sync|sync (?:to |with |it to )?(?:the )?(?:beat|music)|cut (?:to|on) (?:the )?(?:beat|music)|beat sync|on the beat|to the beat/,function(t){ if(!window.amiyoMusicSync) throw new Error("Music Sync is not ready"); var p=/fast|quick/.test(t)?"fast":/calm|slow/.test(t)?"calm":/medium/.test(t)?"medium":null; if(p) window.amiyoMusicSync.setPace(p); else if(window.amiyoMusicSync.moodFromText) window.amiyoMusicSync.moodFromText(t); if(/right away|now/.test(t)){ window.amiyoMusicSync.run("now"); return "Cutting on the beat"; } window.amiyoMusicSync.open(); return "Opened Music Sync"; }],
    [/subtitle|caption|music|first\s+\d|shorter|\bshort\b/,function(t){ if(window.runAgentCommand){ window.runAgentCommand(t); return "Opened the plan for: "+t; } throw new Error("That needs the AI plan panel"); }],
    [/^(?:split|cut|slice)\b/,function(){ needClip(); splitSelected(); return "Split at the playhead"; }],
    [/^(?:delete|remove|erase|trash)\b/,function(){ needClip(); deleteSelected(); return "Deleted the clip"; }],
    [/^(?:duplicate|copy|clone)\b/,function(){ needClip(); duplicateSelected(); return "Duplicated the clip"; }],
    [/^(?:mute|silence this|no sound)\b/,function(){ var f=needClip(); tx("Mute clip",function(){ f.clip.volume=0; }); return "Muted"; }],
    [/^unmute\b/,function(){ var f=needClip(); tx("Unmute clip",function(){ f.clip.volume=1; }); return "Sound back to 100%"; }],
    [/volume\D*(\d{1,3})\s*%?/,function(t,m){ var f=needClip(), v=Math.max(0,Math.min(100,+m[1]))/100; tx("Change volume",function(){ f.clip.volume=v; }); return "Volume "+Math.round(v*100)+"%"; }],
    [/opacity\D*(\d{1,3})\s*%?/,function(t,m){ var f=needClip(), v=Math.max(0,Math.min(100,+m[1]))/100; tx("Change opacity",function(){ f.clip.opacity=v; }); return "Opacity "+Math.round(v*100)+"%"; }],
    [/fade\s*in(?:\D*(\d+(?:\.\d+)?))?/,function(t,m){ var f=needClip(), v=m[1]?+m[1]:1; tx("Fade in",function(){ f.clip.fadeIn=v; }); return "Fade in "+v+" s"; }],
    [/fade\s*out(?:\D*(\d+(?:\.\d+)?))?/,function(t,m){ var f=needClip(), v=m[1]?+m[1]:1; tx("Fade out",function(){ f.clip.fadeOut=v; }); return "Fade out "+v+" s"; }],
    [/(?:speed|faster|slower|slow|fast|normal)/,function(t){
      var m=t.match(/(\d+(?:\.\d+)?)\s*x/)||t.match(/speed\D*(\d+(?:\.\d+)?)/), v;
      if(m) v=+m[1]; else if(/slow/.test(t)) v=.5; else if(/normal/.test(t)) v=1; else v=2;
      v=Math.max(.1,Math.min(8,v)); var f=needClip();
      tx("Change speed",function(){ var c=f.clip, src=(c.outPoint!=null?c.outPoint:c.duration)-(c.inPoint||0); c.speed=v; c.duration=Math.max(.05,src/v); });
      return "Speed "+v+"x"; }],
    [/^(?:add|insert|new|create)?\s*(?:a\s+)?(?:text|title|caption|heading)\b\s*(.*)$/,function(t,m,raw){
      var q=raw.match(/["“']([^"”']+)["”']/), txt=q?q[1]:(m[1]||"").replace(/^(?:saying|that says|called|:)\s*/,"").trim();
      addTextClip(txt||"Title"); return "Added text: "+(txt||"Title"); }],
    [/(?:go to|jump to|seek to|move to|playhead (?:to|at))\s*(start|beginning|end|[\d:.]+\s*(?:s|sec|secs|seconds?)?)/,function(t,m){
      var w=m[1].trim(), v; if(/start|beginning/.test(w)) v=0; else if(w==="end") v=getProjectDuration(); else v=parseTime(w);
      if(v==null) throw new Error("I couldn't read that time. Try 1:30 or 45 seconds."); setCurrentTime(v); return "Playhead at "+fmt(Math.max(0,Math.min(v,getProjectDuration()))); }],
    [/vertical|portrait|9:16|tiktok|reel|shorts/,function(){ tx("Vertical 9:16",function(){ project.settings.width=720; project.settings.height=1280; project.settings.aspect="9:16"; }); return "Project is now vertical 9:16"; }],
    [/square|1:1|instagram post/,function(){ tx("Square 1:1",function(){ project.settings.width=1080; project.settings.height=1080; project.settings.aspect="1:1"; }); return "Project is now square 1:1"; }],
    [/landscape|horizontal|16:9|youtube/,function(){ tx("Landscape 16:9",function(){ project.settings.width=1280; project.settings.height=720; project.settings.aspect="16:9"; }); return "Project is now landscape 16:9"; }],
    [/zoom in/,function(){ window.amiyoZoomBy&&window.amiyoZoomBy(1.6,null,true); return "Zoomed in"; }],
    [/zoom out/,function(){ window.amiyoZoomBy&&window.amiyoZoomBy(1/1.6,null,true); return "Zoomed out"; }],
    [/\bfit\b|zoom to fit|show all/,function(){ var b=$("fitTimelineBtn"); if(b) b.click(); return "Timeline fitted"; }],
    [/export|render|save video/,function(){ closeSheet(); exportProject(); return "Opening export"; }]
  ];
  function split(raw){
    if(/["“']/.test(raw)) return [raw];
    /* Ask AI step 2: some "and" belong inside one command (fade in and out, black and white, between 5 and 10, volume up and down) */
    if(/^\s*(?:please\s+)?(?:add\s+)?(?:a\s+)?(?:narrate|narration|voice ?over)\b/i.test(raw)) return [raw];
    var keep=[], safe=raw.replace(/\b(?:fade (?:the )?(?:music|song|soundtrack) in (?:and|&) out|fade in (?:and|&) out|fade in\/out|black (?:and|&) white|(?:between|from) [\d:.]+\s*(?:s|sec|seconds?)? (?:and|to) [\d:.]+(?:\s*(?:s|sec|seconds?))?|fade in [\d.]+\s*(?:s|sec|seconds?)? and (?:fade )?out [\d.]+\s*(?:s|sec|seconds?)?)/ig,function(m){ keep.push(m); return "\u0001"+(keep.length-1)+"\u0002"; });
    return safe.split(/\s*(?:,|;|\bthen\b|\band then\b|\band\b)\s*/i).filter(Boolean).map(function(p){ return p.replace(/\u0001(\d+)\u0002/g,function(_,i){ return keep[+i]; }); });
  }
  function runOne(raw){ return window.amiyoRunWrap?window.amiyoRunWrap(raw,runOne0):runOne0(raw); }
  function runOne0(raw){
    try{ var __p=window.amiyoIntentPre&&window.amiyoIntentPre(raw); if(__p!=null) return __p; }catch(__e){ throw __e; }
    var t=raw.toLowerCase().replace(/[.!?]+$/,"").replace(/^(?:please|can you|could you|hey|ai)\s+/,"").replace(/\s+(?:please|here|now)$/,"").trim();
    for(var i=0;i<steps.length;i++){ var m=t.match(steps[i][0]); if(m) return steps[i][1](t,m,raw); }
    var ue=new Error("I don't know \u201c"+raw+"\u201d yet."); ue.unknown=true; throw ue;
  }
  function smartOn(){ return !!(window.amiyoSmartAsk&&window.amiyoSmartAsk.enabled()&&window.amiyoLLM); }
  var askBusy=false;
  function run(text){
    text=String(text||"").trim(); if(!text){ say("Type what you want, e.g. \u201csplit here and delete\u201d","bad"); return; }
    if(askBusy){ say("Still thinking about the last request\u2026"); return; }
    var parts=split(text), done=[], i=0;
    /* free-form / long requests go to the AI first; short exact commands stay instant and local */
    if(smartOn()&&parts.some(function(p){ return p.trim().split(/\s+/).length>5; })) return smartRun(text,[],parts,true);
    try{ for(;i<parts.length;i++) done.push(runOne(parts[i])); say("\u2713 "+done.join(" \u00b7 "),"ok"); try{ toast(done[done.length-1]); }catch(e){} }
    catch(e){
      if(e&&e.unknown&&smartOn()) return smartRun(parts.slice(i).join(" and "),done,parts.slice(i),false);
      say((done.length?"\u2713 "+done.join(" \u00b7 ")+"\n":"")+"\u2717 "+(e.message||e),"bad");
    }
  }
  function smartRun(req,done,localParts,isLong){
    askBusy=true; var pre=done.length?"\u2713 "+done.join(" \u00b7 ")+"\n":"";
    say(pre+"Thinking\u2026");
    window.amiyoSmartAsk.ask(req,runOne,function(m){ say(pre+m); }).then(function(r){
      askBusy=false;
      var lines=r.results.map(function(x){ return "\u2713 "+x; }).concat(r.skipped.map(function(x){ return "\u2013 skipped: "+x; }));
      if(r.say) lines.push(r.say);
      if(r.results.length>1) lines.push("Each change is its own undo step, so tap \u21b6 once per change to go back.");
      lines.push("(via "+r.provider+")");
      say(pre+lines.join("\n"),r.results.length?"ok":(r.say?"":"bad"));
      if(r.results.length){ try{ toast(r.results[r.results.length-1]); }catch(e){} }
    },function(err){
      askBusy=false; var why=(err&&err.message)||"AI unavailable";
      if(isLong){ say(pre+"\u2717 The AI could not be reached, so I did not guess.\n"+why+"\nTip: tap \u2699 Providers to set up Ollama or a free provider.","bad"); return; }
      var d2=done.slice();
      try{ localParts.forEach(function(p){ d2.push(runOne(p)); }); say("\u2713 "+d2.join(" \u00b7 "),"ok"); }
      catch(e){ say((d2.length?"\u2713 "+d2.join(" \u00b7 ")+"\n":"")+"\u2717 "+(e.message||e)+"\nAI: "+why,"bad"); }
    });
  }
  /* ---- UI ---- */
  var sheet=null, input=null, mic=null, rec=null;
  var CHIPS=["Find highlights","Split here","Split here and delete","Speed up 2x","Slow motion","Mute","Fade in 1 second","Add title \"Hello\"","Add title \"Hello\" for 3 seconds at the start","Fade in and out","Louder","Quieter","Cut from 0:10 to 0:20","Keep the first 30 seconds","Half speed","Warm film look","List looks","Go to start","Make it vertical","Smart cut","Style my captions","Sync to music","Undo"];
  function closeSheet(){ if(sheet) sheet.style.display="none"; try{ rec&&rec.stop(); }catch(e){} }
  function openSheet(){
    if(!sheet) build(); sheet.style.display="flex"; setTimeout(function(){ try{ input.focus(); }catch(e){} },60);
  }
  function build(){
    var css=document.createElement("style");
    css.textContent="#aiCmdBtn{position:fixed;right:12px;bottom:calc(env(safe-area-inset-bottom,0px) + 84px);z-index:150;min-height:44px;padding:0 16px;border-radius:22px;border:1px solid var(--accent,#ff7a3d);background:rgba(20,14,9,.92);color:#ffb454;font:700 14px system-ui,sans-serif;box-shadow:0 6px 20px rgba(0,0,0,.5)}"+
    "#aiCmd{position:fixed;inset:0;z-index:300;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.6)}"+
    "#aiCmd .box{background:#14120f;border-top:1px solid var(--line,#302c26);border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;max-height:78vh;overflow:auto}"+
    "#aiCmd .row{display:flex;gap:8px}#aiCmd input{flex:1;min-width:0;min-height:48px;border-radius:12px;border:1px solid var(--line,#302c26);background:#0a0908;color:#f1ece2;padding:0 12px;font-size:16px}"+
    "#aiCmd button{min-height:48px;min-width:48px;border-radius:12px;border:1px solid var(--line,#302c26);background:#211f1b;color:#f1ece2;font-size:15px;padding:0 12px}#aiCmd .go{background:var(--accent,#ff7a3d);color:#14120f;font-weight:700;border:0}"+
    "#aiCmd .chips{display:flex;flex-wrap:wrap;gap:6px}#aiCmd .chips button{min-height:38px;font-size:13px;border-radius:19px}#aiCmdOut{white-space:pre-wrap;font-size:13px;line-height:1.45;min-height:18px;color:#948a79}#aiCmd h4{margin:0;font:700 15px system-ui;color:#ffb454}";
    document.head.appendChild(css);
    sheet=document.createElement("div"); sheet.id="aiCmd"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","Ask AI to edit");
    sheet.innerHTML='<div class="box"><div class="row" style="justify-content:space-between;align-items:center"><h4>\u2728 Ask AI to edit</h4><button type="button" id="aiCmdX" aria-label="Close" style="min-height:40px">\u2715</button></div>'+
      '<div class="row"><input id="aiCmdIn" type="text" enterkeyhint="go" autocomplete="off" placeholder="e.g. split here and delete" aria-label="Edit command"><button type="button" id="aiCmdMic" aria-label="Speak a command">\ud83c\udfa4</button><button type="button" class="go" id="aiCmdGo">Go</button></div>'+
      '<div id="aiCmdOut" role="status">Works on the clip at the playhead (or the selected clip). You can chain steps with \u201cand\u201d.</div><div class="chips" id="aiCmdChips"></div></div>';
    document.body.appendChild(sheet);
    input=$("aiCmdIn"); mic=$("aiCmdMic");
    var ch=$("aiCmdChips"); CHIPS.forEach(function(c){ var b=document.createElement("button"); b.type="button"; b.textContent=c; b.onclick=function(){ input.value=c; run(c); }; ch.appendChild(b); });
    $("aiCmdGo").onclick=function(){ run(input.value); }; try{ if(window.amiyoSmartAsk) window.amiyoSmartAsk.mount(sheet); }catch(e){}
    input.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); run(input.value); } });
    $("aiCmdX").onclick=closeSheet; sheet.addEventListener("click",function(e){ if(e.target===sheet) closeSheet(); });
    var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SR){ mic.style.display="none"; }
    else mic.onclick=function(){
      try{
        if(rec){ rec.stop(); return; }
        rec=new SR(); rec.lang=document.documentElement.lang||"en-US"; rec.interimResults=false; rec.maxAlternatives=1;
        rec.onresult=function(e){ var t=e.results[0][0].transcript; input.value=t; run(t); };
        rec.onerror=function(e){ say("Microphone: "+(e.error||"error"),"bad"); };
        rec.onend=function(){ rec=null; mic.textContent="\ud83c\udfa4"; };
        rec.start(); mic.textContent="\u23fa"; say("Listening\u2026");
      }catch(e){ rec=null; say("Voice input is not available here","bad"); }
    };
  }
  var b=document.createElement("button"); b.type="button"; b.id="aiCmdBtn"; b.textContent="\u2728 Ask AI"; b.setAttribute("aria-label","Ask AI to edit"); b.onclick=openSheet;
  var css0=document.createElement("style"); css0.textContent="#aiCmdBtn{position:fixed;right:12px;bottom:calc(env(safe-area-inset-bottom,0px) + 84px);z-index:150;min-height:44px;padding:0 16px;border-radius:22px;border:1px solid var(--accent,#ff7a3d);background:rgba(20,14,9,.92);color:#ffb454;font:700 14px system-ui,sans-serif;box-shadow:0 6px 20px rgba(0,0,0,.5)}";
  document.head.appendChild(css0); document.body.appendChild(b);
  window.amiyoAskAI={run:run,open:openSheet,runOne:runOne,parse:function(t){ return split(t); }};
  try{ window.AMIYO_EDITOR_BUILD="plus5-ai-command-bar"; }catch(e){}
})();

;
/* ==================== Script 372 id="amiyo-plus-step7-ai-smartcut" ==================== */
/* Plus Step 7: AI Smart Cut. One tap removes dead air from the clip at the playhead, using the editor's own silence engine (it listens to the clip,
   finds its quiet level by itself, and cuts the pauses in one undo step). Pick how tight: Gentle keeps natural breathing room, Tight cuts fast.
   By default the result is shown for review before anything is cut. Spoken filler words ("um") need transcription and are not covered. */
(function(){
  "use strict";
  var $=function(id){return document.getElementById(id)};
  var PRESETS={gentle:{min:.8,pad:.18,off:-3,label:"Gentle"},balanced:{min:.5,pad:.1,off:0,label:"Balanced"},tight:{min:.3,pad:.06,off:3,label:"Tight"}};
  var sheet=null, busy=false;
  function say(m,k){ var n=$("scOut"); if(n){ n.textContent=m; n.style.color=k==="bad"?"#ff91a0":k==="ok"?"#5fd88a":"#948a79"; } try{ if(!sheet||sheet.style.display==="none") toast(m); }catch(e){} }
  function ensureClip(){
    var f=getClip(); if(f&&f.clip.assetId) return f;
    var t=currentTime, best=null;
    (project.tracks||[]).forEach(function(tr){ if(tr.kind!=="video"&&tr.kind!=="audio") return; (tr.clips||[]).forEach(function(c){
      if(c.assetId&&t>=c.start-.001&&t<=c.start+c.duration+.001&&(!best||tr.kind==="video")) best={track:tr,clip:c}; }); });
    if(!best) (project.tracks||[]).forEach(function(tr){ if(!best&&(tr.kind==="video"||tr.kind==="audio")) (tr.clips||[]).forEach(function(c){ if(!best&&c.assetId) best={track:tr,clip:c}; }); });
    if(best){ selectedClipId=best.clip.id; selectedTrackId=best.track.id; try{ renderTracks(); }catch(e){} }
    return best;
  }
  function wait(ms){ return new Promise(function(r){ setTimeout(r,ms); }); }
  function setVal(id,v){ var e=$(id); if(!e) return; e.value=String(v); e.dispatchEvent(new Event("input",{bubbles:true})); }
  async function run(key,apply){
    if(busy) return; var P=PRESETS[key]||PRESETS.balanced;
    if(!window.amiyoCut||!window.amiyoCut.silences){ say("The silence tool is not available in this build.","bad"); return; }
    if(!ensureClip()){ say("Add a video or audio clip to the timeline first.","bad"); return; }
    try{ if(isPlaying) pause(); }catch(e){}
    busy=true; var a=$("aiCmd"); if(a) a.style.display="none"; if(sheet) sheet.style.display="none";
    window.amiyoCut.silences();
    try{
      var t0=Date.now(), ok=false;
      while(Date.now()-t0<120000){
        await wait(200);
        var dlg=document.querySelector(".cs-dlg"); if(!dlg) return;                         /* user closed it */
        var s=dlg.querySelector(".cs-status"), go=$("csGo");
        if(s&&/Drag the level|Could not read/.test(s.textContent)){ ok=!/Could not read/.test(s.textContent); break; }
      }
      if(!ok){ var ss=document.querySelector(".cs-dlg .cs-status"); try{ toast(ss&&/no sound track/.test(ss.textContent)?"This clip has no sound, so Smart Cut has nothing to cut.":"Smart Cut could not read this clip's audio."); }catch(e){} return; }
      var thr=+$("csThr").value; setVal("csThr",Math.max(-70,Math.min(-15,thr+P.off))); setVal("csMin",P.min); setVal("csPad",P.pad);
      await wait(250);
      var go2=$("csGo"); if(!go2) return;
      if(go2.disabled){ try{ toast(key==="tight"?"No pauses found, even on Tight. The clip is steady sound all the way.":"No pauses found at "+P.label+". Try Tight."); }catch(e){} return; }                                                          /* the dialog's own text says nothing was found */
      if(apply){ go2.click(); }
    } finally { busy=false; }
  }
  function build(){
    var css=document.createElement("style");
    css.textContent="#scSheet{position:fixed;inset:0;z-index:310;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.6)}#scSheet .box{background:#14120f;border-top:1px solid #302c26;border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;color:#f1ece2;font-family:system-ui,sans-serif}"+
      "#scSheet h4{margin:0;font:700 15px system-ui;color:#ffb454}#scSheet button{min-height:48px;border-radius:12px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font-size:14px;padding:0 14px}#scSheet .go{background:#ff7a3d;color:#14120f;font-weight:700;border:0}"+
      "#scRow{display:flex;gap:8px}#scRow button{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:8px 4px}#scRow small{font-size:11px;color:inherit;opacity:.75}#scOut{font-size:13px;line-height:1.45;color:#948a79;white-space:pre-wrap}#scSheet label{display:flex;align-items:center;gap:8px;font-size:13px;min-height:36px}#scSheet input[type=checkbox]{width:20px;height:20px}";
    document.head.appendChild(css);
    sheet=document.createElement("div"); sheet.id="scSheet"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","AI Smart Cut");
    sheet.innerHTML='<div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h4>\u2702\ufe0f AI Smart Cut</h4><button type="button" id="scX" aria-label="Close" style="min-height:40px">\u2715</button></div>'+
      '<div id="scOut">Removes dead air from the clip at the playhead (or the selected clip). You see how much will be cut before anything changes.</div>'+
      '<div id="scRow"><button type="button" data-k="gentle">Gentle<small>pauses over 0.8 s</small></button><button type="button" data-k="balanced" class="go">Balanced<small>pauses over 0.5 s</small></button><button type="button" data-k="tight">Tight<small>pauses over 0.3 s</small></button></div>'+
      '<label><input type="checkbox" id="scApply"> Cut right away (skip the review)</label></div>';
    document.body.appendChild(sheet);
    $("scX").onclick=function(){ sheet.style.display="none"; }; sheet.addEventListener("click",function(e){ if(e.target===sheet) sheet.style.display="none"; });
    [].forEach.call(sheet.querySelectorAll("#scRow button"),function(b){ b.onclick=function(){ run(b.getAttribute("data-k"),$("scApply").checked); }; });
  }
  function open(){ if(!sheet) build(); var a=$("aiCmd"); if(a) a.style.display="none"; sheet.style.display="flex"; }
  window.amiyoSmartCut={open:open,run:run};
  try{ window.AMIYO_EDITOR_BUILD="plus7-ai-smartcut"; }catch(e){}
})();

;
/* ==================== Script 373 id="amiyo-plus-step8-ai-caption-styler" ==================== */
/* Plus Step 8: AI Caption Styler. Looks at 5 frames of your video (how bright and busy the bottom of the picture is, how colourful, how much it changes)
   plus the shape of the project (vertical / short), then recommends the 3 caption styles most likely to be easy to read, with the reason.
   Tap a tile to apply it to all captions (and to new ones). Uses the editor's own caption styles, so every tap is one undo step. Runs on this device. */
(function(){
  "use strict";
  var $=function(id){return document.getElementById(id)};
  function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
  function rgba(hex,a){ var h=String(hex||"#000").replace("#",""); if(h.length===3) h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2]; var n=parseInt(h,16); if(isNaN(n)) return "rgba(0,0,0,"+a+")"; return "rgba("+(n>>16&255)+","+(n>>8&255)+","+(n&255)+","+a+")"; }
  function capCss(s){
    var t=[]; t.push("font-weight:"+(s.weight||700)); t.push("font-size:"+Math.min(20,Math.max(11,(s.sz||5)*2.6))+"px"); t.push("color:"+(s.color||"#fff"));
    if(s.shadow) t.push("text-shadow:"+(s.shadowColor?"0 0 8px "+s.shadowColor+",0 0 3px "+s.shadowColor:"0 2px 4px rgba(0,0,0,.8)"));
    if(s.stroke){ t.push("-webkit-text-stroke:"+Math.max(1.5,(s.strokeW||.12)*14)+"px "+(s.strokeColor||"#000")); t.push("paint-order:stroke fill"); }
    if(s.bg){ var b="#ff7a3d"; try{ if(s.brand&&window.AMIYO_BRAND) b=window.AMIYO_BRAND.primary()||b; }catch(e){} t.push("background:"+rgba(s.brand?b:(s.bgColor||"#000"),s.bgOpacity==null?.85:s.bgOpacity)); t.push("padding:2px 8px"); }
    return t.join(";");
  }
  function pickClip(){
    var f=getClip(); if(f&&f.clip.assetId&&(f.track.kind==="video"||f.track.kind==="image")) return f;
    var t=currentTime, best=null;
    (project.tracks||[]).forEach(function(tr){ if(tr.kind!=="video"&&tr.kind!=="image") return; (tr.clips||[]).forEach(function(c){ if(c.assetId&&t>=c.start-.001&&t<=c.start+c.duration+.001&&!best) best={track:tr,clip:c}; }); });
    if(!best) (project.tracks||[]).forEach(function(tr){ if(!best&&(tr.kind==="video"||tr.kind==="image")) (tr.clips||[]).forEach(function(c){ if(!best&&c.assetId) best={track:tr,clip:c}; }); });
    return best;
  }
  function frameStats(cx,w,h){
    var px=cx.getImageData(0,0,w,h).data, y0=Math.floor(h*.68), n=0, sum=0, sq=0, sat=0, all=0, lum=new Float32Array(w*h);
    for(var y=0;y<h;y++) for(var x=0;x<w;x++){
      var i=(y*w+x)*4, r=px[i],g=px[i+1],b=px[i+2], L=.3*r+.59*g+.11*b, mx=Math.max(r,g,b), mn=Math.min(r,g,b);
      lum[y*w+x]=L; sat+=mx?(mx-mn)/mx:0; all++;
      if(y>=y0){ n++; sum+=L; sq+=L*L; }
    }
    var m=sum/n; return {bot:m,busy:Math.sqrt(Math.max(0,sq/n-m*m)),sat:sat/all,lum:lum};
  }
  async function sample(f){
    var c=f.clip, a=getAsset(c.assetId), url=await ensureUrl(a); if(!url) throw new Error("This clip's file could not be opened.");
    var W=64,H=36, cv=document.createElement("canvas"); cv.width=W; cv.height=H; var cx=cv.getContext("2d",{willReadFrequently:true}), out=[], thumb=null;
    var big=document.createElement("canvas"); big.width=200; big.height=112; var bx=big.getContext("2d");
    if(a.type==="image"){
      var im=await new Promise(function(res,rej){ var i=new Image(); i.onload=function(){ res(i); }; i.onerror=function(){ rej(new Error("The picture could not be opened.")); }; i.src=url; });
      cx.drawImage(im,0,0,W,H); out.push(frameStats(cx,W,H)); bx.drawImage(im,0,0,200,112); thumb=big.toDataURL("image/jpeg",.6); return {frames:out,thumb:thumb};
    }
    var v=document.createElement("video"); v.muted=true; v.playsInline=true; v.preload="auto"; v.src=url;
    await new Promise(function(res,rej){ var t=setTimeout(function(){ rej(new Error("The video could not be opened for analysis.")); },9000); v.onloadedmetadata=function(){ clearTimeout(t); res(); }; v.onerror=function(){ clearTimeout(t); rej(new Error("The video could not be opened for analysis.")); }; });
    var inP=c.inPoint||0, outP=(c.outPoint!=null?c.outPoint:inP+c.duration*(c.speed||1)), span=Math.max(.2,outP-inP), fr=[.1,.3,.5,.7,.9];
    for(var k=0;k<fr.length;k++){
      await new Promise(function(res){ var done=false, h=function(){ if(done) return; done=true; v.removeEventListener("seeked",h); res(); }; v.addEventListener("seeked",h); setTimeout(h,1500); v.currentTime=Math.min(Math.max(0,inP+span*fr[k]),Math.max(0,(v.duration||outP)-.05)); });
      try{ cx.drawImage(v,0,0,W,H); out.push(frameStats(cx,W,H)); if(k===2){ bx.drawImage(v,0,0,200,112); thumb=big.toDataURL("image/jpeg",.6); } }catch(e){}
    }
    v.removeAttribute("src"); v.load();
    if(!out.length) throw new Error("No picture could be read from this clip.");
    return {frames:out,thumb:thumb};
  }
  function analyseFacts(frames){
    var bot=0,busy=0,sat=0; frames.forEach(function(f){ bot+=f.bot; busy+=f.busy; sat+=f.sat; }); var n=frames.length; bot/=n; busy/=n; sat/=n;
    var vr=0,pairs=0; for(var i=1;i<frames.length;i++){ var a=frames[i-1].lum,b=frames[i].lum,d=0; for(var k=0;k<a.length;k++) d+=Math.abs(a[k]-b[k]); vr+=d/a.length; pairs++; }
    vr=pairs?vr/pairs:0;
    var s=project.settings||{}, vertical=(s.height||720)>(s.width||1280), dur=0; try{ dur=getProjectDuration(); }catch(e){}
    return {bot:bot,busy:busy,sat:sat,variety:vr,vertical:vertical,short:dur>0&&dur<=90,bright:bot>150,dark:bot<70,isBusy:busy>42,vivid:sat>.45,energetic:vr>38,calm:vr<18};
  }
  function recommend(F,styles){
    var sc={},why={}; function add(id,p,r){ sc[id]=(sc[id]||0)+p; if(r&&p>0){ (why[id]=why[id]||[]).push(r); } }
    var hardToRead=F.bright||F.isBusy;
    add("tiktok",0,""); add("pop",0,"");
    if(F.vertical||F.short){ add("tiktok",3,"made for vertical or short videos"); add("pop",2,"word-by-word highlight keeps short videos lively"); }
    if(F.energetic){ add("tiktok",2,"fast-changing picture"); add("pop",2,"fast-changing picture"); add("comic",1,"fast-changing picture"); add("outline",1,"punchy for fast video"); }
    if(F.bright){ add("boxed",3,"bright bottom of the picture needs a dark box"); add("outline",2,"thick outline stays readable on bright areas"); add("tiktok",1,"outline stays readable on bright areas"); }
    if(F.isBusy){ add("boxed",2,"busy background behind the words"); add("bar",1,"solid bar cuts through a busy background"); add("outline",1,"outline separates words from clutter"); }
    if(F.dark&&!F.isBusy){ add("classic",2,"dark, calm bottom: clean white text works"); add("minimal",2,"dark, calm bottom: light touch is enough"); add("night",1,"dark scene"); }
    if(F.dark&&F.vivid){ add("neon",2,"dark, colourful scene suits a glow"); }
    if(F.dark&&F.isBusy){ add("bar",2,"white bar stands out on dark clutter"); add("marker",1,"yellow marker stands out on dark"); }
    if(F.vivid&&F.energetic){ add("comic",2,"very colourful and busy"); }
    if(F.calm&&!F.short&&!F.vertical){ add("cinema",3,"calm, longer landscape video"); add("minimal",1,"calm footage"); }
    if(!hardToRead){ add("classic",1,"safe everyday choice"); } else { ["classic","minimal","cinema","neon"].forEach(function(id){ add(id,-3,""); }); }
    var list=styles.filter(function(s){ return sc[s.id]!=null; }).map(function(s){ return {s:s,score:sc[s.id],why:(why[s.id]||[]).slice(0,2).join("; ")||"general purpose"}; });
    list.sort(function(a,b){ return b.score-a.score; }); return list.slice(0,3);
  }
  function summary(F){
    return "Bottom of picture: "+(F.bright?"bright":F.dark?"dark":"medium")+(F.isBusy?" and busy":" and calm")+" \u00b7 Colours: "+(F.vivid?"vivid":"muted")+" \u00b7 Motion: "+(F.energetic?"fast":F.calm?"slow":"moderate")+" \u00b7 Format: "+(F.vertical?"vertical":"wide")+(F.short?", short":"");
  }
  var sheet=null, busy=false;
  function out(m,k){ var n=$("csrOut"); if(n){ n.textContent=m; n.style.color=k==="bad"?"#ff91a0":k==="ok"?"#5fd88a":"#948a79"; } }
  async function open(){
    if(!window.AMIYO_CAPTIONS||!window.AMIYO_CAPTIONS.styles){ try{ toast("Caption styles are not ready. Reload the editor."); }catch(e){} return; }
    if(!sheet) build(); var a=$("aiCmd"); if(a) a.style.display="none"; sheet.style.display="flex";
    if(busy) return; busy=true; $("csrList").innerHTML=""; out("Looking at your video\u2026");
    try{
      var f=pickClip(); if(!f) throw new Error("Add a video or picture to the timeline first, then try again.");
      try{ if(isPlaying) pause(); }catch(e){}
      var r=await sample(f), F=analyseFacts(r.frames), recs=recommend(F,window.AMIYO_CAPTIONS.styles);
      out(summary(F)+"\nTap a style to use it.","ok"); render(recs,r.thumb);
    }catch(e){ out((e&&e.message)||"Could not analyze the video.","bad"); }
    busy=false;
  }
  function render(recs,thumb){
    var L=$("csrList"); L.innerHTML="";
    recs.forEach(function(x,i){
      var b=document.createElement("button"); b.type="button"; b.className="csrTile"+(i===0?" best":""); b.setAttribute("aria-label","Use caption style "+x.s.label);
      var words=x.s.upper?"THIS IS A SAMPLE CAPTION":"This is a sample caption";
      b.innerHTML='<div class="csrPv" style="background-image:url('+(thumb||"")+')"><span style="'+esc(capCss(x.s))+'">'+esc(words)+'</span></div><div class="csrTx"><b>'+(i===0?"\u2605 Best match \u00b7 ":"")+esc(x.s.label)+'</b><small>'+esc(x.why)+'</small></div>';
      b.onclick=function(){ try{
          var sg=function(){ try{ return JSON.stringify([project.captionDefault,(project.tracks||[]).filter(function(t){ return t.kind==="caption"; }).map(function(t){ return t.clips; })]); }catch(e){ return ""; } };
          var n=0; (project.tracks||[]).forEach(function(t){ if(t.kind==="caption") n+=(t.clips||[]).length; });
          var s0=sg(); window.AMIYO_CAPTIONS.apply(x.s.id); var s1=sg();
          [].forEach.call(L.querySelectorAll(".csrTile"),function(t){ t.classList.toggle("on",t===b); });
          if(s0===s1&&project.captionDefault===x.s.id&&n) out("Your captions already use \u201c"+x.s.label+"\u201d.","ok");
          else if(s0===s1) out("Nothing changed. In the Captions panel, select a caption or switch to \u201cAll captions\u201d, then tap the style again.","bad");
          else if(!n) out("You have no captions yet. New captions will use \u201c"+x.s.label+"\u201d. Undo reverses it.","ok");
          else out("Applied \u201c"+x.s.label+"\u201d to the captions. Undo reverses it.","ok");
        }catch(e){ out("Could not apply that style.","bad"); } };
      L.appendChild(b);
    });
  }
  function build(){
    var css=document.createElement("style");
    css.textContent="#csrSheet{position:fixed;inset:0;z-index:310;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.6)}#csrSheet .box{background:#14120f;border-top:1px solid #302c26;border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;max-height:82vh;overflow:auto;color:#f1ece2;font-family:system-ui,sans-serif}"+
      "#csrSheet h4{margin:0;font:700 15px system-ui;color:#ffb454}#csrSheet .x{min-height:40px;min-width:44px;border-radius:12px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font-size:16px}#csrOut{font-size:12.5px;line-height:1.5;color:#948a79;white-space:pre-wrap}"+
      ".csrTile{display:flex;flex-direction:column;gap:6px;text-align:left;padding:8px;border-radius:12px;border:1px solid #302c26;background:#100f0c;color:#f1ece2;font-family:inherit}.csrTile.best{border-color:#ff7a3d;background:#1d130b}.csrTile.on{outline:2px solid #5fd88a}.csrTile:active{transform:scale(.98)}"+
      ".csrPv{height:96px;border-radius:8px;background:#50372b center/cover no-repeat;display:flex;align-items:flex-end;justify-content:center;padding:8px;overflow:hidden}.csrPv span{max-width:100%;text-align:center;line-height:1.25}.csrTx b{font-size:14px}.csrTx small{display:block;font-size:12px;color:#948a79;margin-top:2px}";
    document.head.appendChild(css);
    sheet=document.createElement("div"); sheet.id="csrSheet"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","AI Caption Styler");
    sheet.innerHTML='<div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h4>\ud83d\udcac AI Caption Styler</h4><button type="button" class="x" id="csrX" aria-label="Close">\u2715</button></div><div id="csrOut">Looking at your video\u2026</div><div id="csrList" style="display:flex;flex-direction:column;gap:10px"></div></div>';
    document.body.appendChild(sheet);
    $("csrX").onclick=function(){ sheet.style.display="none"; }; sheet.addEventListener("click",function(e){ if(e.target===sheet) sheet.style.display="none"; });
  }
  window.amiyoCaptionStyler={open:open,recommend:recommend,facts:analyseFacts};
  try{ window.AMIYO_EDITOR_BUILD="plus8-ai-caption-styler"; }catch(e){}
})();

