  function chromeApi(){ try{ if(window.LanguageModel&&LanguageModel.create) return {kind:"new",api:window.LanguageModel}; if(window.ai&&window.ai.languageModel) return {kind:"old",api:window.ai.languageModel}; }catch(e){} return null; }
