      var j=await res.json(), a=Array.isArray(j)?j:(Array.isArray(j.data)?j.data:(Array.isArray(j.models)?j.models:[])), names=[];
      a.forEach(function(m){ var n=typeof m==="string"?m:(m&&(m.id||m.name||m.model)); if(n&&zUsable(String(n))&&names.indexOf(String(n))<0) names.push(String(n)); });
