    [].forEach.call($("aiHubCards").querySelectorAll("[data-on]"),function(c){ c.onchange=function(){ cfg.on[c.getAttribute("data-on")]=c.checked; save(); }; });
    [].forEach.call($("aiHubCards").querySelectorAll("[data-f]"),function(i){ i.onchange=function(){ var p=i.getAttribute("data-f").split("."); cfg[p[0]][p[1]]=i.value.trim(); save(); if(p[0]==="custom"&&p[1]==="endpoint"){ cfg.custom.model=""; save(); refreshCustom(true); } else if(ZERO[p[0]]&&ZERO[p[0]].user&&p[1]==="endpoint"){ cfg[p[0]].model=""; delete ZMODELS[p[0]]; zSave(); if(ZERO[p[0]].url){ cfg.on[p[0]]=true; save(); } render(); if(ZERO[p[0]].url) findZero(p[0]); } }; });
