    [].forEach.call($("aiHubCards").querySelectorAll("[data-up]"),function(b){ b.onclick=function(){ var k=b.getAttribute("data-up"), i=cfg.order.indexOf(k); if(i>0){ cfg.order.splice(i,1); cfg.order.splice(i-1,0,k); save(); render(); } }; });
    [].forEach.call($("aiHubCards").querySelectorAll("[data-refresh]"),function(b){ b.onclick=function(){ var k=b.getAttribute("data-refresh"); if(k==="local") refreshLocal(); else if(k==="custom") refreshCustom(); else refreshModels(); }; });
    [].forEach.call($("aiHubCards").querySelectorAll("[data-preset]"),function(sl){ sl.onchange=function(){ var p=PRESETS.filter(function(x){ return x[0]===sl.value; })[0]; cfg.local.preset=sl.value; if(p&&p[2]) cfg.local.endpoint=p[2]; cfg.local.model=""; save(); render(); }; });
    [].forEach.call($("aiHubCards").querySelectorAll("[data-zfind]"),function(b){ b.onclick=function(){ findZero(b.getAttribute("data-zfind")); }; });
    [].forEach.call($("aiHubCards").querySelectorAll("[data-zcheck]"),function(b){ b.onclick=function(){ zCheck(b.getAttribute("data-zcheck"),b); }; });
    var pn=$("aiHubPullNow"); if(pn) pn.onclick=pullNow;
