  function copyText(t,cb){
    function fb(){ var ok=false; try{ var ta=document.createElement("textarea"); ta.value=t; ta.style.cssText="position:fixed;opacity:0;top:0"; document.body.appendChild(ta); ta.select(); ok=document.execCommand("copy"); ta.remove(); }catch(e){} cb(ok); }
    try{ if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(function(){ cb(true); },fb); return; } }catch(e){} fb();
  }
  async function detectOllama(){
    stat("ollama","Looking for Ollama\u2026");
    var cands=[]; [cfg.ollama.endpoint,"http://localhost:11434","http://127.0.0.1:11434","http://[::1]:11434"].forEach(function(u){ u=trimEnd(u); if(u&&cands.indexOf(u)<0) cands.push(u); });
    var found=await new Promise(function(res){ var left=cands.length; cands.forEach(function(u){ var tm=withTimeout(null,4000); fetch(u+"/api/tags",{signal:tm.signal}).then(function(r){ tm.done(); if(r.ok) res(u); else if(--left===0) res(""); },function(){ tm.done(); if(--left===0) res(""); }); }); });
    if(!found){ stat("ollama","Ollama was not found on this device. Start it, and set OLLAMA_ORIGINS=* so this page is allowed. On a phone, use the address of the computer running it.","bad"); return; }
    cfg.ollama.endpoint=found; save(); render(); refreshModels();
  }
  /* Plus Step 26: Ollama setup check, copy-paste fixes per system, and installing a model from inside the app (with progress and Cancel). */
  var pullAc=null;
  var FIXES={
    win:['setx OLLAMA_ORIGINS "*"','(then quit Ollama from the tray and start it again)'].join("\n"),
    mac:['launchctl setenv OLLAMA_ORIGINS "*"','(then quit Ollama and open it again)'].join("\n"),
    linux:['sudo systemctl edit ollama.service','[Service]','Environment="OLLAMA_ORIGINS=*"','Environment="OLLAMA_HOST=0.0.0.0"','(then: sudo systemctl restart ollama)'].join("\n"),
    phone:['On the computer that runs Ollama set OLLAMA_HOST=0.0.0.0 and OLLAMA_ORIGINS=*, restart Ollama,','then type that computer address here, for example http://192.168.1.20:11434'].join("\n")
  };
  async function setupCheck(){
    var out=$("aiHubSetupOut"); if(!out) return; var L=[];
    function show(){ out.textContent=L.join("\n"); }
    var ep=trimEnd(cfg.ollama.endpoint)||"http://localhost:11434"; L.push("Checking "+ep+" ..."); show();
    try{ if(location.protocol==="https:"&&/^http:\/\//i.test(ep)&&!/^http:\/\/(localhost|127\.0\.0\.1|\[::1\])/i.test(ep)) L.push("! This page is https but the address is plain http on another device. The browser may block it. Open the page over http, or use an https tunnel."); }catch(e){}
    var reach=false, ok=false, tm=withTimeout(null,6000);
    try{
      var r=await fetch(ep+"/api/version",{signal:tm.signal}); reach=true;
      if(r.ok){ ok=true; var j={}; try{ j=await r.json(); }catch(e){} L.push("OK  Ollama answered"+(j.version?" (version "+j.version+")":"")+"."); }
      else L.push("X   Ollama answered with HTTP "+r.status+(r.status===403?": this page is not allowed. Set OLLAMA_ORIGINS=* (pick your system below) and restart Ollama.":"."));
    }catch(e){
      var t2=withTimeout(null,6000);
      try{ await fetch(ep+"/api/version",{mode:"no-cors",signal:t2.signal}); reach=true; L.push("X   Ollama is running but blocks this page (CORS). Pick your system below, tap Copy fix, run it, then restart Ollama."); }
      catch(e2){ L.push("X   Nothing answered at that address. Start Ollama, or check the address. From a phone, use the computer address and set OLLAMA_HOST=0.0.0.0."); }
      finally{ t2.done(); }
    }finally{ tm.done(); }
    show();
    if(ok){
      try{ var tg=await ollamaTags();
        if(!tg.length) L.push("X   No models installed. Pick one above and tap Install now.");
        else{ L.push("OK  "+tg.length+" model"+(tg.length===1?"":"s")+" installed: "+tg.slice(0,4).map(function(m){ return m.name; }).join(", ")+(tg.length>4?" ...":"")+"."); L.push(cfg.ollama.model?"OK  Using "+cfg.ollama.model+".":"i   The first installed model will be used."); }
      }catch(e){ L.push("X   Could not read the model list."); }
    }
    show();
  }
  async function pullNow(){
    var btn=$("aiHubPullNow"), bar=$("aiHubPullBar"), txt=$("aiHubPullTxt"); if(!btn||!bar||!txt) return;
    if(pullAc){ pullAc.abort(); return; }
    var name=$("aiHubPull").value, ep=trimEnd(cfg.ollama.endpoint)||"http://localhost:11434";
    pullAc=new AbortController(); btn.textContent="Cancel"; bar.style.display="block"; bar.value=0; txt.className="st"; txt.textContent="Starting "+name+" ...";
    try{
      var res=await fetch(ep+"/api/pull",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:name,name:name,stream:true}),signal:pullAc.signal});
      if(!res.ok) throw new Error("HTTP "+res.status+(res.status===403?" (set OLLAMA_ORIGINS=* and restart Ollama)":""));
      var failed="", done=false;
      await readLines(res,function(ln){
        ln=String(ln||"").trim(); if(!ln) return; var p; try{ p=JSON.parse(ln); }catch(e){ return; }
        if(p.error){ failed=String(p.error); return; }
        if(p.status==="success"){ done=true; return; }
        if(p.total>0&&p.completed>=0){ bar.value=Math.min(100,p.completed*100/p.total); txt.textContent="Downloading "+name+": "+Math.round(bar.value)+"% ("+Math.round(p.completed/1e6)+" of "+Math.round(p.total/1e6)+" MB)"; }
        else if(p.status){ txt.textContent=String(p.status).slice(0,60); }
      },pullAc.signal);
      if(failed) throw new Error(failed);
      if(!done) throw new Error("the download stopped early");
      bar.value=100; cfg.ollama.model=name; save(); txt.className="st ok"; txt.textContent=name+" is installed and selected.";
      refreshModels();
    }catch(e){
      txt.className="st bad";
      txt.textContent=(e&&/abort/i.test(e.name||e.message||""))?"Install cancelled. Tap Install now again to continue where it stopped.":("Install failed: "+niceErr("ollama",e));
    }finally{ pullAc=null; var b2=$("aiHubPullNow"); if(b2) b2.textContent="Install now"; }
  }
  /* Plus Step 27: model pickers for the no-key providers. A built-in short list shows at once; "Find models" loads the live list; you can still type any name. */
  /* ===== Zero-auth step 1: no-key provider registry =====
     Each entry: kind (openai = OpenAI-style stream, get = plain GET, puter = Puter.js), url, models list url, a built-in fallback list.
     Model "" means Auto: the app picks the first good model and, if it fails, tries the next ones. */
