    pollinations:{kind:"openai",url:"https://text.pollinations.ai/openai",models:"https://text.pollinations.ai/models",fall:["openai","openai-fast","mistral","llama"]},
    llm7:{kind:"openai",url:"https://api.llm7.io/v1/chat/completions",models:"https://api.llm7.io/v1/models",key:"unused",fall:["default","fast","pro"]},
    pollisimple:{kind:"get",url:"https://text.pollinations.ai/",models:"https://text.pollinations.ai/models",fall:["openai","openai-fast","mistral","llama"]},
    airforce:{kind:"openai",url:"https://api.airforce/v1/chat/completions",models:"https://api.airforce/v1/models",fall:["llama-3.3-70b-chat","gpt-4o-mini","deepseek-v3"]},
    deepinfra:{kind:"openai",url:"https://api.deepinfra.com/v1/openai/chat/completions",models:"https://api.deepinfra.com/v1/openai/models",fall:["meta-llama/Meta-Llama-3.1-8B-Instruct","Qwen/Qwen2.5-72B-Instruct","mistralai/Mistral-Nemo-Instruct-2407"]},
    hackclub:{kind:"openai",url:"https://ai.hackclub.com/chat/completions",fall:["qwen/qwen3-32b","openai/gpt-oss-20b","meta-llama/llama-4-scout-17b-16e-instruct"]},
    mlvoca:{kind:"ollamagen",url:"https://mlvoca.com/api/generate",fall:["tinyllama","deepseek-r1:1.5b"]},
    chat:{kind:"openai",url:"https://ch.at/v1/chat/completions",fall:["gpt-4o"]},
