  function mSave(){ var ks=Object.keys(MH); if(ks.length>300){ ks.sort(function(a,b){ return Math.max(MH[a].ok,MH[a].f)-Math.max(MH[b].ok,MH[b].f); }).slice(0,ks.length-300).forEach(function(x){ delete MH[x]; }); } jset(MK,MH); }
  function mRec(id,m,ok,ttl){ var k=id+"|"+m, h=MH[k]||(MH[k]={ok:0,f:0}); if(ok){ h.ok=Date.now(); delete h.u; }else{ h.f=Date.now(); h.u=h.f+(ttl||3600000); } mSave(); }
  function mState(id,m){ var h=MH[id+"|"+m]; if(!h) return ""; var n=Date.now(); if(h.f&&h.f>h.ok&&n<(h.u||h.f+3600000)) return "bad"; if(h.ok&&h.ok>=h.f&&n-h.ok<24*3600000) return "good"; return ""; }
  function srec(id,ok,ms,err){ var s=stats[id]||(stats[id]={ok:0,f:0,ms:0,err:"",t:0}); if(ok){ s.ok++; s.ms+=ms; }else{ s.f++; s.err=String(err||"").slice(0,120); } s.t=Date.now(); jset(SK,stats); }

  /* ---------- model lists ---------- */
