      var q=x2.getImageData(0,0,24,24).data, n=q.length/4, mu=[0,0,0], sd=0, k2; for(k2=0;k2<q.length;k2+=4){ mu[0]+=q[k2]; mu[1]+=q[k2+1]; mu[2]+=q[k2+2]; } mu=mu.map(function(v){ return v/n; });
