      var body={prompt:String(r.prompt).slice(0,900)+(r.negative?" ### "+String(r.negative).slice(0,300):""),params:{sampler_name:"k_euler_a",cfg_scale:7,width:sz[0],height:sz[1],steps:20,n:1,seed:String(r.seed)},nsfw:false,censor_nsfw:true,trusted_workers:false,slow_workers:true,r2:false};
