        var j={}; try{ j=await res.json(); }catch(e){}
        if(!res.ok){ var msg=String(j.message||("HTTP "+res.status)).slice(0,100); if(res.status===429) msg="HTTP 429 queue is busy"; throw new Error(res.status===401||res.status===403?"HTTP "+res.status+" (needs a key)":msg); }
