    res={chapters:ch,description:want.description?String(j.description||"").trim().slice(0,800):"",titles:want.titles&&Array.isArray(j.titles)?j.titles.map(function(x){ return String(x||"").trim().slice(0,100); }).filter(Boolean).slice(0,5):[],hashtags:want.hashtags?normTags(j.hashtags,tagMax):[],dur:dur};
