    var body=document.createElement("div"); body.className="chBody"; if(m.err) body.textContent="\u26a0 "+m.err+"\nTip: tap \u2699 at the top to pick or fix a provider."; else if(m.r==="assistant") renderMd(body,m.c); else body.textContent=m.c; d.appendChild(body);
    if(m.r==="user"&&(m.img||m.im)){ if(m.img){ var im=document.createElement("img"); im.src=m.img; im.alt="Your picture"; im.style.cssText="max-width:100%;max-height:160px;border-radius:8px;display:block;margin-bottom:6px"; d.insertBefore(im,body); } else { var lb=document.createElement("div"); lb.className="chM"; lb.textContent="\ud83d\uddbc Picture was sent (pictures are not saved)"; d.insertBefore(lb,body); } }
