      var ch=document.createElement("div"); ch.className="chChips";
      ["Ideas for a 30 second travel reel","Write 5 punchy captions about a birthday party","How do I make my video vertical?","Tips to keep viewers watching"].forEach(function(t){ var b=document.createElement("button"); b.type="button"; b.textContent=t; b.onclick=function(){ $("chText").value=t; send(); }; ch.appendChild(b); });
