  function svcState(E,id){ try{ var h=E.health()[id]; if(h&&h.pausedFor>0) return '<br><span class="nt" style="color:#ff91a0">Paused '+h.pausedFor+' s: '+esc(h.error||"failed")+'</span>'; var st=E.stats()[id]; if(st&&st.ok) return '<br><span class="nt" style="color:#5fd88a">Worked '+st.ok+' time'+(st.ok===1?"":"s")+'</span>'; }catch(e){} return ""; }
