        try{ await E.generate("a red circle on a white background",{width:256,height:256,only:p.id,model:ms[j],exact:true,timeout:25000}); ok++; lines.push("\u2713 "+p.name+(ms[j]?" \u00b7 "+ms[j]:"")); }
