/* ==================== Script 388 id="amiyo-plus-step3-preview-gestures" ==================== */
/* Plus Step 3: touch gestures on the preview. Swipe sideways to scrub (drag up for fine control), double-tap the left or right
   side to jump 5 s back / forward, double-tap the middle to play or pause. Mouse use and the on-canvas transform box are untouched. */
(function(){
  "use strict";
  var shell=document.getElementById("canvasShell"), stage=document.querySelector(".preview-stage"); if(!shell||!stage) return;
  var hud=document.createElement("div"); hud.className="pv-hud"; hud.setAttribute("aria-hidden","true"); stage.appendChild(hud);
  var hudT=0;
  function say(main,sub){ hud.innerHTML=main+(sub?"<small>"+sub+"</small>":""); hud.classList.add("on"); clearTimeout(hudT); hudT=setTimeout(function(){ hud.classList.remove("on"); },900); }
  function fmtT(t){ try{ return fmt(t); }catch(e){ return t.toFixed(2)+"s"; } }
  function buzz(){ try{ if(navigator.vibrate) navigator.vibrate(8); }catch(e){} }
  function dur(){ try{ return getProjectDuration(); }catch(e){ return 0; } }
  function frame(){ try{ return 1/((project.settings&&project.settings.fps)||30); }catch(e){ return 1/30; } }
  var g=null, lastTap={t:0,x:0,y:0}, quiet=0, raf=0, want=null;
  function seekTo(t){ want=t; if(raf) return; raf=requestAnimationFrame(function(){ raf=0; if(want==null) return; try{ setCurrentTime(want); }catch(e){ window.__swl&&window.__swl(e); } want=null; }); }
  function inOverlay(el){ return !!(el&&el.closest&&el.closest("#xfOverlay,#xfBox,.xf-h")); }
  shell.addEventListener("pointerdown",function(e){
    if(e.pointerType==="mouse"||inOverlay(e.target)) return;
    if(g){ g=null; return; }                       /* a second finger: leave it to the browser / pinch */
    g={id:e.pointerId,x:e.clientX,y:e.clientY,lx:e.clientX,t0:performance.now(),mode:null,cur:0,was:false};
  });
  shell.addEventListener("pointermove",function(e){
    if(!g||e.pointerId!==g.id) return;
    var dx=e.clientX-g.x, dy=e.clientY-g.y;
    if(!g.mode){
      if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.3){
        g.mode="scrub"; g.was=!!isPlaying; if(g.was){ try{ pause(); }catch(x){} }
        g.cur=currentTime; g.lx=e.clientX;
        try{ shell.setPointerCapture(e.pointerId); }catch(x){}
      } else return;
    }
    var w=Math.max(120,shell.getBoundingClientRect().width), range=Math.min(30,Math.max(6,dur()));
    var fine=(g.y-e.clientY)>60?0.2:1;                 /* drag upward for finer control */
    g.cur=Math.max(0,Math.min(dur(),g.cur+(e.clientX-g.lx)/w*range*fine)); g.lx=e.clientX;
    var t=Math.round(g.cur/frame())*frame(); seekTo(t);
    say(fmtT(t),fine<1?"fine":"swipe");
    e.preventDefault();
  },{passive:false});
  function end(e){
    if(!g||(e&&e.pointerId!==g.id)) return;
    var o=g; g=null;
    if(o.mode==="scrub"){ quiet=performance.now(); if(o.was){ try{ play(); }catch(x){} } return; }
    if(!e||e.type==="pointercancel") return;
    var now=performance.now(), moved=Math.hypot(e.clientX-o.x,e.clientY-o.y);
    if(now-o.t0>350||moved>14) return;               /* a long press or a drag is not a tap */
    if(now-lastTap.t<320&&Math.hypot(e.clientX-lastTap.x,e.clientY-lastTap.y)<48){
      lastTap.t=0; quiet=now;
      var r=shell.getBoundingClientRect(), f=(e.clientX-r.left)/Math.max(1,r.width);
      try{
        if(f<.33){ setCurrentTime(Math.max(0,currentTime-5)); say("\u22125 s"); }
        else if(f>.67){ setCurrentTime(Math.min(dur(),currentTime+5)); say("+5 s"); }
        else if(isPlaying){ pause(); say("Paused"); } else { play(); say("Play"); }
      }catch(x){ window.__swl&&window.__swl(x); }
      buzz();
    } else lastTap={t:now,x:e.clientX,y:e.clientY};
  }
  shell.addEventListener("pointerup",end); shell.addEventListener("pointercancel",end);
  /* a swipe or double-tap must not also select whatever is under the finger */
  shell.addEventListener("click",function(e){ if(performance.now()-quiet<400){ e.stopImmediatePropagation(); e.preventDefault(); } },true);
  try{
    if(matchMedia("(pointer:coarse)").matches&&!localStorage.getItem("amiyo-pv-gestures-hint")){
      localStorage.setItem("amiyo-pv-gestures-hint","1");
      setTimeout(function(){ try{ toast("Tip: swipe the preview to scrub, double-tap its sides to skip 5 s",4200); }catch(e){} },2500);
    }
  }catch(e){}
  try{ window.AMIYO_EDITOR_BUILD="plus-step3-preview-gestures"; }catch(e){}
})();

