        var cursor=base+1, lanes=parts.map(function(p){ var t={id:mkid("track"),kind:p.track.kind,name:"Highlights"+(parts.length>1?" "+p.track.kind:""),clips:[],muted:false,hidden:false}; project.tracks.push(t); return t; });
