  var sheet=null, busy=false, cancel=false, aspect="9:16", mode="balanced", fill="follow";
  function say(m,k){ var n=$("rfOut"); if(n){ n.textContent=m; n.style.color=k==="bad"?"#ff91a0":k==="ok"?"#5fd88a":"#948a79"; } }
  function bar(p){ var b=$("rfBar"); if(!b) return; b.style.display=p==null?"none":"block"; b.firstChild.style.width=Math.round((p||0)*100)+"%"; }
