    if(!base){ var t=currentTime;
      (project.tracks||[]).forEach(function(tr){ if(base||tr.kind!=="video") return; (tr.clips||[]).forEach(function(c){
        var a=c.assetId&&getAsset(c.assetId); if(!base&&a&&a.type==="video"&&t>=c.start-.001&&t<=c.start+c.duration+.001) base={track:tr,clip:c}; }); });
    }
