    await new Promise(function(res,rej){ var to=setTimeout(function(){ rej(new Error("The video took too long to load")); },15000);
      v.onloadedmetadata=function(){ clearTimeout(to); res(); }; v.onerror=function(){ clearTimeout(to); rej(new Error("This video cannot be read here")); }; });
    return v;
