          var sx=0,sy=0,sw=0; faces.forEach(function(f){ var b=f.boundingBox, a=b.width*b.height; sx+=(b.x+b.width/2)*a; sy+=(b.y+b.height/2)*a; sw+=a; });
          if(sw>0) return {x:sx/sw/fw,y:sy/sw/fh,face:true,lum:lum,cut:cutNow};
