/* ==================== Script 396 id="amiyo-pr-step01-targets" ==================== */
/* Premiere step 1: track targeting + sync lock. "Target" decides which track new media lands on (per kind: video / audio).
   "Sync" decides whether a track ripples when you Insert at the playhead; a track with Sync off stays exactly where it is.
   Open it from the timeline toolbar: Targets. Stored on the tracks, so it is saved with the project and is undoable with them. */
(function(){
  "use strict";
  var $=function(id){ return document.getElementById(id); };
  var sheet=null;
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function syncOn(t){ return t.sync!==false; }
  var origGetTrack=window.getTrack;
  if(typeof origGetTrack==="function" && !origGetTrack.__s1){
    window.getTrack=function(kind){
      try{ var t=(project.tracks||[]).filter(function(x){ return x.kind===kind&&x.target===true&&!x.locked; })[0]; if(t) return t; }catch(e){}
      return origGetTrack.apply(this,arguments);
    };
    window.getTrack.__s1=true;
  }
  var origInsert=window.insertSourceAtPlayhead;
  if(typeof origInsert==="function" && !origInsert.__s1){
    window.insertSourceAtPlayhead=function(){
      var keep=[]; (project.tracks||[]).forEach(function(t){ if(!syncOn(t)) (t.clips||[]).forEach(function(c){ keep.push([c,c.start]); }); });
      var n0=project.history.index;
      var r=origInsert.apply(this,arguments);
      if(keep.length){
        keep.forEach(function(k){ k[0].start=k[1]; });
        var e=project.history.entries[project.history.index];
        if(project.history.index>n0&&e){ try{ e.after=serializableProject(); }catch(x){} }
        try{ scheduleAutosave(); renderAll(); }catch(x){}
      }
      return r;
    };
    window.insertSourceAtPlayhead.__s1=true;
  }
  document.addEventListener("click",function(e){
    var b=e.target.closest&&e.target.closest("#insertAtPlayhead"); if(!b) return;
    e.stopImmediatePropagation(); e.preventDefault(); window.insertSourceAtPlayhead();
  },true);
  function paint(){
    var l=$("s1List"); if(!l) return;
    l.innerHTML=(project.tracks||[]).map(function(t,i){
      var can=t.kind==="video"||t.kind==="audio";
      return '<div class="s1r"><div class="s1n">'+esc(t.name||t.kind)+'<small>'+esc(t.kind)+(t.locked?' \u00b7 locked':'')+'</small></div>'+
        (can?'<button type="button" data-i="'+i+'" data-k="target" class="'+(t.target?'on':'')+'" aria-pressed="'+(t.target?'true':'false')+'">Target</button>':'<span class="s1x">\u2014</span>')+
        '<button type="button" data-i="'+i+'" data-k="sync" class="'+(syncOn(t)?'on':'')+'" aria-pressed="'+(syncOn(t)?'true':'false')+'">Sync</button></div>';
    }).join("");
  }
  function onTap(e){
    var b=e.target.closest&&e.target.closest("button[data-k]"); if(!b) return;
    var t=project.tracks[+b.getAttribute("data-i")]; if(!t) return;
    var before=deepClone(serializableProject()), k=b.getAttribute("data-k");
    if(k==="target"){ var on=!t.target; project.tracks.forEach(function(x){ if(x.kind===t.kind) x.target=false; }); t.target=on; }
    else t.sync=!syncOn(t);
    try{ pushHistory("Track "+k,before); }catch(x){ try{ project.history.entries.push({label:"Track "+k,before:before,after:serializableProject()}); project.history.index++; }catch(y){} }
    try{ scheduleAutosave(); }catch(x){}
    paint();
  }
  function css(){
    var s=document.createElement("style"); s.id="s1-css";
    s.textContent="#s1Sheet{position:fixed;inset:0;z-index:318;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.6)}"+
    "#s1Sheet .box{background:#14120f;border-top:1px solid #302c26;border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;max-height:80vh;overflow:auto}"+
    "#s1Sheet h4{margin:0;font:700 15px system-ui;color:#ffb454}#s1Sheet p{margin:0;font-size:12.5px;line-height:1.5;color:#948a79}"+
    "#s1Sheet button{min-height:44px;border-radius:12px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font-size:13.5px;padding:0 14px}"+
    "#s1Sheet button.on{background:linear-gradient(155deg,#ff7a3d,#e8622a);color:#1a0c03;border-color:transparent;font-weight:700}"+
    ".s1r{display:flex;align-items:center;gap:8px}.s1n{flex:1;min-width:0;font-size:13.5px;color:#f1ece2}.s1n small{display:block;font-size:11.5px;color:#8f8777}.s1x{width:74px;text-align:center;color:#5c5548}";
    document.head.appendChild(s);
  }
  function ui(){
    css(); sheet=document.createElement("div"); sheet.id="s1Sheet"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","Track targeting");
    sheet.innerHTML='<div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h4>\uD83C\uDFAF Track targeting</h4><button type="button" id="s1X" aria-label="Close">Close</button></div>'+
      '<p><b>Target</b>: new media goes on this track (one per kind). <b>Sync</b>: the track moves along when you Insert; turn it off to keep a track (like music) fixed.</p><div id="s1List" style="display:flex;flex-direction:column;gap:8px"></div></div>';
    document.body.appendChild(sheet);
    $("s1X").onclick=close; sheet.addEventListener("click",function(e){ if(e.target===sheet) close(); else onTap(e); });
  }
  function open(){ if(!sheet) ui(); paint(); sheet.style.display="flex"; }
  function close(){ if(sheet) sheet.style.display="none"; }
  window.amiyoTargets={open:open,close:close,syncOn:syncOn};
  function addBtn(){
    var bar=document.querySelector(".timeline-toolbar"); if(!bar||$("s1Btn")) return;
    var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id="s1Btn"; b.textContent="\uD83C\uDFAF Targets"; b.title="Track targeting and sync lock"; b.onclick=open;
    var a=$("fitTimelineBtn"); if(a&&a.parentNode) a.parentNode.insertBefore(b,a); else bar.appendChild(b);
  }
  addBtn(); setTimeout(addBtn,1000);
  try{ window.AMIYO_EDITOR_BUILD="pr-step01-targets"; }catch(e){}
})();

