/* ==================== Script 397 id="amiyo-pr-step02-source-marks" ==================== */
/* Premiere step 2: Source monitor with In/Out marks (3-point editing). Pick a clip from the media bin (tap it in the Media tab), open
   "Source" in the timeline toolbar, scrub, Mark In / Mark Out, then Insert or Overwrite: only the marked part is placed at the playhead.
   Marks are saved on the media item. Without marks, Insert/Overwrite work as before. The "," and "." keys use the marks too. */
(function(){
  "use strict";
  var $=function(id){ return document.getElementById(id); };
  var cur=null, sheet=null;
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function tf(t){ t=Math.max(0,+t||0); var m=Math.floor(t/60), s=t-m*60; return m+":"+(s<10?"0":"")+s.toFixed(2); }
  function A(id){ return id&&project.assets?project.assets[id]:null; }
  function say(m){ try{ toast(m); }catch(e){} }
  document.addEventListener("click",function(e){ var el=e.target.closest&&e.target.closest("#leftPanel .asset[data-asset]"); if(el&&!e.target.closest(".asset-add")) cur=el.getAttribute("data-asset"); },true);
  function wrap(name){
    var o=window[name]; if(typeof o!=="function"||o.__s2) return;
    var w=function(){
      var a=A(cur);
      if(!a||(a.type!=="video"&&a.type!=="audio")||(a.markIn==null&&a.markOut==null)) return o.apply(this,arguments);
      var full=a.duration||5, i=Math.max(0,a.markIn||0), out=a.markOut!=null?Math.min(a.markOut,full):full;
      if(out-i<0.1){ say("The In and Out marks are too close together"); return; }
      var ids={}, at=currentTime, idx0=project.history.index;
      project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ ids[c.id]=1; }); });
      var r; a.duration=out-i;
      try{ r=o.apply(this,arguments); } finally{ a.duration=full; }
      var best=null;
      project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ if(!ids[c.id]&&c.assetId===a.id&&(!best||Math.abs(c.start-at)<Math.abs(best.start-at))) best=c; }); });
      if(best){
        best.inPoint=i; best.outPoint=out;
        if(project.history.index>idx0){ var e=project.history.entries[project.history.index]; if(e){ try{ e.after=serializableProject(); }catch(x){} } }
        try{ scheduleAutosave(); renderAll(); }catch(x){}
      }
      return r;
    };
    w.__s2=true; window[name]=w;
  }
  wrap("insertSourceAtPlayhead"); wrap("overwriteSourceAtPlayhead");
  document.addEventListener("keydown",function(e){
    var tag=document.activeElement&&document.activeElement.tagName; if(tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||e.ctrlKey||e.metaKey||e.altKey) return;
    if(e.key===","){ e.preventDefault(); e.stopImmediatePropagation(); window.insertSourceAtPlayhead(); }
    else if(e.key==="."){ e.preventDefault(); e.stopImmediatePropagation(); window.overwriteSourceAtPlayhead(); }
  },true);
  function list(){ return Object.keys(project.assets||{}).map(function(k){ return project.assets[k]; }).filter(function(a){ return a&&(a.type==="video"||a.type==="audio"); }); }
  function vid(){ return $("s2Vid"); }
  function paint(){
    var a=A(cur), L=list(), sel=$("s2Sel");
    sel.innerHTML=L.length?L.map(function(x){ return '<option value="'+esc(x.id)+'"'+(x.id===cur?" selected":"")+'>'+esc(x.name||x.id)+'</option>'; }).join(""):'<option value="">No video or audio yet</option>';
    var v=vid(); if(a){ var u=(typeof assetUrl==="function")?assetUrl(a.id):null; if(u&&v.getAttribute("data-id")!==a.id){ v.src=u; v.setAttribute("data-id",a.id); } }
    var full=a?(a.duration||0):0, i=a&&a.markIn!=null?a.markIn:0, o=a&&a.markOut!=null?a.markOut:full;
    $("s2Info").textContent=a?("In "+tf(i)+"  \u00b7  Out "+tf(o)+"  \u00b7  Length "+tf(Math.max(0,o-i))+(a.markIn==null&&a.markOut==null?"  (whole clip)":"")):"Pick media above.";
    var f=$("s2Fill"); if(f&&full){ f.style.left=(i/full*100)+"%"; f.style.width=(Math.max(0,o-i)/full*100)+"%"; }
  }
  function mark(which){
    var a=A(cur), v=vid(); if(!a){ say("Pick media first"); return; }
    var t=Math.max(0,Math.min(v.currentTime||0,a.duration||v.duration||0));
    if(which==="in"){ a.markIn=t; if(a.markOut!=null&&a.markOut<=t+0.1) a.markOut=null; } else { a.markOut=t; if(a.markIn!=null&&a.markIn>=t-0.1) a.markIn=null; }
    try{ scheduleAutosave(); }catch(e){} paint();
  }
  function place(fn){
    var a=A(cur); if(!a){ say("Pick media first"); return; }
    var el=document.querySelector('#leftPanel .asset[data-asset="'+a.id+'"]');
    if(!el){ say("Open the Media tab once, then try again"); return; }
    el.click(); close(); setTimeout(function(){ window[fn](); },30);
  }
  function css(){
    var s=document.createElement("style"); s.id="s2-css";
    s.textContent="#s2Sheet{position:fixed;inset:0;z-index:318;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.6)}"+
    "#s2Sheet .box{background:#14120f;border-top:1px solid #302c26;border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;max-height:88vh;overflow:auto}"+
    "#s2Sheet h4{margin:0;font:700 15px system-ui;color:#ffb454}#s2Sheet video{width:100%;max-height:34vh;background:#000;border-radius:10px}"+
    "#s2Sheet button,#s2Sheet select{min-height:44px;border-radius:12px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font-size:13.5px;padding:0 12px}"+
    "#s2Sheet button.go{background:linear-gradient(155deg,#ff7a3d,#e8622a);color:#1a0c03;border-color:transparent;font-weight:700}"+
    ".s2row{display:flex;gap:8px;flex-wrap:wrap}.s2row>*{flex:1 1 90px}#s2Info{font-size:12.5px;color:#cfc7b8}"+
    "#s2Rng{position:relative;height:10px;border-radius:99px;background:#100f0c;border:1px solid #302c26;overflow:hidden}#s2Fill{position:absolute;top:0;bottom:0;background:#ff7a3d}";
    document.head.appendChild(s);
  }
  function ui(){
    css(); sheet=document.createElement("div"); sheet.id="s2Sheet"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","Source monitor");
    sheet.innerHTML='<div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h4>\uD83C\uDF9E Source monitor</h4><button type="button" id="s2X" aria-label="Close">Close</button></div>'+
      '<select id="s2Sel" aria-label="Source media"></select><video id="s2Vid" controls playsinline preload="metadata"></video><div id="s2Rng"><i id="s2Fill"></i></div><div id="s2Info" role="status"></div>'+
      '<div class="s2row"><button type="button" id="s2I">Mark In</button><button type="button" id="s2O">Mark Out</button><button type="button" id="s2C">Clear marks</button></div>'+
      '<div class="s2row"><button type="button" class="go" id="s2Ins">\u2935 Insert at playhead</button><button type="button" class="go" id="s2Ovw">\u2933 Overwrite at playhead</button></div></div>';
    document.body.appendChild(sheet);
    $("s2X").onclick=close; sheet.addEventListener("click",function(e){ if(e.target===sheet) close(); });
    $("s2Sel").onchange=function(e){ cur=e.target.value||null; paint(); };
    $("s2I").onclick=function(){ mark("in"); }; $("s2O").onclick=function(){ mark("out"); };
    $("s2C").onclick=function(){ var a=A(cur); if(a){ a.markIn=null; a.markOut=null; try{ scheduleAutosave(); }catch(e){} paint(); } };
    $("s2Ins").onclick=function(){ place("insertSourceAtPlayhead"); }; $("s2Ovw").onclick=function(){ place("overwriteSourceAtPlayhead"); };
  }
  function open(){ if(!sheet) ui(); if(!cur||!A(cur)){ var l=list(); cur=l.length?l[l.length-1].id:null; } paint(); sheet.style.display="flex"; }
  function close(){ if(sheet){ sheet.style.display="none"; try{ vid().pause(); }catch(e){} } }
  window.amiyoSourceMonitor={open:open,close:close,setSource:function(id){ cur=id; }};
  function addBtn(){
    var bar=document.querySelector(".timeline-toolbar"); if(!bar||$("s2Btn")) return;
    var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id="s2Btn"; b.textContent="\uD83C\uDF9E Source"; b.title="Source monitor with In/Out marks"; b.onclick=open;
    var a=$("s1Btn")||$("fitTimelineBtn"); if(a&&a.parentNode===bar) bar.insertBefore(b,a.nextSibling); else bar.appendChild(b);
  }
  addBtn(); setTimeout(addBtn,1000);
  try{ window.AMIYO_EDITOR_BUILD="pr-step02-source-marks"; }catch(e){}
})();

