/* ==================== Script 398 id="amiyo-pr-step03-easing" ==================== */
/* Premiere step 3: keyframe easing. Every keyframe segment can now be Linear, Ease in, Ease out, Ease in-out, Hold (jumps at the next keyframe),
   Bounce, or a custom Bezier curve you drag. The easing of a keyframe shapes the move from that keyframe to the next one, in the preview and the export.
   Open it from the timeline toolbar: Easing. Select a clip that has keyframes first (Add keyframe in the Inspector). One undo step per change. */
(function(){
  "use strict";
  var $=function(id){ return document.getElementById(id); };
  var NAMES=[["linear","Linear"],["ease-in","Ease in"],["ease-out","Ease out"],["ease-in-out","Ease in-out"],["hold","Hold"],["bounce","Bounce"],["bezier","Bezier"]];
  var PRESETS={"Smooth":[.42,0,.58,1],"Fast start":[0,.6,.3,1],"Slow start":[.7,0,1,.4],"Overshoot":[.3,1.5,.6,1],"Snap":[.9,0,.1,1]};
  function bez(x1,y1,x2,y2,p){
    if(p<=0) return 0; if(p>=1) return 1;
    var lo=0, hi=1, t=p, i, x;
    for(i=0;i<28;i++){ x=3*(1-t)*(1-t)*t*x1+3*(1-t)*t*t*x2+t*t*t; if(Math.abs(x-p)<1e-5) break; if(x<p) lo=t; else hi=t; t=(lo+hi)/2; }
    return 3*(1-t)*(1-t)*t*y1+3*(1-t)*t*t*y2+t*t*t;
  }
  window.__amiyoEase=function(name,p,k){
    switch(name){
      case "ease-in": return p*p;
      case "ease-out": return 1-(1-p)*(1-p);
      case "ease-in-out": return p*p*(3-2*p);
      case "hold": return p>=1?1:0;
      case "bounce": { var n1=7.5625, d1=2.75, q=p; if(q<1/d1) return n1*q*q; if(q<2/d1) return n1*(q-=1.5/d1)*q+.75; if(q<2.5/d1) return n1*(q-=2.25/d1)*q+.9375; return n1*(q-=2.625/d1)*q+.984375; }
      case "bezier": { var b=k&&k.bez; if(b&&b.length===4) return bez(b[0],b[1],b[2],b[3],p); return p; }
      default: return p;
    }
  };
  var sheet=null, sel=0;
  function cl(){ try{ return typeof getClip==="function"?getClip():null; }catch(e){ return null; } }
  function keys(f){ return (f&&f.clip&&f.clip.keyframes)||[]; }
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function change(label,fn){
    var f=cl(); if(!f) return; var before=deepClone(serializableProject()); fn(f);
    try{ pushHistory(label,before); }catch(e){ project.history.entries.push({label:label,before:before,after:serializableProject()}); project.history.index=project.history.entries.length-1; }
    try{ scheduleAutosave(); renderAll(); }catch(e){}
    paint();
  }
  function curvePath(k){
    var pts=[], i, n=40; for(i=0;i<=n;i++){ var p=i/n, y=window.__amiyoEase(k.easing||"linear",p,k); pts.push((10+p*180).toFixed(1)+","+(150-y*100).toFixed(1)); }
    return pts.join(" ");
  }
  function paint(){
    var f=cl(), ks=keys(f), box=$("s3Body"); if(!box) return;
    if(!f){ box.innerHTML='<p>Select a clip on the timeline first.</p>'; return; }
    if(!ks.length){ box.innerHTML='<p>This clip has no keyframes. Move the playhead over the clip and tap <b>Add keyframe</b> in the Inspector (at least two), then come back.</p>'; return; }
    if(sel>=ks.length) sel=ks.length-1;
    var k=ks[sel];
    var rows=ks.map(function(x,i){ return '<button type="button" class="s3k'+(i===sel?' on':'')+'" data-k="'+i+'">'+(+x.t).toFixed(2)+'s<small>'+esc(x.easing||"linear")+'</small></button>'; }).join("");
    var names=NAMES.map(function(n){ return '<button type="button" class="'+((k.easing||"linear")===n[0]?"on":"")+'" data-e="'+n[0]+'">'+n[1]+'</button>'; }).join("");
    var bz=k.bez||[.42,0,.58,1], h="";
    var svg='<svg id="s3Svg" viewBox="0 0 200 180" width="100%" style="max-width:340px;touch-action:none;background:#100f0c;border:1px solid #302c26;border-radius:12px"><rect x="10" y="50" width="180" height="100" fill="none" stroke="#302c26"/><line x1="10" y1="150" x2="190" y2="50" stroke="#2a2620" stroke-dasharray="3 3"/><polyline points="'+curvePath(k)+'" fill="none" stroke="#ff7a3d" stroke-width="2.5"/>';
    if(k.easing==="bezier"){
      var x1=10+bz[0]*180,y1=150-bz[1]*100,x2=10+bz[2]*180,y2=150-bz[3]*100;
      svg+='<line x1="10" y1="150" x2="'+x1+'" y2="'+y1+'" stroke="#8f8777"/><line x1="190" y1="50" x2="'+x2+'" y2="'+y2+'" stroke="#8f8777"/><circle data-h="0" cx="'+x1+'" cy="'+y1+'" r="11" fill="#ffb454"/><circle data-h="1" cx="'+x2+'" cy="'+y2+'" r="11" fill="#ffb454"/>';
      h='<div class="s3p">'+Object.keys(PRESETS).map(function(n){ return '<button type="button" data-p="'+esc(n)+'">'+esc(n)+'</button>'; }).join("")+'</div>';
    }
    svg+='</svg>';
    box.innerHTML='<div class="s3r">'+rows+'</div><div class="s3p">'+names+'</div>'+svg+h+'<button type="button" id="s3All">Use this easing on all keyframes</button>'+
      '<p>Keyframe '+(sel+1)+' of '+ks.length+'. Easing shapes the move to the next keyframe'+(sel===ks.length-1?' (this is the last one, so it has no effect).':'.')+'</p>';
  }
  function onTap(e){
    var b=e.target.closest&&e.target.closest("button"); if(!b) return;
    if(b.hasAttribute("data-k")){ sel=+b.getAttribute("data-k"); var f=cl(), k=keys(f)[sel]; if(k&&typeof currentTime!=="undefined"){ try{ currentTime=f.clip.start+k.t; renderAll(); }catch(x){} } paint(); return; }
    if(b.hasAttribute("data-e")){ var nm=b.getAttribute("data-e"); change("Keyframe easing",function(f){ var k=keys(f)[sel]; k.easing=nm; if(nm==="bezier"&&!k.bez) k.bez=[.42,0,.58,1]; }); return; }
    if(b.hasAttribute("data-p")){ var pr=PRESETS[b.getAttribute("data-p")]; change("Keyframe curve",function(f){ var k=keys(f)[sel]; k.easing="bezier"; k.bez=pr.slice(); }); return; }
    if(b.id==="s3All"){ change("Easing on all keyframes",function(f){ var s=keys(f)[sel]; keys(f).forEach(function(k){ k.easing=s.easing||"linear"; if(s.bez) k.bez=s.bez.slice(); else delete k.bez; }); }); }
  }
  var drag=null, before0=null;
  function svgPt(e,svg){ var r=svg.getBoundingClientRect(), x=(e.clientX-r.left)/r.width*200, y=(e.clientY-r.top)/r.height*180; return {x:x,y:y}; }
  function down(e){
    var c=e.target.closest&&e.target.closest("circle[data-h]"); if(!c) return;
    var f=cl(), k=keys(f)[sel]; if(!k||k.easing!=="bezier") return;
    drag={h:+c.getAttribute("data-h"),svg:$("s3Svg")}; before0=deepClone(serializableProject()); try{ e.target.setPointerCapture(e.pointerId); }catch(x){} e.preventDefault();
  }
  function move(e){
    if(!drag) return; var f=cl(), k=keys(f)[sel]; if(!k) return;
    var p=svgPt(e,drag.svg), px=Math.max(0,Math.min(1,(p.x-10)/180)), py=Math.max(-.5,Math.min(1.5,(150-p.y)/100));
    var b=(k.bez||[.42,0,.58,1]).slice(); b[drag.h*2]=+px.toFixed(3); b[drag.h*2+1]=+py.toFixed(3); k.bez=b; paint2(k);
  }
  function paint2(k){
    var svg=$("s3Svg"); if(!svg) return; var bz=k.bez;
    svg.querySelector("polyline").setAttribute("points",curvePath(k));
    var cs=svg.querySelectorAll("circle[data-h]"), ls=svg.querySelectorAll("line[stroke='#8f8777']");
    cs[0].setAttribute("cx",10+bz[0]*180); cs[0].setAttribute("cy",150-bz[1]*100); cs[1].setAttribute("cx",10+bz[2]*180); cs[1].setAttribute("cy",150-bz[3]*100);
    ls[0].setAttribute("x2",10+bz[0]*180); ls[0].setAttribute("y2",150-bz[1]*100); ls[1].setAttribute("x2",10+bz[2]*180); ls[1].setAttribute("y2",150-bz[3]*100);
    try{ renderPreviewFrame(); }catch(e){}
  }
  function up(){
    if(!drag) return; drag=null;
    try{ pushHistory("Keyframe curve",before0); scheduleAutosave(); renderAll(); }catch(e){}
  }
  function css(){
    var s=document.createElement("style"); s.id="s3-css";
    s.textContent="#s3Sheet{position:fixed;inset:0;z-index:318;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.55)}"+
    "#s3Sheet .box{background:#14120f;border-top:1px solid #302c26;border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;max-height:86vh;overflow:auto}"+
    "#s3Sheet h4{margin:0;font:700 15px system-ui;color:#ffb454}#s3Sheet p{margin:0;font-size:12.5px;line-height:1.5;color:#948a79}"+
    "#s3Sheet button{min-height:44px;border-radius:12px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font-size:13.5px;padding:0 12px}"+
    "#s3Sheet button.on{background:linear-gradient(155deg,#ff7a3d,#e8622a);color:#1a0c03;border-color:transparent;font-weight:700}"+
    ".s3r,.s3p{display:flex;gap:6px;flex-wrap:wrap}.s3k small{display:block;font-size:10.5px;opacity:.75}.s3k{min-width:64px}";
    document.head.appendChild(s);
  }
  function ui(){
    css(); sheet=document.createElement("div"); sheet.id="s3Sheet"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","Keyframe easing");
    sheet.innerHTML='<div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h4>\uD83D\uDCC8 Keyframe easing</h4><button type="button" id="s3X" aria-label="Close">Close</button></div><div id="s3Body" style="display:flex;flex-direction:column;gap:10px"></div></div>';
    document.body.appendChild(sheet);
    $("s3X").onclick=close; sheet.addEventListener("click",function(e){ if(e.target===sheet) close(); else onTap(e); });
    sheet.addEventListener("pointerdown",down); sheet.addEventListener("pointermove",move); sheet.addEventListener("pointerup",up); sheet.addEventListener("pointercancel",up);
  }
  function open(){ if(!sheet) ui(); sel=0; paint(); sheet.style.display="flex"; }
  function close(){ if(sheet) sheet.style.display="none"; }
  window.amiyoEasing={open:open,close:close,bezier:bez};
  function addBtn(){
    var bar=document.querySelector(".timeline-toolbar"); if(!bar||$("s3Btn")) return;
    var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id="s3Btn"; b.textContent="\uD83D\uDCC8 Easing"; b.title="Keyframe easing and bezier curves"; b.onclick=open;
    var a=$("s2Btn")||$("fitTimelineBtn"); if(a&&a.parentNode===bar) bar.insertBefore(b,a.nextSibling); else bar.appendChild(b);
  }
  addBtn(); setTimeout(addBtn,1000);
  try{ window.AMIYO_EDITOR_BUILD="pr-step03-easing"; }catch(e){}
})();

