/* ==================== Script 399 id="amiyo-pr-step04-remove-attributes" ==================== */
/* Premiere step 4: Remove Attributes. Reset parts of the selected clip(s) in one go: motion/transform, keyframes, effects and looks, colour,
   keying and masks, audio (volume, fades, EQ) and transitions. Speed and the clip's timing are never touched. One undo step.
   Open it from the timeline toolbar: Reset. */
(function(){
  "use strict";
  var $=function(id){ return document.getElementById(id); };
  var CATS=[
    {id:"motion",label:"Motion and position",hint:"position, scale, rotation, opacity, crop, fit",set:{x:.5,y:.5,scale:1,rotation:0,opacity:1,fit:"contain"},del:["crop"]},
    {id:"keys",label:"Keyframes",hint:"motion and volume keyframes",set:{keyframes:[]},del:["volumeKeyframes","anim","animPreset","animPresetDuration","textFx"]},
    {id:"fx",label:"Effects and looks",hint:"effects, filters, looks, stabilizer, blend mode",set:{effects:[],filterAmt:0},del:["filter","look","cgLook","lut","stab","blendMode","graphicStyle"]},
    {id:"color",label:"Colour",hint:"colour wheels and presets",del:["colorWheels","lumWheels","colorPreset"]},
    {id:"key",label:"Keying and masks",hint:"chroma key, masks",del:["chromaKey"],re:/mask/i},
    {id:"audio",label:"Audio",hint:"volume, fades, EQ",set:{volume:1,fadeIn:0,fadeOut:0},del:["eqFx","volumeKeyframes"]},
    {id:"trans",label:"Transitions",hint:"in and out transitions",set:{transitionIn:null,transitionOut:null}}
  ];
  var pick={}, sheet=null;
  CATS.forEach(function(c){ pick[c.id]=(c.id==="fx"||c.id==="keys"); });
  function targets(){
    var out=[], seen={};
    (project.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.selected&&!seen[c.id]){ seen[c.id]=1; out.push(c); } }); });
    try{ var f=typeof getClip==="function"?getClip():null; if(f&&f.clip&&!seen[f.clip.id]) out.push(f.clip); }catch(e){}
    return out;
  }
  function resetClip(c,cat){
    var n=0;
    if(cat.set) Object.keys(cat.set).forEach(function(k){ var v=cat.set[k]; var cur=c[k]; var same=JSON.stringify(cur)===JSON.stringify(v)||(cur===undefined&&(v===0||v===null)); if(!same){ c[k]=(v&&typeof v==="object")?JSON.parse(JSON.stringify(v)):v; n++; } });
    (cat.del||[]).forEach(function(k){ if(c[k]!==undefined){ delete c[k]; n++; } });
    if(cat.re) Object.keys(c).forEach(function(k){ if(cat.re.test(k)&&c[k]!=null&&c[k]!==false){ delete c[k]; n++; } });
    return n;
  }
  function apply(){
    var cl=targets(); if(!cl.length){ try{ toast("Select a clip first"); }catch(e){} return; }
    var chosen=CATS.filter(function(c){ return pick[c.id]; }); if(!chosen.length){ try{ toast("Tick at least one group"); }catch(e){} return; }
    var before=deepClone(serializableProject()), n=0;
    cl.forEach(function(c){ chosen.forEach(function(cat){ n+=resetClip(c,cat); }); });
    if(!n){ try{ toast("Nothing to remove on the selected clip"); }catch(e){} return; }
    try{ pushHistory("Remove attributes",before); }catch(e){ project.history.entries.push({label:"Remove attributes",before:before,after:serializableProject()}); project.history.index=project.history.entries.length-1; }
    try{ scheduleAutosave(); renderAll(); toast("Reset "+n+" setting"+(n===1?"":"s")+" on "+cl.length+" clip"+(cl.length===1?"":"s")); }catch(e){}
    close();
  }
  function paint(){
    var cl=targets(); $("s4Info").textContent=cl.length?(cl.length+" clip"+(cl.length===1?"":"s")+" selected"):"Select a clip on the timeline first.";
    $("s4List").innerHTML=CATS.map(function(c){ return '<label class="s4k"><input type="checkbox" data-c="'+c.id+'"'+(pick[c.id]?" checked":"")+'><span>'+c.label+'<small>'+c.hint+'</small></span></label>'; }).join("");
  }
  function css(){
    var s=document.createElement("style"); s.id="s4-css";
    s.textContent="#s4Sheet{position:fixed;inset:0;z-index:318;display:none;flex-direction:column;justify-content:flex-end;background:rgba(6,5,4,.6)}"+
    "#s4Sheet .box{background:#14120f;border-top:1px solid #302c26;border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;max-height:86vh;overflow:auto}"+
    "#s4Sheet h4{margin:0;font:700 15px system-ui;color:#ffb454}#s4Info{font-size:12.5px;color:#948a79}"+
    "#s4Sheet button{min-height:44px;border-radius:12px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font-size:13.5px;padding:0 14px}"+
    "#s4Sheet button.go{background:linear-gradient(155deg,#ff7a3d,#e8622a);color:#1a0c03;border-color:transparent;font-weight:700}"+
    ".s4k{display:flex;gap:10px;align-items:center;min-height:44px;font-size:13.5px;color:#f1ece2}.s4k input{width:22px;height:22px;flex:none}.s4k small{display:block;font-size:11.5px;color:#8f8777}";
    document.head.appendChild(s);
  }
  function ui(){
    css(); sheet=document.createElement("div"); sheet.id="s4Sheet"; sheet.setAttribute("role","dialog"); sheet.setAttribute("aria-label","Remove attributes");
    sheet.innerHTML='<div class="box"><div style="display:flex;justify-content:space-between;align-items:center"><h4>\u267B Remove attributes</h4><button type="button" id="s4X" aria-label="Close">Close</button></div><div id="s4Info"></div><div id="s4List"></div><button type="button" class="go" id="s4Go">Remove from selected clips</button></div>';
    document.body.appendChild(sheet);
    $("s4X").onclick=close; $("s4Go").onclick=apply;
    sheet.addEventListener("click",function(e){ if(e.target===sheet) close(); });
    sheet.addEventListener("change",function(e){ var id=e.target.getAttribute&&e.target.getAttribute("data-c"); if(id) pick[id]=e.target.checked; });
  }
  function open(){ if(!sheet) ui(); paint(); sheet.style.display="flex"; }
  function close(){ if(sheet) sheet.style.display="none"; }
  window.amiyoRemoveAttributes={open:open,close:close,reset:function(clip,ids){ var n=0; CATS.forEach(function(c){ if(!ids||ids.indexOf(c.id)>=0) n+=resetClip(clip,c); }); return n; }};
  function addBtn(){
    var bar=document.querySelector(".timeline-toolbar"); if(!bar||$("s4Btn")) return;
    var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.id="s4Btn"; b.textContent="\u267B Reset"; b.title="Remove attributes from the selected clips"; b.onclick=open;
    var a=$("s3Btn")||$("fitTimelineBtn"); if(a&&a.parentNode===bar) bar.insertBefore(b,a.nextSibling); else bar.appendChild(b);
  }
  addBtn(); setTimeout(addBtn,1000);
  try{ window.AMIYO_EDITOR_BUILD="pr-step04-remove-attributes"; }catch(e){}
})();
